-- Review release, not a declaration of a passed 25% held-out experiment.
-- All234 keys were independently grounded; all media must be deployed first.
do $publish_six$
declare
 wanted jsonb := $six_papers$[{"id":"tcf-listening-01","version":"tcf-listening-2026-11-test01-v4","title":"TCF Listening · Test 01","seconds":2100,"questions":[{"number":1,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","transcript":"Question 1.\nÉcoutez les quatre propositions. Choisissez celle qui correspond à l'image. A. Il parle au caissier. B. Il pousse un chariot de courses. C. Il pose ses sacs par terre. D. Il porte deux sacs de courses.","explanation":"Réponse D : On voit clairement la personne debout, tenant deux sacs de courses, un dans chaque main. C’est la seule description qui correspond exactement à l’image. A : On ne voit pas de caissier ni de situation de dialogue dans l’image. Quelqu’un pourrait penser qu’il parle à un caissier parce qu’il se trouve dans un environnement qui pourrait rappeler un magasin, mais il n’y a aucun signe de conversation. B : Il n’y a pas de chariot de courses visible sur l’image. La confusion pourrait venir du fait qu’il est dans un contexte d’achats, mais il porte des sacs, pas un chariot. C : Il tient les sacs dans ses mains, ils ne sont pas posés par terre. Quelqu’un pourrait mal interpréter la position des sacs, mais ils sont clairement portés.","segments":[{"voice":"female","text":"Question 1."},{"voice":"female","text":"Écoutez les quatre propositions. Choisissez celle qui correspond à l'image. A. Il parle au caissier. B. Il pousse un chariot de courses. C. Il pose ses sacs par terre. D. Il porte deux sacs de courses."}],"image":"q-01.svg","audio":"q-01.mp3","audioSeconds":16.875,"slotSeconds":35},{"number":2,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","transcript":"Question 2.\nÉcoutez les quatre propositions. A. Elle plante une graine dans le pot. B. Elle redresse une plante tombée. C. Elle arrose une plante en pot. D. Elle nettoie le sol près du pot.","explanation":"Réponse C : La personne tient un arrosoir et verse de l’eau sur la plante en pot, ce qui correspond exactement à l’énoncé. A : On ne voit pas la personne planter une graine dans le pot, mais elle tient un arrosoir, ce qui pourrait faire penser à une activité de jardinage. B : La plante est droite dans le pot, il n'y a aucun geste de redressement observé. Quelqu’un pourrait croire qu’elle aide la plante, mais ce n’est pas le cas ici. D : La personne ne nettoie pas le sol, elle est concentrée sur la plante. L’arrosoir pourrait être confondu avec un outil de nettoyage, mais ce n’est pas le cas.","segments":[{"voice":"female","text":"Question 2."},{"voice":"female","text":"Écoutez les quatre propositions. A. Elle plante une graine dans le pot. B. Elle redresse une plante tombée. C. Elle arrose une plante en pot. D. Elle nettoie le sol près du pot."}],"image":"q-02.svg","audio":"q-02.mp3","audioSeconds":14.393,"slotSeconds":31},{"number":3,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","transcript":"Question 3.\nÉcoutez les quatre propositions. A. Ils déplacent des pions sur un plateau. B. Ils regardent un film sur une tablette. C. Ils mangent ensemble à table. D. Ils écrivent chacun sur un carnet.","explanation":"Réponse A : L'image montre deux personnes assises de part et d'autre d'une table, avec un plateau de jeu et des pions dessus. Cela correspond à la description : 'Ils déplacent des pions sur un plateau.' B : On pourrait croire qu'ils regardent quelque chose sur la table, mais il n'y a pas de tablette visible sur l'image, seulement un plateau de jeu. C : Les deux personnes sont assises à une table, ce qui pourrait faire penser à un repas, mais il n'y a ni nourriture ni assiettes visibles. D : Ils ont les mains sur le plateau, mais aucun carnet ou stylo n'est visible, donc ils n'écrivent pas.","segments":[{"voice":"female","text":"Question 3."},{"voice":"male","text":"Écoutez les quatre propositions. A. Ils déplacent des pions sur un plateau. B. Ils regardent un film sur une tablette. C. Ils mangent ensemble à table. D. Ils écrivent chacun sur un carnet."}],"image":"q-03.svg","audio":"q-03.mp3","audioSeconds":17.58,"slotSeconds":32},{"number":4,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","transcript":"Question 4.\nÉcoutez les quatre propositions. A. Il lave les roues de son vélo. B. Il verrouille son vélo à un poteau. C. Il vérifie la chaîne de son vélo. D. Il gonfle le pneu de son vélo.","explanation":"Réponse D : On voit clairement la personne utiliser une pompe reliée à la roue du vélo, ce qui indique qu'il gonfle le pneu. A : On ne voit pas d'eau, d'éponge ou de geste de nettoyage sur l'image. Quelqu'un pourrait croire qu'il lave les roues car il touche la roue, mais il utilise une pompe. B : Il n'y a pas de poteau ni de cadenas visible sur l'image. La confusion pourrait venir du fait que la personne est près du vélo, mais il n'y a aucun geste de verrouillage. C : La personne ne touche pas la chaîne du vélo, et il n'y a aucun geste indiquant une vérification de la chaîne. Quelqu'un pourrait confondre car la pompe est reliée à la roue, près de la chaîne.","segments":[{"voice":"female","text":"Question 4."},{"voice":"female","text":"Écoutez les quatre propositions. A. Il lave les roues de son vélo. B. Il verrouille son vélo à un poteau. C. Il vérifie la chaîne de son vélo. D. Il gonfle le pneu de son vélo."}],"image":"q-04.svg","audio":"q-04.mp3","audioSeconds":15.438,"slotSeconds":32},{"number":5,"kind":"response","question":"Quelle réponse convient à la situation ?","options":["Réponse A","Réponse B","Réponse C","Réponse D"],"correct":"B","transcript":"Question 5.\nBonjour, cette place est libre ?\nA. Je préfère rester debout, merci. B. Oui, bien sûr, asseyez-vous. C. Oui, c’est bien la bonne direction. D. Je crois que vous êtes en avance.","explanation":"Réponse B : La question demande si la place est libre, donc inviter la personne à s’asseoir (« Oui, bien sûr, asseyez-vous. ») est la réponse appropriée. A : Quelqu’un pourrait penser qu’on propose de s’asseoir, donc répondre qu’il préfère rester debout, mais la question porte sur la disponibilité de la place, pas sur une invitation à s’asseoir. C : Quelqu’un pourrait confondre avec une question sur la direction ou le chemin, mais ici il s’agit d’une place assise, donc cette réponse ne convient pas. D : On pourrait croire que la question porte sur l’horaire ou l’arrivée, mais il s’agit de la disponibilité d’une place, donc cette réponse n’est pas appropriée.","segments":[{"voice":"female","text":"Question 5."},{"voice":"male","text":"Bonjour, cette place est libre ?"},{"voice":"female","text":"A. Je préfère rester debout, merci. B. Oui, bien sûr, asseyez-vous. C. Oui, c’est bien la bonne direction. D. Je crois que vous êtes en avance."}],"audio":"q-05.mp3","audioSeconds":16.588,"slotSeconds":32},{"number":6,"kind":"response","question":"Quelle réponse convient à la situation ?","options":["Réponse A","Réponse B","Réponse C","Réponse D"],"correct":"C","transcript":"Question 6.\nExcusez-moi, où est l'arrêt du bus vingt-deux ?\nA. Désolé, je ne connais pas ce bus. B. Le prochain passe dans dix minutes. C. L'arrêt est juste après le carrefour. D. Il faut acheter le ticket dedans.","explanation":"Réponse C : Cette réponse indique clairement où se trouve l'arrêt, ce qui correspond exactement à la question posée. A : Cette réponse pourrait être choisie si l'on croit que la personne demande des informations sur le bus lui-même, mais la question porte sur l'emplacement de l'arrêt, pas sur la connaissance du bus. B : Quelqu'un pourrait penser que la question concerne l'heure de passage du bus, mais la question porte sur l'emplacement de l'arrêt, pas sur l'horaire. D : On pourrait croire que la question porte sur l'achat du ticket, mais la question concerne uniquement l'emplacement de l'arrêt.","segments":[{"voice":"female","text":"Question 6."},{"voice":"female","text":"Excusez-moi, où est l'arrêt du bus vingt-deux ?"},{"voice":"male","text":"A. Désolé, je ne connais pas ce bus. B. Le prochain passe dans dix minutes. C. L'arrêt est juste après le carrefour. D. Il faut acheter le ticket dedans."}],"audio":"q-06.mp3","audioSeconds":17.998,"slotSeconds":35},{"number":7,"kind":"response","question":"Quelle réponse convient à la situation ?","options":["Réponse A","Réponse B","Réponse C","Réponse D"],"correct":"D","transcript":"Question 7.\nTu veux venir marcher avec nous dimanche matin ?\nA. Désolé, je dois conduire les enfants à midi. B. Je peux passer prendre la voiture ? C. Non merci, je déteste marcher la nuit. D. Oui, volontiers, je serai là.","explanation":"Réponse D : Cette réponse accepte clairement l'invitation à marcher dimanche matin. Elle répond directement et positivement à la question. A : Cette réponse pourrait être choisie si l'on confondait le moment de la marche (dimanche matin) avec un autre moment (midi). Cependant, la question porte sur une marche le matin, pas à midi. La réponse n'est donc pas adaptée à la proposition. B : Quelqu'un pourrait croire qu'il s'agit d'un déplacement en voiture, mais la question porte sur marcher, pas sur prendre une voiture. Cette réponse ne correspond pas à la proposition faite. C : Cette réponse pourrait être choisie si l'on pensait que la marche avait lieu la nuit, alors qu'il s'agit du matin. Elle montre une confusion sur le moment de l'activité.","segments":[{"voice":"female","text":"Question 7."},{"voice":"male","text":"Tu veux venir marcher avec nous dimanche matin ?"},{"voice":"female","text":"A. Désolé, je dois conduire les enfants à midi. B. Je peux passer prendre la voiture ? C. Non merci, je déteste marcher la nuit. D. Oui, volontiers, je serai là."}],"audio":"q-07.mp3","audioSeconds":18.442,"slotSeconds":36},{"number":8,"kind":"response","question":"Quelle réponse convient à la situation ?","options":["Réponse A","Réponse B","Réponse C","Réponse D"],"correct":"D","transcript":"Question 8.\nCette chemise est trop petite. Est-ce que je peux l'échanger ?\nA. On peut la faire retoucher si vous voulez. B. Je peux seulement vous proposer un remboursement immédiat. C. Non, nous ne faisons pas d’échange sur les chemises. D. Oui, bien sûr, à condition d’avoir le ticket.","explanation":"Réponse D : C’est la seule réponse qui accepte l’échange, tout en précisant la condition nécessaire (avoir le ticket), ce qui répond exactement à la demande du client. A : La personne demande explicitement si elle peut échanger la chemise, pas la faire retoucher. Quelqu’un pourrait confondre « échanger » et « retoucher » car les deux sont des solutions à un problème de taille, mais la demande porte sur l’échange. B : Proposer un remboursement immédiat pourrait sembler une alternative à l’échange, mais la question porte sur la possibilité d’échanger, pas de rembourser. Quelqu’un pourrait penser que si l’échange n’est pas possible, le remboursement l’est, mais ce n’est pas la réponse à la question posée. C : Cette réponse nie la possibilité d’échanger, ce qui pourrait être choisi si l’on croit que le magasin refuse les échanges. Cependant, la bonne réponse indique que l’échange est possible sous condition, ce qui contredit ce refus catégorique.","segments":[{"voice":"female","text":"Question 8."},{"voice":"female","text":"Cette chemise est trop petite. Est-ce que je peux l'échanger ?"},{"voice":"male","text":"A. On peut la faire retoucher si vous voulez. B. Je peux seulement vous proposer un remboursement immédiat. C. Non, nous ne faisons pas d’échange sur les chemises. D. Oui, bien sûr, à condition d’avoir le ticket."}],"audio":"q-08.mp3","audioSeconds":21.185,"slotSeconds":37},{"number":9,"kind":"announcement","question":"Que précise l’annonce à propos de l’horaire du train pour Tours ?","options":["Le train partira finalement plus tôt.","L’heure d’arrivée à Tours est avancée.","Le départ est retardé, sans nouvelle heure indiquée.","L’heure de départ reste la même."],"correct":"D","transcript":"Question 9.\nVotre attention, s'il vous plaît. Le train pour Tours, prévu à dix heures vingt sur le quai deux, arrivera sur le quai quatre. Son heure de départ ne change pas. Merci de rejoindre ce nouveau quai.\nQue précise l’annonce à propos de l’horaire du train pour Tours ?","explanation":"Réponse D : L'annonce précise explicitement que l'heure de départ reste la même malgré le changement de quai. A : Quelqu'un pourrait penser que le train part plus tôt à cause du changement de quai, mais l'annonce précise que l'heure de départ ne change pas. B : On pourrait croire que l'heure d'arrivée change à cause du changement de quai, mais l'annonce ne parle que du quai et précise que l'heure de départ reste la même. C : Le changement de quai pourrait faire croire à un retard sans nouvelle heure, mais l'annonce dit explicitement que l'heure de départ ne change pas.","segments":[{"voice":"female","text":"Question 9."},{"voice":"female","text":"Votre attention, s'il vous plaît. Le train pour Tours, prévu à dix heures vingt sur le quai deux, arrivera sur le quai quatre. Son heure de départ ne change pas. Merci de rejoindre ce nouveau quai."},{"voice":"female","text":"Que précise l’annonce à propos de l’horaire du train pour Tours ?"}],"audio":"q-09.mp3","audioSeconds":17.11,"slotSeconds":36},{"number":10,"kind":"dialogue","question":"Finalement, à quelle heure décident-ils de se retrouver ?","options":["À dix-neuf heures.","À dix-huit heures.","À dix-neuf heures trente.","À dix-huit heures trente."],"correct":"A","transcript":"Question 10.\nOn se retrouve à dix-huit heures devant le cinéma ?\nJe termine mon travail à dix-huit heures trente. Dix-neuf heures, ce serait mieux.\nD'accord, à dix-neuf heures. Je prendrai les billets avant ton arrivée.\nFinalement, à quelle heure décident-ils de se retrouver ?","explanation":"Réponse A : La décision finale est clairement exprimée par l'accord sur dix-neuf heures : « D'accord, à dix-neuf heures. » C'est donc l'heure choisie pour se retrouver. B : Quelqu'un pourrait croire que l'heure initialement proposée (dix-huit heures) a été retenue, car c'est la première mentionnée. Cependant, cette proposition est rejetée car l'autre personne termine son travail plus tard. C : On pourrait confondre l'heure de fin de travail (dix-huit heures trente) avec l'heure du rendez-vous, mais ce n'est qu'une contrainte, pas l'heure décidée. D : Cette heure est mentionnée comme heure de fin de travail, pas comme heure de rendez-vous. Quelqu'un pourrait mal comprendre et penser que c'est l'heure du rendez-vous, mais ce n'est pas le cas.","segments":[{"voice":"female","text":"Question 10."},{"voice":"male","text":"On se retrouve à dix-huit heures devant le cinéma ?"},{"voice":"female","text":"Je termine mon travail à dix-huit heures trente. Dix-neuf heures, ce serait mieux."},{"voice":"male","text":"D'accord, à dix-neuf heures. Je prendrai les billets avant ton arrivée."},{"voice":"female","text":"Finalement, à quelle heure décident-ils de se retrouver ?"}],"audio":"q-10.mp3","audioSeconds":19.435,"slotSeconds":39},{"number":11,"kind":"announcement","question":"Que dit précisément l’annonce à propos de l’inscription à l’atelier ?","options":["L’inscription est gratuite, mais les places sont limitées.","L’inscription est obligatoire uniquement pour les membres de l’association.","L’inscription est payante, et le nombre de places est illimité.","L’inscription est gratuite, et chacun peut venir sans limite de place."],"correct":"A","transcript":"Question 11.\nSamedi, notre atelier de réparation ouvre à quatorze heures. Nous fournissons les aiguilles, le fil et les ciseaux. Apportez simplement un vêtement que vous voulez réparer. L'inscription est gratuite, mais les places sont limitées.\nQue dit précisément l’annonce à propos de l’inscription à l’atelier ?","explanation":"Réponse A : L'annonce précise explicitement que l'inscription est gratuite et que les places sont limitées. Cette option reprend exactement ces deux éléments. B : Quelqu'un pourrait croire que seuls les membres doivent s'inscrire, mais l'annonce ne mentionne aucune condition liée à l'appartenance à une association. Elle parle simplement de l'inscription en général. C : On pourrait confondre la gratuité avec le paiement, mais l'annonce dit clairement que l'inscription est gratuite et non payante. De plus, elle précise que les places sont limitées, pas illimitées. D : Quelqu'un pourrait retenir uniquement la gratuité et oublier la limitation du nombre de places, mais l'annonce insiste bien sur le fait que les places sont limitées.","segments":[{"voice":"female","text":"Question 11."},{"voice":"male","text":"Samedi, notre atelier de réparation ouvre à quatorze heures. Nous fournissons les aiguilles, le fil et les ciseaux. Apportez simplement un vêtement que vous voulez réparer. L'inscription est gratuite, mais les places sont limitées."},{"voice":"female","text":"Que dit précisément l’annonce à propos de l’inscription à l’atelier ?"}],"audio":"q-11.mp3","audioSeconds":21.081,"slotSeconds":40},{"number":12,"kind":"dialogue","question":"(Question modifiée) Que précise la cliente à propos du paiement de la lampe ?","options":["Qu’elle utilisera un bon d’achat pour payer.","Qu’elle doit encore la payer en magasin.","Qu’elle l’a déjà réglée en ligne.","Qu’elle n’a versé qu’un acompte par internet."],"correct":"C","transcript":"Question 12.\nBonjour, j'ai reçu votre message pour ma lampe.\nVous venez la chercher ? Elle est prête, au comptoir du fond.\nParfait. Je l'ai déjà payée en ligne. Voici le numéro de ma commande.\n(Question modifiée) Que précise la cliente à propos du paiement de la lampe ?","explanation":"Réponse C : La cliente affirme explicitement qu'elle a déjà réglé la lampe en ligne, ce qui répond précisément à la question. A : La cliente dit qu'elle a déjà payé la lampe en ligne, mais ne mentionne pas l'utilisation d'un bon d'achat. Quelqu'un pourrait confondre un paiement en ligne avec un bon d'achat électronique, mais ce n'est pas précisé. B : La cliente précise qu'elle a déjà payé la lampe en ligne, donc elle ne doit plus la payer en magasin. Quelqu'un pourrait penser qu'il reste un paiement à faire parce qu'elle vient la chercher, mais c'est contredit par sa déclaration. D : La cliente ne mentionne pas d'acompte, mais un paiement complet en ligne. Quelqu'un pourrait supposer qu'il ne s'agit que d'un acompte, mais rien ne l'indique dans l'extrait.","segments":[{"voice":"female","text":"Question 12."},{"voice":"female","text":"Bonjour, j'ai reçu votre message pour ma lampe."},{"voice":"male","text":"Vous venez la chercher ? Elle est prête, au comptoir du fond."},{"voice":"female","text":"Parfait. Je l'ai déjà payée en ligne. Voici le numéro de ma commande."},{"voice":"female","text":"(Question modifiée) Que précise la cliente à propos du paiement de la lampe ?"}],"audio":"q-12.mp3","audioSeconds":19.54,"slotSeconds":38},{"number":13,"kind":"announcement","question":"Comment la piscine fonctionnera-t-elle précisément le mercredi annoncé ?","options":["Elle ouvrira et fermera aux mêmes heures qu'habituellement, mais tous les horaires du mercredi seront avancés d'une heure.","Elle restera ouverte comme d'habitude, mais les cours de l'après-midi commenceront exceptionnellement à quatorze heures trente.","Elle sera fermée de huit heures à midi, puis rouvrira à quatorze heures avec ses horaires habituels.","Elle restera fermée toute la journée de mercredi pour permettre l'intervention technique."],"correct":"C","transcript":"Question 13.\nEn raison d'une intervention technique, la piscine sera fermée mercredi de huit heures à midi. Les cours reprendront à quatorze heures. Les autres jours de la semaine, les horaires habituels seront conservés. Merci de votre compréhension.\nComment la piscine fonctionnera-t-elle précisément le mercredi annoncé ?","explanation":"Réponse C : C'est la seule option qui reprend précisément les informations du texte : fermeture de 8h à midi, puis réouverture à 14h avec les horaires habituels. A : Quelqu'un pourrait croire que les horaires sont simplement avancés, mais le texte précise une fermeture spécifique le mercredi matin, pas un décalage général des horaires. B : On pourrait croire que seuls les cours de l'après-midi sont concernés, mais le texte indique une fermeture de la piscine, pas seulement un changement d'horaire pour les cours. D : On pourrait croire à une fermeture totale, mais le texte précise une réouverture à 14h, donc la piscine n'est pas fermée toute la journée.","segments":[{"voice":"female","text":"Question 13."},{"voice":"female","text":"En raison d'une intervention technique, la piscine sera fermée mercredi de huit heures à midi. Les cours reprendront à quatorze heures. Les autres jours de la semaine, les horaires habituels seront conservés. Merci de votre compréhension."},{"voice":"female","text":"Comment la piscine fonctionnera-t-elle précisément le mercredi annoncé ?"}],"audio":"q-13.mp3","audioSeconds":21.002,"slotSeconds":40},{"number":14,"kind":"dialogue","question":"Que propose Paul de préparer avec ce qu’ils ont à la maison ?","options":["Des pâtes.","Une soupe.","Une salade.","Un sandwich."],"correct":"B","transcript":"Question 14.\nPaul, je n'ai pas eu le temps de faire les courses. Il n'y a plus de pain.\nCe n'est pas grave. On a des légumes et des pommes de terre. Je peux préparer une soupe.\nBonne idée, je vais mettre la table.\nQue propose Paul de préparer avec ce qu’ils ont à la maison ?","explanation":"Réponse B : Paul dit clairement qu'il peut préparer une soupe avec les légumes et les pommes de terre disponibles. C'est la seule proposition explicite dans l'extrait. A : Quelqu'un pourrait penser à des pâtes car c'est un plat courant à préparer rapidement, mais Paul ne mentionne pas de pâtes ni d'ingrédients associés. Il parle uniquement de légumes et de pommes de terre, ce qui ne correspond pas à des pâtes. C : Quelqu'un pourrait penser à une salade car il y a des légumes, mais Paul précise qu'il va faire une soupe, pas une salade. Les pommes de terre sont aussi plus courantes dans une soupe que dans une salade. D : On pourrait croire à un sandwich car le pain est mentionné, mais justement, il est dit qu'il n'y en a plus, donc ce n'est pas possible. Paul ne propose pas de sandwich.","segments":[{"voice":"female","text":"Question 14."},{"voice":"female","text":"Paul, je n'ai pas eu le temps de faire les courses. Il n'y a plus de pain."},{"voice":"male","text":"Ce n'est pas grave. On a des légumes et des pommes de terre. Je peux préparer une soupe."},{"voice":"female","text":"Bonne idée, je vais mettre la table."},{"voice":"female","text":"Que propose Paul de préparer avec ce qu’ils ont à la maison ?"}],"audio":"q-14.mp3","audioSeconds":18.939,"slotSeconds":39},{"number":15,"kind":"announcement","question":"Que dit l’annonce au sujet du formulaire sur l’aménagement de la place ?","options":["Il est réservé aux habitants qui participent à la réunion de samedi.","Il doit être complété et rendu avant la fin de la journée.","Il ne peut être rempli que le jour de la réunion publique.","Il est disponible sur le site de la mairie et à l’accueil jusqu’au vingt mai."],"correct":"D","transcript":"Question 15.\nLa mairie prépare l'aménagement de la place des Érables et souhaite connaître vos habitudes. Un formulaire est disponible sur son site et à l'accueil jusqu'au vingt mai. Une réunion aura également lieu samedi à dix heures. Vous n'avez pas besoin d'assister à la réunion pour remplir le formulaire. Les propositions seront ensuite présentées au conseil municipal.\nQue dit l’annonce au sujet du formulaire sur l’aménagement de la place ?","explanation":"Réponse D : L'annonce précise que le formulaire est disponible sur le site de la mairie et à l'accueil jusqu'au vingt mai, ce qui correspond exactement à cette option. A : Quelqu'un pourrait croire que le formulaire est réservé aux participants de la réunion car la réunion et le formulaire sont tous deux mentionnés, mais l'annonce précise explicitement que la participation à la réunion n'est pas nécessaire. B : On pourrait penser qu'il faut rendre le formulaire avant la fin de la journée, mais la date limite donnée est le vingt mai, pas aujourd'hui. C : Certains pourraient croire que le formulaire ne peut être rempli que le jour de la réunion publique, car la réunion est mentionnée, mais il est clairement dit que ce n'est pas nécessaire.","segments":[{"voice":"female","text":"Question 15."},{"voice":"male","text":"La mairie prépare l'aménagement de la place des Érables et souhaite connaître vos habitudes. Un formulaire est disponible sur son site et à l'accueil jusqu'au vingt mai. Une réunion aura également lieu samedi à dix heures. Vous n'avez pas besoin d'assister à la réunion pour remplir le formulaire. Les propositions seront ensuite présentées au conseil municipal."},{"voice":"female","text":"Que dit l’annonce au sujet du formulaire sur l’aménagement de la place ?"}],"audio":"q-15.mp3","audioSeconds":29.074,"slotSeconds":49},{"number":16,"kind":"dialogue","question":"Comment la responsable réorganise-t-elle les permanences ?","options":["Ils décalent tous les deux leurs horaires et réduisent l'ouverture.","Elle assure l'accueil du matin et Karim la fin de journée.","Elle avance l'ouverture et confie tout l'après-midi à Karim.","Karim garde l'accueil du matin et elle prend la fermeture."],"correct":"B","transcript":"Question 16.\nKarim, tu m'as dit que les horaires de la crèche allaient changer ?\nOui, à partir de lundi, je ne pourrai plus être ici avant neuf heures trente.\nAlors, je prendrai l'accueil du matin et tu assureras ma permanence de fin de journée. Comme cela, nous conserverons les mêmes heures d'ouverture.\nMerci, cette organisation me convient.\nComment la responsable réorganise-t-elle les permanences ?","explanation":"Réponse B : La responsable dit clairement qu'elle prendra l'accueil du matin et que Karim assurera la permanence de fin de journée, ce qui correspond exactement à cette option. A : Quelqu'un pourrait croire que les horaires sont décalés et l'ouverture réduite car Karim ne peut plus être là avant 9h30, mais la responsable précise explicitement qu'ils conservent les mêmes heures d'ouverture. C : Quelqu'un pourrait croire qu'elle avance l'ouverture et confie tout l'après-midi à Karim, car elle prend le matin, mais il n'est jamais question d'avancer l'ouverture ni de confier tout l'après-midi à Karim. D : On pourrait penser que Karim garde l'accueil du matin, car il le faisait avant, mais il dit explicitement qu'il ne pourra plus être là avant 9h30, donc c'est la responsable qui prend le matin.","segments":[{"voice":"female","text":"Question 16."},{"voice":"female","text":"Karim, tu m'as dit que les horaires de la crèche allaient changer ?"},{"voice":"male","text":"Oui, à partir de lundi, je ne pourrai plus être ici avant neuf heures trente."},{"voice":"female","text":"Alors, je prendrai l'accueil du matin et tu assureras ma permanence de fin de journée. Comme cela, nous conserverons les mêmes heures d'ouverture."},{"voice":"male","text":"Merci, cette organisation me convient."},{"voice":"female","text":"Comment la responsable réorganise-t-elle les permanences ?"}],"audio":"q-16.mp3","audioSeconds":27.429,"slotSeconds":48},{"number":17,"kind":"announcement","question":"Selon le document, comment un habitant doit-il procéder pour bénéficier du service de portage ?","options":["En signalant ses difficultés de déplacement au bénévole qui passe déjà chez lui.","En contactant l'accueil pour en faire la demande.","En utilisant simplement sa carte de bibliothèque lors d'un prêt.","En empruntant un premier livre afin d'être automatiquement inscrit au service."],"correct":"B","transcript":"Question 17.\nLa bibliothèque lance un service de portage pour les habitants qui ont des difficultés à se déplacer, même temporairement. Après un échange sur leurs goûts, un bénévole leur apportera une sélection de livres à domicile. Les prêts restent gratuits et les dates de retour seront convenues avec l'équipe. Pour demander ce service, contactez l'accueil ; une carte de bibliothèque ne suffit pas à déclencher automatiquement une livraison.\nSelon le document, comment un habitant doit-il procéder pour bénéficier du service de portage ?","explanation":"Réponse B : Le document indique explicitement que pour bénéficier du service de portage, il faut contacter l'accueil. C'est la seule démarche mentionnée pour accéder au service. A : On pourrait croire que le bénévole passe déjà chez la personne et qu'il suffit de lui signaler ses difficultés, car le texte mentionne un échange avec un bénévole. Cependant, il est précisé qu'il faut d'abord contacter l'accueil pour bénéficier du service. C : Quelqu'un pourrait croire qu'utiliser sa carte de bibliothèque suffit, car la carte est évoquée dans le texte. Cependant, il est clairement dit que cela ne déclenche pas le service. D : On pourrait penser qu'emprunter un premier livre inscrit automatiquement au service, mais le texte précise que ce n'est pas automatique et qu'il faut faire une demande spécifique.","segments":[{"voice":"female","text":"Question 17."},{"voice":"female","text":"La bibliothèque lance un service de portage pour les habitants qui ont des difficultés à se déplacer, même temporairement. Après un échange sur leurs goûts, un bénévole leur apportera une sélection de livres à domicile. Les prêts restent gratuits et les dates de retour seront convenues avec l'équipe. Pour demander ce service, contactez l'accueil ; une carte de bibliothèque ne suffit pas à déclencher automatiquement une livraison."},{"voice":"female","text":"Selon le document, comment un habitant doit-il procéder pour bénéficier du service de portage ?"}],"audio":"q-17.mp3","audioSeconds":32.235,"slotSeconds":51},{"number":18,"kind":"dialogue","question":"Quelle solution les collègues choisissent-ils pour la présentation ?","options":["Projeter la version enregistrée sur l’ordinateur et commenter le dernier graphique à l’oral.","Imprimer la présentation et la distribuer aux participants à la place de la projection.","Reporter la présentation afin d’ajouter le dernier graphique avant de la montrer.","Essayer de rétablir la connexion pour utiliser les diapositives en ligne complètes."],"correct":"A","transcript":"Question 18.\nLa connexion coupe encore. Si nous ouvrons les diapositives en ligne, la présentation va s'interrompre.\nJ'ai enregistré une copie sur mon ordinateur ce matin. Il manque seulement le dernier graphique.\nUtilisons cette version. Je pourrai expliquer le graphique à l'oral et envoyer le document complet après la réunion.\nD'accord, je branche mon ordinateur au projecteur.\nQuelle solution les collègues choisissent-ils pour la présentation ?","explanation":"Réponse A : Les collègues décident d'utiliser la version enregistrée sur l'ordinateur, de projeter cette version et de commenter le dernier graphique à l'oral, comme indiqué explicitement dans le dialogue. B : Quelqu'un pourrait penser que la distribution de copies papier est envisagée car il est question d'envoyer le document complet après la réunion, mais il n'est jamais question d'imprimer ou de distribuer la présentation pendant la réunion. C : On pourrait croire qu'ils reportent la présentation pour ajouter le graphique, car il manque un élément, mais ils choisissent de continuer avec la version incomplète et de commenter le graphique oralement. D : Quelqu'un pourrait penser qu'ils essaient de rétablir la connexion, car le problème de connexion est mentionné, mais ils décident explicitement de ne pas utiliser la version en ligne à cause de l'instabilité.","segments":[{"voice":"female","text":"Question 18."},{"voice":"male","text":"La connexion coupe encore. Si nous ouvrons les diapositives en ligne, la présentation va s'interrompre."},{"voice":"female","text":"J'ai enregistré une copie sur mon ordinateur ce matin. Il manque seulement le dernier graphique."},{"voice":"male","text":"Utilisons cette version. Je pourrai expliquer le graphique à l'oral et envoyer le document complet après la réunion."},{"voice":"female","text":"D'accord, je branche mon ordinateur au projecteur."},{"voice":"female","text":"Quelle solution les collègues choisissent-ils pour la présentation ?"}],"audio":"q-18.mp3","audioSeconds":32.575,"slotSeconds":52},{"number":19,"kind":"announcement","question":"Que précise l'annonce au sujet du niveau des participants à cette visite du jeudi ?","options":["Elle est réservée aux spécialistes du domaine présenté.","Elle exige au minimum quelques notions de base sur le sujet.","Elle s'adresse surtout aux personnes qui découvrent le musée.","Elle est ouverte à tous, sans connaissances préalables."],"correct":"D","transcript":"Question 19.\nÀ partir de ce mois-ci, le musée propose une visite du jeudi limitée à douze personnes. Le guide prendra le temps de répondre aux questions et de discuter des objets que vous aurez envie d'observer. Il ne s'agit pas d'un cours réservé aux spécialistes : aucune connaissance préalable n'est nécessaire. Le tarif habituel s'applique. Pensez toutefois à réserver, car nous ne pourrons pas agrandir le groupe.\nQue précise l'annonce au sujet du niveau des participants à cette visite du jeudi ?","explanation":"Réponse D : L'annonce précise explicitement que la visite est ouverte à tous, sans connaissances préalables. A : Quelqu'un pourrait croire que la visite est réservée aux spécialistes car il s'agit d'un musée et d'une visite guidée, mais l'annonce précise explicitement que ce n'est pas le cas. B : On pourrait penser qu'il faut quelques notions de base, mais l'annonce dit clairement qu'aucune connaissance préalable n'est nécessaire. C : Il est tentant de penser que la visite s'adresse surtout aux débutants ou à ceux qui découvrent le musée, mais l'annonce ne le précise pas ; elle dit seulement que tout le monde peut venir, sans restriction de niveau.","segments":[{"voice":"female","text":"Question 19."},{"voice":"male","text":"À partir de ce mois-ci, le musée propose une visite du jeudi limitée à douze personnes. Le guide prendra le temps de répondre aux questions et de discuter des objets que vous aurez envie d'observer. Il ne s'agit pas d'un cours réservé aux spécialistes : aucune connaissance préalable n'est nécessaire. Le tarif habituel s'applique. Pensez toutefois à réserver, car nous ne pourrons pas agrandir le groupe."},{"voice":"female","text":"Que précise l'annonce au sujet du niveau des participants à cette visite du jeudi ?"}],"audio":"q-19.mp3","audioSeconds":31.269,"slotSeconds":51},{"number":20,"kind":"dialogue","question":"Comment l'agent propose-t-il d'aider la locataire à évaluer le trajet ?","options":["En contactant la compagnie de bus pour connaître l’affluence.","En lui envoyant les horaires des deux lignes de bus.","En lui proposant de faire le trajet avec elle une première fois.","En lui fournissant un plan détaillé du quartier."],"correct":"B","transcript":"Question 20.\nL'appartement me plaît. La cuisine est lumineuse et le loyer correspond à mon budget.\nVous souhaitez déposer un dossier aujourd'hui ?\nJe voudrais d'abord essayer le trajet en bus demain matin. Sur le plan, ce n'est pas loin de mon travail, mais il y a une correspondance.\nBien sûr. Je vous enverrai les horaires des deux lignes, et nous pourrons nous rappeler ensuite.\nComment l'agent propose-t-il d'aider la locataire à évaluer le trajet ?","explanation":"Réponse B : L'agent propose explicitement d'envoyer les horaires des deux lignes de bus, ce qui correspond exactement à la manière dont il aide la locataire à évaluer le trajet. A : Quelqu'un pourrait penser que l'agent va contacter la compagnie de bus pour obtenir des informations sur l'affluence, car la locataire s'inquiète du trajet et de la correspondance. Cependant, l'agent ne mentionne jamais l'affluence ni le contact avec la compagnie de bus. C : La phrase 'nous pourrons nous rappeler ensuite' pourrait être mal comprise comme une proposition d'accompagnement, mais il n'est jamais question que l'agent fasse le trajet avec la locataire. D : Quelqu'un pourrait croire que l'agent va fournir un plan détaillé du quartier, car la locataire parle du plan, mais l'agent ne propose que d'envoyer les horaires.","segments":[{"voice":"female","text":"Question 20."},{"voice":"female","text":"L'appartement me plaît. La cuisine est lumineuse et le loyer correspond à mon budget."},{"voice":"male","text":"Vous souhaitez déposer un dossier aujourd'hui ?"},{"voice":"female","text":"Je voudrais d'abord essayer le trajet en bus demain matin. Sur le plan, ce n'est pas loin de mon travail, mais il y a une correspondance."},{"voice":"male","text":"Bien sûr. Je vous enverrai les horaires des deux lignes, et nous pourrons nous rappeler ensuite."},{"voice":"female","text":"Comment l'agent propose-t-il d'aider la locataire à évaluer le trajet ?"}],"audio":"q-20.mp3","audioSeconds":28.996,"slotSeconds":51},{"number":21,"kind":"announcement","question":"Que peuvent préciser les habitants au moment de s’inscrire à la journée de jardinage ?","options":["S’ils ont déjà une expérience en jardinage ou non.","S’ils préfèrent une tâche assise ou s’ils doivent partir plus tôt.","S’ils apporteront leurs propres outils de jardinage.","S’ils participeront aussi aux prochaines séances de jardinage."],"correct":"B","transcript":"Question 21.\nNotre journée de jardinage collectif aura lieu dimanche, de neuf heures à midi. Tous les habitants sont les bienvenus, y compris ceux qui n'ont jamais jardiné. Merci de vous inscrire avant vendredi : nous pourrons prévoir assez d'outils et organiser les petits groupes. Vous pouvez signaler si vous préférez une tâche assise ou si vous devez partir plus tôt. L'inscription ne vous engage pas à participer aux prochaines séances.\nQue peuvent préciser les habitants au moment de s’inscrire à la journée de jardinage ?","explanation":"Réponse B : Le texte indique explicitement que les habitants peuvent préciser ces deux éléments lors de l'inscription, ce qui correspond exactement à la question. A : Il est mentionné que tous sont les bienvenus, même sans expérience, mais il n'est jamais demandé de préciser son expérience lors de l'inscription. Quelqu'un pourrait croire qu'il faut indiquer son expérience car le texte insiste sur l'accueil des débutants, mais ce n'est pas demandé. C : Le texte dit que l'organisation prévoit assez d'outils, mais il n'est jamais demandé ou proposé de signaler si l'on apporte ses propres outils. Quelqu'un pourrait mal interpréter la phrase sur la prévision des outils comme une invitation à signaler ce point, mais ce n'est pas le cas. D : Le texte précise que l'inscription n'engage pas pour les prochaines séances, donc il n'est pas demandé de préciser si l'on participera à l'avenir. Quelqu'un pourrait mal comprendre la phrase sur l'engagement comme une demande d'information, mais c'est l'inverse.","segments":[{"voice":"female","text":"Question 21."},{"voice":"female","text":"Notre journée de jardinage collectif aura lieu dimanche, de neuf heures à midi. Tous les habitants sont les bienvenus, y compris ceux qui n'ont jamais jardiné. Merci de vous inscrire avant vendredi : nous pourrons prévoir assez d'outils et organiser les petits groupes. Vous pouvez signaler si vous préférez une tâche assise ou si vous devez partir plus tôt. L'inscription ne vous engage pas à participer aux prochaines séances."},{"voice":"female","text":"Que peuvent préciser les habitants au moment de s’inscrire à la journée de jardinage ?"}],"audio":"q-21.mp3","audioSeconds":30.772,"slotSeconds":51},{"number":22,"kind":"interview","question":"Que précise la cycliste à propos du temps qu’elle met pour aller au travail ?","options":["Il est devenu plus long, car elle fait exprès des détours par la librairie et le marché.","Il n’est pas systématiquement plus court que le métro, surtout quand il pleut ou qu’il y a des travaux.","Il prend autant de temps qu’avant, mais la sensation de durée a changé.","Il gagne presque toujours du temps sur le métro."],"correct":"B","transcript":"Question 22.\nDepuis un an, vous allez au travail à vélo. Vous gagnez du temps ?\nPas forcément. Quand il pleut ou qu'il y a des travaux, le métro serait parfois plus rapide. Mais j'ai découvert des rues que je ne traversais jamais, une petite librairie, un marché. Le trajet fait maintenant partie de ma journée, au lieu d'être seulement un temps à supprimer. C'est cela que j'apprécie le plus.\nQue précise la cycliste à propos du temps qu’elle met pour aller au travail ?","explanation":"Réponse B : La cycliste précise bien que le vélo n’est pas systématiquement plus rapide que le métro, surtout dans certaines conditions comme la pluie ou les travaux. Cela répond exactement à la question sur la précision apportée concernant le temps de trajet. A : Quelqu’un pourrait croire que la cycliste fait exprès des détours par la librairie et le marché, ce qui rallongerait le trajet. Cependant, elle ne dit pas qu’elle s’arrête ou fait des détours intentionnels, seulement qu’elle découvre ces lieux en passant. Elle ne précise pas que le temps est devenu plus long à cause de cela. C : On pourrait croire que le temps de trajet est resté identique mais que seule la perception a changé. Cependant, elle ne dit pas explicitement que la durée est la même qu’avant, seulement que son ressenti a évolué. D : Quelqu’un pourrait penser que le vélo fait toujours gagner du temps, mais la cycliste précise justement que ce n’est pas le cas dans toutes les situations.","segments":[{"voice":"female","text":"Question 22."},{"voice":"male","text":"Depuis un an, vous allez au travail à vélo. Vous gagnez du temps ?"},{"voice":"female","text":"Pas forcément. Quand il pleut ou qu'il y a des travaux, le métro serait parfois plus rapide. Mais j'ai découvert des rues que je ne traversais jamais, une petite librairie, un marché. Le trajet fait maintenant partie de ma journée, au lieu d'être seulement un temps à supprimer. C'est cela que j'apprécie le plus."},{"voice":"female","text":"Que précise la cycliste à propos du temps qu’elle met pour aller au travail ?"}],"audio":"q-22.mp3","audioSeconds":29.127,"slotSeconds":50},{"number":23,"kind":"dialogue","question":"Pourquoi les organisateurs décident-ils de séparer les jeux et les lectures dans deux pièces différentes ?","options":["Parce que le bruit des jeux empêchait de bien entendre les lectures.","Parce que la répartition des tables ne laisse plus assez de place dans la grande salle.","Parce que les panneaux d’orientation se sont révélés trop compliqués pour les nouveaux arrivants.","Parce que plusieurs familles ont demandé à regrouper toutes les animations dans une seule pièce."],"correct":"A","transcript":"Question 23.\nLa journée de samedi a bien fonctionné, mais plusieurs familles ont trouvé les lectures difficiles à entendre.\nOui, les jeux de construction étaient installés juste à côté. Nous avions prévu les espaces selon le nombre de tables, sans penser au bruit.\nLa prochaine fois, gardons les jeux dans la grande salle et installons les lectures dans la pièce voisine.\nIl faudra améliorer les panneaux pour que chacun trouve les deux espaces. Je peux préparer un plan simple et demander aux bénévoles d'accompagner les nouveaux arrivants.\nPourquoi les organisateurs décident-ils de séparer les jeux et les lectures dans deux pièces différentes ?","explanation":"Réponse A : Le texte explique clairement que le bruit des jeux de construction, placés à côté des lectures, rendait celles-ci difficiles à entendre. C'est donc la raison pour laquelle les organisateurs décident de séparer les deux activités dans des pièces différentes. B : Quelqu'un pourrait croire que la répartition des tables est la cause, car il est mentionné que les espaces ont été prévus selon le nombre de tables. Cependant, le problème évoqué est le bruit, pas le manque de place. C : L'amélioration des panneaux d’orientation est mentionnée, mais comme une mesure d’accompagnement pour aider à trouver les espaces, pas comme la raison de la séparation des activités. D : Plusieurs familles ont fait une remarque, mais elles ont demandé une meilleure écoute des lectures, pas de regrouper toutes les animations dans une seule pièce. Cette option inverse la demande réelle.","segments":[{"voice":"female","text":"Question 23."},{"voice":"female","text":"La journée de samedi a bien fonctionné, mais plusieurs familles ont trouvé les lectures difficiles à entendre."},{"voice":"male","text":"Oui, les jeux de construction étaient installés juste à côté. Nous avions prévu les espaces selon le nombre de tables, sans penser au bruit."},{"voice":"female","text":"La prochaine fois, gardons les jeux dans la grande salle et installons les lectures dans la pièce voisine."},{"voice":"male","text":"Il faudra améliorer les panneaux pour que chacun trouve les deux espaces. Je peux préparer un plan simple et demander aux bénévoles d'accompagner les nouveaux arrivants."},{"voice":"female","text":"Pourquoi les organisateurs décident-ils de séparer les jeux et les lectures dans deux pièces différentes ?"}],"audio":"q-23.mp3","audioSeconds":39.576,"slotSeconds":60},{"number":24,"kind":"interview","question":"Que dit la chercheuse des travailleurs de nuit et des anciens usagers ?","options":["Les travailleurs de nuit ont surtout répondu ; les anciens usagers sont peu représentés.","Les travailleurs de nuit sont peu représentés ; les anciens usagers n’ont pas été interrogés.","Les deux groupes ont reçu le questionnaire, mais n’ont pas souhaité y répondre.","Les deux groupes ont répondu, mais leurs réponses ont été écartées du bilan."],"correct":"B","transcript":"Question 24.\nVotre enquête montre que les voyageurs sont satisfaits des nouveaux horaires. Peut-on dire que la réforme est un succès ?\nC'est un signal intéressant, mais notre questionnaire a surtout été distribué dans les bus en journée. Les salariés qui travaillent la nuit sont peu présents dans les réponses. Nous n'avons pas non plus interrogé ceux qui ont cessé de prendre cette ligne. Avant de conclure, il faut les contacter. Une enquête auprès des usagers actuels décrit une partie de la situation ; elle ne dit pas automatiquement ce que vivent les personnes absentes.\nQue dit la chercheuse des travailleurs de nuit et des anciens usagers ?","explanation":"Réponse B : C'est exactement ce que dit la chercheuse : les travailleurs de nuit sont peu représentés dans les réponses et les anciens usagers n'ont pas été interrogés. A : Cette option inverse la situation des deux groupes : elle affirme que les travailleurs de nuit ont surtout répondu, alors que le texte dit explicitement qu'ils sont peu présents dans les réponses. Elle affirme aussi que les anciens usagers sont peu représentés, mais le texte précise qu'ils n'ont pas été interrogés du tout. Quelqu'un pourrait confondre 'peu présents' et 'peu représentés', mais la formulation du texte contredit cette option. C : Cette option suppose que les deux groupes ont reçu le questionnaire mais n'ont pas souhaité répondre. Or, le texte précise que les anciens usagers n'ont pas été interrogés du tout, et que les travailleurs de nuit sont peu présents dans les réponses, ce qui ne signifie pas nécessairement qu'ils ont refusé de répondre, mais plutôt qu'ils n'ont pas été suffisamment sollicités. D : Cette option affirme que les deux groupes ont répondu mais que leurs réponses ont été écartées, ce qui n'est pas le cas. Le texte dit que les travailleurs de nuit sont peu présents dans les réponses (donc très peu ont répondu) et que les anciens usagers n'ont pas été interrogés du tout. Quelqu'un pourrait mal comprendre 'peu présents' comme 'leurs réponses ont été écartées', mais ce n'est pas ce qui est dit.","segments":[{"voice":"female","text":"Question 24."},{"voice":"male","text":"Votre enquête montre que les voyageurs sont satisfaits des nouveaux horaires. Peut-on dire que la réforme est un succès ?"},{"voice":"female","text":"C'est un signal intéressant, mais notre questionnaire a surtout été distribué dans les bus en journée. Les salariés qui travaillent la nuit sont peu présents dans les réponses. Nous n'avons pas non plus interrogé ceux qui ont cessé de prendre cette ligne. Avant de conclure, il faut les contacter. Une enquête auprès des usagers actuels décrit une partie de la situation ; elle ne dit pas automatiquement ce que vivent les personnes absentes."},{"voice":"female","text":"Que dit la chercheuse des travailleurs de nuit et des anciens usagers ?"}],"audio":"q-24.mp3","audioSeconds":37.224,"slotSeconds":59},{"number":25,"kind":"announcement","question":"D’après le reportage, dans quelles conditions le projet estime-t‑il qu’un équipement partagé devient vraiment utile ?","options":["Quand les usagers savent s’en servir et peuvent demander de l’aide sur place.","Quand le nombre d’adhérents est suffisamment élevé pour rentabiliser l’achat du matériel.","Quand les outils sont prêtés pour de longues durées, sans limite stricte de retour.","Quand l’atelier met surtout à disposition des machines récentes et très performantes."],"correct":"A","transcript":"Question 25.\nDans cet atelier de quartier, on peut emprunter une perceuse ou une ponceuse. Pourtant, la nouveauté n'est pas seulement dans les étagères remplies d'outils. Une bénévole prend le temps d'expliquer les gestes, de vérifier le matériau et de dire quand il vaut mieux renoncer. Un participant résume : j'avais déjà accès à une perceuse, mais je n'osais pas m'en servir. Le projet rappelle qu'un équipement partagé devient réellement utile quand les personnes savent l'utiliser et peuvent demander de l'aide.\nD’après le reportage, dans quelles conditions le projet estime-t‑il qu’un équipement partagé devient vraiment utile ?","explanation":"Réponse A : La citation du reportage indique explicitement que l’utilité réelle de l’équipement partagé dépend de la capacité des usagers à s’en servir et de la possibilité de demander de l’aide sur place. C’est la seule condition mentionnée comme essentielle. B : Quelqu’un pourrait croire que la rentabilité liée au nombre d’adhérents est importante, car cela semble logique pour un projet collectif. Cependant, le reportage ne mentionne à aucun moment la question de rentabilité ou du nombre d’adhérents comme critère d’utilité. C : On pourrait penser que la durée de prêt est importante, car la flexibilité semble utile. Toutefois, le texte ne parle pas de durée de prêt mais de l’accompagnement et de l’apprentissage. D : La mention d’outils disponibles pourrait faire croire que la modernité ou la performance des machines est un critère, mais le reportage ne met pas l’accent sur la qualité ou la nouveauté du matériel, seulement sur l’accompagnement et l’apprentissage.","segments":[{"voice":"female","text":"Question 25."},{"voice":"male","text":"Dans cet atelier de quartier, on peut emprunter une perceuse ou une ponceuse. Pourtant, la nouveauté n'est pas seulement dans les étagères remplies d'outils. Une bénévole prend le temps d'expliquer les gestes, de vérifier le matériau et de dire quand il vaut mieux renoncer. Un participant résume : j'avais déjà accès à une perceuse, mais je n'osais pas m'en servir. Le projet rappelle qu'un équipement partagé devient réellement utile quand les personnes savent l'utiliser et peuvent demander de l'aide."},{"voice":"female","text":"D’après le reportage, dans quelles conditions le projet estime-t‑il qu’un équipement partagé devient vraiment utile ?"}],"audio":"q-25.mp3","audioSeconds":39.001,"slotSeconds":57},{"number":26,"kind":"interview","question":"Selon quel critère principal la restauratrice choisit-elle désormais les plats de sa carte réduite ?","options":["En fonction des plats les plus demandés par les habitués.","En fonction des ingrédients dont le prix est le plus bas.","En fonction des livraisons des producteurs.","En fonction du temps de préparation le plus court."],"correct":"C","transcript":"Question 26.\nDepuis ce printemps, votre restaurant propose moins de plats. Vous cherchez surtout à aller plus vite ?\nLa rapidité compte, mais nous voulions surtout mieux travailler. Avec une carte très longue, nous conservions trop de produits différents et certains finissaient à la poubelle. Maintenant, nous choisissons quelques recettes selon les livraisons des producteurs. Les cuisiniers peuvent les préparer avec davantage d'attention. Certains clients ont d'abord regretté leurs habitudes ; nous leur expliquons les changements et gardons toujours une possibilité végétarienne. Réduire le nombre de lignes n'a pas réduit notre envie de bien accueillir.\nSelon quel critère principal la restauratrice choisit-elle désormais les plats de sa carte réduite ?","explanation":"Réponse C : La restauratrice dit explicitement que le choix des plats dépend désormais des livraisons des producteurs. C'est le critère principal mentionné. A : Quelqu'un pourrait croire que les plats sont choisis selon les préférences des habitués, car il est mentionné que certains clients regrettent leurs habitudes. Cependant, il n'est jamais dit que la carte est construite selon les plats les plus demandés. B : La mention du gaspillage pourrait faire penser à une recherche d'économie, donc à choisir les ingrédients les moins chers. Mais il n'est jamais question de prix comme critère principal. D : La rapidité est évoquée, ce qui pourrait faire croire que le temps de préparation est le critère principal. Mais la restauratrice précise que ce n'est pas le cas, la priorité étant la qualité et l'adaptation aux livraisons.","segments":[{"voice":"female","text":"Question 26."},{"voice":"female","text":"Depuis ce printemps, votre restaurant propose moins de plats. Vous cherchez surtout à aller plus vite ?"},{"voice":"male","text":"La rapidité compte, mais nous voulions surtout mieux travailler. Avec une carte très longue, nous conservions trop de produits différents et certains finissaient à la poubelle. Maintenant, nous choisissons quelques recettes selon les livraisons des producteurs. Les cuisiniers peuvent les préparer avec davantage d'attention. Certains clients ont d'abord regretté leurs habitudes ; nous leur expliquons les changements et gardons toujours une possibilité végétarienne. Réduire le nombre de lignes n'a pas réduit notre envie de bien accueillir."},{"voice":"female","text":"Selon quel critère principal la restauratrice choisit-elle désormais les plats de sa carte réduite ?"}],"audio":"q-26.mp3","audioSeconds":45.767,"slotSeconds":66},{"number":27,"kind":"dialogue","question":"Comment l’orateur propose-t-il d’ajuster l’organisation de la place ?","options":["Décider dès maintenant d’un aménagement définitif en réunion de quartier.","Lancer d’abord un vote en ligne pour choisir un plan, puis l’appliquer sans période d’essai.","Mettre en place pendant un mois un aménagement provisoire et recueillir ensuite les avis des habitants, des passants et des commerçants.","Tester pendant un mois un nouveau dispositif, puis demander seulement l’avis des riverains."],"correct":"C","transcript":"Question 27.\nLes joueurs de ballon demandent de garder la place ouverte, mais des voisins se plaignent du bruit près des bancs.\nOn ne réglera pas cela en décidant que seuls les enfants ou seuls les adultes ont le droit d'être là.\nNous pourrions déplacer les bancs vers le jardin et définir des horaires pour les jeux les plus bruyants.\nEssayons pendant un mois. Il faudra écouter aussi les personnes qui traversent la place et les commerçants. Le but n'est pas de faire disparaître les différences, mais d'éviter que chaque usage rende les autres impossibles.\nComment l’orateur propose-t-il d’ajuster l’organisation de la place ?","explanation":"Réponse C : L’orateur propose explicitement de mettre en place un aménagement provisoire pendant un mois, puis de recueillir les avis de plusieurs groupes, ce qui correspond exactement à cette option. A : Quelqu’un pourrait croire qu’il s’agit de décider immédiatement en réunion, car l’orateur évoque des propositions concrètes, mais il précise qu’il faut d’abord essayer pendant un mois, donc pas de décision définitive immédiate. B : On pourrait croire qu’un vote en ligne serait proposé, car il est question de recueillir des avis, mais l’orateur parle d’un essai suivi de la collecte d’avis, pas d’un vote préalable ni d’application sans essai. D : Quelqu’un pourrait penser que seuls les riverains sont concernés, car les voisins sont mentionnés, mais l’orateur insiste sur la nécessité d’écouter aussi les passants et les commerçants, donc l’option est trop restrictive.","segments":[{"voice":"female","text":"Question 27."},{"voice":"female","text":"Les joueurs de ballon demandent de garder la place ouverte, mais des voisins se plaignent du bruit près des bancs."},{"voice":"male","text":"On ne réglera pas cela en décidant que seuls les enfants ou seuls les adultes ont le droit d'être là."},{"voice":"female","text":"Nous pourrions déplacer les bancs vers le jardin et définir des horaires pour les jeux les plus bruyants."},{"voice":"male","text":"Essayons pendant un mois. Il faudra écouter aussi les personnes qui traversent la place et les commerçants. Le but n'est pas de faire disparaître les différences, mais d'éviter que chaque usage rende les autres impossibles."},{"voice":"female","text":"Comment l’orateur propose-t-il d’ajuster l’organisation de la place ?"}],"audio":"q-27.mp3","audioSeconds":36.937,"slotSeconds":60},{"number":28,"kind":"interview","question":"Selon l’invitée, que risque-t-on en lançant les travaux avant la concertation avec les associations ?","options":["Les futures salles seront trop spécialisées pour évoluer ensuite.","Les associations devront partager les mêmes salles aux mêmes horaires.","Les activités devront se plier à des salles mal adaptées.","Les aménagements choisis empêcheront d’accueillir de nouvelles associations."],"correct":"C","transcript":"Question 28.\nLa rénovation du centre culturel doit commencer dès cet été. Vous avez pourtant demandé un report. Êtes-vous opposée au projet ?\nAu contraire, le bâtiment a besoin de travaux. Mais on a choisi le plan des salles avant de demander aux associations ce qu'elles y feront. Certaines ont besoin de calme, d'autres d'un sol résistant ou de rangement. Si nous construisons d'abord, nous adapterons ensuite les activités aux murs, alors que l'inverse serait préférable. Quelques semaines d'étude maintenant peuvent éviter des modifications coûteuses. Accélérer le début du chantier ne signifie pas toujours gagner du temps sur l'ensemble du projet.\nSelon l’invitée, que risque-t-on en lançant les travaux avant la concertation avec les associations ?","explanation":"Réponse C : L’invitée explique clairement que si on construit d’abord, les activités devront s’adapter à des salles qui risquent d’être mal adaptées à leurs besoins, ce qui correspond exactement à cette option. A : Quelqu’un pourrait croire que des salles trop spécialisées seraient le problème, car il est question de plans décidés sans concertation, mais l’invitée ne parle pas de spécialisation excessive, seulement d’inadaptation générale. B : On pourrait penser que les associations devront partager les mêmes salles ou horaires, car il est question de besoins différents, mais il n’est jamais dit qu’elles devront partager les mêmes espaces en même temps. D : Quelqu’un pourrait croire que les aménagements empêcheront d’accueillir de nouvelles associations, car il est question de modifications futures, mais l’invitée ne parle pas d’empêchement total, seulement de difficultés d’adaptation et de coûts supplémentaires.","segments":[{"voice":"female","text":"Question 28."},{"voice":"male","text":"La rénovation du centre culturel doit commencer dès cet été. Vous avez pourtant demandé un report. Êtes-vous opposée au projet ?"},{"voice":"female","text":"Au contraire, le bâtiment a besoin de travaux. Mais on a choisi le plan des salles avant de demander aux associations ce qu'elles y feront. Certaines ont besoin de calme, d'autres d'un sol résistant ou de rangement. Si nous construisons d'abord, nous adapterons ensuite les activités aux murs, alors que l'inverse serait préférable. Quelques semaines d'étude maintenant peuvent éviter des modifications coûteuses. Accélérer le début du chantier ne signifie pas toujours gagner du temps sur l'ensemble du projet."},{"voice":"female","text":"Selon l’invitée, que risque-t-on en lançant les travaux avant la concertation avec les associations ?"}],"audio":"q-28.mp3","audioSeconds":46.315,"slotSeconds":67},{"number":29,"kind":"announcement","question":"Lors de leur prochain bilan, comment les responsables comptent-ils mieux apprécier le fonctionnement du service ?","options":["En comparant uniquement le nombre d’objets proposés au nombre d’utilisateurs actifs.","En regroupant dans une seule statistique les inscriptions et les demandes abandonnées.","En ne retenant que l’évolution mensuelle du nombre d’inscriptions.","En distinguant les comptes créés, les prêts réalisés et les difficultés rencontrées."],"correct":"D","transcript":"Question 29.\nL'application de prêt d'objets du quartier compte déjà deux mille inscrits. Un chiffre impressionnant, qui ne dit pourtant pas combien de voisins ont effectivement emprunté quelque chose. L'équipe vient donc d'étudier les demandes abandonnées. Certains objets étaient trop loin ; d'autres ne pouvaient être récupérés qu'aux heures de travail. Les responsables vont proposer des points de rencontre et préciser les disponibilités. Leur prochain bilan distinguera les comptes créés, les prêts réalisés et les difficultés rencontrées. La popularité annoncée est un début d'information, pas encore la preuve que le service répond aux besoins quotidiens.\nLors de leur prochain bilan, comment les responsables comptent-ils mieux apprécier le fonctionnement du service ?","explanation":"Réponse D : C’est exactement ce que le texte annonce pour le prochain bilan, afin de mieux apprécier le fonctionnement du service. A : Quelqu’un pourrait penser que comparer le nombre d’objets proposés au nombre d’utilisateurs actifs permettrait de mieux apprécier le fonctionnement, car le texte souligne que le nombre d’inscrits ne suffit pas. Cependant, il n’est jamais question de comparer ces deux chiffres dans le prochain bilan. B : Le texte mentionne l’étude des demandes abandonnées, ce qui pourrait faire croire qu’on va regrouper inscriptions et demandes abandonnées dans une seule statistique. Mais il est précisé que le prochain bilan distinguera ces éléments, et non les regroupera. C : Quelqu’un pourrait croire que ne retenir que l’évolution mensuelle du nombre d’inscriptions suffirait, car le nombre d’inscrits est mentionné comme impressionnant. Mais le texte précise que cela ne suffit pas et qu’il faut distinguer plusieurs éléments.","segments":[{"voice":"female","text":"Question 29."},{"voice":"female","text":"L'application de prêt d'objets du quartier compte déjà deux mille inscrits. Un chiffre impressionnant, qui ne dit pourtant pas combien de voisins ont effectivement emprunté quelque chose. L'équipe vient donc d'étudier les demandes abandonnées. Certains objets étaient trop loin ; d'autres ne pouvaient être récupérés qu'aux heures de travail. Les responsables vont proposer des points de rencontre et préciser les disponibilités. Leur prochain bilan distinguera les comptes créés, les prêts réalisés et les difficultés rencontrées. La popularité annoncée est un début d'information, pas encore la preuve que le service répond aux besoins quotidiens."},{"voice":"female","text":"Lors de leur prochain bilan, comment les responsables comptent-ils mieux apprécier le fonctionnement du service ?"}],"audio":"q-29.mp3","audioSeconds":42.841,"slotSeconds":64},{"number":30,"kind":"interview","question":"Selon la conservatrice, qu’est-ce qui permet de transformer l’usine en bibliothèque sans rompre avec son histoire ?","options":["Le fait d’accroître fortement la fréquentation grâce à un nouvel équipement culturel attractif.","Le fait de garder les volumes et certains éléments de travail tout en rendant ces choix visibles dans le projet.","Le fait de laisser le bâtiment vide, seulement entretenu pour que les visiteurs puissent l’observer.","Le fait de retirer les machines afin que les nouveaux usages et les circulations ne soient pas entravés."],"correct":"B","transcript":"Question 30.\nInstaller une bibliothèque dans une ancienne usine, n'est-ce pas dénaturer le patrimoine ?\nTout dépend des interventions. Nous voulons conserver ce qui permet de comprendre le travail qui s'y faisait : les volumes, certaines machines, les circulations. Mais un bâtiment vide, entretenu uniquement pour être regardé, n'est pas la seule façon de transmettre son histoire. Les nouveaux usages peuvent lui donner une place dans la vie locale. Il faut expliquer les choix, rendre les transformations lisibles et accepter d'en discuter. Préserver ne signifie pas immobiliser chaque détail ; cela demande de savoir ce que l'on veut transmettre et dans quelles conditions les habitants pourront s'en saisir.\nSelon la conservatrice, qu’est-ce qui permet de transformer l’usine en bibliothèque sans rompre avec son histoire ?","explanation":"Réponse B : La conservatrice explique que la transformation respecte l'histoire si l'on garde les volumes et certains éléments de travail, tout en rendant ces choix visibles dans le projet. Elle insiste sur la lisibilité des transformations et la conservation de ce qui permet de comprendre l'activité passée. A : Cette option pourrait sembler plausible car le texte évoque l'importance des nouveaux usages pour intégrer le bâtiment dans la vie locale. Cependant, il n'est jamais question d'accroître fortement la fréquentation ni de mettre l'accent sur l'attractivité culturelle comme moyen de préserver l'histoire. La conservatrice insiste sur la conservation des volumes et des éléments de travail, pas sur la fréquentation. C : Quelqu'un pourrait croire que laisser le bâtiment vide est une façon de préserver l'histoire, car le texte mentionne cette possibilité. Cependant, la conservatrice rejette explicitement cette idée en disant que ce n'est pas la seule façon, et elle privilégie l'intégration de nouveaux usages. D : On pourrait penser que retirer les machines est nécessaire pour faciliter les nouveaux usages, car le texte parle de circulations et d'adaptation. Cependant, la conservatrice précise qu'il faut justement garder certaines machines pour préserver la mémoire du lieu.","segments":[{"voice":"female","text":"Question 30."},{"voice":"male","text":"Installer une bibliothèque dans une ancienne usine, n'est-ce pas dénaturer le patrimoine ?"},{"voice":"female","text":"Tout dépend des interventions. Nous voulons conserver ce qui permet de comprendre le travail qui s'y faisait : les volumes, certaines machines, les circulations. Mais un bâtiment vide, entretenu uniquement pour être regardé, n'est pas la seule façon de transmettre son histoire. Les nouveaux usages peuvent lui donner une place dans la vie locale. Il faut expliquer les choix, rendre les transformations lisibles et accepter d'en discuter. Préserver ne signifie pas immobiliser chaque détail ; cela demande de savoir ce que l'on veut transmettre et dans quelles conditions les habitants pourront s'en saisir."},{"voice":"female","text":"Selon la conservatrice, qu’est-ce qui permet de transformer l’usine en bibliothèque sans rompre avec son histoire ?"}],"audio":"q-30.mp3","audioSeconds":48.98,"slotSeconds":71},{"number":31,"kind":"interview","question":"Selon la sociologue, quelle interprétation erronée risque-t-on si l’on ne tient pas compte de ce que les personnes peuvent réellement faire de leur temps soi-disant « libre » ?","options":["Penser que la faible participation s’explique d’abord par un manque d’information sur les activités.","Penser que la faible participation vient surtout d’une offre d’activités insuffisante.","Penser que la faible participation traduit un manque d’intérêt pour les activités proposées.","Penser que la forte participation prouve automatiquement que les gens ont davantage de temps libre."],"correct":"C","transcript":"Question 31.\nOn affirme souvent que les personnes disposent de davantage de temps libre. Votre étude invite à nuancer cette idée. Pourquoi ?\nParce qu'une heure vide sur un calendrier n'est pas nécessairement une heure dont on peut disposer. Attendre le retour d'un proche, surveiller un enfant qui dort ou rester joignable pour son travail limite les possibilités. On peut lire quelques pages, mais pas forcément rejoindre une activité loin de chez soi. Nous avons donc demandé non seulement combien de temps restait, mais aussi ce que les personnes pouvaient en faire. Sans cette distinction, on risque d'interpréter une faible participation comme un manque d'intérêt alors qu'elle résulte de contraintes très concrètes.\nSelon la sociologue, quelle interprétation erronée risque-t-on si l’on ne tient pas compte de ce que les personnes peuvent réellement faire de leur temps soi-disant « libre » ?","explanation":"Réponse C : La sociologue explique explicitement que si on ne tient pas compte des contraintes réelles, on risque de croire à tort que la faible participation traduit un manque d’intérêt, alors qu’elle est due à des contraintes concrètes. A : Quelqu’un pourrait croire que le manque d’information explique la faible participation, mais la sociologue ne mentionne pas ce facteur. Elle insiste sur la confusion entre temps libre apparent et réel, et sur le risque d’attribuer à tort la faible participation à un manque d’intérêt, pas à un manque d’information. B : Il serait tentant de penser que l’offre d’activités est insuffisante, mais la sociologue ne parle pas de ce facteur. Elle explique que la mauvaise interprétation consiste à croire que les gens ne s’intéressent pas aux activités, alors que des contraintes concrètes limitent leur participation. D : La sociologue ne parle pas de forte participation ni de la relier automatiquement à la quantité de temps libre. Cette option inverse la logique du propos et n’est pas évoquée dans le stimulus.","segments":[{"voice":"female","text":"Question 31."},{"voice":"female","text":"On affirme souvent que les personnes disposent de davantage de temps libre. Votre étude invite à nuancer cette idée. Pourquoi ?"},{"voice":"male","text":"Parce qu'une heure vide sur un calendrier n'est pas nécessairement une heure dont on peut disposer. Attendre le retour d'un proche, surveiller un enfant qui dort ou rester joignable pour son travail limite les possibilités. On peut lire quelques pages, mais pas forcément rejoindre une activité loin de chez soi. Nous avons donc demandé non seulement combien de temps restait, mais aussi ce que les personnes pouvaient en faire. Sans cette distinction, on risque d'interpréter une faible participation comme un manque d'intérêt alors qu'elle résulte de contraintes très concrètes."},{"voice":"female","text":"Selon la sociologue, quelle interprétation erronée risque-t-on si l’on ne tient pas compte de ce que les personnes peuvent réellement faire de leur temps soi-disant « libre » ?"}],"audio":"q-31.mp3","audioSeconds":52.088,"slotSeconds":71},{"number":32,"kind":"interview","question":"Selon le scientifique, qu’est‑ce qu’il faut ajouter à un simple chiffre pour qu’il informe vraiment sur une estimation incertaine ?","options":["Des repères sur les observations, la méthode et ce qui pourrait modifier la conclusion.","Une comparaison avec les opinions d’autres spécialistes pour situer ce chiffre parmi leurs avis.","Une reformulation en termes simples, sans entrer dans les détails techniques de la méthode.","Une marge d’erreur chiffrée plus étroite autour de la valeur annoncée."],"correct":"A","transcript":"Question 32.\nQuand vous dites que votre estimation comporte une incertitude, certains auditeurs comprennent que vous ne savez rien. Comment leur répondez-vous ?\nJe leur donne un exemple. Prévoir une zone de risque ne permet pas de dire quelle maison sera touchée à quelle date. Cela reste pourtant utile pour préparer les secours ou éviter une construction mal située. L'incertitude indique la portée de ce que nous pouvons affirmer. Nous devons expliquer les observations, la méthode et ce qui pourrait modifier la conclusion. Présenter un chiffre sans ces repères donne une apparence de précision, mais pas nécessairement une meilleure information. Reconnaître des limites n'oblige pas à traiter comme équivalentes toutes les affirmations.\nSelon le scientifique, qu’est‑ce qu’il faut ajouter à un simple chiffre pour qu’il informe vraiment sur une estimation incertaine ?","explanation":"Réponse A : Le scientifique explique qu'il faut accompagner un chiffre d'explications sur les observations, la méthode et les facteurs pouvant modifier la conclusion, pour que l'information soit vraiment utile et compréhensible. B : Quelqu'un pourrait croire que comparer avec d'autres spécialistes est utile pour situer le chiffre, mais le texte ne parle pas de comparaison avec des avis extérieurs, seulement d'expliquer le contexte et la méthode. C : On pourrait penser qu'une reformulation simple suffit, mais le scientifique insiste sur la nécessité de donner des repères précis, pas juste de simplifier le discours. D : Quelqu'un pourrait croire qu'une marge d'erreur plus étroite rend le chiffre plus informatif, mais le scientifique explique que ce sont les repères contextuels qui sont essentiels, pas seulement la précision apparente.","segments":[{"voice":"female","text":"Question 32."},{"voice":"male","text":"Quand vous dites que votre estimation comporte une incertitude, certains auditeurs comprennent que vous ne savez rien. Comment leur répondez-vous ?"},{"voice":"female","text":"Je leur donne un exemple. Prévoir une zone de risque ne permet pas de dire quelle maison sera touchée à quelle date. Cela reste pourtant utile pour préparer les secours ou éviter une construction mal située. L'incertitude indique la portée de ce que nous pouvons affirmer. Nous devons expliquer les observations, la méthode et ce qui pourrait modifier la conclusion. Présenter un chiffre sans ces repères donne une apparence de précision, mais pas nécessairement une meilleure information. Reconnaître des limites n'oblige pas à traiter comme équivalentes toutes les affirmations."},{"voice":"female","text":"Selon le scientifique, qu’est‑ce qu’il faut ajouter à un simple chiffre pour qu’il informe vraiment sur une estimation incertaine ?"}],"audio":"q-32.mp3","audioSeconds":48.588,"slotSeconds":70},{"number":33,"kind":"announcement","question":"Sur quel point précis le chroniqueur estime-t-il que le nombre de nuitées devient trompeur lorsqu’il est utilisé comme unique indicateur ?","options":["Il ne renseigne ni sur les conditions d’emploi ni sur la capacité des travailleurs à se loger durablement dans la station.","Il masque l’augmentation des fermetures de commerces en fin de saison en les compensant par les bons résultats de l’été.","Il ignore la situation des résidents permanents en se limitant aux comportements des touristes de passage.","Il sous-estime l’impact environnemental de la station en ne tenant pas compte de la hausse de la consommation d’eau."],"correct":"A","transcript":"Question 33.\nLa station annonce une saison exceptionnelle : les nuitées ont augmenté de douze pour cent. Ce résultat mérite d'être connu, mais il ne raconte pas toute l'année vécue sur place. Des restaurants ont manqué de personnel parce que les salariés ne trouvaient pas à se loger. La consommation d'eau a progressé pendant une période sèche, tandis que certains commerces ont fermé dès septembre. Le nombre de nuitées reste utile pour suivre la fréquentation. Il devient trompeur si on lui fait résumer à lui seul la qualité du développement local. Un bilan plus complet regarderait aussi les conditions d'emploi, les ressources mobilisées et la possibilité, pour ceux qui travaillent dans la station, d'y vivre durablement.\nSur quel point précis le chroniqueur estime-t-il que le nombre de nuitées devient trompeur lorsqu’il est utilisé comme unique indicateur ?","explanation":"Réponse A : Le chroniqueur souligne que le nombre de nuitées ne suffit pas à rendre compte de la réalité locale, notamment parce qu'il ne dit rien sur les conditions d'emploi ni sur la capacité des travailleurs à se loger durablement. C'est précisément ce point qui est jugé trompeur si l'on se limite à cet indicateur. B : La fermeture des commerces est mentionnée, mais il n'est pas dit que le nombre de nuitées masque cette réalité en la compensant par les résultats de l'été. Quelqu'un pourrait croire que la hausse des nuitées cache les fermetures, mais le texte ne fait pas ce lien direct. C : Le texte parle de la qualité du développement local et de la vie des travailleurs, mais ne dit pas que l'indicateur ignore spécifiquement la situation des résidents permanents au profit des touristes. La confusion vient du fait que les travailleurs sont évoqués, mais pas les résidents permanents en général. D : L'impact environnemental est mentionné (hausse de la consommation d'eau), mais il n'est pas dit que le nombre de nuitées sous-estime cet impact. Quelqu'un pourrait croire que l'indicateur occulte l'environnement, mais ce n'est pas le point jugé trompeur par le chroniqueur.","segments":[{"voice":"female","text":"Question 33."},{"voice":"male","text":"La station annonce une saison exceptionnelle : les nuitées ont augmenté de douze pour cent. Ce résultat mérite d'être connu, mais il ne raconte pas toute l'année vécue sur place. Des restaurants ont manqué de personnel parce que les salariés ne trouvaient pas à se loger. La consommation d'eau a progressé pendant une période sèche, tandis que certains commerces ont fermé dès septembre. Le nombre de nuitées reste utile pour suivre la fréquentation. Il devient trompeur si on lui fait résumer à lui seul la qualité du développement local. Un bilan plus complet regarderait aussi les conditions d'emploi, les ressources mobilisées et la possibilité, pour ceux qui travaillent dans la station, d'y vivre durablement."},{"voice":"female","text":"Sur quel point précis le chroniqueur estime-t-il que le nombre de nuitées devient trompeur lorsqu’il est utilisé comme unique indicateur ?"}],"audio":"q-33.mp3","audioSeconds":52.689,"slotSeconds":73},{"number":34,"kind":"dialogue","question":"Sur quel point les deux intervenants se rejoignent-ils ?","options":["Il faut combiner un accueil accompagné avec des ajustements du formulaire en ligne.","Il faut d’abord multiplier les ateliers de formation, les autres changements pouvant attendre.","Il suffit de rendre le site plus intuitif pour envisager de fermer la permanence physique.","Les usagers doivent surtout s’habituer aux outils existants sans qu’on retouche l’interface."],"correct":"A","transcript":"Question 34.\nNous avons mis toutes les démarches en ligne, mais les files d'attente à l'accueil n'ont presque pas diminué.\nCela ne m'étonne pas. Une personne peut avoir un téléphone sans savoir joindre un document ou comprendre pourquoi son dossier est bloqué.\nIl faudrait donc multiplier les formations ?\nOui, pour certains besoins. Mais il faut aussi simplifier les écrans et garder un contact humain. Sinon, nous demandons aux usagers d'apprendre à contourner une difficulté que le service pourrait supprimer.\nEssayons les deux : une permanence accompagnée et des tests du formulaire avec des personnes qui le découvrent. Nous verrons où elles hésitent réellement.\nSur quel point les deux intervenants se rejoignent-ils ?","explanation":"Réponse A : Les deux intervenants s'accordent sur la nécessité de combiner un accueil accompagné (permanence) avec des ajustements du formulaire en ligne (tests du formulaire pour simplifier les écrans). C'est la synthèse de leurs propositions. B : Quelqu'un pourrait croire que la multiplication des ateliers de formation est la priorité, car cela est évoqué, mais l'autre intervenant précise qu'il ne faut pas s'arrêter là et qu'il faut aussi simplifier les écrans et garder le contact humain. Donc, ce n'est pas un point de convergence. C : On pourrait penser que rendre le site plus intuitif suffirait, car la simplification des écrans est mentionnée. Cependant, il est clairement dit qu'il faut aussi garder un contact humain, donc la fermeture de la permanence physique n'est pas envisagée. D : On pourrait croire que les usagers doivent s'habituer aux outils existants, mais il est explicitement dit que ce n'est pas souhaitable : il vaut mieux supprimer les difficultés que demander aux usagers de s'adapter.","segments":[{"voice":"female","text":"Question 34."},{"voice":"female","text":"Nous avons mis toutes les démarches en ligne, mais les files d'attente à l'accueil n'ont presque pas diminué."},{"voice":"male","text":"Cela ne m'étonne pas. Une personne peut avoir un téléphone sans savoir joindre un document ou comprendre pourquoi son dossier est bloqué."},{"voice":"female","text":"Il faudrait donc multiplier les formations ?"},{"voice":"male","text":"Oui, pour certains besoins. Mais il faut aussi simplifier les écrans et garder un contact humain. Sinon, nous demandons aux usagers d'apprendre à contourner une difficulté que le service pourrait supprimer."},{"voice":"female","text":"Essayons les deux : une permanence accompagnée et des tests du formulaire avec des personnes qui le découvrent. Nous verrons où elles hésitent réellement."},{"voice":"female","text":"Sur quel point les deux intervenants se rejoignent-ils ?"}],"audio":"q-34.mp3","audioSeconds":47.02,"slotSeconds":70},{"number":35,"kind":"interview","question":"Quel facteur l’architecte met-il au premier plan pour expliquer l’écart entre prévisions et consommations ?","options":["Le manque de suivi d’entretien après la mise en service des appareils.","La tendance des occupants à contourner les commandes complexes en ouvrant les fenêtres.","Les conflits entre les réglages des différents systèmes installés dans le bâtiment.","Le décalage entre les performances indiquées sur les équipements et le service réellement rendu, dépendant des usages observés."],"correct":"D","transcript":"Question 35.\nVotre bâtiment a reçu plusieurs équipements très performants. Pourtant, les consommations dépassent les prévisions. Comment l'expliquez-vous ?\nOn a évalué chaque élément séparément, avec des hypothèses d'utilisation qui ne correspondaient pas toujours à la vie du lieu. Certains réglages se contredisaient. Les occupants, de leur côté, évitaient une commande trop complexe et ouvraient les fenêtres quand ils avaient trop chaud. Ce n'est pas une raison pour leur reprocher de ne pas vivre comme dans une simulation. Il faut regarder l'ensemble : conception, installation, entretien et gestes quotidiens. Une fiche technique peut nous renseigner sur un appareil ; elle ne décrit pas automatiquement le service réellement obtenu. Nous avons donc commencé par observer les usages avant d'ajouter du matériel.\nQuel facteur l’architecte met-il au premier plan pour expliquer l’écart entre prévisions et consommations ?","explanation":"Réponse D : L'architecte insiste sur le fait que les performances indiquées sur les équipements ne correspondent pas toujours au service réellement rendu, car cela dépend des usages observés. Il explique que l'écart vient du décalage entre la théorie (prévisions, fiches techniques) et la réalité des usages. A : L'entretien est mentionné comme un élément à considérer, mais l'architecte ne le met pas au premier plan. Il insiste surtout sur l'écart entre les performances théoriques et l'usage réel. Quelqu'un pourrait croire que l'entretien est la cause principale car il est cité dans la liste des facteurs à surveiller. B : L'architecte mentionne ce comportement, mais il précise que ce n'est pas la raison principale et qu'il ne faut pas le reprocher aux occupants. Ce point illustre un symptôme, pas la cause fondamentale selon l'architecte. Quelqu'un pourrait mal comprendre et penser que c'est la cause principale car ce comportement est décrit en détail. C : L'architecte évoque des conflits de réglages, mais il ne les place pas au premier plan. Il insiste sur l'écart entre les performances annoncées et l'usage réel. Un candidat pourrait croire que c'est la cause principale car ce problème technique est cité explicitement.","segments":[{"voice":"female","text":"Question 35."},{"voice":"female","text":"Votre bâtiment a reçu plusieurs équipements très performants. Pourtant, les consommations dépassent les prévisions. Comment l'expliquez-vous ?"},{"voice":"male","text":"On a évalué chaque élément séparément, avec des hypothèses d'utilisation qui ne correspondaient pas toujours à la vie du lieu. Certains réglages se contredisaient. Les occupants, de leur côté, évitaient une commande trop complexe et ouvraient les fenêtres quand ils avaient trop chaud. Ce n'est pas une raison pour leur reprocher de ne pas vivre comme dans une simulation. Il faut regarder l'ensemble : conception, installation, entretien et gestes quotidiens. Une fiche technique peut nous renseigner sur un appareil ; elle ne décrit pas automatiquement le service réellement obtenu. Nous avons donc commencé par observer les usages avant d'ajouter du matériel."},{"voice":"female","text":"Quel facteur l’architecte met-il au premier plan pour expliquer l’écart entre prévisions et consommations ?"}],"audio":"q-35.mp3","audioSeconds":54.1,"slotSeconds":75},{"number":36,"kind":"interview","question":"D’après l’invitée, qu’est-ce qui fait réellement la différence entre de simples occasions de rencontre et un véritable rapprochement entre générations dans la résidence ?","options":["La répartition des rôles où les jeunes enseignent l’informatique et les personnes âgées transmettent des souvenirs du passé.","Le fait que tout le monde participe à un nombre minimal d’activités collectives fixé par la résidence.","La possibilité pour chacun de refuser une invitation et de proposer une activité qui lui convient, ce qui favorise peu à peu la confiance.","La proximité quotidienne qui pousse les habitants à se voir et à partager spontanément davantage de moments ensemble."],"correct":"C","transcript":"Question 36.\nVotre résidence rassemble des étudiants et des retraités. Peut-on considérer que la proximité règle à elle seule le problème de l'isolement ?\nNon. Elle crée des occasions de rencontre, ce qui est précieux, mais elle ne fabrique pas automatiquement une relation. Au début, nous avions prévu beaucoup d'activités collectives. Certains habitants se sentaient obligés de venir pour ne pas paraître indifférents. Nous avons revu le programme. Chacun peut refuser une invitation et proposer une activité qui l'intéresse. Nous évitons aussi de supposer que les jeunes apprendront forcément l'informatique aux plus âgés, qui leur raconteront ensuite le passé. Les envies circulent autrement. Une personne de quatre-vingts ans peut vouloir parler de cinéma contemporain et un étudiant découvrir le jardinage. Ce qui compte, c'est la possibilité de choisir et la confiance qui se construit, pas le nombre de rencontres inscrit dans notre bilan.\nD’après l’invitée, qu’est-ce qui fait réellement la différence entre de simples occasions de rencontre et un véritable rapprochement entre générations dans la résidence ?","explanation":"Réponse C : L’invitée insiste sur l’importance de pouvoir refuser une invitation et de proposer une activité qui convient à chacun, ce qui favorise la confiance et un véritable rapprochement. C’est la seule option qui correspond exactement à ce qui est dit dans l’enregistrement. A : Quelqu’un pourrait croire que la répartition classique des rôles (jeunes = informatique, âgés = souvenirs) est valorisée, car elle est évoquée dans l’enregistrement. Cependant, l’invitée précise explicitement qu’ils évitent ce schéma, ce qui contredit cette option. B : On pourrait croire que le nombre minimal d’activités collectives est important, car il est mentionné que beaucoup d’activités étaient prévues au début. Mais l’invitée explique qu’ils ont changé ce système, car il poussait les gens à participer par obligation et non par envie, ce qui est précisément ce qu’ils veulent éviter. D : On pourrait croire que la proximité quotidienne suffit, car elle est mentionnée comme créant des occasions de rencontre. Mais l’invitée précise que cela ne suffit pas à créer une vraie relation, ce qui contredit cette option.","segments":[{"voice":"female","text":"Question 36."},{"voice":"male","text":"Votre résidence rassemble des étudiants et des retraités. Peut-on considérer que la proximité règle à elle seule le problème de l'isolement ?"},{"voice":"female","text":"Non. Elle crée des occasions de rencontre, ce qui est précieux, mais elle ne fabrique pas automatiquement une relation. Au début, nous avions prévu beaucoup d'activités collectives. Certains habitants se sentaient obligés de venir pour ne pas paraître indifférents. Nous avons revu le programme. Chacun peut refuser une invitation et proposer une activité qui l'intéresse. Nous évitons aussi de supposer que les jeunes apprendront forcément l'informatique aux plus âgés, qui leur raconteront ensuite le passé. Les envies circulent autrement. Une personne de quatre-vingts ans peut vouloir parler de cinéma contemporain et un étudiant découvrir le jardinage. Ce qui compte, c'est la possibilité de choisir et la confiance qui se construit, pas le nombre de rencontres inscrit dans notre bilan."},{"voice":"female","text":"D’après l’invitée, qu’est-ce qui fait réellement la différence entre de simples occasions de rencontre et un véritable rapprochement entre générations dans la résidence ?"}],"audio":"q-36.mp3","audioSeconds":64.836,"slotSeconds":86},{"number":37,"kind":"interview","question":"Selon l’historienne, comment traite-t-elle des récits contradictoires sur la fermeture d’une usine ?","options":["Elle conserve le contexte de chaque entretien et confronte ces récits aux archives disponibles.","Elle retient uniquement le témoignage dont les détails paraissent les plus précis et écarte les autres.","Elle fusionne les différentes versions pour produire un récit plus cohérent et rassurant.","Elle s’en remet d’abord aux archives écrites pour désigner immédiatement le témoin qui se trompe."],"correct":"A","transcript":"Question 37.\nQuand deux témoins racontent différemment la fermeture d'une usine, comment décidez-vous lequel dit vrai ?\nNous vérifions les faits qui peuvent l'être : les dates, les décisions, les effectifs. Mais toutes les différences ne se ramènent pas à une erreur. Un cadre, une ouvrière et un commerçant voisin n'ont pas vécu la même journée, même s'ils parlent du même événement. Leurs récits montrent ce qu'ils pouvaient voir, ce qu'ils redoutaient et ce qu'ils ont retenu. Nous gardons donc les circonstances de chaque entretien et comparons les témoignages avec les archives. Il ne s'agit pas de déclarer que tout se vaut, ni d'effacer les contradictions pour produire un récit plus confortable. Les écarts peuvent devenir une source d'information, à condition d'être examinés plutôt que simplement juxtaposés ou utilisés pour accuser d'emblée l'un des témoins de mentir.\nSelon l’historienne, comment traite-t-elle des récits contradictoires sur la fermeture d’une usine ?","explanation":"Réponse A : L’historienne explique qu’elle conserve le contexte de chaque entretien et confronte les récits aux archives, ce qui correspond exactement à la première proposition. B : Quelqu’un pourrait croire qu’elle retient uniquement le témoignage le plus précis, car elle parle de vérifier les faits, mais elle précise qu’elle ne cherche pas à éliminer les autres récits. Elle insiste sur l’importance de garder les différences et de les examiner. C : La tentation de fusionner les versions pour un récit cohérent est explicitement rejetée par l’historienne, qui affirme qu’il ne s’agit pas d’effacer les contradictions. D : Certains pourraient penser qu’elle s’en remet d’abord aux archives pour désigner qui se trompe, car elle parle de vérification, mais elle précise qu’il ne s’agit pas d’accuser immédiatement un témoin de mentir.","segments":[{"voice":"female","text":"Question 37."},{"voice":"female","text":"Quand deux témoins racontent différemment la fermeture d'une usine, comment décidez-vous lequel dit vrai ?"},{"voice":"male","text":"Nous vérifions les faits qui peuvent l'être : les dates, les décisions, les effectifs. Mais toutes les différences ne se ramènent pas à une erreur. Un cadre, une ouvrière et un commerçant voisin n'ont pas vécu la même journée, même s'ils parlent du même événement. Leurs récits montrent ce qu'ils pouvaient voir, ce qu'ils redoutaient et ce qu'ils ont retenu. Nous gardons donc les circonstances de chaque entretien et comparons les témoignages avec les archives. Il ne s'agit pas de déclarer que tout se vaut, ni d'effacer les contradictions pour produire un récit plus confortable. Les écarts peuvent devenir une source d'information, à condition d'être examinés plutôt que simplement juxtaposés ou utilisés pour accuser d'emblée l'un des témoins de mentir."},{"voice":"female","text":"Selon l’historienne, comment traite-t-elle des récits contradictoires sur la fermeture d’une usine ?"}],"audio":"q-37.mp3","audioSeconds":56.738,"slotSeconds":80},{"number":38,"kind":"announcement","question":"Quelle limite principale les responsables reconnaissent-ils à l’idée de diffuser d’autres images du lieu ?","options":["Elle permettrait d’éviter de consulter les habitants sur l’accueil des touristes.","Elle provoquerait une chute durable du nombre total de visiteurs.","Elle risquerait surtout de déplacer la fréquentation vers des zones encore fragiles.","Elle garantirait une meilleure répartition des visites sur toute l’année."],"correct":"C","transcript":"Question 38.\nSur les affiches, une seule silhouette regarde un lac au milieu des montagnes. Sur place, certains jours, une file se forme pour reproduire exactement cette photographie. La destination attire par une promesse de solitude que son succès contribue à défaire. Les responsables pourraient diffuser d'autres points de vue, mais cela risquerait seulement de déplacer la pression vers des espaces encore fragiles. Ils discutent donc avec les habitants et les gestionnaires : quelles visites souhaite-t-on favoriser, à quelles périodes, avec quels accès et quelles limites ? Il ne suffit pas d'annoncer un nombre de visiteurs plus élevé comme une réussite évidente. La question est aussi de savoir si les conditions qui rendent le lieu désirable peuvent être maintenues. Une communication plus honnête devra montrer un territoire habité et fréquenté, sans réduire son avenir à l'image qui attire le plus de clics.\nQuelle limite principale les responsables reconnaissent-ils à l’idée de diffuser d’autres images du lieu ?","explanation":"Réponse C : C'est exactement la limite principale reconnue par les responsables : diffuser d'autres images risquerait de déplacer la fréquentation vers des zones encore fragiles. A : Quelqu'un pourrait croire que diffuser d'autres images éviterait de consulter les habitants, car le texte mentionne des discussions avec eux. Cependant, la diffusion d'autres images n'est pas présentée comme un moyen d'éviter la concertation, mais comme un risque de déplacer la pression touristique. B : On pourrait penser qu'une chute du nombre de visiteurs serait une conséquence, mais le texte ne parle pas d'une baisse durable du nombre total de visiteurs, seulement d'un déplacement de la fréquentation. D : Quelqu'un pourrait croire qu'une meilleure répartition des visites serait garantie par la diffusion d'autres images, car le texte évoque la nécessité d'une communication plus honnête. Cependant, il n'est pas dit que cela garantirait une meilleure répartition, mais plutôt que cela risquerait de déplacer la pression.","segments":[{"voice":"female","text":"Question 38."},{"voice":"female","text":"Sur les affiches, une seule silhouette regarde un lac au milieu des montagnes. Sur place, certains jours, une file se forme pour reproduire exactement cette photographie. La destination attire par une promesse de solitude que son succès contribue à défaire. Les responsables pourraient diffuser d'autres points de vue, mais cela risquerait seulement de déplacer la pression vers des espaces encore fragiles. Ils discutent donc avec les habitants et les gestionnaires : quelles visites souhaite-t-on favoriser, à quelles périodes, avec quels accès et quelles limites ? Il ne suffit pas d'annoncer un nombre de visiteurs plus élevé comme une réussite évidente. La question est aussi de savoir si les conditions qui rendent le lieu désirable peuvent être maintenues. Une communication plus honnête devra montrer un territoire habité et fréquenté, sans réduire son avenir à l'image qui attire le plus de clics."},{"voice":"female","text":"Quelle limite principale les responsables reconnaissent-ils à l’idée de diffuser d’autres images du lieu ?"}],"audio":"q-38.mp3","audioSeconds":57.156,"slotSeconds":80},{"number":39,"kind":"interview","question":"Comment l’intervenant caractérise-t-il le rôle du succès de la phase d’essai dans la décision de pérenniser le café associatif ?","options":["Comme un argument en faveur d’un financement ponctuel supplémentaire, sans remettre en cause le fonctionnement quotidien du lieu.","Comme une indication forte de la demande, qui oblige néanmoins à chiffrer les moyens et à adapter l’organisation.","Comme un résultat surtout lié à l’effort exceptionnel des bénévoles, qu’il faudrait reproduire tel quel à plus long terme.","Comme la preuve qu’il faut reconduire à l’identique le dispositif testé."],"correct":"B","transcript":"Question 39.\nLe café associatif a fait le plein pendant ses trois mois d'essai. Pourquoi ne pas le maintenir exactement sous cette forme ?\nParce que l'essai reposait sur des conditions particulières. Le local était prêté et plusieurs bénévoles avaient accepté un effort exceptionnel. Leur enthousiasme montre que le lieu répond à une envie, mais il ne crée pas à lui seul un budget ni du temps disponible chaque semaine. Il faut maintenant préciser les coûts, partager les responsabilités et envisager plusieurs soutiens. Cela peut conduire à réduire certains horaires ou à rémunérer une partie de l'accueil. Ce n'est pas trahir l'expérience : c'est chercher les conditions de sa durée. Nous devons écouter les visiteurs et ceux qui font fonctionner le service. Le succès d'un projet temporaire constitue une information précieuse ; il ne dispense pas de transformer son organisation lorsqu'on souhaite en faire une institution quotidienne.\nComment l’intervenant caractérise-t-il le rôle du succès de la phase d’essai dans la décision de pérenniser le café associatif ?","explanation":"Réponse B : L’intervenant explique que le succès de la phase d’essai montre une forte demande, mais qu’il faut désormais chiffrer les moyens et adapter l’organisation pour assurer la pérennité du café. Il ne suffit pas de reconduire à l’identique : il faut transformer l’organisation. A : Quelqu’un pourrait croire que le succès justifie simplement un financement ponctuel, car le texte mentionne la nécessité de trouver des soutiens. Cependant, l’intervenant insiste sur la transformation de l’organisation, pas seulement sur un financement ponctuel, et il évoque la nécessité d’adapter le fonctionnement quotidien. C : On pourrait penser que le succès est surtout dû à l’effort des bénévoles, car le texte mentionne leur engagement exceptionnel. Cependant, l’intervenant précise qu’il ne s’agit pas de reproduire tel quel cet effort à long terme, mais de transformer l’organisation pour la pérennité. D : Quelqu’un pourrait croire que le succès prouve qu’il faut reconduire à l’identique, mais l’intervenant explique précisément que ce n’est pas possible à cause des conditions particulières de l’essai (local prêté, bénévoles très engagés). Il insiste sur la nécessité d’adapter l’organisation.","segments":[{"voice":"female","text":"Question 39."},{"voice":"female","text":"Le café associatif a fait le plein pendant ses trois mois d'essai. Pourquoi ne pas le maintenir exactement sous cette forme ?"},{"voice":"male","text":"Parce que l'essai reposait sur des conditions particulières. Le local était prêté et plusieurs bénévoles avaient accepté un effort exceptionnel. Leur enthousiasme montre que le lieu répond à une envie, mais il ne crée pas à lui seul un budget ni du temps disponible chaque semaine. Il faut maintenant préciser les coûts, partager les responsabilités et envisager plusieurs soutiens. Cela peut conduire à réduire certains horaires ou à rémunérer une partie de l'accueil. Ce n'est pas trahir l'expérience : c'est chercher les conditions de sa durée. Nous devons écouter les visiteurs et ceux qui font fonctionner le service. Le succès d'un projet temporaire constitue une information précieuse ; il ne dispense pas de transformer son organisation lorsqu'on souhaite en faire une institution quotidienne."},{"voice":"female","text":"Comment l’intervenant caractérise-t-il le rôle du succès de la phase d’essai dans la décision de pérenniser le café associatif ?"}],"audio":"q-39.mp3","audioSeconds":63.687,"slotSeconds":86}]},{"id":"tcf-listening-02","version":"tcf-listening-2026-11-test02-v4","title":"TCF Listening · Test 02","seconds":2100,"questions":[{"number":1,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"Réponse D : On voit clairement une personne qui marche à côté de son vélo devant un bâtiment identifié comme une gare. A : On ne voit pas la personne attendre sur un quai ni le vélo posé derrière elle. La scène se passe devant la gare, pas sur un quai. B : Il n'y a aucun élément visuel indiquant un parking souterrain, ni que la personne gare son vélo. La scène est à l'extérieur devant la gare. C : La personne n'est pas en train de traverser la place sans vélo : elle est à côté de son vélo, ce qui contredit cette proposition.","transcript":"Question 1.\nÉcoutez les quatre propositions. A. Elle attend son train sur le quai, son vélo posé derrière elle. B. Elle gare son vélo dans un parking souterrain de la gare. C. Elle traverse la place de la gare sans vélo. D. Elle marche à côté de son vélo devant la gare.","segments":[{"voice":"female","text":"Question 1."},{"voice":"female","text":"Écoutez les quatre propositions. A. Elle attend son train sur le quai, son vélo posé derrière elle. B. Elle gare son vélo dans un parking souterrain de la gare. C. Elle traverse la place de la gare sans vélo. D. Elle marche à côté de son vélo devant la gare."}],"image":"q-01.svg","audio":"q-01.mp3","audioSeconds":19.592,"slotSeconds":35},{"number":2,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"Réponse D : La personne est assise à un bureau et utilise un ordinateur portable, ce qui correspond exactement à la description. A : On ne voit pas de vitrine ni de téléphone visible dans l’image. Quelqu’un pourrait confondre l’écran devant la personne avec une vitrine, mais il n’y a aucun geste de discussion téléphonique. B : La personne est assise à un bureau et non en train de marcher. Il y a un appareil devant elle, mais il ressemble à un ordinateur portable, pas à une tablette. C : Il y a une étagère dans l’image, mais la personne n’est pas en train de ranger des dossiers ; elle est assise à un bureau.","transcript":"Question 2.\nA. Il discute au téléphone derrière une vitrine. B. Il tape un message sur une tablette en marchant. C. Il range des dossiers sur une étagère. D. Il travaille sur un ordinateur portable.","segments":[{"voice":"female","text":"Question 2."},{"voice":"male","text":"A. Il discute au téléphone derrière une vitrine. B. Il tape un message sur une tablette en marchant. C. Il range des dossiers sur une étagère. D. Il travaille sur un ordinateur portable."}],"image":"q-02.svg","audio":"q-02.mp3","audioSeconds":17.345,"slotSeconds":31},{"number":3,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"Réponse B : L'image montre clairement deux personnes assises devant le musée, ce qui correspond exactement à la description. A : On voit deux personnes devant le musée, mais elles sont assises et non en train de se promener. C : Les deux personnes sont devant le musée, mais elles ne sont pas debout en file d'attente, elles sont assises. D : Les deux personnes sont devant le musée, mais elles ne descendent pas les marches, elles sont assises.","transcript":"Question 3.\nA. Deux personnes se promènent sur la place près du musée. B. Deux personnes sont assises devant le musée. C. Deux personnes font la queue pour entrer au musée. D. Deux personnes quittent le musée en descendant les marches.","segments":[{"voice":"female","text":"Question 3."},{"voice":"female","text":"A. Deux personnes se promènent sur la place près du musée. B. Deux personnes sont assises devant le musée. C. Deux personnes font la queue pour entrer au musée. D. Deux personnes quittent le musée en descendant les marches."}],"image":"q-03.svg","audio":"q-03.mp3","audioSeconds":15.726,"slotSeconds":32},{"number":4,"kind":"image","question":"Quelle proposition correspond à l'image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"Réponse D : La personne regarde un plan affiché à l’arrêt de bus, ce qui correspond à l’examen du plan du quartier. A : On voit que la personne regarde un plan, donc elle ne fait pas simplement la queue sans prêter attention au plan. B : La personne regarde un plan schématique, pas une feuille d’horaires ; il n’y a aucun indice visuel d’horaires. C : La personne ne montre rien au conducteur, elle regarde un plan devant l’arrêt, et le bus est à l’arrêt sans interaction visible.","transcript":"Question 4.\nA. Elle attend le bus sans prêter attention au plan. B. Elle lit les horaires de la ligne de bus. C. Elle montre au conducteur l’itinéraire qu’elle veut suivre. D. Elle examine le plan du quartier à l’arrêt de bus.","segments":[{"voice":"female","text":"Question 4."},{"voice":"female","text":"A. Elle attend le bus sans prêter attention au plan. B. Elle lit les horaires de la ligne de bus. C. Elle montre au conducteur l’itinéraire qu’elle veut suivre. D. Elle examine le plan du quartier à l’arrêt de bus."}],"image":"q-04.svg","audio":"q-04.mp3","audioSeconds":15.856,"slotSeconds":32},{"number":5,"kind":"response","question":"Quelle réponse convient à la situation ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"Réponse C : C'est la seule réponse qui répond directement et positivement à la demande de prêter un stylo ('Oui, bien sûr, tenez mon stylo.'). A : Cette réponse ('Désolé, je viens de le perdre.') pourrait être choisie si l'on comprend que la personne n'a plus de stylo à prêter, mais elle ne répond pas positivement à la demande et n'est pas la réponse attendue pour prêter un stylo. B : Répondre 'Oui, j'en cherche un aussi.' montre que la personne n'a pas de stylo non plus. Quelqu'un pourrait choisir cette option s'il comprend que les deux personnes sont dans la même situation, mais cela ne répond pas à la demande de prêter un stylo. D : Répondre 'Non, j'écris toujours au crayon.' pourrait être choisi si l'on comprend que la personne n'utilise pas de stylo, mais cela ne répond pas à la demande de prêter un stylo et indique simplement une préférence personnelle.","transcript":"Question 5.\nExcusez-moi, vous auriez un stylo à me prêter ?\nA. Désolé, je viens de le perdre. B. Oui, j'en cherche un aussi. C. Oui, bien sûr, tenez mon stylo. D. Non, j'écris toujours au crayon.","segments":[{"voice":"female","text":"Question 5."},{"voice":"male","text":"Excusez-moi, vous auriez un stylo à me prêter ?"},{"voice":"female","text":"A. Désolé, je viens de le perdre. B. Oui, j'en cherche un aussi. C. Oui, bien sûr, tenez mon stylo. D. Non, j'écris toujours au crayon."}],"audio":"q-05.mp3","audioSeconds":18.338,"slotSeconds":32},{"number":6,"kind":"response","question":"Quelle réponse convient à la situation ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"Réponse D : C’est la seule réponse qui accepte explicitement la demande de passer ce soir, en précisant même une heure adaptée (après 19h). Elle répond directement et positivement à la question posée. A : Cette réponse refuse la demande de passer ce soir, car la personne part à 19h. Quelqu’un pourrait croire que c’est une réponse adaptée s’il pense que la disponibilité avant 19h est possible, mais la formulation indique clairement un refus pour ce soir. B : Cette réponse propose un autre moment (demain en fin d’après-midi) et ne répond pas positivement à la demande de passer ce soir. Quelqu’un pourrait la choisir s’il pense que la question porte sur la meilleure option, mais ce n’est pas une acceptation pour ce soir. C : Cette réponse accepte, mais impose une condition incompatible avec la demande de passer le soir (avant 17h n’est pas le soir). Quelqu’un pourrait la choisir s’il ne fait pas attention à la contrainte horaire, mais elle contredit la demande explicite de passer le soir.","transcript":"Question 6.\nJe peux passer récupérer mon livre ce soir ?\nA. Non, ce soir je pars vers dix-neuf heures. B. Ce sera mieux demain en fin d’après-midi. C. Oui, mais il faut venir avant dix-sept heures. D. Oui, passe plutôt après dix-neuf heures.","segments":[{"voice":"female","text":"Question 6."},{"voice":"female","text":"Je peux passer récupérer mon livre ce soir ?"},{"voice":"male","text":"A. Non, ce soir je pars vers dix-neuf heures. B. Ce sera mieux demain en fin d’après-midi. C. Oui, mais il faut venir avant dix-sept heures. D. Oui, passe plutôt après dix-neuf heures."}],"audio":"q-06.mp3","audioSeconds":20.689,"slotSeconds":35},{"number":7,"kind":"response","question":"Quelle réponse convient à la situation ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"Réponse C : C’est la seule réponse qui répond directement à l’invitation de venir au marché de Noël, en acceptant (« Oui, bien sûr, je viens. »). A : Cette réponse parle de nourriture et de fromage, ce qui n’a aucun lien avec l’invitation à venir au marché de Noël. Quelqu’un pourrait mal comprendre et penser qu’on parle de ce qu’on mange au marché, mais la question porte sur la participation. B : Répondre qu’on a vu quelque chose à la télévision pourrait venir d’une confusion : la personne croit qu’on lui demande si elle connaît le marché de Noël, mais la question porte sur le fait de venir, pas sur la connaissance. D : Dire où se trouve quelque chose (« Il se trouve juste derrière l’église. ») pourrait venir d’une confusion : la personne croit qu’on demande l’emplacement du marché, alors qu’on propose de venir.","transcript":"Question 7.\nOn va visiter le marché de Noël samedi. Tu viens avec nous ?\nA. Ça se mange avec du fromage. B. Je l’ai vu à la télévision. C. Oui, bien sûr, je viens. D. Il se trouve juste derrière l’église.","segments":[{"voice":"female","text":"Question 7."},{"voice":"female","text":"On va visiter le marché de Noël samedi. Tu viens avec nous ?"},{"voice":"male","text":"A. Ça se mange avec du fromage. B. Je l’ai vu à la télévision. C. Oui, bien sûr, je viens. D. Il se trouve juste derrière l’église."}],"audio":"q-07.mp3","audioSeconds":17.789,"slotSeconds":36},{"number":8,"kind":"response","question":"Quelle réponse convient à la situation ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"Réponse B : C’est la seule réponse qui propose de vérifier en réserve si la taille demandée (plus petite) est disponible, ce qui répond directement à la demande du client. A : Cette réponse suppose que le magasin n’a que des tailles plus grandes, ce qui pourrait être tenté si on a mal compris la demande du client (qui cherche plus petit, pas plus grand). Cependant, rien dans l’enregistrement ne suggère que seules des tailles plus grandes sont disponibles, donc cette réponse ne répond pas à la demande. C : Proposer de raccourcir le pantalon pourrait sembler pertinent si le problème était la longueur, mais ici le client demande une taille en dessous (donc un problème de taille globale, pas seulement de longueur). Cette réponse ne répond pas à la demande précise. D : Dire qu’on a seulement une autre couleur pourrait être tenté si on pense que la taille demandée n’est pas disponible, mais la question porte sur la taille, pas la couleur. Cette réponse ne répond pas à la demande du client.","transcript":"Question 8.\nCe pantalon est un peu grand. Est-ce que vous avez la taille en dessous ?\nA. Non, on n’a que plus grand. B. Oui, je vais vérifier en réserve. C. Je peux vous le faire raccourcir. D. On l’a seulement dans une autre couleur.","segments":[{"voice":"female","text":"Question 8."},{"voice":"male","text":"Ce pantalon est un peu grand. Est-ce que vous avez la taille en dessous ?"},{"voice":"female","text":"A. Non, on n’a que plus grand. B. Oui, je vais vérifier en réserve. C. Je peux vous le faire raccourcir. D. On l’a seulement dans une autre couleur."}],"audio":"q-08.mp3","audioSeconds":17.737,"slotSeconds":37},{"number":9,"kind":"announcement","question":"De quel quai le train régional pour Blois partira-t-il finalement ?","options":["Du quai six","Du quai trois","Du quai quatre","Du quai cinq"],"correct":"D","explanation":"Réponse D : L'annonce précise que le train pour Blois partira exceptionnellement du quai cinq en raison de travaux sur le quai trois. C'est donc la seule réponse correcte. A : Quelqu'un pourrait choisir le quai six en pensant à un autre train ou en confondant les numéros de quai, mais il n'est pas mentionné pour le train de Blois. B : Le quai trois est mentionné comme étant en travaux, donc quelqu'un pourrait croire que le train part de là par habitude, mais il est explicitement dit que ce n'est pas le cas. C : Le quai quatre n'est pas mentionné dans l'annonce, mais quelqu'un pourrait le choisir par erreur ou par confusion avec les autres quais.","transcript":"Question 9.\nVotre attention, s'il vous plaît. En raison de travaux sur le quai trois, le train régional à destination de Blois partira exceptionnellement du quai cinq. L'horaire de départ, onze heures quarante, reste inchangé. Merci de vérifier les panneaux d'affichage.\nDe quel quai le train régional pour Blois partira-t-il finalement ?","segments":[{"voice":"female","text":"Question 9."},{"voice":"female","text":"Votre attention, s'il vous plaît. En raison de travaux sur le quai trois, le train régional à destination de Blois partira exceptionnellement du quai cinq. L'horaire de départ, onze heures quarante, reste inchangé. Merci de vérifier les panneaux d'affichage."},{"voice":"female","text":"De quel quai le train régional pour Blois partira-t-il finalement ?"}],"audio":"q-09.mp3","audioSeconds":20.558,"slotSeconds":36},{"number":10,"kind":"dialogue","question":"Où et à quelle heure décident-elles de se retrouver ?","options":["Devant l’entrée de la bibliothèque à 17 h 15.","À l’intérieur de la bibliothèque, près du comptoir, à 17 h 15.","Devant le café près de l’école, juste après le cours, vers 17 h 15.","Devant l’entrée de la bibliothèque à 18 h."],"correct":"A","explanation":"Réponse A : La personne précise clairement qu'elle attendra devant l'entrée de la bibliothèque à 17 h 15, ce qui correspond exactement à l'option 0. B : Quelqu'un pourrait penser qu'elles se retrouvent à l'intérieur près du comptoir car elles parlent de rendre des livres, mais il est bien précisé qu'elles se retrouvent devant l'entrée, pas à l'intérieur. C : On pourrait croire qu'elles se retrouvent devant le café après le cours, car le café est mentionné, mais il est explicitement dit qu'il est fermé et qu'elles choisissent la bibliothèque à la place. D : Quelqu'un pourrait confondre l'heure, pensant qu'elles se retrouvent à 18 h, mais l'heure exacte donnée est 17 h 15.","transcript":"Question 10.\nOn prend un café après ton cours de français ?\nLe café près de l'école est fermé aujourd'hui, mais la bibliothèque est ouverte jusqu'à vingt heures.\nAlors retrouvons-nous à la bibliothèque. Je t'attendrai devant l'entrée à dix-sept heures quinze.\nParfait, je pourrai aussi rendre mes livres.\nOù et à quelle heure décident-elles de se retrouver ?","segments":[{"voice":"female","text":"Question 10."},{"voice":"female","text":"On prend un café après ton cours de français ?"},{"voice":"male","text":"Le café près de l'école est fermé aujourd'hui, mais la bibliothèque est ouverte jusqu'à vingt heures."},{"voice":"female","text":"Alors retrouvons-nous à la bibliothèque. Je t'attendrai devant l'entrée à dix-sept heures quinze."},{"voice":"male","text":"Parfait, je pourrai aussi rendre mes livres."},{"voice":"female","text":"Où et à quelle heure décident-elles de se retrouver ?"}],"audio":"q-10.mp3","audioSeconds":23.327,"slotSeconds":39},{"number":11,"kind":"announcement","question":"Quelle consigne précise est donnée pour valider l’inscription à la visite ?","options":["Envoyer à l’avance un chèque de réservation.","Se présenter au jardin samedi avant le départ.","Téléphoner à l’association avant vendredi midi.","S’inscrire sur le site avant jeudi soir."],"correct":"D","explanation":"Réponse D : La consigne précise est de remplir le formulaire sur le site avant jeudi soir, ce qui correspond exactement à cette option. A : Quelqu’un pourrait penser qu’un chèque est nécessaire pour réserver, car c’est une pratique courante, mais le texte précise explicitement qu’aucun paiement n’est demandé. B : On pourrait croire qu’il suffit de se présenter le jour même, mais la consigne précise qu’il faut s’inscrire à l’avance en ligne. C : Quelqu’un pourrait confondre l’inscription en ligne avec un appel téléphonique, mais le texte ne mentionne que le formulaire sur le site.","transcript":"Question 11.\nL'association des riverains organise samedi une visite guidée du jardin partagé. La participation est gratuite, mais les places sont limitées. Pour confirmer votre présence, remplissez le formulaire sur notre site avant jeudi soir. Aucun paiement n'est demandé.\nQuelle consigne précise est donnée pour valider l’inscription à la visite ?","segments":[{"voice":"female","text":"Question 11."},{"voice":"female","text":"L'association des riverains organise samedi une visite guidée du jardin partagé. La participation est gratuite, mais les places sont limitées. Pour confirmer votre présence, remplissez le formulaire sur notre site avant jeudi soir. Aucun paiement n'est demandé."},{"voice":"female","text":"Quelle consigne précise est donnée pour valider l’inscription à la visite ?"}],"audio":"q-11.mp3","audioSeconds":21.812,"slotSeconds":40},{"number":12,"kind":"dialogue","question":"Qu’indique le vendeur au sujet de l’intervention du technicien ?","options":["Il a remplacé la pièce défectueuse.","Il a conseillé d’en acheter une nouvelle.","Il a simplement nettoyé l’appareil.","Il a constaté que la cafetière était irréparable."],"correct":"A","explanation":"Réponse A : Le vendeur dit explicitement que le technicien a remplacé la pièce défectueuse, ce qui répond directement à la question. B : Quelqu’un pourrait croire que le technicien a conseillé d’acheter une nouvelle pièce si la mention de remplacement était mal comprise, mais il est clairement dit que la cafetière fonctionne à nouveau, ce qui contredit l’idée d’un simple conseil d’achat. C : On pourrait penser à un simple nettoyage si on n’a pas bien entendu le mot 'remplacé', mais le texte précise qu’une pièce a été changée, pas seulement nettoyée. D : Quelqu’un pourrait croire que la cafetière était irréparable si le message avait été négatif, mais il est dit qu’elle fonctionne à nouveau, ce qui contredit cette option.","transcript":"Question 12.\nBonjour. J'ai laissé ma cafetière ici mardi dernier. Vous m'avez envoyé un message ce matin.\nOui, notre technicien a remplacé la pièce défectueuse. Elle fonctionne à nouveau.\nTrès bien. Je peux la reprendre maintenant ?\nBien sûr, voici le reçu de la réparation.\nQu’indique le vendeur au sujet de l’intervention du technicien ?","segments":[{"voice":"female","text":"Question 12."},{"voice":"male","text":"Bonjour. J'ai laissé ma cafetière ici mardi dernier. Vous m'avez envoyé un message ce matin."},{"voice":"female","text":"Oui, notre technicien a remplacé la pièce défectueuse. Elle fonctionne à nouveau."},{"voice":"male","text":"Très bien. Je peux la reprendre maintenant ?"},{"voice":"female","text":"Bien sûr, voici le reçu de la réparation."},{"voice":"female","text":"Qu’indique le vendeur au sujet de l’intervention du technicien ?"}],"audio":"q-12.mp3","audioSeconds":25.104,"slotSeconds":38},{"number":13,"kind":"announcement","question":"Que précise l’annonce au sujet de la projection du documentaire prévue à dix-neuf heures ?","options":["Elle commencera à vingt heures.","Elle est avancée à dix-huit heures.","Elle est annulée pour ce soir.","Elle reste finalement à dix-neuf heures."],"correct":"A","explanation":"Réponse A : L'annonce précise que la projection prévue à 19h commencera finalement à 20h, ce qui correspond exactement à l'option 1. B : Quelqu'un pourrait confondre le sens du changement d'horaire et penser que la séance est avancée plutôt que retardée, mais le texte indique clairement qu'elle commencera plus tard, pas plus tôt. C : On pourrait croire que la séance est annulée à cause du problème technique, mais l'annonce précise seulement un report, pas une annulation. D : Quelqu'un pourrait ne pas remarquer le changement d'horaire et penser que l'heure reste la même, mais l'annonce indique explicitement un report à 20h.","transcript":"Question 13.\nInformation aux visiteurs du centre culturel : en raison d'un problème technique, la projection du documentaire prévue à dix-neuf heures commencera à vingt heures. L'exposition et la rencontre avec les bénévoles auront lieu aux horaires habituels. Merci de votre compréhension.\nQue précise l’annonce au sujet de la projection du documentaire prévue à dix-neuf heures ?","segments":[{"voice":"female","text":"Question 13."},{"voice":"male","text":"Information aux visiteurs du centre culturel : en raison d'un problème technique, la projection du documentaire prévue à dix-neuf heures commencera à vingt heures. L'exposition et la rencontre avec les bénévoles auront lieu aux horaires habituels. Merci de votre compréhension."},{"voice":"female","text":"Que précise l’annonce au sujet de la projection du documentaire prévue à dix-neuf heures ?"}],"audio":"q-13.mp3","audioSeconds":24.555,"slotSeconds":40},{"number":14,"kind":"dialogue","question":"Comment décident-ils de s'adapter à la diapositive manquante ?","options":["Imprimer les derniers chiffres et les distribuer au lieu de les projeter.","Projeter la copie locale et préciser le chiffre manquant à l’oral.","Retirer toute mention du chiffre manquant pour ne pas en parler.","Attendre que le serveur refonctionne pour projeter la version complète."],"correct":"B","explanation":"Réponse B : Ils décident de projeter la copie locale malgré l'absence de la dernière diapositive et de préciser le chiffre manquant à l'oral. C'est exactement ce qui est dit dans l'extrait. A : Quelqu'un pourrait penser qu'ils vont distribuer les chiffres, mais il n'est jamais question d'imprimer quoi que ce soit. La solution proposée est d'expliquer le chiffre manquant à l'oral, pas de le distribuer. C : Quelqu'un pourrait croire qu'ils préfèrent éviter de parler du chiffre manquant, mais ils disent explicitement qu'ils vont l'expliquer à l'oral, donc ils ne retirent pas la mention. D : On pourrait penser qu'ils attendent le serveur, mais ils décident d'utiliser la copie locale immédiatement et de compléter à l'oral, donc ils n'attendent pas.","transcript":"Question 14.\nJe n'arrive pas à ouvrir la présentation sur le serveur.\nJ'ai une copie enregistrée sur mon ordinateur, mais il manque la dernière diapositive.\nCe n'est pas grave. On expliquera le chiffre manquant à l'oral et on enverra la version complète ensuite.\nD'accord, je branche l'ordinateur au projecteur.\nComment décident-ils de s'adapter à la diapositive manquante ?","segments":[{"voice":"female","text":"Question 14."},{"voice":"female","text":"Je n'arrive pas à ouvrir la présentation sur le serveur."},{"voice":"male","text":"J'ai une copie enregistrée sur mon ordinateur, mais il manque la dernière diapositive."},{"voice":"female","text":"Ce n'est pas grave. On expliquera le chiffre manquant à l'oral et on enverra la version complète ensuite."},{"voice":"male","text":"D'accord, je branche l'ordinateur au projecteur."},{"voice":"female","text":"Comment décident-ils de s'adapter à la diapositive manquante ?"}],"audio":"q-14.mp3","audioSeconds":26.906,"slotSeconds":39},{"number":15,"kind":"radio-news","question":"Selon ce message, à quoi doit servir principalement l’aide proposée aux commerçants proches de la gare ?","options":["À recruter du personnel supplémentaire pendant le réaménagement.","À financer des travaux de rénovation dans leurs locaux.","À adapter leurs horaires d’ouverture et leur signalisation.","À compenser la baisse de chiffre d’affaires liée aux travaux."],"correct":"C","explanation":"Réponse C : Le texte précise explicitement que l’aide temporaire est destinée à adapter les horaires d’ouverture ou à améliorer la signalisation, ce qui correspond exactement à cette option. A : Le texte ne mentionne pas le recrutement de personnel supplémentaire. Quelqu’un pourrait croire que l’aide vise à renforcer le personnel pour faire face aux perturbations, mais il est précisé que l’aide concerne l’adaptation des horaires et la signalisation. B : Le texte ne parle pas de financer des travaux de rénovation dans les locaux. On pourrait penser que des travaux de réaménagement impliquent aussi des rénovations internes, mais l’aide vise spécifiquement l’adaptation des horaires et la signalisation. D : Il est mentionné que la fréquentation a baissé, ce qui pourrait laisser penser que l’aide vise à compenser une perte de chiffre d’affaires. Cependant, le texte précise que l’aide porte uniquement sur l’adaptation des horaires et la signalisation, pas sur une compensation financière directe.","transcript":"Question 15.\nVoici les informations locales. La municipalité a présenté ce matin un dispositif de soutien aux commerçants autour de la gare. Les travaux de réaménagement ont réduit la fréquentation de certaines rues. Les établissements concernés pourront demander une aide temporaire pour adapter leurs horaires ou améliorer leur signalisation. Les élus promettent un premier bilan dans trois mois.\nSelon ce message, à quoi doit servir principalement l’aide proposée aux commerçants proches de la gare ?","segments":[{"voice":"female","text":"Question 15."},{"voice":"female","text":"Voici les informations locales. La municipalité a présenté ce matin un dispositif de soutien aux commerçants autour de la gare. Les travaux de réaménagement ont réduit la fréquentation de certaines rues. Les établissements concernés pourront demander une aide temporaire pour adapter leurs horaires ou améliorer leur signalisation. Les élus promettent un premier bilan dans trois mois."},{"voice":"female","text":"Selon ce message, à quoi doit servir principalement l’aide proposée aux commerçants proches de la gare ?"}],"audio":"q-15.mp3","audioSeconds":29.623,"slotSeconds":49},{"number":16,"kind":"dialogue","question":"Comment la responsable décide-t-elle d’organiser la présence au comptoir pour demain ?","options":["La responsable reste seule toute la journée pendant que Sofia prend un jour de repos.","Elles sont toutes les deux présentes le matin mais aucune le soir.","Sofia commence tôt le matin et la responsable prend la fermeture.","Elle assure l’accueil tôt le matin et Sofia reste pour la fermeture."],"correct":"D","explanation":"Réponse D : La responsable dit explicitement qu'elle assure l'accueil tôt le matin et que Sofia reste pour la fermeture, ce qui correspond exactement à cette option. A : Quelqu'un pourrait croire que la responsable reste seule toute la journée, mais le dialogue montre clairement que Sofia sera présente pour la fermeture, donc la responsable n'est pas seule toute la journée. B : On pourrait penser qu'elles ne sont présentes que le matin, mais la responsable précise que Sofia reste pour la fermeture, donc il y a bien une présence le soir. C : Quelqu'un pourrait croire que Sofia commence tôt, mais c'est la responsable qui commence tôt, Sofia commence plus tard et reste pour la fermeture.","transcript":"Question 16.\nSofia, tu peux commencer une heure plus tard demain ?\nOui, mais je devrai aussi partir après dix-huit heures.\nCela me convient. Je prendrai l'accueil tôt le matin et tu resteras pour la fermeture. Comme ça, personne n'attendra devant un comptoir vide.\nParfait, je vais mettre le planning à jour.\nComment la responsable décide-t-elle d’organiser la présence au comptoir pour demain ?","segments":[{"voice":"female","text":"Question 16."},{"voice":"female","text":"Sofia, tu peux commencer une heure plus tard demain ?"},{"voice":"male","text":"Oui, mais je devrai aussi partir après dix-huit heures."},{"voice":"female","text":"Cela me convient. Je prendrai l'accueil tôt le matin et tu resteras pour la fermeture. Comme ça, personne n'attendra devant un comptoir vide."},{"voice":"male","text":"Parfait, je vais mettre le planning à jour."},{"voice":"female","text":"Comment la responsable décide-t-elle d’organiser la présence au comptoir pour demain ?"}],"audio":"q-16.mp3","audioSeconds":26.88,"slotSeconds":48},{"number":17,"kind":"announcement","question":"Selon l’annonce, dans quelle situation peut-on demander la livraison de livres à domicile ?","options":["Uniquement quand on est âgé et qu’on ne sort presque plus de chez soi.","Quand on a des difficultés à se déplacer, même si cela ne dure que quelques semaines.","À condition d’avoir un handicap reconnu officiellement et permanent.","Seulement lorsqu’on est immobilisé pour une très longue période, sans date de fin prévue."],"correct":"B","explanation":"Réponse B : C'est la seule option qui reprend exactement la condition mentionnée dans l'annonce : le service s'adresse aussi à ceux qui ont des difficultés à se déplacer, même de façon temporaire. A : Cette option est tentante car les personnes âgées qui sortent peu sont concernées, mais l'annonce ne limite pas le service à ce seul groupe. Elle inclut toute personne ayant des difficultés à se déplacer, même temporairement. C : Quelqu’un pourrait croire qu’il faut un handicap officiel et permanent, mais l’annonce précise que même des difficultés temporaires suffisent, donc ce n’est pas requis. D : L’annonce précise que la durée n’a pas besoin d’être longue ou indéterminée, donc cette option est trop restrictive. Quelqu’un pourrait mal comprendre la durée minimale requise.","transcript":"Question 17.\nLa médiathèque de Saint-Roch lance un service de livraison de livres à domicile. Il est destiné aux personnes qui ne peuvent pas se déplacer facilement, y compris pour quelques semaines seulement. Un bénévole discutera de vos préférences avant de préparer une sélection. L'inscription à ce service se fait par téléphone auprès de l'accueil. Les livres restent prêtés gratuitement.\nSelon l’annonce, dans quelle situation peut-on demander la livraison de livres à domicile ?","segments":[{"voice":"female","text":"Question 17."},{"voice":"female","text":"La médiathèque de Saint-Roch lance un service de livraison de livres à domicile. Il est destiné aux personnes qui ne peuvent pas se déplacer facilement, y compris pour quelques semaines seulement. Un bénévole discutera de vos préférences avant de préparer une sélection. L'inscription à ce service se fait par téléphone auprès de l'accueil. Les livres restent prêtés gratuitement."},{"voice":"female","text":"Selon l’annonce, dans quelle situation peut-on demander la livraison de livres à domicile ?"}],"audio":"q-17.mp3","audioSeconds":28.447,"slotSeconds":51},{"number":18,"kind":"telephone","question":"Quel avantage du point relais le client met-il en avant ?","options":["Il lui évite d’avoir à rester chez lui pour attendre le livreur.","Il reste ouvert plus tard que la livraison à domicile.","Il est situé tout près de son bureau.","Il se trouve à côté de chez lui."],"correct":"C","explanation":"Réponse C : Le client précise clairement que l'avantage du point relais est sa proximité avec son bureau, ce qui répond directement à la question. A : Le client mentionne qu'il travaille toute la journée et ne peut donc pas attendre le livreur chez lui, ce qui pourrait faire croire que l'avantage est d'éviter d'attendre à la maison. Cependant, ce n'est pas l'avantage du point relais qu'il met en avant, mais plutôt sa proximité avec le bureau. B : Le point relais ferme à vingt heures, ce qui est plus tard que la plage de livraison à domicile, mais le client ne met pas en avant cet aspect. Il insiste sur la proximité avec son bureau. D : Le client parle de la proximité avec son bureau, pas avec son domicile. Quelqu'un pourrait confondre les deux lieux s'il n'écoute pas attentivement.","transcript":"Question 18.\nBonjour, je vous appelle pour mon colis. On me propose une livraison demain entre neuf heures et dix-huit heures, mais je travaille toute la journée.\nNous pouvons le déposer dans un point relais qui ferme à vingt heures. Cela vous conviendrait ?\nOui, c'est plus simple. Il est à cinq minutes de mon bureau.\nJe confirme le changement, vous recevrez un message.\nQuel avantage du point relais le client met-il en avant ?","segments":[{"voice":"female","text":"Question 18."},{"voice":"male","text":"Bonjour, je vous appelle pour mon colis. On me propose une livraison demain entre neuf heures et dix-huit heures, mais je travaille toute la journée."},{"voice":"female","text":"Nous pouvons le déposer dans un point relais qui ferme à vingt heures. Cela vous conviendrait ?"},{"voice":"male","text":"Oui, c'est plus simple. Il est à cinq minutes de mon bureau."},{"voice":"female","text":"Je confirme le changement, vous recevrez un message."},{"voice":"female","text":"Quel avantage du point relais le client met-il en avant ?"}],"audio":"q-18.mp3","audioSeconds":29.362,"slotSeconds":52},{"number":19,"kind":"announcement","question":"Selon l’annonce, quel est l’avantage principal des groupes limités à dix personnes ?","options":["La maison du patrimoine est moins exposée aux dégradations grâce à un flux réduit de visiteurs.","Le service de réservations peut gérer plus facilement les inscriptions et les listes d’attente.","Le guide peut répondre aux questions et adapter le parcours aux intérêts du groupe.","Le guide peut terminer la visite plus rapidement et enchaîner davantage de groupes dans la journée."],"correct":"C","explanation":"Réponse C : C’est exactement ce que dit l’annonce : le principal avantage est que le guide peut répondre aux questions et adapter le parcours aux intérêts du groupe. A : Quelqu’un pourrait penser qu’un nombre réduit de visiteurs protège la maison, mais l’annonce ne mentionne pas la préservation du lieu ou la réduction des dégradations. Le texte se concentre uniquement sur l’expérience des visiteurs. B : On pourrait croire que la gestion des réservations est facilitée avec de petits groupes, mais l’annonce ne parle pas du tout du service de réservations ou de la gestion administrative, seulement de l’interaction pendant la visite. D : Quelqu’un pourrait supposer qu’un groupe plus petit permet d’aller plus vite, mais l’annonce ne mentionne pas la rapidité ou la possibilité d’enchaîner plus de groupes. Elle insiste sur la qualité de l’expérience, pas sur la quantité de visites.","transcript":"Question 19.\nÀ partir du mois prochain, les visites de la maison du patrimoine seront organisées par groupes de dix personnes maximum. Ce choix permettra au guide de répondre aux questions et d'adapter le parcours aux intérêts des visiteurs. Il ne s'agit pas d'une visite réservée aux spécialistes : tout le monde peut participer, sur réservation.\nSelon l’annonce, quel est l’avantage principal des groupes limités à dix personnes ?","segments":[{"voice":"female","text":"Question 19."},{"voice":"female","text":"À partir du mois prochain, les visites de la maison du patrimoine seront organisées par groupes de dix personnes maximum. Ce choix permettra au guide de répondre aux questions et d'adapter le parcours aux intérêts des visiteurs. Il ne s'agit pas d'une visite réservée aux spécialistes : tout le monde peut participer, sur réservation."},{"voice":"female","text":"Selon l’annonce, quel est l’avantage principal des groupes limités à dix personnes ?"}],"audio":"q-19.mp3","audioSeconds":25.522,"slotSeconds":51},{"number":20,"kind":"dialogue","question":"Pourquoi la locataire propose-t-elle de revenir le lendemain matin ?","options":["Pour discuter directement avec les ouvriers du magasin au rez-de-chaussée.","Pour vérifier si les travaux du magasin s’entendent dans la chambre.","Pour voir si la lumière naturelle est suffisante à cette heure-là.","Pour contrôler si le bruit se fait entendre surtout dans le salon."],"correct":"B","explanation":"Réponse B : La locataire explique clairement qu'elle veut revenir pour vérifier si le bruit des travaux du magasin s'entend dans la chambre. C'est l'objet explicite de sa demande. A : Quelqu'un pourrait croire qu'elle veut parler aux ouvriers parce qu'elle mentionne les travaux du magasin, mais elle ne parle jamais de discuter avec eux, seulement de vérifier le bruit. C : Quelqu'un pourrait penser qu'elle veut vérifier la lumière naturelle car elle mentionne que l'appartement est lumineux, mais elle ne relie pas sa visite du lendemain à la lumière, seulement au bruit. D : La locataire précise qu'elle veut vérifier le bruit dans la chambre, pas dans le salon. Quelqu'un pourrait confondre les pièces, mais la chambre est explicitement mentionnée.","transcript":"Question 20.\nL'appartement est lumineux et le loyer me convient.\nSouhaitez-vous déposer votre dossier ?\nJ'aimerais d'abord revenir demain matin. Le magasin du rez-de-chaussée fait des travaux, et je voudrais savoir si on entend beaucoup de bruit dans la chambre.\nBien sûr. Je pourrai vous accueillir à neuf heures pour une seconde visite.\nPourquoi la locataire propose-t-elle de revenir le lendemain matin ?","segments":[{"voice":"female","text":"Question 20."},{"voice":"female","text":"L'appartement est lumineux et le loyer me convient."},{"voice":"male","text":"Souhaitez-vous déposer votre dossier ?"},{"voice":"female","text":"J'aimerais d'abord revenir demain matin. Le magasin du rez-de-chaussée fait des travaux, et je voudrais savoir si on entend beaucoup de bruit dans la chambre."},{"voice":"male","text":"Bien sûr. Je pourrai vous accueillir à neuf heures pour une seconde visite."},{"voice":"female","text":"Pourquoi la locataire propose-t-elle de revenir le lendemain matin ?"}],"audio":"q-20.mp3","audioSeconds":25.391,"slotSeconds":51},{"number":21,"kind":"announcement","question":"Comment l’organisateur prévoit-il d’éviter qu’il y ait trop de bénévoles à certains moments et pas assez à d’autres ?","options":["En demandant aux bénévoles de s’inscrire directement à l’accueil le jour de la fête.","En demandant aux bénévoles d’indiquer leurs horaires avant mercredi.","En imposant un planning de roulement identique pour tous, décidé la veille de la fête.","En limitant chaque bénévole à un seul créneau d’une heure."],"correct":"B","explanation":"Réponse B : C’est la seule option qui correspond exactement à la méthode décrite dans le texte : demander aux bénévoles d’indiquer leurs horaires avant mercredi pour éviter un déséquilibre dans la répartition. A : Quelqu’un pourrait croire que l’inscription se fait à l’accueil le jour même, mais le texte précise que les horaires doivent être indiqués avant mercredi, donc cette option est contredite. C : On pourrait croire qu’un planning identique est imposé, mais le texte parle de choix individuels des horaires, pas d’un planning imposé à tous. D : Quelqu’un pourrait penser qu’il y a une limitation stricte à un créneau d’une heure, mais le texte indique que les bénévoles peuvent participer plus longtemps s’ils le souhaitent.","transcript":"Question 21.\nLa fête du quartier aura lieu samedi prochain. Les bénévoles peuvent participer une heure ou toute la journée. Pour préparer les équipes d'accueil, de nettoyage et d'animation, nous vous demandons de préciser vos horaires avant mercredi. Cette information nous évitera de réunir trop de personnes à un même moment tout en laissant certains stands sans aide. Aucune expérience particulière n'est nécessaire.\nComment l’organisateur prévoit-il d’éviter qu’il y ait trop de bénévoles à certains moments et pas assez à d’autres ?","segments":[{"voice":"female","text":"Question 21."},{"voice":"female","text":"La fête du quartier aura lieu samedi prochain. Les bénévoles peuvent participer une heure ou toute la journée. Pour préparer les équipes d'accueil, de nettoyage et d'animation, nous vous demandons de préciser vos horaires avant mercredi. Cette information nous évitera de réunir trop de personnes à un même moment tout en laissant certains stands sans aide. Aucune expérience particulière n'est nécessaire."},{"voice":"female","text":"Comment l’organisateur prévoit-il d’éviter qu’il y ait trop de bénévoles à certains moments et pas assez à d’autres ?"}],"audio":"q-21.mp3","audioSeconds":30.929,"slotSeconds":51},{"number":22,"kind":"interview","question":"Quand une récolte échoue, que dit la personne interrogée en repartant du jardin partagé ?","options":["Qu’elle se sent responsable de l’échec de la récolte.","Qu’elle regrette d’être venue ce jour-là.","Qu’elle se promet de ne plus revenir avant la prochaine saison.","Qu’elle a tout de même passé un bon moment."],"correct":"D","explanation":"Réponse D : C’est exactement ce que dit la personne : elle repart avec le sentiment d’avoir passé un bon moment, même en cas d’échec. A : La personne ne mentionne à aucun moment se sentir responsable de l’échec. Quelqu’un pourrait mal interpréter son implication dans le jardin comme un sentiment de responsabilité, mais le texte ne le suggère pas. B : La personne ne regrette pas d’être venue ; au contraire, elle exprime qu’elle passe toujours un bon moment, même en cas d’échec. Quelqu’un pourrait croire qu’un échec entraîne du regret, mais ce n’est pas le cas ici. C : La personne ne dit pas qu’elle ne reviendra plus avant la prochaine saison. Elle continue à venir malgré les échecs. On pourrait croire qu’un échec la décourage, mais elle affirme le contraire.","transcript":"Question 22.\nVous participez depuis deux ans au jardin partagé. Est-ce que vous y venez surtout pour récolter des légumes ?\nJ'aime rapporter des tomates, bien sûr, mais ce n'est pas ce qui me retient ici. Avant, je connaissais à peine les habitants de mon immeuble. Aujourd'hui, je discute avec des voisins de tous âges. Nous apprenons à nous organiser, et parfois à accepter que chacun travaille autrement. Même quand une récolte échoue, je repars avec le sentiment d'avoir passé un bon moment.\nQuand une récolte échoue, que dit la personne interrogée en repartant du jardin partagé ?","segments":[{"voice":"female","text":"Question 22."},{"voice":"male","text":"Vous participez depuis deux ans au jardin partagé. Est-ce que vous y venez surtout pour récolter des légumes ?"},{"voice":"female","text":"J'aime rapporter des tomates, bien sûr, mais ce n'est pas ce qui me retient ici. Avant, je connaissais à peine les habitants de mon immeuble. Aujourd'hui, je discute avec des voisins de tous âges. Nous apprenons à nous organiser, et parfois à accepter que chacun travaille autrement. Même quand une récolte échoue, je repars avec le sentiment d'avoir passé un bon moment."},{"voice":"female","text":"Quand une récolte échoue, que dit la personne interrogée en repartant du jardin partagé ?"}],"audio":"q-22.mp3","audioSeconds":34.978,"slotSeconds":50},{"number":23,"kind":"panel-discussion","question":"Quelle solution commune finit par émerger ?","options":["Introduire progressivement un plat végétarien fixe chaque semaine sans mesurer les quantités jetées.","Lancer pendant un mois deux menus végétariens tests et en suivre les restes et les avis des élèves.","Former le personnel à de nouvelles recettes végétariennes avant de décider s’il faut modifier les menus.","Organiser un sondage écrit auprès des familles avant tout changement de menu."],"correct":"B","explanation":"Réponse B : C’est exactement la solution commune retenue : tester deux menus végétariens pendant un mois, suivre les restes et recueillir les avis des élèves. Cela reprend les propositions de la direction et des parents, et la conclusion collective. A : Cette option propose d'introduire un plat végétarien fixe chaque semaine sans mesurer les quantités jetées, alors que la solution commune évoque explicitement la mesure des restes. Quelqu’un pourrait confondre l’idée d’introduire un plat végétarien régulièrement avec la solution retenue, mais l’absence de suivi des restes contredit le consensus. C : Le cuisinier évoque la formation du personnel, mais ce n’est pas la solution commune retenue. Quelqu’un pourrait croire que la formation est la première étape, mais la discussion aboutit à une expérimentation concrète avant toute modification durable. D : La représentante des parents suggère de recueillir l’avis des élèves, mais il n’est jamais question d’un sondage écrit auprès des familles avant tout changement. Quelqu’un pourrait confondre la consultation des élèves avec celle des familles, mais la solution commune porte sur l’expérimentation et la publication des réactions, pas sur un sondage préalable.","transcript":"Question 23.\nVous écoutez une discussion consacrée à la cantine scolaire. Comment proposer davantage de plats végétariens ?\nJe suis cuisinier. Nous pouvons changer les recettes, mais il faut apprendre à les préparer en grande quantité sans augmenter le gaspillage.\nJe représente des parents. Les enfants accepteront mieux les changements s'ils peuvent goûter et donner leur avis.\nDu côté de la direction, nous pourrions essayer deux nouveaux menus pendant un mois et mesurer les restes.\nAlors, commençons par cette expérience, puis publions les réactions des élèves et de l'équipe.\nQuelle solution commune finit par émerger ?","segments":[{"voice":"female","text":"Question 23."},{"voice":"female","text":"Vous écoutez une discussion consacrée à la cantine scolaire. Comment proposer davantage de plats végétariens ?"},{"voice":"male","text":"Je suis cuisinier. Nous pouvons changer les recettes, mais il faut apprendre à les préparer en grande quantité sans augmenter le gaspillage."},{"voice":"female","text":"Je représente des parents. Les enfants accepteront mieux les changements s'ils peuvent goûter et donner leur avis."},{"voice":"male","text":"Du côté de la direction, nous pourrions essayer deux nouveaux menus pendant un mois et mesurer les restes."},{"voice":"female","text":"Alors, commençons par cette expérience, puis publions les réactions des élèves et de l'équipe."},{"voice":"female","text":"Quelle solution commune finit par émerger ?"}],"audio":"q-23.mp3","audioSeconds":37.433,"slotSeconds":60},{"number":24,"kind":"interview","question":"Quelle population sera contactée lors de la prochaine étape ?","options":["Les personnes ayant cessé de prendre cette ligne.","Les personnes chargées de distribuer les questionnaires.","Les personnes interrogées à bord des autobus.","Les voyageurs utilisant d’autres lignes de bus."],"correct":"A","explanation":"Réponse A : Le texte explique clairement que la prochaine étape sera de contacter directement les personnes qui ont cessé de prendre cette ligne, car elles n'ont pas été suffisamment représentées dans l'enquête initiale. B : Quelqu’un pourrait confondre les enquêteurs (qui distribuent les questionnaires) avec la population à contacter, mais le texte précise que ce sont les anciens usagers qui seront contactés, pas les enquêteurs. C : On pourrait croire que les personnes interrogées à bord des autobus seront recontactées, mais le texte indique qu'elles ont déjà été interrogées et que la prochaine étape vise une population différente. D : Quelqu’un pourrait penser que tous les voyageurs d’autres lignes seront contactés, mais le texte cible spécifiquement ceux qui ont arrêté d’utiliser cette ligne précise.","transcript":"Question 24.\nVotre étude indique que les usagers des transports sont plutôt satisfaits. Cela prouve-t-il que le service s'est amélioré ?\nNous devons être prudents. Nos enquêteurs ont distribué les questionnaires à bord des autobus. Nous avons donc entendu surtout ceux qui continuaient à voyager. Les personnes qui ont renoncé à prendre cette ligne, parce que les horaires ne convenaient plus, n'apparaissent presque pas dans les réponses. Une prochaine étape consistera à les contacter directement. Sans cela, nous risquons de confondre satisfaction des usagers actuels et qualité générale du service.\nQuelle population sera contactée lors de la prochaine étape ?","segments":[{"voice":"female","text":"Question 24."},{"voice":"male","text":"Votre étude indique que les usagers des transports sont plutôt satisfaits. Cela prouve-t-il que le service s'est amélioré ?"},{"voice":"female","text":"Nous devons être prudents. Nos enquêteurs ont distribué les questionnaires à bord des autobus. Nous avons donc entendu surtout ceux qui continuaient à voyager. Les personnes qui ont renoncé à prendre cette ligne, parce que les horaires ne convenaient plus, n'apparaissent presque pas dans les réponses. Une prochaine étape consistera à les contacter directement. Sans cela, nous risquons de confondre satisfaction des usagers actuels et qualité générale du service."},{"voice":"female","text":"Quelle population sera contactée lors de la prochaine étape ?"}],"audio":"q-24.mp3","audioSeconds":39.131,"slotSeconds":59},{"number":25,"kind":"television-report","question":"Comment les responsables du projet décident-ils de s’organiser pour limiter la gêne causée par le chantier ?","options":["Concentrer l’ensemble des travaux sur une courte période de fermeture totale.","Réserver les interventions aux nuits et aux tout débuts de matinée.","Rediriger temporairement toutes les livraisons vers une zone logistique en périphérie.","Échelonner les interventions par secteurs en aménageant des accès provisoires."],"correct":"D","explanation":"Réponse D : C'est la seule option qui correspond exactement à l'organisation décrite : échelonner les interventions par secteurs et aménager des accès provisoires pour limiter la gêne. A : Quelqu'un pourrait penser que concentrer les travaux sur une courte période limiterait la gêne, mais le texte précise que les responsables préfèrent échelonner les interventions par secteurs, ce qui contredit l'idée d'une fermeture totale et brève. B : Il serait tentant de croire que les travaux sont réservés à la nuit ou au matin pour limiter la gêne, mais le texte ne mentionne aucune restriction horaire ; il parle d'organisation spatiale et d'accès provisoires. C : On pourrait croire que les livraisons sont redirigées ailleurs, mais le texte insiste sur le maintien de l'accès aux livraisons via des chemins provisoires, pas sur leur redirection vers une zone périphérique.","transcript":"Question 25.\nDans la vallée de l'Arnon, la municipalité veut restaurer les berges d'une rivière fragilisée par plusieurs épisodes de sécheresse. L'objectif est de redonner de l'espace à la végétation et d'améliorer les habitats des poissons.\nUn commerçant explique que les travaux doivent néanmoins laisser un accès aux livraisons et à la promenade, très fréquentée les week-ends.\nLes responsables du projet discutent donc d'un calendrier par secteurs et de chemins provisoires. Leur défi : protéger durablement le cours d'eau sans exclure les habitants qui en dépendent au quotidien.\nComment les responsables du projet décident-ils de s’organiser pour limiter la gêne causée par le chantier ?","segments":[{"voice":"female","text":"Question 25."},{"voice":"female","text":"Dans la vallée de l'Arnon, la municipalité veut restaurer les berges d'une rivière fragilisée par plusieurs épisodes de sécheresse. L'objectif est de redonner de l'espace à la végétation et d'améliorer les habitats des poissons."},{"voice":"male","text":"Un commerçant explique que les travaux doivent néanmoins laisser un accès aux livraisons et à la promenade, très fréquentée les week-ends."},{"voice":"female","text":"Les responsables du projet discutent donc d'un calendrier par secteurs et de chemins provisoires. Leur défi : protéger durablement le cours d'eau sans exclure les habitants qui en dépendent au quotidien."},{"voice":"female","text":"Comment les responsables du projet décident-ils de s’organiser pour limiter la gêne causée par le chantier ?"}],"audio":"q-25.mp3","audioSeconds":40.908,"slotSeconds":57},{"number":26,"kind":"interview","question":"Selon la libraire, que devient concrètement l’accès aux livres qui ne sont plus exposés en rayon ?","options":["Ils restent disponibles sur commande, souvent livrés dès le lendemain.","Ils ne sont plus proposés qu’à travers le site internet de la librairie.","Ils sont remplacés chaque saison par une nouvelle sélection définitivement différente.","Ils sont stockés en réserve et remis en rayon seulement lors de promotions."],"correct":"A","explanation":"Réponse A : La libraire explique clairement que les livres qui ne sont plus exposés peuvent toujours être commandés, souvent livrés dès le lendemain. Cela répond précisément à la question sur l'accès concret à ces livres. B : Quelqu’un pourrait croire que l’accès passe uniquement par le site internet, car la commande évoque un processus à distance. Cependant, la libraire ne mentionne pas de restriction au site internet, seulement la possibilité de commander, ce qui peut aussi se faire en magasin. C : On pourrait penser que les livres sont remplacés chaque saison par une sélection différente, car la libraire parle de renouveler la présentation. Mais elle précise que les autres livres ne sont pas supprimés, ils restent disponibles sur commande. D : Quelqu’un pourrait croire que les livres sont stockés en réserve et remis en rayon lors de promotions, car ils ne sont plus exposés. Mais la libraire ne mentionne pas de stockage en réserve ni de remise en rayon lors de promotions, seulement la commande rapide.","transcript":"Question 26.\nVous avez réduit le nombre de livres exposés dans votre librairie. Est-ce une conséquence du manque de clients ?\nPas exactement. Notre local est petit, et nous accumulions des titres qui restaient des mois sur les étagères. Nous avons choisi de mieux présenter quelques collections, notamment celles des éditeurs de la région. Les autres livres ne sont pas supprimés : nous pouvons les commander, souvent pour le lendemain. Il faut bien expliquer cette possibilité, car certaines personnes croient d'abord que notre offre a diminué. En réalité, nous essayons de rendre la librairie plus facile à parcourir sans renoncer à la diversité.\nSelon la libraire, que devient concrètement l’accès aux livres qui ne sont plus exposés en rayon ?","segments":[{"voice":"female","text":"Question 26."},{"voice":"male","text":"Vous avez réduit le nombre de livres exposés dans votre librairie. Est-ce une conséquence du manque de clients ?"},{"voice":"female","text":"Pas exactement. Notre local est petit, et nous accumulions des titres qui restaient des mois sur les étagères. Nous avons choisi de mieux présenter quelques collections, notamment celles des éditeurs de la région. Les autres livres ne sont pas supprimés : nous pouvons les commander, souvent pour le lendemain. Il faut bien expliquer cette possibilité, car certaines personnes croient d'abord que notre offre a diminué. En réalité, nous essayons de rendre la librairie plus facile à parcourir sans renoncer à la diversité."},{"voice":"female","text":"Selon la libraire, que devient concrètement l’accès aux livres qui ne sont plus exposés en rayon ?"}],"audio":"q-26.mp3","audioSeconds":43.024,"slotSeconds":66},{"number":27,"kind":"dialogue","question":"Selon la discussion, quelle organisation des permanences envisagent-ils pour pouvoir ouvrir plus tôt ?","options":["Demander aux volontaires d’avancer leurs permanences du matin, sans toucher à celle du soir.","Regrouper toutes les heures de bénévolat sur la matinée, en supprimant la permanence du soir.","Maintenir les mêmes créneaux de bénévolat et chercher seulement plus de volontaires ponctuels.","Décaler la fermeture du soir pour compenser, sans modifier les permanences du matin."],"correct":"A","explanation":"Réponse A : La discussion propose d'avancer les permanences du matin pour ouvrir plus tôt, tout en maintenant la permanence du soir. Cela correspond exactement à l'option 0. B : Quelqu'un pourrait croire qu'il s'agit de regrouper toutes les heures sur la matinée et donc de supprimer la permanence du soir, car l'objectif est d'ouvrir plus tôt. Cependant, la phrase 'sans supprimer celle du soir' contredit explicitement cette interprétation. C : On pourrait penser que la solution consiste à garder les mêmes créneaux et à chercher plus de volontaires ponctuels, car le manque de bénévoles est évoqué. Toutefois, la discussion porte sur le décalage des permanences existantes, pas sur le recrutement de nouveaux volontaires ponctuels. D : Certains pourraient croire qu'il s'agit de décaler la fermeture du soir pour compenser, mais la discussion porte sur avancer l'ouverture du matin, pas sur modifier la fermeture du soir.","transcript":"Question 27.\nPlusieurs salariés arrivent en retard parce que la garderie n'ouvre qu'à huit heures trente. Pourtant, certains commencent à huit heures.\nNous pourrions avancer l'ouverture, mais les bénévoles du matin ne sont pas assez nombreux.\nEt si nous demandions aux volontaires de décaler leurs permanences, sans supprimer celle du soir ?\nIl faudra consulter les familles qui travaillent tard. Notre solution ne doit pas résoudre un problème en en créant un autre.\nD'accord. Essayons sur deux semaines et recueillons les retours avant de décider.\nSelon la discussion, quelle organisation des permanences envisagent-ils pour pouvoir ouvrir plus tôt ?","segments":[{"voice":"female","text":"Question 27."},{"voice":"female","text":"Plusieurs salariés arrivent en retard parce que la garderie n'ouvre qu'à huit heures trente. Pourtant, certains commencent à huit heures."},{"voice":"male","text":"Nous pourrions avancer l'ouverture, mais les bénévoles du matin ne sont pas assez nombreux."},{"voice":"female","text":"Et si nous demandions aux volontaires de décaler leurs permanences, sans supprimer celle du soir ?"},{"voice":"male","text":"Il faudra consulter les familles qui travaillent tard. Notre solution ne doit pas résoudre un problème en en créant un autre."},{"voice":"female","text":"D'accord. Essayons sur deux semaines et recueillons les retours avant de décider."},{"voice":"female","text":"Selon la discussion, quelle organisation des permanences envisagent-ils pour pouvoir ouvrir plus tôt ?"}],"audio":"q-27.mp3","audioSeconds":39.758,"slotSeconds":60},{"number":28,"kind":"interview","question":"Selon l'invitée, qu'est-ce qui pose surtout problème dans la manière dont l’aire de jeux a été conçue ?","options":["Les plans ont été élaborés avant que l’équipe ne rencontre les familles utilisatrices du parc.","Les besoins des enfants sensibles au bruit ont été recueillis mais écartés lors du choix des jeux.","Les aménagements pour fauteuil roulant ont été pensés uniquement pour satisfaire aux normes réglementaires.","L’observation des usages du parc n’a été prévue qu’après l’achèvement complet du chantier."],"correct":"A","explanation":"Réponse A : L'invitée explique clairement que le principal problème est que les plans ont été élaborés avant de consulter les familles utilisatrices, ce qui a mené à une conception qui ne prend pas en compte tous les besoins. B : Il est mentionné que certains enfants sont sensibles au bruit, mais il n'est jamais dit que leurs besoins ont été recueillis puis écartés. La critique porte sur l'absence de prise en compte initiale, pas sur un choix délibéré d'exclure ces besoins. C : L'invitée évoque le besoin de cheminements adaptés, mais elle ne dit pas que les aménagements ont été pensés uniquement pour satisfaire aux normes. Elle critique le fait de ne pas intégrer ces besoins dès le début, pas une conformité minimale aux normes. D : L'invitée souhaite que l'observation ait lieu avant la conception, pas après l’achèvement. Elle critique justement le fait de ne pas anticiper ces observations, donc cette option inverse la chronologie du problème.","transcript":"Question 28.\nLa nouvelle aire de jeux devrait être inaugurée en juin. Vous avez demandé quelques modifications, pourquoi ?\nL'équipe a sélectionné de très beaux jeux, mais les plans ont été dessinés avant les rencontres avec les familles. Certaines personnes ont besoin de cheminements assez larges pour un fauteuil. D'autres enfants sont sensibles au bruit et cherchent des espaces plus calmes. Nous ne voulons pas simplement ajouter une rampe à la fin du chantier. Il faudrait observer comment différents publics utilisent le parc et penser leurs parcours dès le départ. Cela peut demander quelques semaines de travail, mais évitera des adaptations coûteuses plus tard.\nSelon l'invitée, qu'est-ce qui pose surtout problème dans la manière dont l’aire de jeux a été conçue ?","segments":[{"voice":"female","text":"Question 28."},{"voice":"male","text":"La nouvelle aire de jeux devrait être inaugurée en juin. Vous avez demandé quelques modifications, pourquoi ?"},{"voice":"female","text":"L'équipe a sélectionné de très beaux jeux, mais les plans ont été dessinés avant les rencontres avec les familles. Certaines personnes ont besoin de cheminements assez larges pour un fauteuil. D'autres enfants sont sensibles au bruit et cherchent des espaces plus calmes. Nous ne voulons pas simplement ajouter une rampe à la fin du chantier. Il faudrait observer comment différents publics utilisent le parc et penser leurs parcours dès le départ. Cela peut demander quelques semaines de travail, mais évitera des adaptations coûteuses plus tard."},{"voice":"female","text":"Selon l'invitée, qu'est-ce qui pose surtout problème dans la manière dont l’aire de jeux a été conçue ?"}],"audio":"q-28.mp3","audioSeconds":43.703,"slotSeconds":67},{"number":29,"kind":"debate","question":"Quelle différence de point de vue apparaît sur la manière d’évaluer les nouvelles restrictions de circulation ?","options":["L’un souhaite attendre plusieurs années de données avant toute décision, l’autre veut appliquer immédiatement de nouvelles restrictions.","L’un affirme que la pollution a déjà nettement baissé, l’autre soutient qu’on n’observe pour l’instant aucune amélioration.","L’un estime que les mesures réalisées en centre-ville suffisent pour décider, l’autre veut y ajouter une évaluation dans les quartiers voisins et auprès des usagers.","L’un s’intéresse seulement aux habitants du centre, l’autre uniquement aux automobilistes de passage."],"correct":"C","explanation":"Réponse C : L'un estime que les mesures du centre suffisent (« Les concentrations de certains polluants ont baissé près des grands axes »), l'autre veut compléter l'évaluation dans les quartiers voisins et auprès des usagers (« il faut aussi savoir où passent désormais les voitures », « une évaluation qui inclue les habitants et les travailleurs concernés »). A : Quelqu'un pourrait croire que l'un veut attendre longtemps avant d'agir, car il demande une évaluation plus large. Cependant, il précise : « Je ne demande pas l'inaction. » Il ne souhaite donc pas attendre plusieurs années, mais une évaluation plus complète. B : On pourrait croire que l'un affirme une baisse nette et l'autre aucune amélioration, mais le second intervenant ne nie pas la baisse ; il veut simplement élargir l'évaluation. Il ne dit pas qu'il n'y a aucune amélioration. D : On pourrait croire que l'un ne s'intéresse qu'aux habitants du centre et l'autre aux automobilistes de passage, mais il est explicitement question d'inclure aussi les travailleurs et de mesurer dans les quartiers voisins, pas seulement les automobilistes de passage.","transcript":"Question 29.\nVous écoutez un débat sur la circulation automobile en centre-ville. Les nouvelles restrictions fonctionnent-elles ?\nNous disposons déjà de chiffres. Les concentrations de certains polluants ont baissé près des grands axes ; c'est un résultat important.\nCes mesures sont utiles, mais il faut aussi savoir où passent désormais les voitures. Si elles empruntent les rues des quartiers voisins, nous devons mesurer cet effet.\nD'accord pour compléter les mesures, mais n'attendons pas des années avant d'agir.\nJe ne demande pas l'inaction. Je demande une évaluation qui inclue les habitants et les travailleurs concernés, pas uniquement les capteurs du centre.\nQuelle différence de point de vue apparaît sur la manière d’évaluer les nouvelles restrictions de circulation ?","segments":[{"voice":"female","text":"Question 29."},{"voice":"female","text":"Vous écoutez un débat sur la circulation automobile en centre-ville. Les nouvelles restrictions fonctionnent-elles ?"},{"voice":"male","text":"Nous disposons déjà de chiffres. Les concentrations de certains polluants ont baissé près des grands axes ; c'est un résultat important."},{"voice":"female","text":"Ces mesures sont utiles, mais il faut aussi savoir où passent désormais les voitures. Si elles empruntent les rues des quartiers voisins, nous devons mesurer cet effet."},{"voice":"male","text":"D'accord pour compléter les mesures, mais n'attendons pas des années avant d'agir."},{"voice":"female","text":"Je ne demande pas l'inaction. Je demande une évaluation qui inclue les habitants et les travailleurs concernés, pas uniquement les capteurs du centre."},{"voice":"female","text":"Quelle différence de point de vue apparaît sur la manière d’évaluer les nouvelles restrictions de circulation ?"}],"audio":"q-29.mp3","audioSeconds":45.871,"slotSeconds":64},{"number":30,"kind":"interview","question":"Quelle conception de la conservation du patrimoine l'architecte défend-il ?","options":["Préserver les éléments porteurs de sens tout en documentant les transformations et en acceptant de nouveaux usages.","Donner la priorité à toute fonction rentable, même si elle efface les marques du passé.","Reconstruire à neuf en imitant le style ancien sans conserver les traces réelles.","Figer intégralement les bâtiments dans leur état d’origine."],"correct":"A","explanation":"Réponse A : L'architecte insiste sur l'importance de préserver les éléments porteurs de sens (portes, charpente, traces du passé), tout en documentant les transformations et en acceptant de nouveaux usages (salle de spectacles). Il rejette l'idée de figer le bâtiment ou de tout sacrifier à la rentabilité. B : Quelqu'un pourrait croire que l'architecte privilégie la rentabilité ou la nouvelle fonction, car il accepte la transformation en salle de spectacles. Cependant, il précise qu'il ne faut pas effacer les éléments qui permettent de comprendre le passé, ce qui contredit l'idée de donner la priorité à la rentabilité au détriment du patrimoine. C : On pourrait penser que l'architecte accepte de reconstruire à neuf en imitant l'ancien, car il n'exige pas de tout figer. Mais il insiste sur la nécessité de préserver les éléments authentiques et de documenter les transformations, pas de tout remplacer par du neuf. D : Certains pourraient croire qu'il faut tout figer dans l'état d'origine, mais l'architecte rejette explicitement cette idée en disant que ce n'est pas nécessaire d'immobiliser chaque détail.","transcript":"Question 30.\nL'ancienne gare de marchandises va devenir une salle de spectacles. Est-ce encore une forme de conservation du patrimoine ?\nOui, si nous savons ce que nous cherchons à transmettre. Les grandes portes, la charpente et les traces laissées par les anciennes activités racontent une histoire qu'il faut rendre lisible. Mais garder un bâtiment vide n'est pas la seule manière de la préserver. Une salle fréquentée peut lui donner une nouvelle place dans la ville. L'essentiel est de documenter les transformations et de ne pas effacer les éléments qui permettent de comprendre son passé. La conservation n'exige pas d'immobiliser chaque détail pour toujours.\nQuelle conception de la conservation du patrimoine l'architecte défend-il ?","segments":[{"voice":"female","text":"Question 30."},{"voice":"male","text":"L'ancienne gare de marchandises va devenir une salle de spectacles. Est-ce encore une forme de conservation du patrimoine ?"},{"voice":"female","text":"Oui, si nous savons ce que nous cherchons à transmettre. Les grandes portes, la charpente et les traces laissées par les anciennes activités racontent une histoire qu'il faut rendre lisible. Mais garder un bâtiment vide n'est pas la seule manière de la préserver. Une salle fréquentée peut lui donner une nouvelle place dans la ville. L'essentiel est de documenter les transformations et de ne pas effacer les éléments qui permettent de comprendre son passé. La conservation n'exige pas d'immobiliser chaque détail pour toujours."},{"voice":"female","text":"Quelle conception de la conservation du patrimoine l'architecte défend-il ?"}],"audio":"q-30.mp3","audioSeconds":44.33,"slotSeconds":71},{"number":31,"kind":"academic-monologue","question":"Quelle distinction précise la conférencière demande-t-elle d’opérer lorsqu’elle évoque les quartiers plus arborés ?","options":["Entre des quartiers très végétalisés et ceux qui ne disposent d’aucun arbre.","Entre la corrélation observée et la causalité réellement démontrée.","Entre l’effet supposé des arbres et celui d’autres facteurs comme la largeur des rues ou les matériaux.","Entre des variations ponctuelles de température et une tendance générale au réchauffement."],"correct":"B","explanation":"Réponse B : La conférencière insiste explicitement sur la nécessité de distinguer la corrélation observée (présence d’arbres et températures plus basses) de la causalité démontrée. C’est la distinction précise qu’elle demande d’opérer. A : Quelqu’un pourrait croire que la distinction porte sur la quantité d’arbres (quartiers très végétalisés vs. sans arbres), car la conférencière mentionne la différence de température selon la présence d’arbres. Cependant, elle ne demande pas d’opérer cette distinction précise, mais de réfléchir à la nature du lien entre arbres et température. C : Il est tentant de penser que la distinction porte sur l’effet des arbres par rapport à d’autres facteurs, car la conférencière mentionne d’autres influences. Cependant, elle ne demande pas de distinguer entre ces effets, mais bien entre corrélation et causalité. D : On pourrait croire que la distinction concerne la différence entre variations ponctuelles et tendance générale, car il est question de températures plus basses. Toutefois, la conférencière ne demande pas d’opérer cette distinction, mais bien celle entre corrélation et causalité.","transcript":"Question 31.\nVous écoutez un extrait de conférence sur les îlots de chaleur urbains. Nous observons que les quartiers comprenant davantage d'arbres présentent souvent des températures plus basses pendant l'été. Cette association ne signifie pas pour autant que chaque arbre planté produira automatiquement la même baisse de température. La largeur des rues, les matériaux des façades, le vent et l'accès à l'eau influencent également les mesures. Pour comprendre les mécanismes, il faut comparer les lieux avec prudence, suivre leur évolution et distinguer la corrélation constatée de la relation causale que nous sommes réellement capables de démontrer. Une politique de végétalisation peut être utile, mais son évaluation demande plus qu'un chiffre isolé.\nQuelle distinction précise la conférencière demande-t-elle d’opérer lorsqu’elle évoque les quartiers plus arborés ?","segments":[{"voice":"female","text":"Question 31."},{"voice":"female","text":"Vous écoutez un extrait de conférence sur les îlots de chaleur urbains. Nous observons que les quartiers comprenant davantage d'arbres présentent souvent des températures plus basses pendant l'été. Cette association ne signifie pas pour autant que chaque arbre planté produira automatiquement la même baisse de température. La largeur des rues, les matériaux des façades, le vent et l'accès à l'eau influencent également les mesures. Pour comprendre les mécanismes, il faut comparer les lieux avec prudence, suivre leur évolution et distinguer la corrélation constatée de la relation causale que nous sommes réellement capables de démontrer. Une politique de végétalisation peut être utile, mais son évaluation demande plus qu'un chiffre isolé."},{"voice":"female","text":"Quelle distinction précise la conférencière demande-t-elle d’opérer lorsqu’elle évoque les quartiers plus arborés ?"}],"audio":"q-31.mp3","audioSeconds":47.543,"slotSeconds":71},{"number":32,"kind":"interview","question":"Selon le scientifique, quelle manière de chiffrer le risque d’inondation est préférable à l’autre ?","options":["Donner une date très précise même si l’emplacement exact reste incertain.","Décrire le risque maison par maison plutôt qu’en parlant d’une zone exposée.","Annoncer une fourchette raisonnable plutôt qu’un chiffre unique trompeusement précis.","Insister surtout sur l’incertitude plutôt que sur l’utilité pratique de la prévision."],"correct":"C","explanation":"Réponse C : Le scientifique affirme explicitement qu'une fourchette raisonnable est préférable à un chiffre unique trompeusement précis. A : Quelqu'un pourrait croire qu'une date très précise est préférable, car la question mentionne la précision, mais le scientifique dit explicitement que la précision trompeuse est un problème. B : On pourrait penser que la description maison par maison est meilleure, car le scientifique évoque la différence, mais il ne dit pas que c'est préférable ; il souligne au contraire l'incertitude à ce niveau de détail. D : On pourrait croire qu'il faut insister surtout sur l'incertitude, mais le scientifique précise que reconnaître les limites ne signifie pas que toutes les opinions se valent, donc il ne privilégie pas l'incertitude sur l'utilité.","transcript":"Question 32.\nQuand vous annoncez un risque d'inondation sans pouvoir citer une date précise, certains pensent que vos prévisions ne servent à rien. Que leur répondez-vous ?\nJe leur explique la différence entre prévoir une zone exposée et décrire avec certitude ce qui se passera dans chaque maison. Une estimation peut aider à préparer les secours ou à éviter un aménagement dangereux même si elle comporte une marge d'incertitude. Nous devons décrire les observations, la méthode utilisée et ce qui pourrait changer notre conclusion. Donner un chiffre très précis sans expliquer ses limites peut être plus trompeur qu'annoncer une fourchette raisonnable. Reconnaître ces limites ne rend pas toutes les opinions équivalentes.\nSelon le scientifique, quelle manière de chiffrer le risque d’inondation est préférable à l’autre ?","segments":[{"voice":"female","text":"Question 32."},{"voice":"male","text":"Quand vous annoncez un risque d'inondation sans pouvoir citer une date précise, certains pensent que vos prévisions ne servent à rien. Que leur répondez-vous ?"},{"voice":"female","text":"Je leur explique la différence entre prévoir une zone exposée et décrire avec certitude ce qui se passera dans chaque maison. Une estimation peut aider à préparer les secours ou à éviter un aménagement dangereux même si elle comporte une marge d'incertitude. Nous devons décrire les observations, la méthode utilisée et ce qui pourrait changer notre conclusion. Donner un chiffre très précis sans expliquer ses limites peut être plus trompeur qu'annoncer une fourchette raisonnable. Reconnaître ces limites ne rend pas toutes les opinions équivalentes."},{"voice":"female","text":"Selon le scientifique, quelle manière de chiffrer le risque d’inondation est préférable à l’autre ?"}],"audio":"q-32.mp3","audioSeconds":48.771,"slotSeconds":70},{"number":33,"kind":"commentary","question":"Quelle réserve la chroniqueuse émet-elle sur l'indicateur économique présenté ?","options":["Il devrait être abandonné au profit d’un indicateur composite intégrant revenus et temps de travail.","Il exagère automatiquement l’amélioration réelle du marché du travail.","Il renseigne sur la tendance de l’emploi sans dire si les postes sont stables, bien rémunérés et compatibles avec la vie quotidienne.","Il devient trompeur dès qu’on inclut des emplois à temps partiel dans le calcul."],"correct":"C","explanation":"Réponse C : La chroniqueuse souligne que l'indicateur ne renseigne pas sur la stabilité, la rémunération ou la compatibilité des emplois avec la vie quotidienne. Elle insiste sur le fait qu'il ne donne pas d'informations qualitatives sur les emplois créés. A : La chroniqueuse suggère qu'un bilan plus juste devrait inclure d'autres critères, mais elle ne dit pas qu'il faut abandonner l'indicateur actuel au profit d'un indicateur composite. Elle nuance l'utilité de l'indicateur, sans prôner son abandon. B : La chroniqueuse ne dit pas que l'indicateur exagère automatiquement l'amélioration, mais qu'il ne donne pas une image complète. Elle reconnaît sa valeur pour suivre la tendance, ce qui contredit l'idée d'exagération systématique. D : La chroniqueuse évoque la question du temps partiel, mais elle ne dit pas que l'indicateur devient trompeur dès qu'on inclut des emplois à temps partiel. Elle met en avant le manque d'information sur la qualité de ces emplois, pas une tromperie automatique.","transcript":"Question 33.\nLe dernier bulletin régional annonce une hausse du taux d'emploi. Voilà une nouvelle encourageante, mais qui mérite un examen plus attentif. Combien de postes sont stables ? Les salariés disposent-ils d'horaires prévisibles ? Et ceux qui travaillent à temps partiel le font-ils par choix ou faute d'autre possibilité ? Un indicateur unique ne permet pas de répondre à ces questions. Il reste précieux pour suivre une tendance, à condition de ne pas en faire le portrait complet d'une économie. Un bilan plus juste regarderait aussi les revenus, la sécurité des contrats et la possibilité de concilier activité professionnelle et vie quotidienne.\nQuelle réserve la chroniqueuse émet-elle sur l'indicateur économique présenté ?","segments":[{"voice":"female","text":"Question 33."},{"voice":"female","text":"Le dernier bulletin régional annonce une hausse du taux d'emploi. Voilà une nouvelle encourageante, mais qui mérite un examen plus attentif. Combien de postes sont stables ? Les salariés disposent-ils d'horaires prévisibles ? Et ceux qui travaillent à temps partiel le font-ils par choix ou faute d'autre possibilité ? Un indicateur unique ne permet pas de répondre à ces questions. Il reste précieux pour suivre une tendance, à condition de ne pas en faire le portrait complet d'une économie. Un bilan plus juste regarderait aussi les revenus, la sécurité des contrats et la possibilité de concilier activité professionnelle et vie quotidienne."},{"voice":"female","text":"Quelle réserve la chroniqueuse émet-elle sur l'indicateur économique présenté ?"}],"audio":"q-33.mp3","audioSeconds":43.598,"slotSeconds":73},{"number":34,"kind":"roundtable","question":"Sur quel point précis les deux intervenants tombent-ils d'accord pour améliorer les démarches en ligne ?","options":["Concentrer l’évaluation du site sur le nombre de démarches entièrement finalisées plutôt que sur les simples connexions.","Faire tester le site par des usagers variés et conserver une aide humaine tant que les blocages persistent.","Remplacer progressivement l’aide humaine par des tutoriels vidéo accessibles depuis le site.","Revoir d’abord la rédaction des formulaires avant de penser à modifier l’interface en ligne."],"correct":"B","explanation":"Réponse B : Les deux intervenants tombent d'accord explicitement sur le fait de faire tester le site par des usagers variés et de maintenir une aide humaine tant que les problèmes persistent. L'accord est clairement exprimé par \"Je suis d'accord\". A : Un intervenant mentionne qu'ils mesurent les connexions plutôt que les démarches finalisées, ce qui pourrait laisser croire qu'ils souhaitent concentrer l’évaluation sur ce critère. Cependant, il n'est pas dit que les deux intervenants tombent d'accord sur ce point comme solution à adopter. C : Il pourrait être tentant de penser que l’aide humaine sera remplacée par des tutoriels vidéo, mais le texte insiste sur le maintien de l’aide humaine tant que les blocages persistent, ce qui contredit l’idée de la remplacer progressivement. D : Un intervenant évoque la complexité des formulaires, ce qui pourrait laisser croire qu’il faut d’abord revoir la rédaction. Cependant, la solution sur laquelle ils tombent d’accord concerne les tests utilisateurs et l’aide humaine, pas la rédaction des formulaires.","transcript":"Question 34.\nNous parlons aujourd'hui des démarches administratives en ligne. Pourquoi le nouveau site reste-t-il difficile à utiliser ?\nNous avons numérisé des formulaires complexes sans simplifier les étapes.\nEt les personnes qui ne comprennent pas le système reviennent au guichet avec un dossier incomplet. Ce sont souvent les mêmes difficultés qui se répètent.\nDe notre côté, nous mesurons le nombre de connexions, mais pas toujours le nombre de démarches réellement terminées.\nAlors, faisons tester les écrans par des usagers variés et maintenons une aide humaine tant que les problèmes ne sont pas résolus.\nJe suis d'accord, à condition que les observations puissent modifier le service.\nSur quel point précis les deux intervenants tombent-ils d'accord pour améliorer les démarches en ligne ?","segments":[{"voice":"female","text":"Question 34."},{"voice":"female","text":"Nous parlons aujourd'hui des démarches administratives en ligne. Pourquoi le nouveau site reste-t-il difficile à utiliser ?"},{"voice":"male","text":"Nous avons numérisé des formulaires complexes sans simplifier les étapes."},{"voice":"female","text":"Et les personnes qui ne comprennent pas le système reviennent au guichet avec un dossier incomplet. Ce sont souvent les mêmes difficultés qui se répètent."},{"voice":"male","text":"De notre côté, nous mesurons le nombre de connexions, mais pas toujours le nombre de démarches réellement terminées."},{"voice":"female","text":"Alors, faisons tester les écrans par des usagers variés et maintenons une aide humaine tant que les problèmes ne sont pas résolus."},{"voice":"male","text":"Je suis d'accord, à condition que les observations puissent modifier le service."},{"voice":"female","text":"Sur quel point précis les deux intervenants tombent-ils d'accord pour améliorer les démarches en ligne ?"}],"audio":"q-34.mp3","audioSeconds":47.491,"slotSeconds":70},{"number":35,"kind":"interview","question":"Selon l'ingénieure, quelle supposition initiale sur la performance énergétique s’est révélée trompeuse ?","options":["Que l’entretien du matériel est la principale cause des écarts entre prévisions et consommations.","Que des réglages complexes obligeront les occupants à adapter facilement leurs habitudes.","Que les performances mesurées en laboratoire suffisent à prédire la consommation réelle du bâtiment.","Que de bons panneaux solaires compensent automatiquement des usages imprévus des habitants."],"correct":"C","explanation":"Réponse C : L'ingénieure explique que la supposition trompeuse était de croire que les performances mesurées en laboratoire suffisaient à prédire la consommation réelle. Elle insiste sur l'écart entre conditions idéales et usage réel. A : Quelqu'un pourrait croire que l'entretien est la principale cause car l'ingénieure mentionne qu'il faut le revoir, mais elle ne dit pas que c'était la supposition initiale trompeuse. Elle insiste plutôt sur la différence entre laboratoire et usage réel. B : On pourrait penser que la supposition initiale était que les occupants s'adapteraient facilement, mais l'ingénieure ne dit pas que c'était une supposition de départ, seulement que la complexité pose problème. La supposition trompeuse concerne la prédiction basée sur le laboratoire. D : Quelqu'un pourrait croire que de bons panneaux solaires compensent les usages imprévus, car la performance des panneaux est mentionnée, mais l'ingénieure ne dit pas que c'était une supposition initiale. Elle parle plutôt de la différence entre prévisions et réalité d'usage.","transcript":"Question 35.\nVous avez installé des panneaux solaires très performants. Pourtant, le bâtiment consomme davantage d'électricité que prévu. Comment l'expliquez-vous ?\nNous avions comparé les équipements séparément, dans des conditions idéales. Sur place, certaines orientations ne sont pas optimales, et les habitants utilisent les appareils à des horaires que notre simulation n'avait pas anticipés. Les réglages sont aussi trop complexes : plusieurs personnes les contournent au lieu de les modifier. Ce n'est pas une raison pour leur reprocher de ne pas vivre comme dans un laboratoire. Nous devons observer les usages réels, revoir l'entretien et mesurer l'ensemble du système. Une bonne fiche technique ne suffit pas à décrire le résultat obtenu chaque jour.\nSelon l'ingénieure, quelle supposition initiale sur la performance énergétique s’est révélée trompeuse ?","segments":[{"voice":"female","text":"Question 35."},{"voice":"male","text":"Vous avez installé des panneaux solaires très performants. Pourtant, le bâtiment consomme davantage d'électricité que prévu. Comment l'expliquez-vous ?"},{"voice":"female","text":"Nous avions comparé les équipements séparément, dans des conditions idéales. Sur place, certaines orientations ne sont pas optimales, et les habitants utilisent les appareils à des horaires que notre simulation n'avait pas anticipés. Les réglages sont aussi trop complexes : plusieurs personnes les contournent au lieu de les modifier. Ce n'est pas une raison pour leur reprocher de ne pas vivre comme dans un laboratoire. Nous devons observer les usages réels, revoir l'entretien et mesurer l'ensemble du système. Une bonne fiche technique ne suffit pas à décrire le résultat obtenu chaque jour."},{"voice":"female","text":"Selon l'ingénieure, quelle supposition initiale sur la performance énergétique s’est révélée trompeuse ?"}],"audio":"q-35.mp3","audioSeconds":51.644,"slotSeconds":75},{"number":36,"kind":"interview","question":"Selon l’invitée, quel changement concret a rendu les ateliers intergénérationnels plus satisfaisants pour les participants ?","options":["Le fait de demander aux participants ce qu’ils voulaient vraiment partager et d’ajuster les ateliers en fonction de leurs envies.","L’augmentation du nombre de séances afin que les mêmes activités reviennent plus souvent dans l’année.","La décision de séparer les discussions libres des activités organisées dans des créneaux différents.","Le retour au programme initial où les jeunes enseignent l’informatique et les aînés racontent leurs souvenirs."],"correct":"A","explanation":"Réponse A : L'invitée explique que le changement concret a été de demander aux participants ce qu'ils voulaient vraiment partager et d'ajuster les ateliers en fonction de leurs envies, ce qui a permis une plus grande satisfaction. B : Quelqu'un pourrait croire que l'augmentation du nombre de séances améliore la satisfaction, mais l'invitée précise que ce n'est pas le cas et que la qualité des liens ne dépend pas du nombre de rendez-vous. C : On pourrait penser que les discussions libres ont été séparées des activités organisées, mais l'invitée dit seulement que certains préfèrent discuter, pas qu'il y a eu une séparation formelle. D : Quelqu'un pourrait croire que revenir au programme initial a amélioré la satisfaction, mais l'invitée explique que ce modèle ne convenait pas et a été abandonné.","transcript":"Question 36.\nVotre médiathèque accueille désormais des ateliers communs pour adolescents et retraités. Peut-on dire que cela suffit à lutter contre l'isolement ?\nNon, même si les occasions de rencontre sont précieuses. Au début, nous avions établi un programme très chargé, avec l'idée que les jeunes apprendraient l'informatique aux personnes âgées et que celles-ci raconteraient leurs souvenirs. Plusieurs participants ne se reconnaissaient pas dans ces rôles. Nous leur avons demandé ce qu'ils souhaitaient réellement partager. Une retraitée anime maintenant un atelier de jeux vidéo et un lycéen propose un club de jardinage. Certains préfèrent simplement discuter. L'essentiel est de pouvoir choisir, refuser une activité et construire progressivement une confiance réciproque. Le nombre de rendez-vous ne mesure pas à lui seul la qualité des liens.\nSelon l’invitée, quel changement concret a rendu les ateliers intergénérationnels plus satisfaisants pour les participants ?","segments":[{"voice":"female","text":"Question 36."},{"voice":"male","text":"Votre médiathèque accueille désormais des ateliers communs pour adolescents et retraités. Peut-on dire que cela suffit à lutter contre l'isolement ?"},{"voice":"female","text":"Non, même si les occasions de rencontre sont précieuses. Au début, nous avions établi un programme très chargé, avec l'idée que les jeunes apprendraient l'informatique aux personnes âgées et que celles-ci raconteraient leurs souvenirs. Plusieurs participants ne se reconnaissaient pas dans ces rôles. Nous leur avons demandé ce qu'ils souhaitaient réellement partager. Une retraitée anime maintenant un atelier de jeux vidéo et un lycéen propose un club de jardinage. Certains préfèrent simplement discuter. L'essentiel est de pouvoir choisir, refuser une activité et construire progressivement une confiance réciproque. Le nombre de rendez-vous ne mesure pas à lui seul la qualité des liens."},{"voice":"female","text":"Selon l’invitée, quel changement concret a rendu les ateliers intergénérationnels plus satisfaisants pour les participants ?"}],"audio":"q-36.mp3","audioSeconds":55.98,"slotSeconds":86},{"number":37,"kind":"interview","question":"Selon l’historienne, à quel moment les contradictions entre récits deviennent-elles vraiment intéressantes à conserver ?","options":["Quand elles portent sur un même détail factuel, comme une date ou un chiffre précis.","Quand on peut les analyser et retracer l’origine de chaque point de vue.","Quand elles disent toutes exactement la même chose que les archives officielles.","Quand il est impossible de trancher laquelle correspond le mieux à la réalité des faits."],"correct":"B","explanation":"Réponse B : C'est exactement ce que dit l'historienne : les contradictions sont intéressantes à conserver lorsqu'on peut les analyser et retracer l'origine de chaque point de vue. A : Quelqu'un pourrait croire que les contradictions sont intéressantes lorsqu'elles concernent un détail factuel, car l'historienne mentionne la vérification de faits précis. Cependant, elle explique que ce n'est pas là que les contradictions deviennent intéressantes à conserver, mais plutôt lorsqu'on peut en analyser l'origine. C : On pourrait croire que seules les versions identiques aux archives officielles sont retenues, car l'historienne parle de comparer aux documents d'époque. Mais elle précise que ce n'est pas le cas, et que toutes les affirmations ne se valent pas. D : Quelqu'un pourrait penser que les contradictions sont intéressantes lorsqu'il est impossible de savoir laquelle est vraie, mais l'historienne précise que toutes les affirmations ne se valent pas et qu'il s'agit d'expliquer leur origine, pas de rester dans l'incertitude.","transcript":"Question 37.\nVous avez recueilli des récits très différents sur la fermeture de l'ancien port. Comment décidez-vous lequel raconter dans votre exposition ?\nNous vérifions d'abord ce qui peut l'être : les décisions municipales, les dates et le nombre de travailleurs concernés. Mais les différences entre les souvenirs ne proviennent pas toujours d'une erreur. Un docker, un commerçant et une habitante qui vivait près des quais n'ont pas perçu l'événement de la même manière. Leurs témoignages montrent ce qu'ils pouvaient observer, ce qu'ils craignaient et ce qu'ils ont retenu. Nous conservons donc le contexte des entretiens et nous les comparons aux documents d'époque. Cela ne signifie pas que toutes les affirmations se valent. Les contradictions deviennent intéressantes lorsqu'on les examine et qu'on peut expliquer leur origine.\nSelon l’historienne, à quel moment les contradictions entre récits deviennent-elles vraiment intéressantes à conserver ?","segments":[{"voice":"female","text":"Question 37."},{"voice":"male","text":"Vous avez recueilli des récits très différents sur la fermeture de l'ancien port. Comment décidez-vous lequel raconter dans votre exposition ?"},{"voice":"female","text":"Nous vérifions d'abord ce qui peut l'être : les décisions municipales, les dates et le nombre de travailleurs concernés. Mais les différences entre les souvenirs ne proviennent pas toujours d'une erreur. Un docker, un commerçant et une habitante qui vivait près des quais n'ont pas perçu l'événement de la même manière. Leurs témoignages montrent ce qu'ils pouvaient observer, ce qu'ils craignaient et ce qu'ils ont retenu. Nous conservons donc le contexte des entretiens et nous les comparons aux documents d'époque. Cela ne signifie pas que toutes les affirmations se valent. Les contradictions deviennent intéressantes lorsqu'on les examine et qu'on peut expliquer leur origine."},{"voice":"female","text":"Selon l’historienne, à quel moment les contradictions entre récits deviennent-elles vraiment intéressantes à conserver ?"}],"audio":"q-37.mp3","audioSeconds":52.323,"slotSeconds":80},{"number":38,"kind":"public-lecture","question":"D’après l’intervenant, sur quels aspects du tourisme les responsables devraient-ils avant tout délibérer avec la communauté locale ?","options":["Sur les périodes de fréquentation, les modes de déplacement et les formes d’accueil à privilégier.","Sur les types de commerces touristiques à attirer, les loyers des locations saisonnières et les plafonds de nuitées.","Sur le nombre de logements à réserver aux habitants, la limitation des photos diffusées et les horaires d’ouverture des sites.","Sur la répartition des bénéfices de la promotion, les emplois créés et les compensations pour les nuisances."],"correct":"A","explanation":"Réponse A : L’intervenant insiste explicitement sur la nécessité de délibérer avec la communauté locale concernant les périodes de fréquentation, les modes de déplacement et les formes d’accueil à privilégier. Ces éléments sont cités mot à mot dans l’extrait. B : Cette option reprend des conséquences évoquées (logements, commerces), mais l’intervenant ne propose pas d’en discuter les types de commerces à attirer, les loyers ou les plafonds de nuitées avec la communauté. Il s’agit d’une extrapolation à partir de problèmes mentionnés, mais non d’aspects à délibérer selon l’intervenant. C : L’intervenant mentionne la transformation des logements, mais ne propose pas de discuter du nombre de logements à réserver aux habitants, ni de la limitation des photos ou des horaires d’ouverture. Cette option mélange des éléments évoqués (logements) avec d’autres absents du discours. D : L’intervenant critique le manque de prise en compte des conséquences économiques et sociales, mais il ne suggère pas de délibérer sur la répartition des bénéfices, les emplois ou les compensations. Cette option généralise la critique sans correspondre aux recommandations précises de l’intervenant.","transcript":"Question 38.\nVous écoutez un extrait de conférence publique sur le tourisme durable. Une photographie d'un village paisible peut susciter des milliers de visites, mais la réussite de sa diffusion transforme parfois profondément la vie locale. Les routes deviennent encombrées, certains logements se convertissent en locations temporaires et les habitants perdent des commerces nécessaires au quotidien. Les responsables ont alors tendance à célébrer la hausse des arrivées, sans toujours mesurer ce que cette affluence coûte au territoire. Il ne s'agit pas d'interdire toute visite ni de vouloir figer les villages. Il faut plutôt réfléchir aux périodes, aux modes de déplacement et aux conditions d'accueil que la communauté souhaite développer. Une destination peut être très recherchée tout en devenant moins agréable à vivre. Nous devons donc distinguer le succès d'une campagne et la qualité durable de ses conséquences.\nD’après l’intervenant, sur quels aspects du tourisme les responsables devraient-ils avant tout délibérer avec la communauté locale ?","segments":[{"voice":"female","text":"Question 38."},{"voice":"female","text":"Vous écoutez un extrait de conférence publique sur le tourisme durable. Une photographie d'un village paisible peut susciter des milliers de visites, mais la réussite de sa diffusion transforme parfois profondément la vie locale. Les routes deviennent encombrées, certains logements se convertissent en locations temporaires et les habitants perdent des commerces nécessaires au quotidien. Les responsables ont alors tendance à célébrer la hausse des arrivées, sans toujours mesurer ce que cette affluence coûte au territoire. Il ne s'agit pas d'interdire toute visite ni de vouloir figer les villages. Il faut plutôt réfléchir aux périodes, aux modes de déplacement et aux conditions d'accueil que la communauté souhaite développer. Une destination peut être très recherchée tout en devenant moins agréable à vivre. Nous devons donc distinguer le succès d'une campagne et la qualité durable de ses conséquences."},{"voice":"female","text":"D’après l’intervenant, sur quels aspects du tourisme les responsables devraient-ils avant tout délibérer avec la communauté locale ?"}],"audio":"q-38.mp3","audioSeconds":58.723,"slotSeconds":80},{"number":39,"kind":"interview","question":"Que recommande l’économiste comme prochaine étape pour que le café coopératif puisse durer ?","options":["Geler les dépenses en limitant les horaires d’ouverture afin de rester entièrement basé sur le bénévolat.","Chercher une nouvelle salle gratuite et recruter encore plus de bénévoles pour conserver le même fonctionnement.","Clarifier les dépenses, réorganiser horaires et remplacements, et envisager de payer certaines tâches.","Profiter de la forte fréquentation pour augmenter les prix sans modifier la répartition du travail."],"correct":"C","explanation":"Réponse C : C’est exactement ce que recommande l’économiste comme prochaine étape pour assurer la pérennité du café coopératif. A : Quelqu’un pourrait croire qu’il faut limiter les horaires pour ne pas épuiser les bénévoles, mais l’économiste ne recommande pas de geler les dépenses ni de rester entièrement basé sur le bénévolat. Au contraire, il propose d’envisager de rémunérer certaines tâches. B : On pourrait penser qu’il faut chercher une nouvelle salle gratuite et plus de bénévoles, mais l’économiste explique que ce modèle n’est pas durable car il ne garantit pas la répartition équitable du travail ni les revenus nécessaires. D : Quelqu’un pourrait croire qu’augmenter les prix suffirait, mais l’économiste précise que la fréquentation ne garantit pas la viabilité financière ni une bonne organisation du travail.","transcript":"Question 39.\nLe café coopératif du quartier a attiré beaucoup de monde pendant ses trois premiers mois. Pourquoi ne pas conserver exactement son organisation actuelle ?\nParce que l'essai reposait sur des circonstances particulières. La salle était mise gratuitement à disposition et les bénévoles ont fourni un effort exceptionnel que nous ne pouvons pas exiger chaque semaine. La fréquentation nous montre que les habitants souhaitent ce lieu, mais elle ne garantit ni les revenus nécessaires ni une répartition équitable du travail. Nous devons maintenant préciser les dépenses, discuter des horaires, prévoir les remplacements et peut-être rémunérer certaines tâches. Cela ne signifie pas renoncer à l'esprit de départ. Au contraire, il s'agit de créer les conditions qui permettront au projet de continuer sans épuiser les personnes qui l'ont rendu possible.\nQue recommande l’économiste comme prochaine étape pour que le café coopératif puisse durer ?","segments":[{"voice":"female","text":"Question 39."},{"voice":"male","text":"Le café coopératif du quartier a attiré beaucoup de monde pendant ses trois premiers mois. Pourquoi ne pas conserver exactement son organisation actuelle ?"},{"voice":"female","text":"Parce que l'essai reposait sur des circonstances particulières. La salle était mise gratuitement à disposition et les bénévoles ont fourni un effort exceptionnel que nous ne pouvons pas exiger chaque semaine. La fréquentation nous montre que les habitants souhaitent ce lieu, mais elle ne garantit ni les revenus nécessaires ni une répartition équitable du travail. Nous devons maintenant préciser les dépenses, discuter des horaires, prévoir les remplacements et peut-être rémunérer certaines tâches. Cela ne signifie pas renoncer à l'esprit de départ. Au contraire, il s'agit de créer les conditions qui permettront au projet de continuer sans épuiser les personnes qui l'ont rendu possible."},{"voice":"female","text":"Que recommande l’économiste comme prochaine étape pour que le café coopératif puisse durer ?"}],"audio":"q-39.mp3","audioSeconds":55.249,"slotSeconds":86}]},{"id":"tcf-listening-03","version":"tcf-listening-2026-11-test03-v4","title":"TCF Listening · Test 03","seconds":2100,"questions":[{"number":1,"kind":"image","question":"Quelle description correspond à l’image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"Réponse A : Sur l’image, on voit une personne derrière un comptoir (probablement le pharmacien) qui tend un objet rectangulaire (ressemblant à une boîte de médicaments) à une autre personne (la cliente). Cela correspond à la description : 'Le pharmacien tend une boîte de médicaments à la cliente.' B : Personne ne tient d’argent ni de carte bancaire, et aucun geste d’encaissement n’est visible. Quelqu’un pourrait croire à un paiement car il y a un échange d’objet, mais rien n’indique un paiement. C : La cliente reçoit un objet du pharmacien, elle ne remet rien. Quelqu’un pourrait croire qu’elle donne une ordonnance car l’objet est rectangulaire, mais le geste montre qu’elle le reçoit. D : Aucun élément visuel ne suggère une carte de fidélité (ni logo, ni format typique de carte). On pourrait confondre avec une carte à cause de la forme rectangulaire, mais l’objet ressemble plus à une boîte de médicaments.","transcript":"Question 1.\nRegardez l’image et écoutez les propositions.\nA. Le pharmacien tend une boîte de médicaments à la cliente. B. Le pharmacien encaisse le paiement de la cliente. C. La cliente remet une ordonnance au pharmacien. D. La cliente récupère une carte de fidélité au comptoir.","segments":[{"voice":"female","text":"Question 1."},{"voice":"female","text":"Regardez l’image et écoutez les propositions."},{"voice":"female","text":"A. Le pharmacien tend une boîte de médicaments à la cliente. B. Le pharmacien encaisse le paiement de la cliente. C. La cliente remet une ordonnance au pharmacien. D. La cliente récupère une carte de fidélité au comptoir."}],"audio":"q-01.mp3","audioSeconds":21.159,"slotSeconds":34,"image":"q-01.svg"},{"number":2,"kind":"image","question":"Quelle description correspond à l’image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"Réponse B : L'image montre clairement la patiente qui regarde le panneau d'affichage du numéro appelé, ce qui correspond à la description. A : On ne voit pas la patiente remplir un formulaire, il n'y a aucun papier ni stylo visible. C : Aucune carte n'est visible dans l'image, la patiente n'est pas en train de présenter un document. D : Il n'y a aucun échange d'argent ou de facture visible, la patiente est simplement assise.","transcript":"Question 2.\nRegardez l’image et écoutez les propositions.\nA. Une patiente complète un formulaire médical. B. Une patiente consulte le numéro affiché. C. Une patiente présente sa carte d’assurance. D. Une patiente règle sa facture médicale.","segments":[{"voice":"female","text":"Question 2."},{"voice":"female","text":"Regardez l’image et écoutez les propositions."},{"voice":"female","text":"A. Une patiente complète un formulaire médical. B. Une patiente consulte le numéro affiché. C. Une patiente présente sa carte d’assurance. D. Une patiente règle sa facture médicale."}],"audio":"q-02.mp3","audioSeconds":19.749,"slotSeconds":32,"image":"q-02.svg"},{"number":3,"kind":"image","question":"Quelle description correspond à l’image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"Réponse B : L’image montre une infirmière tendant ce qui ressemble à une solution hydro-alcoolique à un patient, ce qui correspond à la description d’une démonstration d’utilisation de solution hydro-alcoolique. A : On ne voit pas de gants sur l’image, ni de geste qui évoque l’enfilage de gants. Quelqu’un pourrait croire à cette option car l’infirmière tend un objet, mais il ne s’agit pas de gants. C : Il n’y a aucun signe de lavage des mains au savon (pas d’eau, pas de savon visible). Quelqu’un pourrait confondre avec une vérification d’hygiène, mais l’action montrée est différente. D : Aucune désinfection de plaie n’est visible, il n’y a pas de matériel médical ni de blessure apparente. On pourrait croire à une désinfection car l’infirmière touche la main, mais il n’y a pas de plaie.","transcript":"Question 3.\nRegardez l’image et écoutez les propositions.\nA. L’infirmière aide un patient à enfiler des gants avant un soin. B. L’infirmière montre à un patient comment utiliser une solution hydro-alcoolique. C. L’infirmière vérifie qu’un patient s’est bien lavé les mains au savon. D. L’infirmière désinfecte une plaie sur la main d’un patient.","segments":[{"voice":"female","text":"Question 3."},{"voice":"female","text":"Regardez l’image et écoutez les propositions."},{"voice":"female","text":"A. L’infirmière aide un patient à enfiler des gants avant un soin. B. L’infirmière montre à un patient comment utiliser une solution hydro-alcoolique. C. L’infirmière vérifie qu’un patient s’est bien lavé les mains au savon. D. L’infirmière désinfecte une plaie sur la main d’un patient."}],"audio":"q-03.mp3","audioSeconds":22.126,"slotSeconds":35,"image":"q-03.svg"},{"number":4,"kind":"image","question":"Quelle description correspond à l’image ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"Réponse D : L'image montre clairement un brassard de tensiomètre sur le bras du patient, ce qui correspond à la prise de la tension. A : On ne voit pas de stéthoscope ni de geste d'écoute du cœur. Quelqu'un pourrait confondre l'appareil tenu par le médecin avec un stéthoscope, mais il est placé sur le bras, ce qui n'est pas la position habituelle pour écouter le cœur. B : Il n'y a pas de thermomètre visible ni de geste associé à la prise de température. L'appareil est placé sur le bras, pas dans la bouche, l'oreille ou sous l'aisselle. C : Il n'y a pas de seringue ni de geste de prélèvement sanguin. Quelqu'un pourrait croire à une prise de sang car le bras est tendu, mais il n'y a pas de piqûre visible.","transcript":"Question 4.\nRegardez l’image et écoutez les propositions.\nA. Le médecin écoute le cœur du patient au stéthoscope. B. Le médecin prend la température du patient. C. Le médecin fait une prise de sang au patient. D. Le médecin prend la tension du patient.","segments":[{"voice":"female","text":"Question 4."},{"voice":"female","text":"Regardez l’image et écoutez les propositions."},{"voice":"female","text":"A. Le médecin écoute le cœur du patient au stéthoscope. B. Le médecin prend la température du patient. C. Le médecin fait une prise de sang au patient. D. Le médecin prend la tension du patient."}],"audio":"q-04.mp3","audioSeconds":18.547,"slotSeconds":34,"image":"q-04.svg"},{"number":5,"kind":"response","question":"Quelle réponse convient à la situation ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"Réponse C : Cette réponse répond directement à la question en confirmant que les résultats sont disponibles à l'accueil aujourd'hui, ce qui correspond exactement à la demande de l'interlocuteur. A : Cette réponse suggère de venir la semaine prochaine, ce qui pourrait être choisi si l'on pense que les résultats ne sont pas prêts aujourd'hui, mais rien dans la question n'indique un délai aussi long. La formulation 'semaine prochaine' n'est pas mentionnée ou sous-entendue. B : Quelqu'un pourrait penser que les résultats sont envoyés par courrier si la procédure habituelle était ainsi, mais la question porte sur une remise en main propre aujourd'hui. Rien n'indique que l'envoi postal est la seule option ou la réponse à la demande. D : Cette réponse pourrait être choisie si l'on croit que les résultats ne sont pas encore prêts, mais elle contredit la possibilité de venir les chercher aujourd'hui ('seulement demain matin'). La question porte sur aujourd'hui, donc cette réponse n'est pas appropriée.","transcript":"Question 5.\nBonjour, je peux venir chercher mes résultats d'analyse aujourd'hui ?\nA. Passez plutôt la semaine prochaine, s'il vous plaît. B. Non, ils vous seront envoyés par courrier. C. Oui, ils vous attendent à l'accueil. D. Ils seront prêts seulement demain matin.","segments":[{"voice":"female","text":"Question 5."},{"voice":"female","text":"Bonjour, je peux venir chercher mes résultats d'analyse aujourd'hui ?"},{"voice":"male","text":"A. Passez plutôt la semaine prochaine, s'il vous plaît. B. Non, ils vous seront envoyés par courrier. C. Oui, ils vous attendent à l'accueil. D. Ils seront prêts seulement demain matin."}],"audio":"q-05.mp3","audioSeconds":21.525,"slotSeconds":35},{"number":6,"kind":"response","question":"Quelle réponse convient à la situation ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"Réponse A : La personne a raté la date de son rendez-vous et demande quoi faire. La réponse la plus appropriée est de rappeler le secrétariat pour reprogrammer, car il faut prendre un nouveau rendez-vous. B : Quelqu’un pourrait croire qu’il faut simplement reporter au mois prochain, mais rien dans l’énoncé n’indique que le rendez-vous doit être aussi loin. La personne cherche une solution immédiate, pas un report lointain. C : On pourrait penser qu’il suffit de venir à l’heure prévue, mais comme la personne s’est trompée de jour, le rendez-vous n’a plus lieu à cette heure-là. Cette option ne répond donc pas à la situation. D : Attendre que le cabinet recontacte suppose que l’initiative viendra d’eux, mais la question montre que la personne cherche à agir elle-même. Il n’est pas dit que le cabinet prendra contact spontanément.","transcript":"Question 6.\nJe me suis trompé de jour pour mon rendez-vous. Que dois-je faire ?\nA. Rappelez le secrétariat pour reprogrammer. B. Reportez votre visite au mois prochain. C. Venez tout de même à l’heure prévue. D. Attendez, le cabinet vous recontactera.","segments":[{"voice":"female","text":"Question 6."},{"voice":"male","text":"Je me suis trompé de jour pour mon rendez-vous. Que dois-je faire ?"},{"voice":"female","text":"A. Rappelez le secrétariat pour reprogrammer. B. Reportez votre visite au mois prochain. C. Venez tout de même à l’heure prévue. D. Attendez, le cabinet vous recontactera."}],"audio":"q-06.mp3","audioSeconds":19.592,"slotSeconds":36},{"number":7,"kind":"response","question":"Quelle réponse convient à la situation ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"Réponse A : Cette réponse répond directement à la question en confirmant que la consultation est possible par téléphone, ce qui correspond exactement à la demande formulée. B : Quelqu’un pourrait croire que la consultation n’est possible que l’après-midi, mais la question porte sur le mode (téléphone), pas sur l’horaire. Cette réponse introduit une restriction de temps non mentionnée dans la question. C : Cette réponse pourrait être choisie si l’on pense que la consultation ne peut se faire qu’en présentiel, mais la question demande explicitement si le téléphone est possible. Cette réponse contredit donc la possibilité évoquée. D : Quelqu’un pourrait croire qu’il faut venir le lendemain, mais la question porte sur le mode de consultation, pas sur la date. Cette réponse ne répond pas à la question posée.","transcript":"Question 7.\nLa consultation peut-elle se faire par téléphone ?\nA. Oui, c’est possible par téléphone. B. Oui, mais uniquement l’après-midi. C. Non, seulement en présentiel. D. Non, il faut venir demain.","segments":[{"voice":"female","text":"Question 7."},{"voice":"female","text":"La consultation peut-elle se faire par téléphone ?"},{"voice":"male","text":"A. Oui, c’est possible par téléphone. B. Oui, mais uniquement l’après-midi. C. Non, seulement en présentiel. D. Non, il faut venir demain."}],"audio":"q-07.mp3","audioSeconds":18.913,"slotSeconds":32},{"number":8,"kind":"response","question":"Quelle réponse convient à la situation ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"Réponse C : La personne demande de l'aide pour retrouver le numéro du cabinet. Lui noter le numéro répond exactement à la demande formulée. A : Quelqu'un pourrait penser qu'appeler le standard de l'hôpital aiderait à retrouver le numéro, mais la personne demande explicitement de l'aide pour retrouver le numéro du cabinet, pas pour être redirigée vers un standard. B : On pourrait croire que la personne cherche le chemin, mais elle demande le numéro de téléphone, pas l'adresse ou l'itinéraire. D : Quelqu'un pourrait penser que les horaires affichés à l'entrée sont utiles, mais la demande porte sur le numéro du cabinet, pas sur les horaires.","transcript":"Question 8.\nJ'ai perdu la carte avec le numéro du cabinet. Vous pouvez m'aider ?\nA. Appelez le standard de l'hôpital. B. Je peux vous indiquer le chemin. C. Je vais vous noter le numéro. D. Les horaires sont affichés à l'entrée.","segments":[{"voice":"female","text":"Question 8."},{"voice":"male","text":"J'ai perdu la carte avec le numéro du cabinet. Vous pouvez m'aider ?"},{"voice":"female","text":"A. Appelez le standard de l'hôpital. B. Je peux vous indiquer le chemin. C. Je vais vous noter le numéro. D. Les horaires sont affichés à l'entrée."}],"audio":"q-08.mp3","audioSeconds":17.868,"slotSeconds":37},{"number":9,"kind":"announcement","question":"Où les patients doivent-ils se présenter ce matin ?","options":["Au premier étage, devant le bureau quatorze.","Au premier étage, devant le bureau douze, côté escalier de droite.","Au rez-de-chaussée, entre les urgences et le bureau douze.","Au rez-de-chaussée, devant le bureau douze, comme d’habitude."],"correct":"B","explanation":"Réponse B : C'est la seule option qui reprend tous les éléments donnés : premier étage, bureau douze, côté escalier de droite. Le texte est explicite. A : Cette option mentionne le bon étage (premier) mais se trompe de numéro de bureau. Quelqu’un ayant entendu 'premier étage' et 'bureau' pourrait confondre les numéros, mais le texte précise 'devant le bureau douze'. C : Cette option mélange le rez-de-chaussée (qui concerne les urgences) et le bureau douze. Quelqu’un pourrait confondre car le bureau douze est mentionné, mais le texte précise que l’accueil des consultations est déplacé au premier étage. D : Cette option correspond à la situation habituelle, mais le texte précise que ce matin, l’accueil est déplacé. Quelqu’un pourrait ignorer le changement temporaire et choisir l’habitude.","transcript":"Question 9.\nL'accueil des consultations est déplacé ce matin. Les urgences restent au rez-de-chaussée. Pour votre rendez-vous, montez au premier étage par l'escalier de droite. Un agent vous attend devant le bureau douze. Demain, l'accueil retrouvera son emplacement habituel.\nOù les patients doivent-ils se présenter ce matin ?","segments":[{"voice":"female","text":"Question 9."},{"voice":"female","text":"L'accueil des consultations est déplacé ce matin. Les urgences restent au rez-de-chaussée. Pour votre rendez-vous, montez au premier étage par l'escalier de droite. Un agent vous attend devant le bureau douze. Demain, l'accueil retrouvera son emplacement habituel."},{"voice":"female","text":"Où les patients doivent-ils se présenter ce matin ?"}],"audio":"q-09.mp3","audioSeconds":20.663,"slotSeconds":38},{"number":10,"kind":"dialogue","question":"Quelle décision prennent finalement la cliente et le pharmacien ?","options":["Attendre le retour de la marque initiale sans rien prendre entre-temps.","Réserver pour demain un générique après accord de sa médecin.","Faire renouveler l’ordonnance dans un autre cabinet avant de revenir.","Accepter immédiatement le générique proposé au comptoir."],"correct":"B","explanation":"Réponse B : La cliente accepte la réservation d’un générique pour le lendemain, à condition que sa médecin donne son accord, ce qui correspond exactement à l’option 2. A : La cliente n’a pas choisi d’attendre sans rien prendre ; elle accepte la réservation d’un générique sous condition d’accord médical. C : Personne ne propose d’aller dans un autre cabinet ; le pharmacien parle de contacter le cabinet de la médecin actuelle, pas d’en changer. D : La cliente refuse de prendre le générique immédiatement sans l’accord de sa médecin, donc cette option est contredite.","transcript":"Question 10.\nBonjour, je viens renouveler mon traitement. Voici mon ordonnance.\nNous n'avons plus les comprimés de cette marque, mais le même dosage existe en générique.\nMa médecin m'avait recommandé de ne pas changer sans la prévenir.\nDans ce cas, je peux réserver une boîte pour demain et contacter son cabinet pour vérifier la substitution.\nJe préfère cette solution, merci.\nQuelle décision prennent finalement la cliente et le pharmacien ?","segments":[{"voice":"female","text":"Question 10."},{"voice":"female","text":"Bonjour, je viens renouveler mon traitement. Voici mon ordonnance."},{"voice":"male","text":"Nous n'avons plus les comprimés de cette marque, mais le même dosage existe en générique."},{"voice":"female","text":"Ma médecin m'avait recommandé de ne pas changer sans la prévenir."},{"voice":"male","text":"Dans ce cas, je peux réserver une boîte pour demain et contacter son cabinet pour vérifier la substitution."},{"voice":"female","text":"Je préfère cette solution, merci."},{"voice":"female","text":"Quelle décision prennent finalement la cliente et le pharmacien ?"}],"audio":"q-10.mp3","audioSeconds":28.682,"slotSeconds":42},{"number":11,"kind":"announcement","question":"Que dit l’annonce au sujet du courriel de confirmation ?","options":["Qu’il doit être montré sur son téléphone à l’arrivée.","Qu’il doit être imprimé et présenté à l’accueil.","Qu’il n’est pas nécessaire de l’imprimer.","Qu’il tient lieu de pièce d’identité à l’entrée."],"correct":"C","explanation":"Réponse C : C’est exactement ce qui est dit dans l’annonce, il n’est pas nécessaire d’imprimer le courriel de confirmation. A : Quelqu’un pourrait penser qu’il faut montrer le courriel sur son téléphone, car il n’est pas demandé de l’imprimer, mais l’annonce ne précise pas qu’il doit être montré sur téléphone, seulement qu’il n’est pas nécessaire de l’imprimer. B : On pourrait croire qu’il faut l’imprimer et le présenter, mais l’annonce dit explicitement que ce n’est pas nécessaire. D : Quelqu’un pourrait confondre le courriel de confirmation avec la pièce d’identité demandée, mais l’annonce précise que c’est une pièce d’identité avec photo qui est exigée, pas le courriel.","transcript":"Question 11.\nLe centre de collecte remercie les personnes inscrites à la séance de samedi. Afin de faciliter l'enregistrement, présentez une pièce d'identité avec photographie. Le questionnaire de santé pourra être rempli sur place. Il n'est pas nécessaire d'imprimer le courriel de confirmation, mais pensez à respecter l'heure de votre réservation.\nQue dit l’annonce au sujet du courriel de confirmation ?","segments":[{"voice":"female","text":"Question 11."},{"voice":"male","text":"Le centre de collecte remercie les personnes inscrites à la séance de samedi. Afin de faciliter l'enregistrement, présentez une pièce d'identité avec photographie. Le questionnaire de santé pourra être rempli sur place. Il n'est pas nécessaire d'imprimer le courriel de confirmation, mais pensez à respecter l'heure de votre réservation."},{"voice":"female","text":"Que dit l’annonce au sujet du courriel de confirmation ?"}],"audio":"q-11.mp3","audioSeconds":26.044,"slotSeconds":40},{"number":12,"kind":"dialogue","question":"Comment s'organisent-ils finalement pour la consultation de la mère ?","options":["Demander une visite du médecin à domicile en matinée.","L'accompagner mardi au cabinet pour une consultation.","La faire venir au camion sur la place du village.","Prendre un rendez-vous pour la permanence à la résidence l'après-midi."],"correct":"D","explanation":"Réponse D : C'est la solution retenue : prendre rendez-vous pour la permanence à la résidence l'après-midi, ce qui est explicitement conseillé dans le texte. A : Quelqu'un pourrait penser qu'une visite à domicile est envisagée car la mère ne peut pas se déplacer seule, mais il est précisé que la solution retenue est la consultation à la résidence, pas à domicile. B : La tentation vient du fait que le camion est au village mardi, mais il est explicitement dit que la mère ne peut pas s'y rendre seule, donc cette option est écartée. C : On pourrait croire que la consultation au camion sur la place est envisagée, mais la mère ne peut pas s'y rendre, donc ce n'est pas la solution retenue.","transcript":"Question 12.\nLe camion de consultation sera au village mardi, mais ma mère ne peut pas se déplacer seule jusqu'à la place.\nIl passera ensuite à la résidence, à quinze heures.\nC'est beaucoup plus simple. Est-ce que je dois appeler pour réserver ?\nOui, demandez un rendez-vous pour la permanence à la résidence. Elle n'aura pas besoin de venir au centre du village.\nComment s'organisent-ils finalement pour la consultation de la mère ?","segments":[{"voice":"female","text":"Question 12."},{"voice":"male","text":"Le camion de consultation sera au village mardi, mais ma mère ne peut pas se déplacer seule jusqu'à la place."},{"voice":"female","text":"Il passera ensuite à la résidence, à quinze heures."},{"voice":"male","text":"C'est beaucoup plus simple. Est-ce que je dois appeler pour réserver ?"},{"voice":"female","text":"Oui, demandez un rendez-vous pour la permanence à la résidence. Elle n'aura pas besoin de venir au centre du village."},{"voice":"female","text":"Comment s'organisent-ils finalement pour la consultation de la mère ?"}],"audio":"q-12.mp3","audioSeconds":27.69,"slotSeconds":43},{"number":13,"kind":"announcement","question":"Que précise l’annonce au sujet de la livraison de doses attendue lundi ?","options":["Elle a été entièrement annulée.","Elle est arrivée plus tard que prévu.","Elle a été refusée pour cause de défaut.","Elle est arrivée incomplète."],"correct":"D","explanation":"Réponse D : L’annonce précise explicitement que la livraison de doses attendue lundi est arrivée incomplète, ce qui correspond exactement à cette option. A : Quelqu’un pourrait croire que la livraison a été annulée car il y a un changement de date et l’annonce parle d’un nouveau lot, mais il est précisé qu’elle est arrivée, bien que partielle, donc elle n’a pas été annulée. B : On pourrait penser qu’un retard a eu lieu à cause du report des injections, mais le texte ne mentionne aucun retard, seulement que la livraison était incomplète. C : Quelqu’un pourrait croire que la livraison a été refusée à cause d’un défaut, car un nouveau lot est attendu, mais il n’est pas question de refus ni de défaut, seulement d’une livraison partielle.","transcript":"Question 13.\nNous informons les personnes inscrites à la campagne de vaccination de mercredi que les injections auront lieu vendredi aux mêmes horaires. La livraison de doses attendue lundi est arrivée incomplète et un nouveau lot sera disponible jeudi. Toutes les réservations sont conservées; aucun nouvel enregistrement n'est nécessaire.\nQue précise l’annonce au sujet de la livraison de doses attendue lundi ?","segments":[{"voice":"female","text":"Question 13."},{"voice":"female","text":"Nous informons les personnes inscrites à la campagne de vaccination de mercredi que les injections auront lieu vendredi aux mêmes horaires. La livraison de doses attendue lundi est arrivée incomplète et un nouveau lot sera disponible jeudi. Toutes les réservations sont conservées; aucun nouvel enregistrement n'est nécessaire."},{"voice":"female","text":"Que précise l’annonce au sujet de la livraison de doses attendue lundi ?"}],"audio":"q-13.mp3","audioSeconds":23.249,"slotSeconds":39},{"number":14,"kind":"dialogue","question":"Selon l’infirmière, dans quel cas le parent doit-il composer immédiatement le numéro d’urgence ?","options":["Si la fièvre reste élevée malgré le traitement habituel.","Si la fillette refuse de boire ou paraît encore plus fatiguée.","Si son état ne s’est pas amélioré d’ici ce soir, en appelant le médecin de garde.","Si la fillette respire difficilement ou devient difficile à réveiller."],"correct":"D","explanation":"Réponse D : C’est exactement ce que dit l’infirmière : l’appel immédiat aux secours est réservé à ces symptômes précis. A : Quelqu’un pourrait croire que la fièvre persistante nécessite un appel immédiat, car la mère mentionne la fièvre et l’infirmière conseille de surveiller l’état et de contacter le médecin. Cependant, elle ne dit pas d’appeler les secours pour une fièvre persistante, mais seulement de contacter le médecin. B : La fillette est déjà très fatiguée, mais l’infirmière ne dit pas d’appeler les secours pour la fatigue ou le refus de boire, seulement de surveiller et de contacter le médecin. L’appel immédiat aux secours n’est conseillé que pour des difficultés respiratoires ou un état de conscience altéré. C : L’infirmière dit de contacter le médecin si l’état ne s’améliore pas, mais ne demande pas d’appeler immédiatement les secours dans ce cas. Ce conseil concerne un suivi médical, pas une urgence vitale.","transcript":"Question 14.\nMa fille a de la fièvre depuis hier. Elle boit encore, mais elle est très fatiguée. Dois-je venir tout de suite ?\nJe ne peux pas poser un diagnostic par téléphone. Surveillez son état et contactez votre médecin aujourd'hui. Si elle respire difficilement ou devient difficile à réveiller, appelez immédiatement les secours.\nJe comprends. Je vais téléphoner à son cabinet.\nSelon l’infirmière, dans quel cas le parent doit-il composer immédiatement le numéro d’urgence ?","segments":[{"voice":"female","text":"Question 14."},{"voice":"male","text":"Ma fille a de la fièvre depuis hier. Elle boit encore, mais elle est très fatiguée. Dois-je venir tout de suite ?"},{"voice":"female","text":"Je ne peux pas poser un diagnostic par téléphone. Surveillez son état et contactez votre médecin aujourd'hui. Si elle respire difficilement ou devient difficile à réveiller, appelez immédiatement les secours."},{"voice":"male","text":"Je comprends. Je vais téléphoner à son cabinet."},{"voice":"female","text":"Selon l’infirmière, dans quel cas le parent doit-il composer immédiatement le numéro d’urgence ?"}],"audio":"q-14.mp3","audioSeconds":32.235,"slotSeconds":46},{"number":15,"kind":"radio-news","question":"Dans le dispositif décrit, que prévoit-on précisément pour le partage des observations faites par les pharmaciens ?","options":["Elles resteront dans chaque pharmacie, sans communication extérieure prévue.","Elles seront envoyées directement aux services d’assurance maladie pour suivi statistique.","Elles seront transmises au médecin traitant, avec l’accord des patients.","Elles serviront uniquement à une évaluation anonyme prévue au printemps."],"correct":"C","explanation":"Réponse C : Le texte indique clairement que les observations seront transmises au médecin traitant, avec l’accord des patients. C’est la seule option qui correspond exactement à ce qui est décrit. A : Quelqu’un pourrait croire que les observations restent dans chaque pharmacie car il n’est pas question de communication extérieure large, mais le texte précise explicitement qu’elles sont transmises au médecin traitant. B : On pourrait penser que les observations sont envoyées à l’assurance maladie pour un suivi statistique, car il est question d’un dispositif de santé, mais le texte ne mentionne que la transmission au médecin traitant. D : Il est mentionné qu’une évaluation aura lieu au printemps, ce qui pourrait faire croire que les observations servent uniquement à cette évaluation. Cependant, le texte précise que les observations sont d’abord transmises au médecin traitant.","transcript":"Question 15.\nDans les nouvelles de santé locale, cinq pharmacies vont proposer un suivi régulier aux personnes sous plusieurs traitements. Les pharmaciens ne modifieront pas les prescriptions. Ils vérifieront avec les patients les horaires de prise, les oublis fréquents et les éventuelles difficultés à comprendre les notices, puis transmettront leurs observations au médecin traitant avec l'accord des intéressés. Une évaluation aura lieu au printemps.\nDans le dispositif décrit, que prévoit-on précisément pour le partage des observations faites par les pharmaciens ?","segments":[{"voice":"female","text":"Question 15."},{"voice":"female","text":"Dans les nouvelles de santé locale, cinq pharmacies vont proposer un suivi régulier aux personnes sous plusieurs traitements. Les pharmaciens ne modifieront pas les prescriptions. Ils vérifieront avec les patients les horaires de prise, les oublis fréquents et les éventuelles difficultés à comprendre les notices, puis transmettront leurs observations au médecin traitant avec l'accord des intéressés. Une évaluation aura lieu au printemps."},{"voice":"female","text":"Dans le dispositif décrit, que prévoit-on précisément pour le partage des observations faites par les pharmaciens ?"}],"audio":"q-15.mp3","audioSeconds":32.392,"slotSeconds":48},{"number":16,"kind":"dialogue","question":"Pourquoi la séance de conseil nutritionnel est-elle raccourcie ?","options":["Parce que la diététicienne doit ensuite effectuer une visite dans un foyer.","Afin de réserver tout le temps disponible à l’analyse des habitudes alimentaires.","Pour pouvoir traiter le reste des questions lors d’un entretien ultérieur à distance.","Parce que le jeudi son planning est déjà surchargé de patients."],"correct":"A","explanation":"Réponse A : La raison donnée explicitement dans le stimulus est que la diététicienne doit effectuer une visite dans un foyer après son service, ce qui explique la réduction de la durée de la séance. B : Quelqu'un pourrait croire que la séance est raccourcie pour se concentrer sur l'analyse des habitudes alimentaires, car il est dit que cet aspect sera maintenu. Cependant, la raison réelle de la réduction de la durée est la visite dans un foyer, non une volonté de réserver tout le temps à l'analyse. C : Il est vrai qu'un entretien ultérieur à distance est prévu, mais ce n'est pas la raison pour laquelle la séance initiale est raccourcie. La réduction de la durée est due à la visite dans un foyer, pas pour traiter le reste des questions plus tard. D : Quelqu'un pourrait penser que le planning du jeudi est surchargé, car il y a une contrainte de temps, mais il est précisé que ce n'est pas à cause du nombre de patients, mais bien à cause d'une visite spécifique à effectuer après le service.","transcript":"Question 16.\nLe rendez-vous de jeudi durera finalement trente minutes au lieu de quarante-cinq.\nEst-ce à cause du nombre de patients ?\nNon, la diététicienne assurera aussi une visite dans un foyer après son service. Nous garderons l'entretien sur vos habitudes alimentaires et prévoirons un second échange à distance pour les questions complémentaires.\nD'accord, je préparerai mon carnet de repas.\nPourquoi la séance de conseil nutritionnel est-elle raccourcie ?","segments":[{"voice":"female","text":"Question 16."},{"voice":"female","text":"Le rendez-vous de jeudi durera finalement trente minutes au lieu de quarante-cinq."},{"voice":"male","text":"Est-ce à cause du nombre de patients ?"},{"voice":"female","text":"Non, la diététicienne assurera aussi une visite dans un foyer après son service. Nous garderons l'entretien sur vos habitudes alimentaires et prévoirons un second échange à distance pour les questions complémentaires."},{"voice":"male","text":"D'accord, je préparerai mon carnet de repas."},{"voice":"female","text":"Pourquoi la séance de conseil nutritionnel est-elle raccourcie ?"}],"audio":"q-16.mp3","audioSeconds":28.238,"slotSeconds":42},{"number":17,"kind":"announcement","question":"Par quelle entrée faut-il rejoindre le cabinet ?","options":["Par le portail du parking situé derrière l’immeuble.","Par la porte principale qui donne sur l’avenue des Acacias.","Par l’entrée secondaire attenante à la réception du cabinet.","Par le passage de la cour accessible depuis la rue des Écoles."],"correct":"D","explanation":"Réponse D : Le texte indique clairement que l’accès se fait par la cour intérieure accessible depuis la rue des Écoles, ce qui correspond exactement à cette option. A : La mention du portail du parking derrière l’immeuble pourrait prêter à confusion avec une entrée alternative, mais le texte précise que l’accès se fait par la cour intérieure depuis la rue des Écoles, et non par un parking. B : Quelqu’un pourrait croire que la porte principale reste accessible, mais le texte indique explicitement qu’elle est fermée à cause des travaux. C : L’entrée secondaire attenante à la réception n’est pas mentionnée comme accès possible ; seul l’accès par la cour intérieure est indiqué.","transcript":"Question 17.\nEn raison des travaux devant le cabinet des Acacias, la porte principale donnant sur l'avenue sera fermée jusqu'à vendredi. Les patients doivent entrer par la cour intérieure, accessible depuis la rue des Écoles. La signalisation a été installée ce matin, et la réception est assurée normalement.\nPar quelle entrée faut-il rejoindre le cabinet ?","segments":[{"voice":"female","text":"Question 17."},{"voice":"male","text":"En raison des travaux devant le cabinet des Acacias, la porte principale donnant sur l'avenue sera fermée jusqu'à vendredi. Les patients doivent entrer par la cour intérieure, accessible depuis la rue des Écoles. La signalisation a été installée ce matin, et la réception est assurée normalement."},{"voice":"female","text":"Par quelle entrée faut-il rejoindre le cabinet ?"}],"audio":"q-17.mp3","audioSeconds":23.249,"slotSeconds":48},{"number":18,"kind":"telephone","question":"Pour quelle raison précise la secrétaire annonce-t-elle que le secrétariat spécialisé rappellera le patient ?","options":["Pour expliquer les délais d’attente en dermatologie avant de décider s’il faut changer le rendez-vous.","Pour valider avec le médecin si la demande de cardiologie doit être maintenue malgré la préférence pour la dermatologie.","Pour simplement confirmer l’horaire du rendez-vous déjà enregistré sans modifier la spécialité demandée.","Pour lever la confusion entre les deux dossiers au même nom et orienter le rendez-vous vers le bon service."],"correct":"D","explanation":"Réponse D : La secrétaire explique clairement qu’il y a deux dossiers au même nom et qu’elle souhaite vérifier l’identité du patient avant d’orienter le rendez-vous vers le bon service. Le rappel vise donc à lever la confusion entre les deux dossiers et à s’assurer que le patient sera dirigé vers la bonne spécialité. A : Quelqu’un pourrait croire que le rappel vise à expliquer les délais ou à décider d’un changement de rendez-vous, car le patient mentionne une demande différente (cardiologie vs dermatologie). Cependant, la secrétaire précise qu’il y a deux dossiers au même nom et qu’elle préfère vérifier la date de naissance, ce qui montre que le rappel sert à lever la confusion d’identité, pas à expliquer des délais. B : On pourrait penser que le rappel sert à valider avec le médecin la spécialité à maintenir, car il y a confusion entre cardiologie et dermatologie. Mais la secrétaire ne parle pas de consulter un médecin, seulement de vérifier l’identité du patient à cause des deux dossiers au même nom. C : Certains pourraient croire que le rappel vise simplement à confirmer l’horaire du rendez-vous, car la secrétaire ne propose pas de modification immédiate. Mais elle insiste sur la nécessité de vérifier l’identité à cause de la confusion entre deux dossiers, ce qui va au-delà d’une simple confirmation d’horaire.","transcript":"Question 18.\nCabinet du docteur Perrin, bonjour.\nJe viens d'avoir un message pour un rendez-vous en cardiologie, mais j'avais demandé la dermatologie.\nJe vois deux dossiers au même nom. Je préfère vérifier votre date de naissance sans discuter de renseignements médicaux au téléphone. Le secrétariat spécialisé pourra vous rappeler dans l'heure.\nTrès bien, je garde mon téléphone près de moi.\nPour quelle raison précise la secrétaire annonce-t-elle que le secrétariat spécialisé rappellera le patient ?","segments":[{"voice":"female","text":"Question 18."},{"voice":"female","text":"Cabinet du docteur Perrin, bonjour."},{"voice":"male","text":"Je viens d'avoir un message pour un rendez-vous en cardiologie, mais j'avais demandé la dermatologie."},{"voice":"female","text":"Je vois deux dossiers au même nom. Je préfère vérifier votre date de naissance sans discuter de renseignements médicaux au téléphone. Le secrétariat spécialisé pourra vous rappeler dans l'heure."},{"voice":"male","text":"Très bien, je garde mon téléphone près de moi."},{"voice":"female","text":"Pour quelle raison précise la secrétaire annonce-t-elle que le secrétariat spécialisé rappellera le patient ?"}],"audio":"q-18.mp3","audioSeconds":31.582,"slotSeconds":47},{"number":19,"kind":"announcement","question":"Que prévoit l’organisation pour la marche accompagnée en cas de forte pluie ?","options":["Elle est raccourcie mais maintenue dans le parc.","Elle est simplement annulée, sans autre proposition.","Elle est remplacée par une séance de mobilité sous le préau.","Elle est déplacée dans la salle bleue."],"correct":"C","explanation":"Réponse C : Le texte indique clairement que la marche est remplacée par une séance de mobilité sous le préau en cas de forte pluie, ce qui correspond exactement à cette option. A : Quelqu’un pourrait croire que la marche est simplement raccourcie et maintenue dans le parc, car il est mentionné qu'il s'agit d'une 'courte marche', mais le texte précise bien qu'en cas de forte pluie, elle est remplacée, pas maintenue. B : On pourrait penser que l’activité est simplement annulée, mais le texte indique explicitement qu’elle est remplacée par une autre activité, donc il y a une alternative prévue. D : Quelqu’un pourrait confondre la salle bleue, mentionnée pour les conseils sur l’alimentation, avec le lieu de remplacement de la marche, mais le texte précise que la marche est remplacée par une séance sous le préau, pas dans la salle bleue.","transcript":"Question 19.\nLa journée de prévention de samedi proposera des démonstrations à l'intérieur du centre et une courte marche accompagnée dans le parc voisin. Les conseils sur l'alimentation auront lieu dans la salle bleue. En cas de forte pluie, seule la marche sera remplacée par une séance de mobilité sous le préau.\nQue prévoit l’organisation pour la marche accompagnée en cas de forte pluie ?","segments":[{"voice":"female","text":"Question 19."},{"voice":"female","text":"La journée de prévention de samedi proposera des démonstrations à l'intérieur du centre et une courte marche accompagnée dans le parc voisin. Les conseils sur l'alimentation auront lieu dans la salle bleue. En cas de forte pluie, seule la marche sera remplacée par une séance de mobilité sous le préau."},{"voice":"female","text":"Que prévoit l’organisation pour la marche accompagnée en cas de forte pluie ?"}],"audio":"q-19.mp3","audioSeconds":23.04,"slotSeconds":41},{"number":20,"kind":"dialogue","question":"Que décide le médecin pour adapter la reprise de la marche à la situation de la patiente ?","options":["Il lui conseille de s’entraîner d’abord à monter et descendre les escaliers de son immeuble avec l’aide d’un proche.","Il suggère de reporter la reprise de la marche tant que l’ascenseur de l’immeuble reste en panne.","Il propose de commencer par de courts trajets sur terrain plat et d’organiser une évaluation avec la kinésithérapeute.","Il prévoit des séances de rééducation exclusivement à domicile pour éviter tout déplacement à l’extérieur."],"correct":"C","explanation":"Réponse C : C’est exactement ce que propose le médecin pour adapter la reprise de la marche à la situation de la patiente : commencer par de courts trajets sur terrain plat et organiser une évaluation avec la kinésithérapeute. A : Quelqu’un pourrait croire qu’il s’agit de s’entraîner dans les escaliers, car la patiente évoque son inquiétude à propos de l’ascenseur et des escaliers. Cependant, le médecin propose explicitement d’éviter les escaliers en privilégiant le terrain plat. B : On pourrait penser qu’il faut reporter la reprise tant que l’ascenseur est en panne, car la patiente mentionne ce problème. Mais le médecin ne propose pas de reporter, il adapte simplement la reprise à la situation. D : Quelqu’un pourrait croire que le médecin veut éviter tout déplacement à l’extérieur à cause des escaliers, mais il propose bien des trajets, ce qui implique des déplacements hors du domicile.","transcript":"Question 20.\nLes résultats sont encourageants. Vous pourrez bientôt reprendre la marche.\nJe suis soulagée, mais j'habite au quatrième étage et l'ascenseur tombe régulièrement en panne.\nDans ce cas, commençons par de petits trajets sur terrain plat et prévoyons une évaluation avec la kinésithérapeute.\nOui, je ne veux pas me retrouver bloquée dans l'escalier.\nQue décide le médecin pour adapter la reprise de la marche à la situation de la patiente ?","segments":[{"voice":"female","text":"Question 20."},{"voice":"male","text":"Les résultats sont encourageants. Vous pourrez bientôt reprendre la marche."},{"voice":"female","text":"Je suis soulagée, mais j'habite au quatrième étage et l'ascenseur tombe régulièrement en panne."},{"voice":"male","text":"Dans ce cas, commençons par de petits trajets sur terrain plat et prévoyons une évaluation avec la kinésithérapeute."},{"voice":"female","text":"Oui, je ne veux pas me retrouver bloquée dans l'escalier."},{"voice":"female","text":"Que décide le médecin pour adapter la reprise de la marche à la situation de la patiente ?"}],"audio":"q-20.mp3","audioSeconds":28.682,"slotSeconds":46},{"number":21,"kind":"announcement","question":"D’après le document, quel déséquilibre précis l’équipe constate déjà dans les disponibilités annoncées des bénévoles ?","options":["Les bénévoles se répartissent assez régulièrement sur toute la journée, sans vraie pointe ni manque net.","Les horaires de soirée sont saturés, tandis que le matin attire peu de volontaires.","Les créneaux du début d’après-midi restent les moins demandés.","Les propositions de présence se concentrent sur le matin, alors que la fin de journée reste presque vide."],"correct":"D","explanation":"Réponse D : C’est exactement ce que dit le document : il y a une concentration des disponibilités le matin et un manque net en fin de journée. A : Quelqu’un pourrait croire à une répartition régulière si il n’écoute pas la partie sur le manque en fin de journée, mais le document indique clairement un déséquilibre entre le matin (plusieurs personnes) et la fin de journée (très peu). B : On pourrait confondre le matin et le soir, mais le texte ne mentionne pas de saturation le soir, seulement un manque en fin de journée. Il n’est pas dit que le matin attire peu de volontaires, au contraire. C : Le texte ne mentionne pas les débuts d’après-midi comme étant problématiques, seulement la fin de journée. Quelqu’un pourrait supposer que le début d’après-midi est concerné s’il généralise le manque à toute la seconde moitié de la journée, mais ce n’est pas précisé.","transcript":"Question 21.\nL'équipe de la clinique associative prépare les permanences de la semaine prochaine. Les bénévoles qui souhaitent aider à l'accueil sont invités à indiquer leurs créneaux exacts d'ici jeudi. Plusieurs personnes sont disponibles le matin, mais très peu en fin de journée. Nous devons répartir les présences pour ne pas laisser les patients sans orientation lorsque les salariés terminent leur service.\nD’après le document, quel déséquilibre précis l’équipe constate déjà dans les disponibilités annoncées des bénévoles ?","segments":[{"voice":"female","text":"Question 21."},{"voice":"male","text":"L'équipe de la clinique associative prépare les permanences de la semaine prochaine. Les bénévoles qui souhaitent aider à l'accueil sont invités à indiquer leurs créneaux exacts d'ici jeudi. Plusieurs personnes sont disponibles le matin, mais très peu en fin de journée. Nous devons répartir les présences pour ne pas laisser les patients sans orientation lorsque les salariés terminent leur service."},{"voice":"female","text":"D’après le document, quel déséquilibre précis l’équipe constate déjà dans les disponibilités annoncées des bénévoles ?"}],"audio":"q-21.mp3","audioSeconds":32.496,"slotSeconds":53},{"number":22,"kind":"interview","question":"Selon le médecin, quelle serait une façon trompeuse d’évaluer l’action du cabinet mobile ?","options":["En se limitant à compter le nombre de visites.","En vérifiant systématiquement si les dossiers ont bien été transmis.","En s’intéressant surtout aux difficultés de distance pour les patients.","En prenant en compte aussi les examens complémentaires réalisés."],"correct":"A","explanation":"Réponse A : Le médecin dit explicitement qu'il serait trompeur de se limiter au nombre de visites pour évaluer l'action du cabinet mobile. B : Quelqu’un pourrait croire que la transmission des dossiers est un critère trompeur, mais le médecin insiste justement sur son importance pour assurer la continuité des soins. C : La distance est mentionnée comme une difficulté, mais ce n’est pas présenté comme un critère d’évaluation trompeur ; c’est un obstacle réel, pas une façon d’évaluer l’action. D : Le médecin cite la prise en compte des examens complémentaires comme un aspect important du suivi, donc ce n’est pas une façon trompeuse d’évaluer l’action.","transcript":"Question 22.\nVotre équipe se rend dans les villages éloignés avec un cabinet mobile. Qu'est-ce qui vous paraît le plus difficile ?\nLa distance est un obstacle, bien sûr, mais on se tromperait en comptant seulement le nombre de visites. Une consultation ponctuelle peut repérer un problème sans assurer la suite. Nous devons transmettre le dossier avec le consentement du patient, vérifier qu'il a trouvé un professionnel près de chez lui et l'aider lorsqu'un examen complémentaire est nécessaire. Sans cette continuité, le passage du camion devient une bonne intention dont les effets restent limités.\nSelon le médecin, quelle serait une façon trompeuse d’évaluer l’action du cabinet mobile ?","segments":[{"voice":"female","text":"Question 22."},{"voice":"male","text":"Votre équipe se rend dans les villages éloignés avec un cabinet mobile. Qu'est-ce qui vous paraît le plus difficile ?"},{"voice":"female","text":"La distance est un obstacle, bien sûr, mais on se tromperait en comptant seulement le nombre de visites. Une consultation ponctuelle peut repérer un problème sans assurer la suite. Nous devons transmettre le dossier avec le consentement du patient, vérifier qu'il a trouvé un professionnel près de chez lui et l'aider lorsqu'un examen complémentaire est nécessaire. Sans cette continuité, le passage du camion devient une bonne intention dont les effets restent limités."},{"voice":"female","text":"Selon le médecin, quelle serait une façon trompeuse d’évaluer l’action du cabinet mobile ?"}],"audio":"q-22.mp3","audioSeconds":39.68,"slotSeconds":61},{"number":23,"kind":"panel-discussion","question":"Finalement, quelle organisation du tri téléphonique décident-ils d’adopter pour les appels non urgents ?","options":["Limiter le tri initial aux appels manifestement non urgents, en orientant directement les autres vers les urgences, puis en corrigeant les erreurs après coup.","Utiliser un questionnaire automatique comme premier filtre, en ne faisant vérifier manuellement qu’un échantillon d’appels au début.","Mettre en place un tri initial par une petite équipe dédiée, avec transfert rapide des cas douteux à un infirmier et contrôle temporaire des erreurs d’aiguillage.","Confier l’ensemble des appels dès le premier contact aux infirmiers, sans étape préalable, afin de ne pas allonger l’attente."],"correct":"C","explanation":"Réponse C : C'est exactement la solution retenue : une petite équipe fait le tri initial, les cas douteux sont transférés à un infirmier, et un contrôle temporaire est prévu pour vérifier les erreurs d’aiguillage. A : Cette option suppose que seuls les appels manifestement non urgents sont triés initialement, et que les autres sont envoyés directement aux urgences, ce qui n'est pas mentionné. Le texte parle d'une équipe qui fait un tri initial, puis transfère les cas douteux à un infirmier, pas d'un tri limité ou d'un transfert direct aux urgences. B : Quelqu’un pourrait penser à un questionnaire automatique car il est mentionné, mais il est explicitement rejeté par un intervenant. D : Quelqu’un pourrait croire que la solution est de confier tous les appels directement aux infirmiers pour éviter d’allonger l’attente, mais cette option n’est pas retenue ; au contraire, il est question de limiter la surcharge des infirmiers.","transcript":"Question 23.\nNotre débat porte sur les appels non urgents qui encombrent la ligne de conseil. Le docteur Martin propose un premier tri téléphonique.\nOui, mais je refuse un questionnaire automatique qui déciderait seul de l'orientation. Certains symptômes s'expliquent mal en quelques mots.\nEn tant que responsable du centre, je crains aussi d'allonger l'attente au téléphone.\nNous pourrions former une petite équipe à poser des questions initiales, puis transférer rapidement les situations incertaines à un infirmier.\nD'accord, si nous vérifions les appels mal orientés pendant les premières semaines.\nFinalement, quelle organisation du tri téléphonique décident-ils d’adopter pour les appels non urgents ?","segments":[{"voice":"female","text":"Question 23.","speaker":"female"},{"voice":"female","text":"Notre débat porte sur les appels non urgents qui encombrent la ligne de conseil. Le docteur Martin propose un premier tri téléphonique.","speaker":"female"},{"voice":"male","text":"Oui, mais je refuse un questionnaire automatique qui déciderait seul de l'orientation. Certains symptômes s'expliquent mal en quelques mots.","speaker":"male"},{"voice":"female","text":"En tant que responsable du centre, je crains aussi d'allonger l'attente au téléphone.","speaker":"female_alt"},{"voice":"male","text":"Nous pourrions former une petite équipe à poser des questions initiales, puis transférer rapidement les situations incertaines à un infirmier.","speaker":"male"},{"voice":"female","text":"D'accord, si nous vérifions les appels mal orientés pendant les premières semaines.","speaker":"female_alt"},{"voice":"female","text":"Finalement, quelle organisation du tri téléphonique décident-ils d’adopter pour les appels non urgents ?","speaker":"female"}],"audio":"q-23.mp3","audioSeconds":44.225,"slotSeconds":71},{"number":24,"kind":"interview","question":"Selon la chercheuse, quel type de patients manque dans les résultats de l’étude actuelle ?","options":["Les patients qui téléphonent d’abord puis finalisent quand même leur rendez-vous sur l’application.","Les patients qui abandonnent face à la procédure de création de compte et de réservation en ligne.","Les patients déjà inscrits sur l’application mais qui n’ont pas encore utilisé la fonction de réservation.","Les patients qui réussissent à créer un compte mais déclarent ensuite être insatisfaits de l’outil."],"correct":"B","explanation":"Réponse B : La chercheuse explique clairement que l'étude actuelle ne prend pas en compte les patients qui abandonnent face à la procédure de création de compte et de réservation en ligne. C'est précisément le type de patients manquant dans les résultats de l'étude actuelle. A : Cette phrase mentionne que la prochaine enquête inclura les patients qui continuent à téléphoner, mais dans l'étude actuelle, il n'est pas précisé qu'ils manquent spécifiquement les patients qui téléphonent puis finalisent sur l'application. La chercheuse parle de ceux qui abandonnent la procédure en ligne, pas de ceux qui la terminent après un appel. C : On pourrait croire que les patients déjà inscrits mais n'ayant pas encore utilisé la réservation manquent, mais la chercheuse précise que seuls ceux ayant réussi à créer un compte ET à réserver ont été interrogés. Les patients déjà inscrits mais inactifs ne sont pas explicitement mentionnés comme manquants. D : Il serait tentant de penser que les patients insatisfaits après création du compte manquent, mais la chercheuse indique qu'ils ont interrogé ceux qui ont réussi à créer un compte et à réserver, et qu'ils connaissent leur avis (qu'il soit positif ou négatif). Ce ne sont donc pas ces patients qui manquent.","transcript":"Question 24.\nVotre étude conclut que l'application de prise de rendez-vous plaît beaucoup aux patients. Est-ce suffisant pour généraliser le système ?\nNous n'avons interrogé que les personnes qui ont réussi à créer un compte et à réserver. Nous savons donc ce qu'elles pensent de l'outil, pas ce que vivent les patients qui abandonnent devant la procédure. Des personnes âgées ou mal équipées peuvent être absentes de nos résultats. Notre prochaine enquête se fera aussi dans les salles d'attente, auprès de ceux qui continuent à téléphoner ou à venir au guichet.\nSelon la chercheuse, quel type de patients manque dans les résultats de l’étude actuelle ?","segments":[{"voice":"female","text":"Question 24."},{"voice":"male","text":"Votre étude conclut que l'application de prise de rendez-vous plaît beaucoup aux patients. Est-ce suffisant pour généraliser le système ?"},{"voice":"female","text":"Nous n'avons interrogé que les personnes qui ont réussi à créer un compte et à réserver. Nous savons donc ce qu'elles pensent de l'outil, pas ce que vivent les patients qui abandonnent devant la procédure. Des personnes âgées ou mal équipées peuvent être absentes de nos résultats. Notre prochaine enquête se fera aussi dans les salles d'attente, auprès de ceux qui continuent à téléphoner ou à venir au guichet."},{"voice":"female","text":"Selon la chercheuse, quel type de patients manque dans les résultats de l’étude actuelle ?"}],"audio":"q-24.mp3","audioSeconds":37.355,"slotSeconds":69},{"number":25,"kind":"television-report","question":"Selon la commune, quelle est la raison principale pour laquelle les cabines sont peu utilisées le soir ?","options":["Le manque de médecins disponibles pour assurer les téléconsultations","L’emplacement des cabines dans des bâtiments municipaux peu fréquentés","L’absence de personnel pour accompagner les usagers à ces horaires","Une campagne d’information insuffisante sur l’existence du dispositif"],"correct":"C","explanation":"Réponse C : C'est la raison explicitement donnée par la commune : l'absence de personnel d'accompagnement le soir explique la faible utilisation des cabines à ces horaires. A : Quelqu’un pourrait croire que le manque de médecins est un problème, car il s'agit de téléconsultations médicales, mais le texte ne mentionne aucune difficulté à obtenir un médecin le soir. Il parle uniquement de l'absence de personnel d'accompagnement. B : On pourrait penser que l'emplacement dans des bâtiments municipaux peu fréquentés le soir explique la faible utilisation, mais le texte n'indique pas que la fréquentation des bâtiments est en cause, seulement l'absence de personnel d'accompagnement. D : Quelqu’un pourrait croire que le problème vient d’un manque de communication, mais le texte ne mentionne aucune campagne d’information insuffisante. Au contraire, il est dit que la commune se félicite des créneaux supplémentaires, ce qui suggère une certaine visibilité du dispositif.","transcript":"Question 25.\nÀ Saint-Malo, deux cabines de téléconsultation ont été installées dans des bâtiments municipaux. Elles permettent de mesurer certains paramètres avant une consultation vidéo.\nJ'ai essayé, raconte une habitante, mais je n'ai pas compris comment régler la caméra. Un agent m'a aidée, sinon je serais repartie.\nLa commune se félicite des créneaux supplémentaires, mais admet que les appareils restent souvent inutilisés le soir, quand le personnel d'accompagnement n'est plus présent. Elle envisage donc une formation des médiateurs plutôt que l'achat immédiat de nouvelles cabines.\nSelon la commune, quelle est la raison principale pour laquelle les cabines sont peu utilisées le soir ?","segments":[{"voice":"female","text":"Question 25."},{"voice":"female","text":"À Saint-Malo, deux cabines de téléconsultation ont été installées dans des bâtiments municipaux. Elles permettent de mesurer certains paramètres avant une consultation vidéo."},{"voice":"male","text":"J'ai essayé, raconte une habitante, mais je n'ai pas compris comment régler la caméra. Un agent m'a aidée, sinon je serais repartie."},{"voice":"female","text":"La commune se félicite des créneaux supplémentaires, mais admet que les appareils restent souvent inutilisés le soir, quand le personnel d'accompagnement n'est plus présent. Elle envisage donc une formation des médiateurs plutôt que l'achat immédiat de nouvelles cabines."},{"voice":"female","text":"Selon la commune, quelle est la raison principale pour laquelle les cabines sont peu utilisées le soir ?"}],"audio":"q-25.mp3","audioSeconds":41.848,"slotSeconds":71},{"number":26,"kind":"interview","question":"Avant d’acheter le robot de rééducation, à quoi la kinésithérapeute veut-elle surtout être attentive ?","options":["À l’impact du coût d’achat et des frais de maintenance sur l’organisation du cabinet.","À la nécessité de choisir un modèle doté de programmes distincts pour chaque type de pathologie.","Au risque que l’appareil affaiblisse l’évaluation clinique et la relation directe avec les patients.","À la correspondance des exercices proposés avec les objectifs variés de ses patients et à la capacité de l’équipe à les adapter."],"correct":"D","explanation":"Réponse D : La kinésithérapeute explique clairement qu'avant d'acheter, elle veut s'assurer que les exercices du robot correspondent aux objectifs variés de ses patients et que l'équipe pourra les adapter. C'est l'élément central de sa réflexion. A : La kinésithérapeute ne mentionne pas le coût d'achat ni les frais de maintenance comme sa préoccupation principale. Quelqu'un pourrait croire que l'aspect organisationnel est important car elle parle d'investissement, mais elle précise que son attention porte sur l'adaptation des exercices aux besoins des patients. B : Il est tentant de penser que la kinésithérapeute veut un appareil avec des programmes distincts pour chaque pathologie, car elle évoque la diversité des besoins. Cependant, elle insiste sur l'adaptation des exercices aux objectifs variés, pas sur la nécessité de programmes prédéfinis pour chaque pathologie. C : La kinésithérapeute mentionne que la machine ne remplace pas l'évaluation clinique ou la relation, mais ce n'est pas ce à quoi elle veut surtout être attentive avant l'achat. Elle veut surtout vérifier l'adaptabilité des exercices. Quelqu'un pourrait croire que le risque d'affaiblissement de la relation est sa préoccupation principale, car elle le mentionne, mais ce n'est pas le critère déterminant pour l'achat.","transcript":"Question 26.\nVotre cabinet pourrait bénéficier d'un robot de rééducation. Pourquoi attendre ?\nL'appareil promet des exercices précis, mais nous recevons des patients qui ont des objectifs très différents. Certains ont besoin d'un soutien pour se relever, d'autres veulent retrouver un geste de la vie quotidienne. Avant d'investir, je souhaite observer si les exercices proposés correspondent à ces besoins et si l'équipe pourra adapter les séances. Un matériel impressionnant ne remplace ni l'évaluation clinique ni la relation avec le patient.\nAvant d’acheter le robot de rééducation, à quoi la kinésithérapeute veut-elle surtout être attentive ?","segments":[{"voice":"female","text":"Question 26."},{"voice":"male","text":"Votre cabinet pourrait bénéficier d'un robot de rééducation. Pourquoi attendre ?"},{"voice":"female","text":"L'appareil promet des exercices précis, mais nous recevons des patients qui ont des objectifs très différents. Certains ont besoin d'un soutien pour se relever, d'autres veulent retrouver un geste de la vie quotidienne. Avant d'investir, je souhaite observer si les exercices proposés correspondent à ces besoins et si l'équipe pourra adapter les séances. Un matériel impressionnant ne remplace ni l'évaluation clinique ni la relation avec le patient."},{"voice":"female","text":"Avant d’acheter le robot de rééducation, à quoi la kinésithérapeute veut-elle surtout être attentive ?"}],"audio":"q-26.mp3","audioSeconds":39.497,"slotSeconds":66},{"number":27,"kind":"dialogue","question":"Quelle organisation des soins à domicile est retenue ?","options":["Décaler à dix heures les passages des lundis et jeudis, en gardant huit heures les autres jours.","Fixer toutes les visites à dix heures chaque matin.","Maintenir les visites à huit heures et déplacer les séances de rééducation.","Supprimer les visites des lundis et jeudis pour ne garder que la rééducation."],"correct":"A","explanation":"Réponse A : La solution retenue est de décaler à dix heures les passages des lundis et jeudis (jours où il y a chevauchement avec la rééducation), tout en gardant les passages à huit heures les autres jours. C'est exactement ce qui est décrit dans la première option. B : Quelqu’un pourrait croire que toutes les visites sont fixées à dix heures, car on parle d’un changement d’horaire, mais le texte précise que seuls les lundis et jeudis sont concernés, les autres jours restent à huit heures. C : On pourrait penser que seules les séances de rééducation sont déplacées, mais le texte indique que c’est le passage infirmier qui est décalé, pas la rééducation. D : Quelqu’un pourrait croire que les visites des lundis et jeudis sont supprimées, mais le texte précise qu’elles sont simplement décalées à dix heures, pas supprimées.","transcript":"Question 27.\nVotre père sort demain, mais le passage infirmier était prévu chaque matin à huit heures.\nIl a une séance de rééducation à la même heure les lundis et jeudis. Peut-on éviter le chevauchement ?\nJe peux demander un passage à dix heures ces deux jours-là et conserver huit heures le reste de la semaine.\nCela lui permettra de suivre les deux soins sans se presser.\nJe note la modification dans le planning partagé.\nQuelle organisation des soins à domicile est retenue ?","segments":[{"voice":"female","text":"Question 27."},{"voice":"female","text":"Votre père sort demain, mais le passage infirmier était prévu chaque matin à huit heures."},{"voice":"male","text":"Il a une séance de rééducation à la même heure les lundis et jeudis. Peut-on éviter le chevauchement ?"},{"voice":"female","text":"Je peux demander un passage à dix heures ces deux jours-là et conserver huit heures le reste de la semaine."},{"voice":"male","text":"Cela lui permettra de suivre les deux soins sans se presser."},{"voice":"female","text":"Je note la modification dans le planning partagé."},{"voice":"female","text":"Quelle organisation des soins à domicile est retenue ?"}],"audio":"q-27.mp3","audioSeconds":29.858,"slotSeconds":59},{"number":28,"kind":"interview","question":"Selon la responsable, comment les professionnels sont-ils formés à vérifier que le patient a bien compris ?","options":["En faisant lire en silence la notice traduite avant de la faire signer.","En faisant reformuler les consignes avec ses propres mots.","En demandant de répéter mot à mot les phrases de la notice.","En posant seulement à la fin quelques questions fermées."],"correct":"B","explanation":"Réponse B : La responsable explique explicitement que les professionnels sont formés à demander au patient de reformuler les consignes avec ses propres mots, ce qui correspond exactement à cette option. A : Quelqu'un pourrait croire que lire la notice traduite en silence puis la signer suffit à vérifier la compréhension, car le texte mentionne l'usage de documents traduits et le temps laissé pour les questions. Cependant, la responsable précise que la traduction seule ne suffit pas et ne mentionne pas la signature comme méthode de vérification. C : Quelqu'un pourrait confondre la reformulation avec la répétition mot à mot, mais la responsable insiste sur l'importance de reformuler avec ses propres mots, ce qui exclut la répétition littérale. D : La mention de 'laisser un temps pour les questions' pourrait faire croire qu'il suffit de poser quelques questions fermées à la fin, mais la responsable met l'accent sur la reformulation active, pas seulement sur des questions fermées.","transcript":"Question 28.\nLes notices traduites existent, pourtant certains patients ne suivent pas correctement leur traitement. Comment l'expliquez-vous ?\nLa traduction seule ne suffit pas. Nos documents contiennent des abréviations médicales et des phrases complexes, même dans la langue maternelle des personnes. Il faut vérifier ce qu'elles ont compris, utiliser des schémas lorsque c'est utile et laisser un temps pour les questions. Nous formons aussi les professionnels à demander au patient de reformuler les consignes avec ses propres mots. Ce n'est pas un examen, c'est une vérification de notre manière d'expliquer.\nSelon la responsable, comment les professionnels sont-ils formés à vérifier que le patient a bien compris ?","segments":[{"voice":"female","text":"Question 28."},{"voice":"male","text":"Les notices traduites existent, pourtant certains patients ne suivent pas correctement leur traitement. Comment l'expliquez-vous ?"},{"voice":"female","text":"La traduction seule ne suffit pas. Nos documents contiennent des abréviations médicales et des phrases complexes, même dans la langue maternelle des personnes. Il faut vérifier ce qu'elles ont compris, utiliser des schémas lorsque c'est utile et laisser un temps pour les questions. Nous formons aussi les professionnels à demander au patient de reformuler les consignes avec ses propres mots. Ce n'est pas un examen, c'est une vérification de notre manière d'expliquer."},{"voice":"female","text":"Selon la responsable, comment les professionnels sont-ils formés à vérifier que le patient a bien compris ?"}],"audio":"q-28.mp3","audioSeconds":39.837,"slotSeconds":66},{"number":29,"kind":"debate","question":"Quelle exigence Mme Leclerc ajoute-t-elle à la proposition du professeur Duval concernant le partage des résultats ?","options":["Que l’accès automatisé soit réservé aux situations présentant un caractère d’urgence vitale.","Que les résultats ne puissent circuler qu’à l’intérieur d’un même établissement de soins.","Que le patient puisse consulter l’historique des accès à ses données et signaler un usage abusif.","Que chaque partage entre services soit précédé d’une nouvelle validation médicale interne."],"correct":"C","explanation":"Réponse C : Mme Leclerc insiste explicitement sur le fait que le patient doit pouvoir savoir qui a consulté ses données et signaler un usage abusif. C’est l’exigence supplémentaire qu’elle ajoute à la proposition du professeur Duval. A : Cette option pourrait être tentante car le professeur Duval évoque un accès sécurisé et limité, ce qui pourrait être interprété comme une restriction à des situations d’urgence. Cependant, il ne parle jamais de réserver l’accès automatisé uniquement aux urgences vitales. Cette exigence n’est pas mentionnée par Mme Leclerc. B : On pourrait croire que Mme Leclerc souhaite limiter la circulation des résultats à l’intérieur d’un même établissement, car la discussion porte sur la limitation de l’accès. Cependant, elle ne parle pas de restriction géographique ou institutionnelle, mais plutôt de transparence vis-à-vis du patient. D : Cette option pourrait sembler plausible car Mme Leclerc insiste sur la nécessité de transparence et de contrôle, ce qui pourrait être interprété comme une demande de validation médicale à chaque partage. Cependant, elle ne demande pas de validation médicale interne supplémentaire, mais bien un droit de regard et de signalement pour le patient.","transcript":"Question 29.\nLes hôpitaux souhaitent partager plus facilement certains résultats entre services. Le professeur Duval, vous y êtes favorable.\nUne analyse répétée inutilement retarde le traitement. Un accès sécurisé, limité aux professionnels concernés, pourrait l'éviter.\nMadame Leclerc, vous n'êtes pas convaincue.\nJe soutiens la coordination, mais le patient doit comprendre qui consulte ses données et pouvoir signaler un accès injustifié. Un système pratique pour les soignants ne suffit pas s'il reste opaque pour les personnes concernées.\nJe suis d'accord sur la transparence, mais elle ne devrait pas bloquer un échange nécessaire aux soins.\nQuelle exigence Mme Leclerc ajoute-t-elle à la proposition du professeur Duval concernant le partage des résultats ?","segments":[{"voice":"female","text":"Question 29.","speaker":"female"},{"voice":"female","text":"Les hôpitaux souhaitent partager plus facilement certains résultats entre services. Le professeur Duval, vous y êtes favorable.","speaker":"female"},{"voice":"male","text":"Une analyse répétée inutilement retarde le traitement. Un accès sécurisé, limité aux professionnels concernés, pourrait l'éviter.","speaker":"male"},{"voice":"female","text":"Madame Leclerc, vous n'êtes pas convaincue.","speaker":"female"},{"voice":"female","text":"Je soutiens la coordination, mais le patient doit comprendre qui consulte ses données et pouvoir signaler un accès injustifié. Un système pratique pour les soignants ne suffit pas s'il reste opaque pour les personnes concernées.","speaker":"female_alt"},{"voice":"male","text":"Je suis d'accord sur la transparence, mais elle ne devrait pas bloquer un échange nécessaire aux soins.","speaker":"male"},{"voice":"female","text":"Quelle exigence Mme Leclerc ajoute-t-elle à la proposition du professeur Duval concernant le partage des résultats ?","speaker":"female"}],"audio":"q-29.mp3","audioSeconds":47.569,"slotSeconds":69},{"number":30,"kind":"interview","question":"Selon l'intervenante, quelle devrait être la priorité de l'association envers les proches aidants ?","options":["Proposer d'abord du répit, une information fiable et une orientation vers des services adaptés.","Mettre en place surtout des formations pour qu'ils assurent eux-mêmes davantage de soins au quotidien.","Réserver les temps de répit aux aidants qui ont déjà accepté de se professionnaliser dans la prise en charge.","Former ceux qui le souhaitent à réaliser une partie des soins, puis seulement ensuite envisager des solutions de répit."],"correct":"A","explanation":"Réponse A : L'intervenante affirme explicitement que la priorité de l'association est de proposer du répit, une information fiable et une orientation vers des services adaptés. Cette option reprend exactement ces éléments. B : Quelqu'un pourrait croire que l'association veut surtout former les aidants, car l'intervenante mentionne que certaines formations sont utiles. Cependant, elle précise qu'il ne faut pas transformer les proches en professionnels, ce qui contredit l'idée de mettre en place surtout des formations pour qu'ils assurent davantage de soins. C : On pourrait penser que le répit est réservé à ceux qui se professionnalisent, mais l'intervenante ne pose aucune condition de ce type. Elle insiste sur le fait que le répit est une priorité générale, sans restriction. D : Cette option inverse l'ordre des priorités : elle propose de former d'abord, puis de penser au répit. Or, l'intervenante dit clairement que le répit et l'orientation sont la priorité, et que la formation n'est qu'un complément possible.","transcript":"Question 30.\nVotre association soutient les personnes qui accompagnent un parent dépendant. Faut-il les former à effectuer davantage de soins ?\nCertaines formations sont utiles, mais il faut éviter de transformer les proches en professionnels à temps plein. Beaucoup travaillent, élèvent leurs enfants et éprouvent déjà une grande fatigue. Notre priorité est de proposer des moments de répit, des renseignements fiables et une orientation vers des services adaptés. Aider une famille, ce n'est pas lui demander de tout faire seule sous prétexte qu'elle connaît bien le malade.\nSelon l'intervenante, quelle devrait être la priorité de l'association envers les proches aidants ?","segments":[{"voice":"female","text":"Question 30."},{"voice":"male","text":"Votre association soutient les personnes qui accompagnent un parent dépendant. Faut-il les former à effectuer davantage de soins ?"},{"voice":"female","text":"Certaines formations sont utiles, mais il faut éviter de transformer les proches en professionnels à temps plein. Beaucoup travaillent, élèvent leurs enfants et éprouvent déjà une grande fatigue. Notre priorité est de proposer des moments de répit, des renseignements fiables et une orientation vers des services adaptés. Aider une famille, ce n'est pas lui demander de tout faire seule sous prétexte qu'elle connaît bien le malade."},{"voice":"female","text":"Selon l'intervenante, quelle devrait être la priorité de l'association envers les proches aidants ?"}],"audio":"q-30.mp3","audioSeconds":37.851,"slotSeconds":68},{"number":31,"kind":"academic-monologue","question":"Selon la conférencière, quelle précaution est indispensable pour attribuer correctement la baisse des hospitalisations au centre de dépistage ?","options":["S’appuyer principalement sur l’avis des professionnels qui travaillent dans le centre.","Prendre en compte les autres évolutions parallèles comme la pollution et les pratiques médicales.","Allonger la période d’observation dans la même ville sans rien changer à l’analyse.","Comparer seulement le nombre d’hospitalisations avant et après l’ouverture du centre."],"correct":"B","explanation":"Réponse B : La conférencière précise qu’il faut tenir compte des évolutions parallèles comme la pollution et les pratiques médicales pour attribuer correctement la baisse des hospitalisations au centre de dépistage. C’est la précaution indispensable explicitement mentionnée. A : Quelqu’un pourrait croire que l’avis des professionnels du centre est essentiel, car le texte mentionne leur changement de pratiques. Cependant, il n’est jamais dit que leur avis suffit pour attribuer la baisse des hospitalisations au centre de dépistage. Le texte insiste sur la nécessité de prendre en compte d’autres facteurs. C : On pourrait penser que simplement allonger la période d’observation suffit, car la conférencière parle d’examiner les données sur une durée suffisante. Cependant, elle précise aussi qu’il faut tenir compte des autres évolutions, donc cette option est incomplète. D : Comparer seulement avant et après l’ouverture du centre est précisément ce que la conférencière déconseille, car la succession temporelle ne prouve pas la causalité. Quelqu’un pourrait se tromper en pensant que cette comparaison suffit.","transcript":"Question 31.\nDans une ville, les hospitalisations pour troubles respiratoires ont diminué après l'ouverture d'un centre de dépistage. Ce résultat semble encourageant, mais il ne démontre pas, à lui seul, que le dépistage en est la cause. La pollution était également moins importante cette année-là et plusieurs professionnels ont changé leurs pratiques. Pour évaluer l'effet propre du centre, nous devons disposer d'une comparaison pertinente, tenir compte de ces évolutions parallèles et examiner les données sur une durée suffisante. Une succession temporelle n'est pas une preuve de causalité.\nSelon la conférencière, quelle précaution est indispensable pour attribuer correctement la baisse des hospitalisations au centre de dépistage ?","segments":[{"voice":"female","text":"Question 31."},{"voice":"female","text":"Dans une ville, les hospitalisations pour troubles respiratoires ont diminué après l'ouverture d'un centre de dépistage. Ce résultat semble encourageant, mais il ne démontre pas, à lui seul, que le dépistage en est la cause. La pollution était également moins importante cette année-là et plusieurs professionnels ont changé leurs pratiques. Pour évaluer l'effet propre du centre, nous devons disposer d'une comparaison pertinente, tenir compte de ces évolutions parallèles et examiner les données sur une durée suffisante. Une succession temporelle n'est pas une preuve de causalité."},{"voice":"female","text":"Selon la conférencière, quelle précaution est indispensable pour attribuer correctement la baisse des hospitalisations au centre de dépistage ?"}],"audio":"q-31.mp3","audioSeconds":43.833,"slotSeconds":75},{"number":32,"kind":"interview","question":"À quel rythme l'équipe confronte-t-elle les estimations du modèle aux admissions réelles ?","options":["Chaque mois","Chaque semaine","Chaque jour","Uniquement lorsque les services sont sous tension"],"correct":"B","explanation":"Réponse B : Le texte indique explicitement que la confrontation des estimations du modèle aux admissions réelles se fait 'chaque semaine', ce qui correspond exactement à cette option. A : Quelqu'un pourrait confondre la fréquence hebdomadaire avec une fréquence mensuelle, car les deux impliquent une certaine régularité. Cependant, le texte précise 'chaque semaine', ce qui exclut 'chaque mois'. C : Quelqu'un pourrait penser que le suivi est quotidien pour une réactivité maximale, mais le texte précise 'chaque semaine', donc 'chaque jour' est trop fréquent. D : La mention de l'utilisation de l'outil en cas de tension pourrait faire croire que la confrontation n'a lieu que dans ces situations. Cependant, le texte précise que la comparaison est hebdomadaire, pas seulement en cas de tension.","transcript":"Question 32.\nVotre équipe prévoit l'occupation des lits à partir des admissions passées. Peut-on fixer définitivement les effectifs sur cette base ?\nNon. Le modèle nous aide à prévoir des fourchettes, mais il ne connaît ni toutes les épidémies futures ni les absences imprévues du personnel. Nous comparons ses estimations aux admissions réelles chaque semaine et nous ajustons les scénarios. Le danger serait de présenter une valeur précise comme une promesse. L'outil doit appuyer une décision humaine, notamment lorsque les services sont sous tension.\nÀ quel rythme l'équipe confronte-t-elle les estimations du modèle aux admissions réelles ?","segments":[{"voice":"female","text":"Question 32."},{"voice":"female","text":"Votre équipe prévoit l'occupation des lits à partir des admissions passées. Peut-on fixer définitivement les effectifs sur cette base ?"},{"voice":"male","text":"Non. Le modèle nous aide à prévoir des fourchettes, mais il ne connaît ni toutes les épidémies futures ni les absences imprévues du personnel. Nous comparons ses estimations aux admissions réelles chaque semaine et nous ajustons les scénarios. Le danger serait de présenter une valeur précise comme une promesse. L'outil doit appuyer une décision humaine, notamment lorsque les services sont sous tension."},{"voice":"female","text":"À quel rythme l'équipe confronte-t-elle les estimations du modèle aux admissions réelles ?"}],"audio":"q-32.mp3","audioSeconds":40.673,"slotSeconds":70},{"number":33,"kind":"commentary","question":"Que souligne la chroniqueuse à propos du délai moyen de huit jours annoncé ?","options":["Qu’il peut donner une image trompeuse en masquant de fortes différences entre patients.","Qu’il devient vite obsolète dès que la demande de rendez-vous augmente.","Qu’il reflète surtout la situation des spécialités où l’attente est la plus longue.","Qu’il manque surtout une séparation claire entre les urgences et les autres consultations."],"correct":"A","explanation":"Réponse A : La chroniqueuse explique que le délai moyen de huit jours peut donner une image trompeuse car il masque de grandes différences entre les patients (certains attendent deux jours, d'autres deux mois). C'est exactement ce que dit l'option 0. B : Quelqu’un pourrait croire que le délai devient obsolète si la demande augmente, car la chroniqueuse évoque des situations d'urgence et des différences selon les spécialités. Cependant, elle ne dit pas que le chiffre devient obsolète avec l’augmentation de la demande, mais que la moyenne masque la diversité des situations. C : La chroniqueuse mentionne qu'il serait utile de publier les différences entre spécialités, mais elle ne dit pas que la moyenne reflète surtout les spécialités où l’attente est la plus longue. Elle critique la moyenne pour masquer les écarts, pas pour être biaisée vers les longues attentes. D : La chroniqueuse évoque qu’il serait utile de distinguer les situations d’urgence, mais elle ne dit pas que le problème principal est l’absence de séparation claire entre urgences et autres consultations. Elle insiste sur le caractère trompeur de la moyenne, pas sur la séparation des types de rendez-vous.","transcript":"Question 33.\nLe nouvel indicateur municipal annonce un délai moyen de huit jours pour consulter un spécialiste. C'est une information intéressante, mais elle ne nous dit pas ce que vivent tous les patients. Si certaines personnes obtiennent une place sous deux jours et d'autres attendent deux mois, la moyenne peut donner une impression trompeuse. Il serait utile de publier aussi la proportion de patients vus dans un délai raisonnable, les différences entre spécialités et les situations d'urgence. Le problème n'est pas le chiffre en lui-même, mais ce qu'on lui fait raconter.\nQue souligne la chroniqueuse à propos du délai moyen de huit jours annoncé ?","segments":[{"voice":"female","text":"Question 33."},{"voice":"female","text":"Le nouvel indicateur municipal annonce un délai moyen de huit jours pour consulter un spécialiste. C'est une information intéressante, mais elle ne nous dit pas ce que vivent tous les patients. Si certaines personnes obtiennent une place sous deux jours et d'autres attendent deux mois, la moyenne peut donner une impression trompeuse. Il serait utile de publier aussi la proportion de patients vus dans un délai raisonnable, les différences entre spécialités et les situations d'urgence. Le problème n'est pas le chiffre en lui-même, mais ce qu'on lui fait raconter."},{"voice":"female","text":"Que souligne la chroniqueuse à propos du délai moyen de huit jours annoncé ?"}],"audio":"q-33.mp3","audioSeconds":36.911,"slotSeconds":67},{"number":34,"kind":"roundtable","question":"Comment le dispositif d’accueil proposé sera-t-il mis en place au départ ?","options":["Par une plateforme téléphonique confidentielle expérimentée dans deux communes avant une extension.","Par une personne de liaison formée, testée comme accueil d’orientation dans deux communes.","Par une personne de liaison formée, déployée tout de suite dans toutes les communes.","Par des équipes médicales qui assureront elles-mêmes le premier entretien d’évaluation dans deux communes."],"correct":"B","explanation":"Réponse B : La solution retenue est bien une personne de liaison formée, testée comme accueil d’orientation dans deux communes avant extension. C'est exactement ce qui est décrit dans le stimulus. A : La proposition parle d'une personne de liaison formée, pas d'une plateforme téléphonique. Quelqu'un pourrait confondre la notion de confidentialité et d'expérimentation dans deux communes avec une plateforme téléphonique, mais il n'est jamais question de téléphone. C : Quelqu'un pourrait penser que le dispositif sera déployé partout tout de suite, mais le texte précise qu'il sera d'abord testé dans deux communes, donc pas de déploiement immédiat généralisé. D : On pourrait croire que ce sont des équipes médicales qui feront le premier entretien, mais le texte précise que ce sera une personne de liaison, non une équipe médicale.","transcript":"Question 34.\nNous parlons de l'accès aux consultations psychologiques dans les petites communes.\nNos permanences sont presque pleines. Ouvrir davantage de créneaux demande des professionnels que nous ne trouvons pas.\nJe représente les associations de jeunes. Beaucoup hésitent à demander de l'aide s'ils doivent expliquer leur situation à plusieurs guichets.\nNous pourrions désigner une personne de liaison formée, capable de proposer un premier entretien et d'orienter rapidement vers le bon service.\nÀ condition que les échanges restent confidentiels et que cette personne ne prétende pas établir un diagnostic.\nD'accord. Nous testerons l'accueil dans deux communes avant de l'étendre.\nComment le dispositif d’accueil proposé sera-t-il mis en place au départ ?","segments":[{"voice":"female","text":"Question 34.","speaker":"female"},{"voice":"female","text":"Nous parlons de l'accès aux consultations psychologiques dans les petites communes.","speaker":"female"},{"voice":"male","text":"Nos permanences sont presque pleines. Ouvrir davantage de créneaux demande des professionnels que nous ne trouvons pas.","speaker":"male"},{"voice":"female","text":"Je représente les associations de jeunes. Beaucoup hésitent à demander de l'aide s'ils doivent expliquer leur situation à plusieurs guichets.","speaker":"female_alt"},{"voice":"male","text":"Nous pourrions désigner une personne de liaison formée, capable de proposer un premier entretien et d'orienter rapidement vers le bon service.","speaker":"male"},{"voice":"female","text":"À condition que les échanges restent confidentiels et que cette personne ne prétende pas établir un diagnostic.","speaker":"female_alt"},{"voice":"male","text":"D'accord. Nous testerons l'accueil dans deux communes avant de l'étendre.","speaker":"male"},{"voice":"female","text":"Comment le dispositif d’accueil proposé sera-t-il mis en place au départ ?","speaker":"female"}],"audio":"q-34.mp3","audioSeconds":47.334,"slotSeconds":69},{"number":35,"kind":"interview","question":"Comment l’ingénieure présente‑t‑elle la signification d’une alerte de la montre ?","options":["Comme un signal à prendre en compte, mais qui doit être confirmé par un professionnel de santé.","Comme la preuve qu’un traitement doit être commencé dès que l’alerte apparaît.","Comme une garantie fiable qu’aucun problème n’existe une fois l’alerte disparue.","Comme un simple bug technique dont il vaut mieux ne pas tenir compte."],"correct":"A","explanation":"Réponse A : L’ingénieure explique qu’une alerte doit être prise en compte, mais qu’elle n’est pas suffisante pour poser un diagnostic. Elle recommande de consulter un professionnel de santé pour confirmation. B : Quelqu’un pourrait croire qu’il faut commencer un traitement dès l’alerte, car il s’agit d’un signal, mais l’ingénieure précise qu’il ne faut pas réagir à chaque notification comme à une certitude, ce qui contredit cette option. C : On pourrait croire que l’absence d’alerte garantit l’absence de problème, mais l’ingénieure dit explicitement que ce n’est pas le cas. D : Quelqu’un pourrait penser que les alertes sont des bugs à ignorer, car les capteurs peuvent être perturbés, mais l’ingénieure précise qu’elles donnent des informations utiles, donc ce n’est pas un simple bug.","transcript":"Question 35.\nCes montres peuvent détecter des variations du rythme cardiaque. Pourquoi certains médecins restent-ils prudents ?\nElles fournissent des informations utiles sur la durée, mais les capteurs peuvent être perturbés par le mouvement ou par un bracelet mal ajusté. Une alerte n'est pas, à elle seule, un diagnostic, et son absence ne garantit pas qu'aucun problème n'existe. Nous conseillons de partager les données avec un professionnel lorsqu'une inquiétude persiste, plutôt que de réagir à chaque notification comme à une certitude.\nComment l’ingénieure présente‑t‑elle la signification d’une alerte de la montre ?","segments":[{"voice":"female","text":"Question 35."},{"voice":"male","text":"Ces montres peuvent détecter des variations du rythme cardiaque. Pourquoi certains médecins restent-ils prudents ?"},{"voice":"female","text":"Elles fournissent des informations utiles sur la durée, mais les capteurs peuvent être perturbés par le mouvement ou par un bracelet mal ajusté. Une alerte n'est pas, à elle seule, un diagnostic, et son absence ne garantit pas qu'aucun problème n'existe. Nous conseillons de partager les données avec un professionnel lorsqu'une inquiétude persiste, plutôt que de réagir à chaque notification comme à une certitude."},{"voice":"female","text":"Comment l’ingénieure présente‑t‑elle la signification d’une alerte de la montre ?"}],"audio":"q-35.mp3","audioSeconds":37.224,"slotSeconds":68},{"number":36,"kind":"interview","question":"Selon le document, à quoi la signature du formulaire de consentement sert-elle surtout ?","options":["À garantir que le patient n’a subi aucune pression pour accepter les soins.","À confirmer que toutes les explications nécessaires ont déjà été fournies par le médecin.","À attester qu’une information a été remise au patient.","À prouver que le patient a pleinement compris ce qui lui a été expliqué."],"correct":"C","explanation":"Réponse C : Le texte dit explicitement que la signature sert à attester qu’une information a été remise au patient, ce qui correspond exactement à cette option. A : Quelqu’un pourrait croire que la signature garantit l’absence de pression, car le texte insiste sur le fait que le patient doit pouvoir refuser sans se sentir puni. Cependant, il n’est jamais dit que la signature du formulaire sert à garantir cela. B : Le texte précise que la signature ne garantit pas que toutes les explications nécessaires ont été fournies, seulement qu'une information a été remise. Quelqu’un pourrait confondre la remise d’information avec la fourniture complète d’explications. D : Le texte précise explicitement que la signature ne garantit pas la compréhension du patient. Quelqu’un pourrait penser que la signature implique la compréhension, mais c’est contredit par le texte.","transcript":"Question 36.\nVous travaillez sur le consentement aux soins. Suffit-il de faire signer un formulaire ?\nLa signature peut attester qu'une information a été remise, mais elle ne garantit pas que la personne l'a comprise ou qu'elle a pu poser des questions. Certains patients ont besoin d'un interprète, d'un délai de réflexion ou d'une explication moins technique. Ils doivent également pouvoir refuser sans se sentir punis. Notre rôle n'est pas de convaincre à tout prix, mais de permettre une décision éclairée dans les limites de la situation médicale.\nSelon le document, à quoi la signature du formulaire de consentement sert-elle surtout ?","segments":[{"voice":"female","text":"Question 36."},{"voice":"male","text":"Vous travaillez sur le consentement aux soins. Suffit-il de faire signer un formulaire ?"},{"voice":"female","text":"La signature peut attester qu'une information a été remise, mais elle ne garantit pas que la personne l'a comprise ou qu'elle a pu poser des questions. Certains patients ont besoin d'un interprète, d'un délai de réflexion ou d'une explication moins technique. Ils doivent également pouvoir refuser sans se sentir punis. Notre rôle n'est pas de convaincre à tout prix, mais de permettre une décision éclairée dans les limites de la situation médicale."},{"voice":"female","text":"Selon le document, à quoi la signature du formulaire de consentement sert-elle surtout ?"}],"audio":"q-36.mp3","audioSeconds":36.754,"slotSeconds":70},{"number":37,"kind":"interview","question":"Selon la chercheuse, comment faut-il traiter les contradictions entre avis sur les visites à domicile ?","options":["Les prendre comme preuve que le ressenti compte davantage que les chiffres de coûts et de planning.","Les utiliser pour repérer l’avis le plus répandu et mettre de côté les autres.","Les considérer comme également exactes pour montrer que tous décrivent les mêmes faits malgré leurs divergences.","Les confronter d’abord aux données disponibles, puis les interpréter en fonction des situations vécues."],"correct":"D","explanation":"Réponse D : La chercheuse explique qu’il faut d’abord confronter les avis aux données objectives, puis interpréter les contradictions en fonction des situations vécues. C’est exactement ce que décrit cette option. A : Quelqu’un pourrait croire que le ressenti prime sur les chiffres car la chercheuse parle de la diversité des expériences et de l’importance du vécu. Cependant, elle précise qu’il faut d’abord vérifier les faits (nombre de visites, coûts, etc.), donc le ressenti ne prime pas sur les données objectives. B : On pourrait penser qu’il faut choisir l’avis majoritaire, car la chercheuse parle de diversité d’opinions. Mais elle rejette explicitement l’idée de mettre de côté certains avis, insistant sur l’importance d’expliquer toutes les contradictions. C : Quelqu’un pourrait croire qu’il faut considérer tous les avis comme également exacts, car la chercheuse insiste sur la diversité des expériences. Mais elle précise qu’il ne faut pas prétendre que tous les témoignages sont exacts sur chaque fait, ce qui contredit cette option.","transcript":"Question 37.\nVotre étude sur les visites à domicile contient des avis très opposés. Comment pouvez-vous en tirer une conclusion ?\nNous vérifions d'abord les faits : nombre de visites, changements de planning, coûts réels. Ensuite, nous situons les expériences. Une personne vivant seule peut apprécier une visite qui rassure; un proche aidant peut juger que cette même visite ne répond pas à ses besoins. Supprimer ces contradictions reviendrait à masquer la diversité du public. Il faut les expliquer et déterminer quelles conditions produisent chaque expérience, sans prétendre que tous les témoignages sont également exacts sur chaque fait.\nSelon la chercheuse, comment faut-il traiter les contradictions entre avis sur les visites à domicile ?","segments":[{"voice":"female","text":"Question 37."},{"voice":"male","text":"Votre étude sur les visites à domicile contient des avis très opposés. Comment pouvez-vous en tirer une conclusion ?"},{"voice":"female","text":"Nous vérifions d'abord les faits : nombre de visites, changements de planning, coûts réels. Ensuite, nous situons les expériences. Une personne vivant seule peut apprécier une visite qui rassure; un proche aidant peut juger que cette même visite ne répond pas à ses besoins. Supprimer ces contradictions reviendrait à masquer la diversité du public. Il faut les expliquer et déterminer quelles conditions produisent chaque expérience, sans prétendre que tous les témoignages sont également exacts sur chaque fait."},{"voice":"female","text":"Selon la chercheuse, comment faut-il traiter les contradictions entre avis sur les visites à domicile ?"}],"audio":"q-37.mp3","audioSeconds":44.513,"slotSeconds":71},{"number":38,"kind":"public-lecture","question":"Dans quel cas précis, selon l'oratrice, une campagne de prévention risque-t-elle de faire baisser la confiance des habitants ?","options":["Quand elle est évaluée principalement au nombre de personnes sensibilisées.","Quand elle révèle un risque sans que les habitants puissent accéder rapidement au suivi annoncé.","Quand elle cible prioritairement les personnes les plus vulnérables au détriment du reste de la population.","Quand elle mobilise davantage de ressources pour former les équipes que pour communiquer avec le public."],"correct":"B","explanation":"Réponse B : L'oratrice explique explicitement que si une campagne révèle un risque sans permettre un accès rapide au suivi, cela peut faire baisser la confiance des habitants. C'est la seule condition clairement liée à une perte de confiance dans le discours. A : Quelqu'un pourrait croire que l'évaluation au nombre de personnes sensibilisées est problématique, car l'oratrice dit qu'il ne faut pas se limiter à ce critère. Cependant, elle ne dit pas que cela fait baisser la confiance, mais plutôt que ce n'est pas suffisant pour juger de l'efficacité. C : L'oratrice mentionne l'importance de prendre en charge les plus vulnérables, mais ne dit pas que cibler ces personnes au détriment des autres ferait baisser la confiance. Quelqu'un pourrait mal interpréter cette insistance comme une critique d'un ciblage exclusif, mais ce n'est pas ce qui est dit. D : L'oratrice parle de la nécessité de former les équipes, mais ne dit pas qu'un déséquilibre entre formation et communication ferait baisser la confiance. On pourrait croire que trop former au détriment de la communication est problématique, mais ce n'est pas évoqué comme cause de perte de confiance.","transcript":"Question 38.\nUne campagne de prévention réussie peut provoquer davantage de demandes d'examens que le système local n'est capable d'en absorber. C'est le paradoxe que nous observons dans plusieurs villes. Informer les habitants est essentiel, mais s'ils découvrent un risque sans pouvoir accéder rapidement au suivi annoncé, l'inquiétude peut augmenter et la confiance diminuer. Les responsables ne devraient donc pas évaluer leur campagne seulement au nombre de personnes sensibilisées. Ils doivent anticiper les consultations, former les équipes et vérifier si les personnes les plus vulnérables obtiennent réellement une prise en charge. Un message efficace n'a de valeur durable que si les services peuvent répondre à la demande qu'il crée.\nDans quel cas précis, selon l'oratrice, une campagne de prévention risque-t-elle de faire baisser la confiance des habitants ?","segments":[{"voice":"female","text":"Question 38."},{"voice":"female","text":"Une campagne de prévention réussie peut provoquer davantage de demandes d'examens que le système local n'est capable d'en absorber. C'est le paradoxe que nous observons dans plusieurs villes. Informer les habitants est essentiel, mais s'ils découvrent un risque sans pouvoir accéder rapidement au suivi annoncé, l'inquiétude peut augmenter et la confiance diminuer. Les responsables ne devraient donc pas évaluer leur campagne seulement au nombre de personnes sensibilisées. Ils doivent anticiper les consultations, former les équipes et vérifier si les personnes les plus vulnérables obtiennent réellement une prise en charge. Un message efficace n'a de valeur durable que si les services peuvent répondre à la demande qu'il crée."},{"voice":"female","text":"Dans quel cas précis, selon l'oratrice, une campagne de prévention risque-t-elle de faire baisser la confiance des habitants ?"}],"audio":"q-38.mp3","audioSeconds":49.267,"slotSeconds":80},{"number":39,"kind":"interview","question":"Selon la responsable, que montre précisément la forte fréquentation du premier trimestre ?","options":["Qu’il existe un besoin, sans preuve que la qualité pourra être maintenue partout.","Que le volume de demandes suffit à financer durablement le cabinet mobile.","Qu’ils peuvent déjà garantir la même qualité de soins en multipliant les tournées.","Que l’itinéraire initial répond pleinement aux attentes de tous les villages concernés."],"correct":"A","explanation":"Réponse A : La responsable explique explicitement que la forte fréquentation montre l'existence d'un besoin, mais précise que cela ne prouve pas que la qualité pourra être maintenue partout. C'est donc la seule option qui reflète précisément ce que dit le texte. B : Quelqu’un pourrait croire que le volume de demandes suffit à financer durablement le cabinet mobile, car la forte fréquentation pourrait être interprétée comme une garantie de viabilité financière. Cependant, la responsable souligne qu'il reste des incertitudes sur le financement et que la fréquentation seule ne suffit pas. C : On pourrait penser que la forte fréquentation prouve déjà la capacité à garantir la même qualité en multipliant les tournées, mais la responsable dit explicitement que ce n'est pas garanti. D : Quelqu’un pourrait croire que l’itinéraire initial répond pleinement aux attentes de tous, mais la responsable précise qu’il faut encore consulter les villages non desservis, donc ce n’est pas prouvé.","transcript":"Question 39.\nLe cabinet mobile a été très fréquenté durant son premier trimestre. Pourquoi ne pas multiplier immédiatement les tournées ?\nParce que les premiers mois reposaient sur du matériel prêté et des heures supplémentaires exceptionnelles. Avant d'ajouter des destinations, nous devons savoir qui financera les remplacements, comment les dossiers seront suivis entre deux passages et où orienter les patients qui ont besoin d'un examen. Nous devons aussi recueillir l'avis des villages qui n'ont pas bénéficié du premier itinéraire. Une forte fréquentation démontre un besoin; elle ne garantit pas que nous pouvons maintenir la qualité des soins partout.\nSelon la responsable, que montre précisément la forte fréquentation du premier trimestre ?","segments":[{"voice":"female","text":"Question 39."},{"voice":"male","text":"Le cabinet mobile a été très fréquenté durant son premier trimestre. Pourquoi ne pas multiplier immédiatement les tournées ?"},{"voice":"female","text":"Parce que les premiers mois reposaient sur du matériel prêté et des heures supplémentaires exceptionnelles. Avant d'ajouter des destinations, nous devons savoir qui financera les remplacements, comment les dossiers seront suivis entre deux passages et où orienter les patients qui ont besoin d'un examen. Nous devons aussi recueillir l'avis des villages qui n'ont pas bénéficié du premier itinéraire. Une forte fréquentation démontre un besoin; elle ne garantit pas que nous pouvons maintenir la qualité des soins partout."},{"voice":"female","text":"Selon la responsable, que montre précisément la forte fréquentation du premier trimestre ?"}],"audio":"q-39.mp3","audioSeconds":42.344,"slotSeconds":82}]},{"id":"tcf-listening-04","version":"tcf-listening-2026-11-test04-v4","title":"TCF Listening · Test 04","seconds":2100,"questions":[{"number":1,"kind":"image","question":"Quelle phrase décrit correctement la scène ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"Réponse A : L'image montre une personne debout à côté d'une table sur laquelle elle aligne des boîtes. Il n'y a pas d'autres personnes ni d'activité de lecture visible. B : Aucune personne n'est assise ni en train de lire un roman sur l'image. La tentation vient du contexte de la médiathèque, mais l'action représentée ne correspond pas. C : Il n'y a qu'une seule personne visible, et aucune discussion devant une entrée n'est représentée. La mention de la médiathèque pourrait induire en erreur. D : La personne n'empile pas de livres sur des étagères hautes, mais aligne des boîtes sur une table. La confusion peut venir de la présence d'étagères à gauche.","transcript":"Question 1.\nRegardez l’image et écoutez les propositions.\nA. Une personne aligne des boîtes sur une table. B. Une personne lit un roman assise au bureau. C. Deux personnes discutent devant l’entrée de la médiathèque. D. Une personne empile des livres sur des étagères hautes.","segments":[{"voice":"female","text":"Question 1."},{"voice":"female","text":"Regardez l’image et écoutez les propositions."},{"voice":"female","text":"A. Une personne aligne des boîtes sur une table. B. Une personne lit un roman assise au bureau. C. Deux personnes discutent devant l’entrée de la médiathèque. D. Une personne empile des livres sur des étagères hautes."}],"audio":"q-01.mp3","audioSeconds":19.644,"slotSeconds":33,"image":"q-01.svg"},{"number":2,"kind":"image","question":"Quelle phrase décrit correctement la scène ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"Réponse C : Le tableau montre clairement des colonnes avec des jours de la semaine, ce qui correspond à un emploi du temps. A : Il n’y a pas de liste de noms d’élèves visible sur l’image, mais la présence d’un tableau pourrait faire penser à une liste pour quelqu’un qui n’a pas bien observé les détails. B : Il n’y a aucune carte du monde ni indication de pays sur l’image. Quelqu’un pourrait confondre l’école des langues avec une carte, mais rien ne le montre visuellement. D : Il n’y a pas de verbes ni de conjugaisons écrits sur le tableau, mais la présence d’un tableau dans une école de langues pourrait tromper quelqu’un.","transcript":"Question 2.\nRegardez l’image et écoutez les propositions.\nA. Une liste de noms d’élèves classés par niveau. B. Une carte du monde indiquant plusieurs pays. C. Un emploi du temps avec les jours de la semaine. D. Un tableau des verbes avec leurs conjugaisons.","segments":[{"voice":"female","text":"Question 2."},{"voice":"female","text":"Regardez l’image et écoutez les propositions."},{"voice":"female","text":"A. Une liste de noms d’élèves classés par niveau. B. Une carte du monde indiquant plusieurs pays. C. Un emploi du temps avec les jours de la semaine. D. Un tableau des verbes avec leurs conjugaisons."}],"audio":"q-02.mp3","audioSeconds":19.67,"slotSeconds":33,"image":"q-02.svg"},{"number":3,"kind":"image","question":"Quelle phrase décrit correctement la scène ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"Réponse C : L’élève tient une carte devant un boîtier, ce qui correspond à l’action de badger sa carte pour entrer en cours. Aucun autre objet ou personne n’est impliqué. A : On ne voit pas de ticket ni de fente sur l’image. Quelqu’un pourrait confondre le badge avec un ticket, mais il n’y a aucun élément visuel montrant une insertion de ticket. B : L’élève ne compose pas de code sur un clavier. Il n’y a pas de touches visibles sur le boîtier, ce qui pourrait prêter à confusion si l’on pense que tout boîtier sert à composer un code. D : Il n’y a pas de surveillant visible sur l’image. Quelqu’un pourrait penser que la carte est montrée à quelqu’un, mais l’élève est seul devant le boîtier.","transcript":"Question 3.\nRegardez l’image et écoutez les propositions.\nA. L’élève insère un ticket dans la fente du portail. B. L’élève compose un code sur le boîtier d’entrée. C. L’élève badge sa carte pour entrer en cours. D. L’élève montre sa carte à un surveillant.","segments":[{"voice":"female","text":"Question 3."},{"voice":"female","text":"Regardez l’image et écoutez les propositions."},{"voice":"female","text":"A. L’élève insère un ticket dans la fente du portail. B. L’élève compose un code sur le boîtier d’entrée. C. L’élève badge sa carte pour entrer en cours. D. L’élève montre sa carte à un surveillant."}],"audio":"q-03.mp3","audioSeconds":19.435,"slotSeconds":35,"image":"q-03.svg"},{"number":4,"kind":"image","question":"Quelle phrase décrit correctement la scène ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"Réponse D : On voit clairement un enfant tendre un livre à un adulte, ce qui correspond à la description correcte de la scène. A : Aucune des trois personnes ne lit un livre ; elles sont assises et un livre est échangé, mais personne ne lit. B : Ce n’est pas un adulte qui rend un livre à un enfant, mais l’inverse ; l’enfant tend le livre à l’adulte. C : Un seul enfant tient un livre, pas deux ; l’autre enfant n’a rien dans les mains.","transcript":"Question 4.\nRegardez l’image et écoutez les propositions.\nA. Les trois personnes lisent tranquillement leur livre. B. Un adulte rend un livre à un enfant. C. Deux enfants tiennent chacun un livre en main. D. Un enfant rend un livre à un adulte.","segments":[{"voice":"female","text":"Question 4."},{"voice":"female","text":"Regardez l’image et écoutez les propositions."},{"voice":"female","text":"A. Les trois personnes lisent tranquillement leur livre. B. Un adulte rend un livre à un enfant. C. Deux enfants tiennent chacun un livre en main. D. Un enfant rend un livre à un adulte."}],"audio":"q-04.mp3","audioSeconds":18.965,"slotSeconds":34,"image":"q-04.svg"},{"number":5,"kind":"response","question":"Quelle réponse convient à la situation ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"Réponse B : La bonne réponse est clairement indiquée dans la formulation de la question et des choix. Le cours de conversation a lieu dans la salle trois, au fond du couloir. A : Quelqu’un pourrait confondre la salle si l’attention est portée sur le numéro ou l’emplacement, mais le texte ne mentionne pas la salle quatre pour le cours de conversation. C : Quelqu’un pourrait se tromper de numéro de salle en retenant seulement l’emplacement 'au fond du couloir', mais la salle deux n’est pas mentionnée pour le cours de conversation. D : On pourrait confondre la salle trois avec un autre emplacement, mais la localisation correcte est 'au fond du couloir', pas 'près de la cour'.","transcript":"Question 5.\nLe cours de conversation a lieu dans quelle salle ?\nA. Dans la salle quatre, à côté du bureau. B. Dans la salle trois, au fond du couloir. C. Dans la salle deux, au fond du couloir. D. Dans la salle trois, près de la cour.","segments":[{"voice":"female","text":"Question 5."},{"voice":"female","text":"Le cours de conversation a lieu dans quelle salle ?"},{"voice":"male","text":"A. Dans la salle quatre, à côté du bureau. B. Dans la salle trois, au fond du couloir. C. Dans la salle deux, au fond du couloir. D. Dans la salle trois, près de la cour."}],"audio":"q-05.mp3","audioSeconds":18.39,"slotSeconds":35},{"number":6,"kind":"response","question":"Quelle réponse convient à la situation ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"Réponse A : La personne demande de l'aide pour un identifiant oublié. Répondre qu'on peut le réinitialiser répond directement à la demande d'aide et à la situation décrite. B : Cette réponse pourrait être choisie si l'on pense que l'interlocuteur ne peut pas aider directement, mais la question porte sur une aide immédiate. Or, la formulation 'Vous pouvez m'aider ?' attend une réponse directe, pas un renvoi. C : Quelqu'un pourrait croire que l'identifiant n'est pas nécessaire, mais la question porte sur l'oubli de l'identifiant pour accéder aux exercices. Rien n'indique dans l'énoncé que les exercices sont accessibles sans code. D : On pourrait penser que la demande d'accès n'est plus pertinente, mais la question ne mentionne pas que les exercices sont terminés, seulement un problème d'identifiant.","transcript":"Question 6.\nJ'ai oublié mon identifiant pour consulter les exercices. Vous pouvez m'aider ?\nA. Bien sûr, je peux le réinitialiser. B. Essayez plutôt d'appeler le secrétariat. C. Oui, les exercices sont accessibles sans code. D. Non, les exercices sont déjà terminés.","segments":[{"voice":"female","text":"Question 6."},{"voice":"male","text":"J'ai oublié mon identifiant pour consulter les exercices. Vous pouvez m'aider ?"},{"voice":"female","text":"A. Bien sûr, je peux le réinitialiser. B. Essayez plutôt d'appeler le secrétariat. C. Oui, les exercices sont accessibles sans code. D. Non, les exercices sont déjà terminés."}],"audio":"q-06.mp3","audioSeconds":21.943,"slotSeconds":36},{"number":7,"kind":"response","question":"Quelle réponse convient à la situation ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"Réponse C : Cette réponse répond directement à la question en confirmant qu'une inscription est nécessaire et précise le moyen (sur le site), ce qui correspond exactement à l'information recherchée. A : Cette réponse suppose que l'inscription n'est requise que pour les non-inscrits, ce qui n'est pas mentionné dans la question. Quelqu'un pourrait penser que la question implique une distinction entre inscrits et non-inscrits, mais il n'y a aucune indication de cette nuance. B : Cette réponse nie le besoin d'inscription, ce qui contredit la formulation de la question qui demande explicitement si une inscription est nécessaire. Quelqu'un pourrait mal comprendre et croire que l'inscription n'est pas requise, mais la question porte précisément sur cette nécessité. D : Cette réponse indique que l'inscription se fait sur place, ce qui pourrait être choisi si l'on comprend que l'inscription est requise mais sans précision sur le mode. Cependant, elle ne répond pas à la question sur la nécessité d'inscription en ligne, et pourrait être tentante si l'on suppose que l'inscription sur place est possible, ce qui n'est pas précisé.","transcript":"Question 7.\nEst-ce que l'atelier de demain demande une inscription ?\nA. Oui, uniquement pour les non-inscrits. B. Non, tu peux venir directement. C. Oui, il faut s'inscrire sur le site. D. Oui, l'inscription se fait sur place.","segments":[{"voice":"female","text":"Question 7."},{"voice":"female","text":"Est-ce que l'atelier de demain demande une inscription ?"},{"voice":"male","text":"A. Oui, uniquement pour les non-inscrits. B. Non, tu peux venir directement. C. Oui, il faut s'inscrire sur le site. D. Oui, l'inscription se fait sur place."}],"audio":"q-07.mp3","audioSeconds":19.592,"slotSeconds":32},{"number":8,"kind":"response","question":"Quelle réponse convient à la situation ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"Réponse B : La demande porte sur un prêt jusqu'à la semaine prochaine, donc un prêt d'une semaine. Cette réponse correspond exactement à la demande formulée. A : La personne demande à emprunter le dictionnaire jusqu'à la semaine prochaine, donc plus longtemps qu'un simple week-end. Quelqu'un pourrait confondre « jusqu'à la semaine prochaine » avec « pour le week-end » si elle pense que la semaine prochaine commence juste après le week-end, mais la demande précise une durée d'une semaine. C : Quelqu'un pourrait croire que certains dictionnaires ne sont pas empruntables et restent en consultation sur place, mais ici la question porte sur la durée de l'emprunt, pas sur la possibilité de l'emprunter en général. Rien n'indique dans la question que le dictionnaire est exclu du prêt. D : La personne demande un prêt jusqu'à la semaine prochaine, donc plus d'une journée. Quelqu'un pourrait croire que le prêt est possible mais pour une durée plus courte (jusqu'à demain), mais cela ne répond pas à la demande initiale.","transcript":"Question 8.\nPuis-je emprunter ce dictionnaire jusqu'à la semaine prochaine ?\nA. Oui, mais uniquement pour le week-end. B. Oui, le prêt d’une semaine est possible. C. Non, ce dictionnaire reste en consultation sur place. D. Oui, mais il doit être rendu dès demain.","segments":[{"voice":"female","text":"Question 8."},{"voice":"male","text":"Puis-je emprunter ce dictionnaire jusqu'à la semaine prochaine ?"},{"voice":"female","text":"A. Oui, mais uniquement pour le week-end. B. Oui, le prêt d’une semaine est possible. C. Non, ce dictionnaire reste en consultation sur place. D. Oui, mais il doit être rendu dès demain."}],"audio":"q-08.mp3","audioSeconds":19.905,"slotSeconds":37},{"number":9,"kind":"announcement","question":"Où les étudiants suivront-ils le cours de demain ?","options":["Au laboratoire trois, au premier étage.","Dans la salle dix-huit, au rez-de-chaussée.","Dans la salle dix-huit, au premier étage.","Au laboratoire trois, au rez-de-chaussée."],"correct":"D","explanation":"Réponse D : Le texte indique clairement que le cours aura lieu au laboratoire trois, au rez-de-chaussée. C'est la seule option qui correspond exactement à l'information donnée. A : Cette option mentionne le bon laboratoire mais se trompe d'étage. Quelqu'un pourrait confondre l'étage habituel de la salle dix-huit (premier étage) avec le laboratoire, mais le texte précise que le laboratoire trois est au rez-de-chaussée. B : Cette option mentionne la salle habituelle (dix-huit, rez-de-chaussée), mais le texte indique explicitement que le cours est déplacé au laboratoire trois. Quelqu'un pourrait ignorer le changement de salle. C : Cette option mélange la salle habituelle (dix-huit) et l'étage du laboratoire (premier étage), alors que le laboratoire trois est au rez-de-chaussée. Quelqu'un pourrait confondre les deux lieux.","transcript":"Question 9.\nLe cours de phonétique du groupe B prévu dans la salle dix-huit aura lieu demain au laboratoire trois, au rez-de-chaussée. Le projecteur de la salle habituelle est en réparation. L'horaire de neuf heures reste inchangé, et les étudiants doivent apporter leurs écouteurs.\nOù les étudiants suivront-ils le cours de demain ?","segments":[{"voice":"female","text":"Question 9."},{"voice":"female","text":"Le cours de phonétique du groupe B prévu dans la salle dix-huit aura lieu demain au laboratoire trois, au rez-de-chaussée. Le projecteur de la salle habituelle est en réparation. L'horaire de neuf heures reste inchangé, et les étudiants doivent apporter leurs écouteurs."},{"voice":"female","text":"Où les étudiants suivront-ils le cours de demain ?"}],"audio":"q-09.mp3","audioSeconds":19.722,"slotSeconds":38},{"number":10,"kind":"dialogue","question":"Jusqu'à quel jour l'administration garantit-elle la place de l'étudiant ?","options":["Jusqu'à la fin du mois","Jusqu'à jeudi","Jusqu'à mercredi","Jusqu'à vendredi"],"correct":"D","explanation":"Réponse D : Le texte indique explicitement que la place est garantie 'jusqu'à vendredi', ce qui répond directement à la question. A : Quelqu'un pourrait penser que 'jusqu'à la fin du mois' est une durée généreuse, mais l'enregistrement précise une date bien plus rapprochée. B : 'Jusqu'à jeudi' est proche de la bonne réponse et pourrait être choisi par quelqu'un qui a mal entendu ou confondu les jours de la semaine. C : 'Jusqu'à mercredi' est aussi une erreur plausible pour quelqu'un qui n'a pas bien retenu le jour exact, mais le texte dit clairement 'vendredi'.","transcript":"Question 10.\nJ'ai reçu le programme de sciences, mais mon nom n'apparaît pas sur la liste des participants.\nVotre dossier est complet, mais l'autorisation de votre établissement n'a pas encore été transmise.\nJe peux vous l'apporter demain.\nOui, nous garderons votre place jusqu'à vendredi. Ensuite, nous confirmerons l'inscription.\nJusqu'à quel jour l'administration garantit-elle la place de l'étudiant ?","segments":[{"voice":"female","text":"Question 10."},{"voice":"male","text":"J'ai reçu le programme de sciences, mais mon nom n'apparaît pas sur la liste des participants."},{"voice":"female","text":"Votre dossier est complet, mais l'autorisation de votre établissement n'a pas encore été transmise."},{"voice":"male","text":"Je peux vous l'apporter demain."},{"voice":"female","text":"Oui, nous garderons votre place jusqu'à vendredi. Ensuite, nous confirmerons l'inscription."},{"voice":"female","text":"Jusqu'à quel jour l'administration garantit-elle la place de l'étudiant ?"}],"audio":"q-10.mp3","audioSeconds":25.731,"slotSeconds":42},{"number":11,"kind":"announcement","question":"Jusqu'à quel moment les participants peuvent-ils proposer un thème de discussion ?","options":["Jusqu'à vendredi à midi.","Jusqu'à mercredi à midi.","Jusqu'à mercredi en fin de journée.","Jusqu'à mardi à midi."],"correct":"B","explanation":"Réponse B : Le texte indique clairement que les participants peuvent proposer un thème jusqu'à mercredi à midi. C'est la seule option qui correspond exactement à l'information donnée. A : Quelqu'un pourrait confondre la date limite pour proposer un thème avec la date d'envoi du programme, qui est vendredi. Cependant, le texte précise que la date limite pour proposer un thème est mercredi à midi. C : Quelqu'un pourrait mal interpréter 'mercredi à midi' comme 'mercredi en fin de journée', pensant que la journée entière est disponible. Cependant, la limite est spécifiquement fixée à midi. D : Une personne pourrait confondre le jour exact, pensant que la date limite est mardi à midi au lieu de mercredi à midi, mais le texte précise bien mercredi.","transcript":"Question 11.\nLe club des langues prépare une soirée d'échanges. Les participants pourront proposer un thème de discussion sur le formulaire du site, jusqu'à mercredi à midi. Les organisateurs choisiront ensuite quatre thèmes et enverront le programme vendredi. Il n'est pas nécessaire de téléphoner pour s'inscrire.\nJusqu'à quel moment les participants peuvent-ils proposer un thème de discussion ?","segments":[{"voice":"female","text":"Question 11."},{"voice":"male","text":"Le club des langues prépare une soirée d'échanges. Les participants pourront proposer un thème de discussion sur le formulaire du site, jusqu'à mercredi à midi. Les organisateurs choisiront ensuite quatre thèmes et enverront le programme vendredi. Il n'est pas nécessaire de téléphoner pour s'inscrire."},{"voice":"female","text":"Jusqu'à quel moment les participants peuvent-ils proposer un thème de discussion ?"}],"audio":"q-11.mp3","audioSeconds":26.175,"slotSeconds":41},{"number":12,"kind":"dialogue","question":"Dans quelles conditions la tutrice accepte-t-elle de poursuivre le tutorat ?","options":["Le jeudi après-midi dans la petite salle près du secrétariat.","Le vendredi matin dans la petite salle près du secrétariat.","Le vendredi après-midi dans la salle habituelle.","Le vendredi après-midi dans la petite salle près du secrétariat."],"correct":"D","explanation":"Réponse D : C'est la seule option qui reprend exactement les conditions acceptées par la tutrice : le vendredi après-midi ET dans la petite salle près du secrétariat. A : Quelqu'un pourrait confondre les jours, pensant que le jeudi est encore possible, mais la tutrice précise qu'elle n'est plus disponible ce jour-là. B : La confusion peut venir du bon jour (vendredi) mais la mauvaise heure (matin au lieu d'après-midi), alors que la tutrice ne propose que l'après-midi. C : La personne pourrait retenir le bon créneau (vendredi après-midi) mais oublier la condition de la salle, alors que la tutrice exige la petite salle près du secrétariat.","transcript":"Question 12.\nJe peux encore vous accompagner en mathématiques le mardi, mais je ne serai plus disponible le jeudi.\nJ'ai déjà un cours de musique le mardi. Est-ce possible de se voir le vendredi ?\nLe vendredi après-midi, oui, si nous utilisons la petite salle près du secrétariat.\nParfait. Je vais prévenir la personne qui coordonne les séances.\nDans quelles conditions la tutrice accepte-t-elle de poursuivre le tutorat ?","segments":[{"voice":"female","text":"Question 12."},{"voice":"female","text":"Je peux encore vous accompagner en mathématiques le mardi, mais je ne serai plus disponible le jeudi."},{"voice":"male","text":"J'ai déjà un cours de musique le mardi. Est-ce possible de se voir le vendredi ?"},{"voice":"female","text":"Le vendredi après-midi, oui, si nous utilisons la petite salle près du secrétariat."},{"voice":"male","text":"Parfait. Je vais prévenir la personne qui coordonne les séances."},{"voice":"female","text":"Dans quelles conditions la tutrice accepte-t-elle de poursuivre le tutorat ?"}],"audio":"q-12.mp3","audioSeconds":27.611,"slotSeconds":43},{"number":13,"kind":"announcement","question":"Quelle activité sera interrompue mardi ?","options":["Les expériences du groupe de troisième.","Les ateliers de lecture organisés à la bibliothèque.","Les contrôles des installations électriques du laboratoire.","Les préparations de cours des enseignants au laboratoire."],"correct":"A","explanation":"Réponse A : Le texte indique explicitement que les expériences du groupe de troisième, prévues mardi, sont reportées à jeudi, donc interrompues mardi. B : Quelqu’un pourrait croire que toutes les activités scolaires sont interrompues, mais le texte précise que les ateliers de lecture à la bibliothèque continuent normalement. C : On pourrait penser que les contrôles sont interrompus, mais au contraire, ils sont la raison de la fermeture du laboratoire mardi, donc ils ont lieu ce jour-là. D : On pourrait croire que les préparations de cours des enseignants sont interrompues, mais le texte précise que le laboratoire reste accessible aux enseignants lundi et mercredi, donc ce n’est pas mardi que leur activité est explicitement interrompue.","transcript":"Question 13.\nLe laboratoire de sciences restera accessible aux enseignants lundi et mercredi, mais il sera fermé aux classes mardi pour vérifier les installations électriques. Les travaux n'affectent pas la bibliothèque, où les ateliers de lecture auront lieu normalement. Les expériences du groupe de troisième sont reportées à jeudi.\nQuelle activité sera interrompue mardi ?","segments":[{"voice":"female","text":"Question 13."},{"voice":"female","text":"Le laboratoire de sciences restera accessible aux enseignants lundi et mercredi, mais il sera fermé aux classes mardi pour vérifier les installations électriques. Les travaux n'affectent pas la bibliothèque, où les ateliers de lecture auront lieu normalement. Les expériences du groupe de troisième sont reportées à jeudi."},{"voice":"female","text":"Quelle activité sera interrompue mardi ?"}],"audio":"q-13.mp3","audioSeconds":21.786,"slotSeconds":39},{"number":14,"kind":"dialogue","question":"Selon l’échange, que prévoit-on pour les étudiants qui attendent leur tour devant l’ordinateur ?","options":["Ils auront une pause libre jusqu’à ce que la salle se libère.","Ils commenceront l’écoute sur leur téléphone personnel.","Ils corrigeront l’exercice d’écoute précédent avec le professeur.","Ils feront un exercice de lecture en attendant."],"correct":"D","explanation":"Réponse D : Le texte indique clairement que les étudiants qui attendent feront un exercice de lecture pendant que l'autre groupe utilise les ordinateurs. A : Il n'est pas question d'une pause libre, mais d'une tâche de lecture prévue pour les étudiants qui attendent. Quelqu'un pourrait croire à une pause car les étudiants ne participent pas immédiatement à l'exercice d'écoute, mais le texte précise une activité à faire. B : Aucune mention n'est faite de l'utilisation du téléphone personnel pour commencer l'écoute. Quelqu'un pourrait penser à cette solution car il s'agit d'un exercice d'écoute et les ordinateurs sont limités, mais le texte indique une autre activité pour ceux qui attendent. C : Il n'est pas question de corriger l'exercice d'écoute précédent avec le professeur. Cette option pourrait sembler plausible car il s'agit d'une activité pédagogique à faire en attendant, mais le texte mentionne explicitement une tâche de lecture.","transcript":"Question 14.\nLe haut-parleur de la salle ne fonctionne plus. Nous avons un exercice d'écoute dans dix minutes.\nLe laboratoire audio est occupé, mais j'ai réservé une petite salle avec huit ordinateurs.\nNous avons douze étudiants.\nOn pourrait les répartir en deux groupes et faire l'activité l'un après l'autre.\nD'accord, je prépare une tâche de lecture pour ceux qui attendent.\nSelon l’échange, que prévoit-on pour les étudiants qui attendent leur tour devant l’ordinateur ?","segments":[{"voice":"female","text":"Question 14."},{"voice":"male","text":"Le haut-parleur de la salle ne fonctionne plus. Nous avons un exercice d'écoute dans dix minutes."},{"voice":"female","text":"Le laboratoire audio est occupé, mais j'ai réservé une petite salle avec huit ordinateurs."},{"voice":"male","text":"Nous avons douze étudiants."},{"voice":"female","text":"On pourrait les répartir en deux groupes et faire l'activité l'un après l'autre."},{"voice":"male","text":"D'accord, je prépare une tâche de lecture pour ceux qui attendent."},{"voice":"female","text":"Selon l’échange, que prévoit-on pour les étudiants qui attendent leur tour devant l’ordinateur ?"}],"audio":"q-14.mp3","audioSeconds":30.955,"slotSeconds":47},{"number":15,"kind":"radio-news","question":"Quelle difficulté accompagne le lancement des cours du soir ?","options":["Plusieurs adultes jugent l’offre en bureautique et en langues trop limitée par rapport à leurs besoins.","Les candidats déplorent l’absence de transports en commun après la fin des cours.","Certains hésitent à s’inscrire parce que le calendrier définitif des cours n’est pas encore arrêté.","Beaucoup de salariés peinent à concilier les horaires proposés avec leur journée de travail."],"correct":"B","explanation":"Réponse B : Le texte mentionne explicitement que le manque de transports collectifs après 22h est une difficulté signalée par plusieurs candidats, ce qui correspond exactement à la réponse. A : Quelqu’un pourrait croire que l’offre est trop limitée, mais le texte indique au contraire que ces cours sont très demandés. Il n’est pas question d’une offre jugée insuffisante. C : Il est vrai que le calendrier n’est pas encore annoncé, mais il n’est pas dit que cela fait hésiter certains à s’inscrire. Le texte ne relie pas l’absence de calendrier à une hésitation des candidats. D : Bien que les cours soient destinés aux adultes en emploi, il n’est pas mentionné que beaucoup de salariés ont du mal à concilier les horaires avec leur travail. Cette difficulté n’est pas évoquée dans le texte.","transcript":"Question 15.\nÀ Rennes, une université populaire ouvre trois nouveaux cours du soir à destination des adultes en emploi. Les inscriptions sont nombreuses, notamment pour la bureautique et les langues. Toutefois, plusieurs candidats regrettent le manque de transports collectifs après vingt-deux heures. L'établissement discute avec la métropole d'une correspondance supplémentaire, sans annoncer encore de calendrier.\nQuelle difficulté accompagne le lancement des cours du soir ?","segments":[{"voice":"female","text":"Question 15."},{"voice":"female","text":"À Rennes, une université populaire ouvre trois nouveaux cours du soir à destination des adultes en emploi. Les inscriptions sont nombreuses, notamment pour la bureautique et les langues. Toutefois, plusieurs candidats regrettent le manque de transports collectifs après vingt-deux heures. L'établissement discute avec la métropole d'une correspondance supplémentaire, sans annoncer encore de calendrier."},{"voice":"female","text":"Quelle difficulté accompagne le lancement des cours du soir ?"}],"audio":"q-15.mp3","audioSeconds":28.944,"slotSeconds":49},{"number":16,"kind":"dialogue","question":"Comment vont-ils concrètement organiser leurs séances ?","options":["Ils échangent leurs groupes de mardi et de jeudi, tout en conservant les mêmes salles.","Ils déplacent les deux séances au jeudi matin, en annulant celle du mardi.","Ils gardent chacun leurs groupes, mais changent de salles pour mardi et jeudi.","Ils échangent seulement le créneau de jeudi, la séance de mardi restant inchangée."],"correct":"A","explanation":"Réponse A : Le texte indique explicitement qu'ils échangent leurs groupes de mardi et de jeudi, tout en gardant les mêmes salles. Cela répond précisément à la question sur l'organisation concrète des séances. B : Quelqu'un pourrait croire qu'ils déplacent tout au jeudi matin car la première phrase mentionne jeudi matin, mais il est clairement dit qu'ils échangent les séances, pas qu'ils annulent celle du mardi. C : On pourrait penser qu'ils gardent leurs groupes mais changent de salles, mais le texte dit explicitement qu'ils échangent les groupes et que les salles ne changent pas. D : On pourrait croire qu'ils n'échangent que le créneau de jeudi, car la première phrase mentionne jeudi matin, mais la suite précise qu'ils échangent les deux séances (mardi et jeudi).","transcript":"Question 16.\nJe peux prendre ton groupe jeudi matin si tu veux. J'ai terminé les évaluations prévues.\nMerci. Un jury d'examen m'a demandé de remplacer un collègue absent à cette heure-là.\nOn intervertira nos séances : tu prendras mon groupe mardi et je garderai le tien jeudi.\nJe préviendrai les étudiants, les salles ne changent pas.\nComment vont-ils concrètement organiser leurs séances ?","segments":[{"voice":"female","text":"Question 16."},{"voice":"female","text":"Je peux prendre ton groupe jeudi matin si tu veux. J'ai terminé les évaluations prévues."},{"voice":"male","text":"Merci. Un jury d'examen m'a demandé de remplacer un collègue absent à cette heure-là."},{"voice":"female","text":"On intervertira nos séances : tu prendras mon groupe mardi et je garderai le tien jeudi."},{"voice":"male","text":"Je préviendrai les étudiants, les salles ne changent pas."},{"voice":"female","text":"Comment vont-ils concrètement organiser leurs séances ?"}],"audio":"q-16.mp3","audioSeconds":26.096,"slotSeconds":41},{"number":17,"kind":"announcement","question":"Que précise l’annonce à propos du certificat scolaire pour s’inscrire à la médiathèque ?","options":["Qu’aucun certificat scolaire n’est exigé pour l’inscription.","Qu’un certificat scolaire est obligatoire pour les nouveaux inscrits mineurs.","Qu’un certificat scolaire est requis uniquement lors du renouvellement de la carte.","Qu’un certificat scolaire peut remplacer le justificatif de domicile demandé."],"correct":"A","explanation":"Réponse A : L'annonce précise explicitement qu'aucun certificat scolaire n'est demandé pour l'inscription. Cela répond directement à la question posée. B : Quelqu'un pourrait croire qu'un certificat scolaire est obligatoire pour les mineurs, car c'est parfois le cas dans d'autres contextes administratifs. Cependant, l'annonce précise qu'aucun certificat scolaire n'est demandé, ce qui contredit cette option. C : On pourrait penser qu'un certificat scolaire est requis lors du renouvellement, mais l'annonce indique seulement que la carte suffit pour prolonger l'abonnement, sans mention de certificat scolaire. Cela contredit donc cette option. D : Quelqu'un pourrait croire qu'un certificat scolaire peut remplacer un justificatif de domicile, mais l'annonce précise qu'il faut un justificatif de domicile et qu'aucun certificat scolaire n'est demandé, donc il ne peut pas servir de remplacement.","transcript":"Question 17.\nLa médiathèque accueillera les nouveaux inscrits samedi. Pour établir une carte, apportez un justificatif de domicile récent et une pièce d'identité. Aucun certificat scolaire n'est demandé. Les personnes ayant déjà une carte peuvent simplement la présenter au guichet pour prolonger leur abonnement.\nQue précise l’annonce à propos du certificat scolaire pour s’inscrire à la médiathèque ?","segments":[{"voice":"female","text":"Question 17."},{"voice":"male","text":"La médiathèque accueillera les nouveaux inscrits samedi. Pour établir une carte, apportez un justificatif de domicile récent et une pièce d'identité. Aucun certificat scolaire n'est demandé. Les personnes ayant déjà une carte peuvent simplement la présenter au guichet pour prolonger leur abonnement."},{"voice":"female","text":"Que précise l’annonce à propos du certificat scolaire pour s’inscrire à la médiathèque ?"}],"audio":"q-17.mp3","audioSeconds":26.201,"slotSeconds":47},{"number":18,"kind":"telephone","question":"Quelle particularité de la session du samedi est indiquée par rapport à celle du lundi au jeudi ?","options":["Elle reprend les mêmes objectifs, mais les exercices se font en petit groupe.","Elle réduit le nombre d’objectifs pour consacrer plus de temps au travail individuel.","Elle garde les mêmes objectifs mais se termine plus tôt chaque journée.","Elle ajoute des objectifs supplémentaires tout en conservant les mêmes horaires."],"correct":"A","explanation":"Réponse A : La session du samedi reprend les mêmes objectifs que celle du lundi au jeudi, mais la différence indiquée est que les exercices se font en petit groupe. C'est explicitement mentionné dans le stimulus. B : Quelqu’un pourrait croire que la session du samedi réduit le nombre d’objectifs pour consacrer plus de temps au travail individuel, car il est mentionné un changement dans la façon de travailler (petit groupe), mais le texte précise bien que les objectifs restent les mêmes. C : On pourrait penser que la session du samedi se termine plus tôt chaque journée, car les horaires du lundi au jeudi sont précisés, mais aucune information n’est donnée sur une modification des horaires pour le samedi. D : On pourrait croire que des objectifs supplémentaires sont ajoutés, mais le texte dit explicitement que les objectifs sont les mêmes.","transcript":"Question 18.\nBonjour, je m'intéresse à votre formation informatique de vingt heures.\nElle commence lundi et se déroule du lundi au jeudi, de neuf à quinze heures.\nJe travaille à ces horaires. Votre brochure mentionne aussi une session répartie sur quatre samedis.\nOui, elle reprend les mêmes objectifs, mais les exercices se font en petit groupe.\nDans ce cas, inscrivez-moi à celle du samedi, s'il reste une place.\nQuelle particularité de la session du samedi est indiquée par rapport à celle du lundi au jeudi ?","segments":[{"voice":"female","text":"Question 18."},{"voice":"female","text":"Bonjour, je m'intéresse à votre formation informatique de vingt heures."},{"voice":"male","text":"Elle commence lundi et se déroule du lundi au jeudi, de neuf à quinze heures."},{"voice":"female","text":"Je travaille à ces horaires. Votre brochure mentionne aussi une session répartie sur quatre samedis."},{"voice":"male","text":"Oui, elle reprend les mêmes objectifs, mais les exercices se font en petit groupe."},{"voice":"female","text":"Dans ce cas, inscrivez-moi à celle du samedi, s'il reste une place."},{"voice":"female","text":"Quelle particularité de la session du samedi est indiquée par rapport à celle du lundi au jeudi ?"}],"audio":"q-18.mp3","audioSeconds":32.627,"slotSeconds":46},{"number":19,"kind":"announcement","question":"Selon ce message, à qui le personnel souhaite-t-il accorder une attention particulière pendant les ateliers ?","options":["Aux enfants qui lisent déjà couramment.","Aux parents qui restent dans l’espace voisin.","Aux enfants qui découvrent encore les sons et les lettres.","Aux familles qui s’inscrivent pour les séances du mercredi."],"correct":"C","explanation":"Réponse C : Le message indique explicitement que le personnel souhaite consacrer davantage de temps à ceux qui découvrent encore les sons et les lettres, ce qui répond précisément à la question. A : Quelqu’un pourrait penser que le personnel veut aider tous les enfants, y compris ceux qui lisent déjà couramment, mais le message précise que l’attention particulière est pour ceux qui découvrent encore les sons et les lettres. B : On mentionne les parents, mais il n’est jamais dit que le personnel souhaite leur accorder une attention particulière ; ils sont simplement autorisés à rester à proximité. D : Quelqu’un pourrait croire que les familles inscrites pour le mercredi reçoivent une attention particulière, mais le texte dit seulement qu’elles pourront participer grâce à des séances supplémentaires, sans mention d’attention particulière.","transcript":"Question 19.\nPendant les vacances, les ateliers de lecture pour les enfants seront limités à dix participants. Le personnel souhaite consacrer davantage de temps à chaque lecteur, notamment à ceux qui découvrent encore les sons et les lettres. Les parents pourront rester dans l'espace voisin. Les séances supplémentaires du mercredi permettront d'accueillir davantage de familles.\nSelon ce message, à qui le personnel souhaite-t-il accorder une attention particulière pendant les ateliers ?","segments":[{"voice":"female","text":"Question 19."},{"voice":"female","text":"Pendant les vacances, les ateliers de lecture pour les enfants seront limités à dix participants. Le personnel souhaite consacrer davantage de temps à chaque lecteur, notamment à ceux qui découvrent encore les sons et les lettres. Les parents pourront rester dans l'espace voisin. Les séances supplémentaires du mercredi permettront d'accueillir davantage de familles."},{"voice":"female","text":"Selon ce message, à qui le personnel souhaite-t-il accorder une attention particulière pendant les ateliers ?"}],"audio":"q-19.mp3","audioSeconds":27.324,"slotSeconds":41},{"number":20,"kind":"dialogue","question":"Que prévoit l’enseignant pour faciliter le travail de l’apprenant ?","options":["Lui remettre uniquement une version imprimée des documents de la leçon.","Lui réserver des séances supplémentaires dans la salle informatique de l’établissement.","Lui préparer une version imprimée et lui indiquer le prêt d’ordinateurs à la bibliothèque.","Lui envoyer davantage d’exercices qu’il pourra faire sur son téléphone familial."],"correct":"C","explanation":"Réponse C : L’enseignant propose explicitement de préparer une version imprimée ET informe l’élève du prêt d’ordinateurs à la bibliothèque. C’est la seule option qui reprend ces deux éléments ensemble. A : Quelqu’un pourrait penser que seule la version imprimée est proposée, car l’enseignant commence par cette solution. Cependant, il ajoute immédiatement une deuxième aide (prêt d’ordinateurs). B : On pourrait croire que l’enseignant organise des séances supplémentaires à l’école, mais il ne s’agit pas de séances encadrées, seulement d’un prêt d’ordinateurs à la bibliothèque. D : Quelqu’un pourrait penser que l’enseignant va envoyer plus d’exercices à faire sur le téléphone, car l’élève mentionne qu’il partage un téléphone familial, mais l’enseignant ne propose pas cette solution.","transcript":"Question 20.\nJ'aime bien les exercices en ligne, mais je n'arrive pas à télécharger les documents de la leçon.\nVotre connexion fonctionne-t-elle normalement ?\nPas toujours. Je partage un seul téléphone avec ma famille et je n'ai pas d'ordinateur chez moi.\nJe peux vous préparer une version imprimée, et la bibliothèque prête des ordinateurs sur rendez-vous.\nCela m'aiderait à travailler régulièrement.\nQue prévoit l’enseignant pour faciliter le travail de l’apprenant ?","segments":[{"voice":"female","text":"Question 20."},{"voice":"male","text":"J'aime bien les exercices en ligne, mais je n'arrive pas à télécharger les documents de la leçon."},{"voice":"female","text":"Votre connexion fonctionne-t-elle normalement ?"},{"voice":"male","text":"Pas toujours. Je partage un seul téléphone avec ma famille et je n'ai pas d'ordinateur chez moi."},{"voice":"female","text":"Je peux vous préparer une version imprimée, et la bibliothèque prête des ordinateurs sur rendez-vous."},{"voice":"male","text":"Cela m'aiderait à travailler régulièrement."},{"voice":"female","text":"Que prévoit l’enseignant pour faciliter le travail de l’apprenant ?"}],"audio":"q-20.mp3","audioSeconds":29.597,"slotSeconds":46},{"number":21,"kind":"announcement","question":"Pourquoi les bénévoles sont-ils invités à confirmer leurs créneaux ?","options":["Pour permettre à la responsable de former des binômes pour chaque créneau.","Pour vérifier qu’il y a assez de monde le mercredi avant d’ouvrir d’autres créneaux.","Pour attribuer en priorité les créneaux du vendredi aux bénévoles les plus expérimentés.","Pour décider quels créneaux pourront être annulés faute de candidats."],"correct":"A","explanation":"Réponse A : Le texte explique clairement que la responsable va former des groupes de deux (binômes) pour chaque créneau, ce qui nécessite de connaître les disponibilités des bénévoles. B : Quelqu’un pourrait croire que la confirmation sert à vérifier le nombre de bénévoles le mercredi, car il est mentionné que ce jour-là est déjà bien couvert. Cependant, la demande de confirmation concerne tous les créneaux, et la formation de binômes est l'objectif principal. C : On pourrait penser que les créneaux du vendredi sont réservés aux bénévoles expérimentés, car il manque de monde ce jour-là. Mais le texte ne parle pas de priorité selon l'expérience, seulement du besoin de binômes. D : Quelqu’un pourrait croire que la confirmation sert à annuler des créneaux sans candidats, mais le texte ne mentionne pas l’annulation de créneaux, seulement la constitution de groupes de deux.","transcript":"Question 21.\nL'association Lire ensemble cherche des bénévoles pour ses ateliers d'aide à la lecture. Les séances du mercredi sont déjà bien couvertes, mais celles du vendredi en fin d'après-midi manquent d'accompagnateurs. Merci d'indiquer vos horaires possibles d'ici lundi. La responsable établira ensuite des groupes de deux, afin que personne n'anime une séance seul lors de sa première participation.\nPourquoi les bénévoles sont-ils invités à confirmer leurs créneaux ?","segments":[{"voice":"female","text":"Question 21."},{"voice":"female","text":"L'association Lire ensemble cherche des bénévoles pour ses ateliers d'aide à la lecture. Les séances du mercredi sont déjà bien couvertes, mais celles du vendredi en fin d'après-midi manquent d'accompagnateurs. Merci d'indiquer vos horaires possibles d'ici lundi. La responsable établira ensuite des groupes de deux, afin que personne n'anime une séance seul lors de sa première participation."},{"voice":"female","text":"Pourquoi les bénévoles sont-ils invités à confirmer leurs créneaux ?"}],"audio":"q-21.mp3","audioSeconds":27.533,"slotSeconds":54},{"number":22,"kind":"interview","question":"Selon la formatrice, à quel moment le vrai changement se produit-il pour ces adultes ?","options":["Quand ils obtiennent une bonne note à une évaluation","Quand ils osent poser une question devant les autres","Quand ils reprennent seuls les notions oubliées à la maison","Quand ils remplissent régulièrement le cahier d’exercices"],"correct":"B","explanation":"Réponse B : La formatrice dit explicitement que le vrai changement se produit lorsqu'ils osent poser une question devant les autres. C'est la réponse directement soutenue par le texte. A : Quelqu'un pourrait croire qu'obtenir une bonne note à une évaluation marque un changement, car la formatrice mentionne la peur de l'évaluation. Cependant, elle précise que le vrai changement se produit lorsqu'ils osent poser une question devant les autres, pas lors d'une évaluation. C : On pourrait penser que reprendre seul les notions oubliées à la maison est le moment du changement, car la formatrice évoque ce besoin. Cependant, elle distingue ce besoin du vrai changement, qui est lié à l'interaction en groupe. D : Remplir le cahier d'exercices est mentionné comme utile, mais explicitement opposé au vrai changement qui vient du soutien entre apprenants, donc ce n'est pas la bonne réponse.","transcript":"Question 22.\nVotre atelier réunit des adultes qui reprennent leurs études après plusieurs années. Que leur apportent surtout les rencontres en groupe ?\nCertains ont besoin de revoir des notions, mais le vrai changement se produit souvent lorsqu'ils osent poser une question devant d'autres personnes. Ils découvrent qu'ils ne sont pas seuls à avoir oublié une méthode ou à redouter une évaluation. Cette confiance les aide à poursuivre un parcours qui paraissait inaccessible. Un cahier d'exercices peut être utile, mais il ne remplace pas ce soutien entre apprenants.\nSelon la formatrice, à quel moment le vrai changement se produit-il pour ces adultes ?","segments":[{"voice":"female","text":"Question 22."},{"voice":"male","text":"Votre atelier réunit des adultes qui reprennent leurs études après plusieurs années. Que leur apportent surtout les rencontres en groupe ?"},{"voice":"female","text":"Certains ont besoin de revoir des notions, mais le vrai changement se produit souvent lorsqu'ils osent poser une question devant d'autres personnes. Ils découvrent qu'ils ne sont pas seuls à avoir oublié une méthode ou à redouter une évaluation. Cette confiance les aide à poursuivre un parcours qui paraissait inaccessible. Un cahier d'exercices peut être utile, mais il ne remplace pas ce soutien entre apprenants."},{"voice":"female","text":"Selon la formatrice, à quel moment le vrai changement se produit-il pour ces adultes ?"}],"audio":"q-22.mp3","audioSeconds":37.695,"slotSeconds":61},{"number":23,"kind":"panel-discussion","question":"Quelle serait la particularité de la permanence proposée pour les devoirs ?","options":["Elle serait facultative et servirait à terminer ce qui pose problème.","Elle serait organisée le week-end pour libérer les soirées de semaine.","Elle serait réservée uniquement aux élèves sans adulte disponible à la maison.","Elle serait obligatoire pour tous les élèves à la fin de chaque journée."],"correct":"A","explanation":"Réponse A : La professeure propose explicitement une permanence facultative pour terminer ce qui pose problème, ce qui correspond exactement à cette option. B : Quelqu'un pourrait penser que la permanence est organisée le week-end pour libérer les soirées de semaine, car il est question de soulager la charge des familles le soir. Cependant, le texte ne mentionne jamais le week-end, ni une organisation spécifique à ce moment-là. C : Il est mentionné que certains enfants n'ont pas d'adulte disponible, ce qui pourrait faire croire que la permanence leur est réservée. Pourtant, il n'est jamais dit qu'elle est exclusivement pour eux, seulement que la permanence est facultative pour tous. D : Le mot 'facultative' est clairement utilisé, donc ce n'est pas obligatoire pour tous. Quelqu'un pourrait confondre la volonté d'aider tous les élèves avec une obligation générale, mais ce n'est pas ce qui est proposé.","transcript":"Question 23.\nUne représentante de parents estime que les devoirs écrits prennent trop de temps aux familles.\nComme professeur, je comprends cette difficulté, mais je souhaite conserver une occasion de réviser les notions.\nLes enfants n'ont pas tous un adulte disponible pour les accompagner.\nNous pourrions proposer des exercices courts, commencés en classe, avec une permanence facultative pour terminer ce qui pose problème.\nSi les consignes sont claires et que la charge est limitée, ce serait un progrès.\nÉvaluons cette formule pendant un trimestre.\nQuelle serait la particularité de la permanence proposée pour les devoirs ?","segments":[{"voice":"female","text":"Question 23.","speaker":"female"},{"voice":"female","text":"Une représentante de parents estime que les devoirs écrits prennent trop de temps aux familles.","speaker":"female"},{"voice":"male","text":"Comme professeur, je comprends cette difficulté, mais je souhaite conserver une occasion de réviser les notions.","speaker":"male"},{"voice":"female","text":"Les enfants n'ont pas tous un adulte disponible pour les accompagner.","speaker":"female_alt"},{"voice":"male","text":"Nous pourrions proposer des exercices courts, commencés en classe, avec une permanence facultative pour terminer ce qui pose problème.","speaker":"male"},{"voice":"female","text":"Si les consignes sont claires et que la charge est limitée, ce serait un progrès.","speaker":"female_alt"},{"voice":"male","text":"Évaluons cette formule pendant un trimestre.","speaker":"male"},{"voice":"female","text":"Quelle serait la particularité de la permanence proposée pour les devoirs ?","speaker":"female"}],"audio":"q-23.mp3","audioSeconds":39.549,"slotSeconds":73},{"number":24,"kind":"interview","question":"Quelle limite principale des résultats actuels la chercheuse met-elle en avant ?","options":["Ils sont recueillis immédiatement après la fin des cours, sans suivi ultérieur.","Ils ne portent que sur les étudiants ayant mené la formation à son terme.","Ils comparent la satisfaction des diplômés sans tenir compte de leurs progrès effectifs.","Ils mélangent dans une même analyse les attentes de départ et les difficultés rencontrées."],"correct":"B","explanation":"Réponse B : La chercheuse insiste sur le fait que les résultats actuels ne concernent que les étudiants ayant mené la formation à son terme, ce qui constitue la limite principale mise en avant. A : Quelqu'un pourrait croire que l'absence de suivi ultérieur est un problème, car la chercheuse mentionne l'intention de contacter d'autres étudiants et de comparer les progrès. Cependant, la limite principale évoquée concerne l'absence des abandons dans les résultats, pas le moment de la collecte des données. C : On pourrait croire que la comparaison de la satisfaction sans tenir compte des progrès est la limite, car la chercheuse évoque la nécessité de comparer les progressions réelles. Cependant, elle précise que le problème principal est l'absence des abandons dans les résultats. D : La chercheuse parle de comparer attentes et progrès, mais ne dit pas qu'elles sont mélangées dans l'analyse actuelle. Ce n'est donc pas la limite principale évoquée.","transcript":"Question 24.\nVous avez interrogé les étudiants qui ont achevé leur formation et presque tous se disent satisfaits. Est-ce suffisant pour évaluer le programme ?\nNon, car ceux qui ont quitté les cours avant la fin sont précisément absents de nos résultats. Certains ont pu rencontrer des difficultés d'horaire, de transport ou de compréhension que nous ignorons encore. Nous allons les contacter, mais aussi comparer les progressions réelles aux attentes de départ. Une satisfaction élevée chez les diplômés ne dit pas à elle seule si le programme convient à tous les inscrits.\nQuelle limite principale des résultats actuels la chercheuse met-elle en avant ?","segments":[{"voice":"female","text":"Question 24."},{"voice":"male","text":"Vous avez interrogé les étudiants qui ont achevé leur formation et presque tous se disent satisfaits. Est-ce suffisant pour évaluer le programme ?"},{"voice":"female","text":"Non, car ceux qui ont quitté les cours avant la fin sont précisément absents de nos résultats. Certains ont pu rencontrer des difficultés d'horaire, de transport ou de compréhension que nous ignorons encore. Nous allons les contacter, mais aussi comparer les progressions réelles aux attentes de départ. Une satisfaction élevée chez les diplômés ne dit pas à elle seule si le programme convient à tous les inscrits."},{"voice":"female","text":"Quelle limite principale des résultats actuels la chercheuse met-elle en avant ?"}],"audio":"q-24.mp3","audioSeconds":38.557,"slotSeconds":70},{"number":25,"kind":"television-report","question":"D’après le reportage, quelle limite freine surtout l’usage des tablettes pour les devoirs à la maison ?","options":["Le manque de connexion haut débit dans l’école.","Le fait que certains élèves ne ramènent pas leur tablette chez eux.","L’absence de connexion Internet fiable dans certaines familles.","Le nombre insuffisant de tablettes pour toutes les classes."],"correct":"C","explanation":"Réponse C : Le reportage précise que le frein principal est l’absence de connexion Internet fiable dans certaines familles, ce qui empêche l’accès aux devoirs numériques à la maison. A : Quelqu’un pourrait confondre la connexion à l’école avec celle à la maison, mais le reportage parle explicitement du problème de connexion chez les familles, pas dans l’école. B : On pourrait croire que certains élèves oublient leur tablette, mais le texte dit que l’école prête des équipements, donc ce n’est pas le principal frein mentionné. D : On pourrait penser que le nombre de tablettes est insuffisant, mais le texte indique qu’elles ont déjà été distribuées à toutes les classes et que le problème principal est la connexion à domicile.","transcript":"Question 25.\nDans une école primaire d'Annecy, des tablettes ont été distribuées à toutes les classes. Les enseignants peuvent proposer des exercices adaptés à différents niveaux.\nMais plusieurs familles ne disposent pas de connexion stable à domicile, explique la directrice. Les devoirs numériques n'étaient donc pas accessibles à tous.\nL'école prête désormais des équipements et laisse les exercices disponibles sur papier. Les responsables souhaitent vérifier si les résultats s'améliorent réellement avant de commander davantage d'appareils.\nD’après le reportage, quelle limite freine surtout l’usage des tablettes pour les devoirs à la maison ?","segments":[{"voice":"female","text":"Question 25."},{"voice":"female","text":"Dans une école primaire d'Annecy, des tablettes ont été distribuées à toutes les classes. Les enseignants peuvent proposer des exercices adaptés à différents niveaux."},{"voice":"male","text":"Mais plusieurs familles ne disposent pas de connexion stable à domicile, explique la directrice. Les devoirs numériques n'étaient donc pas accessibles à tous."},{"voice":"female","text":"L'école prête désormais des équipements et laisse les exercices disponibles sur papier. Les responsables souhaitent vérifier si les résultats s'améliorent réellement avant de commander davantage d'appareils."},{"voice":"female","text":"D’après le reportage, quelle limite freine surtout l’usage des tablettes pour les devoirs à la maison ?"}],"audio":"q-25.mp3","audioSeconds":39.941,"slotSeconds":71},{"number":26,"kind":"interview","question":"Selon le responsable, sur quel aspect précis faut-il surtout s’attarder pour évaluer le dispositif d’apprentissage au-delà du seul diplôme obtenu ?","options":["Sur la capacité de l’entreprise à garder la plupart des apprentis à la fin de leur contrat","Sur la qualité de l’accompagnement et des conditions de travail vécues par les apprentis","Sur le nombre total d’apprentis recrutés chaque année par l’entreprise","Sur le fait que les apprentis découvrent parfois un métier différent de celui qu’ils visaient au départ"],"correct":"B","explanation":"Réponse B : Le responsable insiste explicitement sur la nécessité de s'attarder sur la qualité de l'accompagnement et les conditions de travail vécues par les apprentis, ce qui répond précisément à la question. A : Le texte mentionne que certains jeunes restent dans l'entreprise, mais cela n'est pas présenté comme le critère principal d'évaluation. L'accent est mis sur la qualité de l'accompagnement et des conditions de travail, pas sur le taux de rétention. C : Le nombre total d'apprentis recrutés est mentionné dans la question introductive, mais le responsable ne le cite jamais comme critère d'évaluation du dispositif. D : Le responsable évoque que certains apprentis découvrent un métier différent, mais cela illustre la diversité des parcours, pas un critère d'évaluation du dispositif.","transcript":"Question 26.\nVotre entreprise recrute chaque année plusieurs apprentis. Pourquoi ne pas juger le dispositif uniquement à partir du diplôme obtenu ?\nLe diplôme est un repère, mais il ne raconte pas tout. Certains jeunes restent dans l'entreprise, d'autres trouvent un métier différent après avoir découvert leurs compétences. Nous devons regarder la qualité de l'accompagnement, les conditions de travail et la façon dont ils progressent. Un apprenti qui termine son contrat sans jamais obtenir de conseils peut être diplômé tout en ayant vécu une expérience difficile.\nSelon le responsable, sur quel aspect précis faut-il surtout s’attarder pour évaluer le dispositif d’apprentissage au-delà du seul diplôme obtenu ?","segments":[{"voice":"female","text":"Question 26."},{"voice":"female","text":"Votre entreprise recrute chaque année plusieurs apprentis. Pourquoi ne pas juger le dispositif uniquement à partir du diplôme obtenu ?"},{"voice":"male","text":"Le diplôme est un repère, mais il ne raconte pas tout. Certains jeunes restent dans l'entreprise, d'autres trouvent un métier différent après avoir découvert leurs compétences. Nous devons regarder la qualité de l'accompagnement, les conditions de travail et la façon dont ils progressent. Un apprenti qui termine son contrat sans jamais obtenir de conseils peut être diplômé tout en ayant vécu une expérience difficile."},{"voice":"female","text":"Selon le responsable, sur quel aspect précis faut-il surtout s’attarder pour évaluer le dispositif d’apprentissage au-delà du seul diplôme obtenu ?"}],"audio":"q-26.mp3","audioSeconds":43.729,"slotSeconds":66},{"number":27,"kind":"dialogue","question":"Selon leur accord, comment la salle douze équipée pour l'enregistrement sera-t-elle utilisée ?","options":["Le groupe du second enseignant y commence à 9h et les deux groupes gardent ensuite leurs salles initiales.","D’abord le groupe du premier enseignant de 9h à midi, puis celui du second après l’échange de salles.","Le premier groupe reste en salle quinze et seul le second se déplace à midi vers la salle douze.","Les deux enseignants s’y relaient dès 9h en faisant passer tour à tour quelques élèves de chaque groupe."],"correct":"B","explanation":"Réponse B : C'est la seule option qui correspond exactement à l'organisation décrite : le premier enseignant commence avec son groupe en salle douze de 9h à midi, puis les groupes échangent de salle à midi, permettant au second groupe d'utiliser la salle douze équipée. A : Cette option inverse l'ordre des groupes : elle indique que le groupe du second enseignant commence en salle douze à 9h, alors que c'est le groupe du premier enseignant qui y commence. Quelqu'un pourrait confondre les rôles des enseignants, car les deux groupes commencent à 9h mais dans des salles différentes. C : Cette option suppose que seul le second groupe se déplace à midi, mais le texte précise un échange de salles, donc les deux groupes changent de salle à midi. Quelqu'un pourrait croire que seul le groupe ayant besoin du matériel change de salle, mais ce n'est pas ce qui est convenu. D : Cette option imagine une alternance d'élèves des deux groupes dans la salle douze dès 9h, mais le texte indique que chaque groupe reste dans une salle distincte jusqu'à midi, sans alternance. On pourrait croire à une organisation plus flexible, mais ce n'est pas ce qui est dit.","transcript":"Question 27.\nLes deux groupes de langues passent l'oral jeudi, mais nous avons réservé la même salle.\nJe peux commencer avec mon groupe à neuf heures dans la salle douze. Tu prendras la salle quinze à la même heure.\nLe matériel d'enregistrement est installé dans la salle douze.\nAlors échangeons nos salles à midi, quand mon groupe aura terminé. Les deux examens pourront se dérouler sans retard.\nParfait, j'envoie le nouveau plan aux étudiants.\nSelon leur accord, comment la salle douze équipée pour l'enregistrement sera-t-elle utilisée ?","segments":[{"voice":"female","text":"Question 27."},{"voice":"male","text":"Les deux groupes de langues passent l'oral jeudi, mais nous avons réservé la même salle."},{"voice":"female","text":"Je peux commencer avec mon groupe à neuf heures dans la salle douze. Tu prendras la salle quinze à la même heure."},{"voice":"male","text":"Le matériel d'enregistrement est installé dans la salle douze."},{"voice":"female","text":"Alors échangeons nos salles à midi, quand mon groupe aura terminé. Les deux examens pourront se dérouler sans retard."},{"voice":"male","text":"Parfait, j'envoie le nouveau plan aux étudiants."},{"voice":"female","text":"Selon leur accord, comment la salle douze équipée pour l'enregistrement sera-t-elle utilisée ?"}],"audio":"q-27.mp3","audioSeconds":34.821,"slotSeconds":59},{"number":28,"kind":"interview","question":"Selon l'experte, quel type d'aménagement rendrait l'épreuve plus juste pour les élèves qui peinent à lire rapidement le document ?","options":["Remplacer les documents écrits par un QCM qui demande très peu de lecture.","Raccourcir systématiquement les textes et les questions pour l’ensemble des candidats.","Diminuer la difficulté des notions scientifiques évaluées pour les élèves qui lisent lentement.","Reformuler les mêmes informations dans un texte plus clair ou accorder davantage de temps de lecture."],"correct":"D","explanation":"Réponse D : L’experte recommande explicitement de reformuler les informations dans un texte plus clair ou d’accorder davantage de temps de lecture, sans modifier le niveau d’exigence. A : Quelqu’un pourrait croire que remplacer les documents écrits par un QCM simplifierait l’accès à l’épreuve pour les élèves en difficulté de lecture. Cependant, l’experte précise qu’il ne s’agit pas de simplifier les questions ou de changer fondamentalement leur nature, mais d’adapter la présentation ou le temps accordé. B : La tentation ici vient de l’idée de rendre l’épreuve plus accessible en raccourcissant systématiquement les textes. Or, l’experte insiste sur le fait qu’il ne s’agit pas de simplifier pour tout le monde, mais d’adapter la présentation ou le temps pour ceux qui en ont besoin. C : On pourrait croire qu’il faut diminuer la difficulté des notions pour aider les élèves qui lisent lentement, mais l’experte précise qu’il faut garder le même niveau d’exigence sur les connaissances scientifiques.","transcript":"Question 28.\nCertaines épreuves demandent de lire rapidement un long document avant de répondre. Pourquoi faudrait-il les adapter ?\nParce que nous devons distinguer la compétence réellement évaluée des obstacles liés au support. Si l'objectif est de vérifier un raisonnement scientifique, une lecture particulièrement difficile risque de pénaliser un élève qui connaît pourtant les notions. Cela ne signifie pas simplifier les questions pour tous. On peut proposer une présentation plus accessible ou un temps adapté, tout en conservant le même niveau d'exigence sur les connaissances.\nSelon l'experte, quel type d'aménagement rendrait l'épreuve plus juste pour les élèves qui peinent à lire rapidement le document ?","segments":[{"voice":"female","text":"Question 28."},{"voice":"male","text":"Certaines épreuves demandent de lire rapidement un long document avant de répondre. Pourquoi faudrait-il les adapter ?"},{"voice":"female","text":"Parce que nous devons distinguer la compétence réellement évaluée des obstacles liés au support. Si l'objectif est de vérifier un raisonnement scientifique, une lecture particulièrement difficile risque de pénaliser un élève qui connaît pourtant les notions. Cela ne signifie pas simplifier les questions pour tous. On peut proposer une présentation plus accessible ou un temps adapté, tout en conservant le même niveau d'exigence sur les connaissances."},{"voice":"female","text":"Selon l'experte, quel type d'aménagement rendrait l'épreuve plus juste pour les élèves qui peinent à lire rapidement le document ?"}],"audio":"q-28.mp3","audioSeconds":43.363,"slotSeconds":66},{"number":29,"kind":"debate","question":"Que recommandent les intervenants lorsqu’un logiciel signale un devoir comme suspect ?","options":["Abandonner ces logiciels et se fier uniquement au jugement des professeurs.","Demander à l’élève des traces de son travail avant de trancher.","Ignorer l’alerte si l’élève a d’ordinaire un bon comportement.","Sanctionner immédiatement l’élève en se fondant sur le score du logiciel."],"correct":"B","explanation":"Réponse B : Les intervenants recommandent explicitement de demander des traces du travail à l’élève avant de prendre une décision, ce qui correspond exactement à cette option. A : Quelqu'un pourrait croire que les intervenants recommandent d'abandonner les logiciels, car ils mentionnent que leurs résultats sont parfois erronés. Cependant, ils précisent qu'il serait irresponsable de les ignorer totalement, ce qui contredit cette option. C : On pourrait penser qu'il faut ignorer l’alerte si l’élève a un bon comportement, car la confiance est évoquée. Mais les intervenants disent qu’il ne faut pas ignorer les indices donnés par le logiciel, même si le score peut être erroné. D : Quelqu’un pourrait croire qu’il faut sanctionner immédiatement sur la base du score, car le logiciel alerte sur des travaux suspects. Mais les intervenants disent explicitement qu’il ne faut pas sanctionner immédiatement sur la seule base du score.","transcript":"Question 29.\nLes enseignants utilisent de plus en plus des logiciels pour détecter les textes générés automatiquement. Est-ce une bonne solution ?\nIls peuvent nous alerter sur certains travaux suspects. Il serait irresponsable d'ignorer totalement ces indices.\nMais leurs résultats sont parfois erronés. Accuser un élève sur la seule base d'un score peut abîmer la confiance.\nNous devons alors demander des traces du travail, comme des brouillons, plutôt que de sanctionner immédiatement.\nD'accord pour vérifier, mais il faut aussi apprendre aux élèves à citer leurs sources et à expliquer leur démarche.\nQue recommandent les intervenants lorsqu’un logiciel signale un devoir comme suspect ?","segments":[{"voice":"female","text":"Question 29.","speaker":"female"},{"voice":"female","text":"Les enseignants utilisent de plus en plus des logiciels pour détecter les textes générés automatiquement. Est-ce une bonne solution ?","speaker":"female"},{"voice":"male","text":"Ils peuvent nous alerter sur certains travaux suspects. Il serait irresponsable d'ignorer totalement ces indices.","speaker":"male"},{"voice":"female","text":"Mais leurs résultats sont parfois erronés. Accuser un élève sur la seule base d'un score peut abîmer la confiance.","speaker":"female_alt"},{"voice":"male","text":"Nous devons alors demander des traces du travail, comme des brouillons, plutôt que de sanctionner immédiatement.","speaker":"male"},{"voice":"female","text":"D'accord pour vérifier, mais il faut aussi apprendre aux élèves à citer leurs sources et à expliquer leur démarche.","speaker":"female_alt"},{"voice":"female","text":"Que recommandent les intervenants lorsqu’un logiciel signale un devoir comme suspect ?","speaker":"female"}],"audio":"q-29.mp3","audioSeconds":41.117,"slotSeconds":69},{"number":30,"kind":"interview","question":"En quoi, selon la responsable, les nouveaux parcours bilingues se distinguent-ils d’une simple traduction mot à mot ?","options":["Ils proposent des œuvres différentes dans chaque langue pour varier les approches.","Ils modifient l’ordre de visite des salles selon la langue choisie.","Ils adaptent exemples, explications et images aux références de chaque public.","Ils raccourcissent le contenu en supprimant les notions jugées trop complexes."],"correct":"C","explanation":"Réponse C : La responsable explique explicitement que les parcours bilingues se distinguent d’une simple traduction mot à mot car ils adaptent exemples, explications et images aux références de chaque public. A : Quelqu’un pourrait croire que la collaboration avec des médiateurs implique la sélection d’œuvres différentes selon la langue, mais le texte ne mentionne pas de changement d’œuvres, seulement une adaptation des explications et exemples. B : L’idée d’un ordre de visite différent pourrait venir de la volonté de s’adapter à chaque public, mais il est précisé que le patrimoine reste le même et il n’est jamais question de modifier l’ordre des salles. D : Quelqu’un pourrait penser que l’adaptation implique de raccourcir ou simplifier le contenu, mais il s’agit d’adapter les explications, pas de supprimer des notions complexes.","transcript":"Question 30.\nVotre musée propose désormais des parcours bilingues, mais ils ne sont pas tous de simples traductions. Pourquoi ?\nNous avons remarqué que les visiteurs ne connaissent pas nécessairement les mêmes références culturelles. Certains concepts demandent une explication supplémentaire, des exemples différents ou des images plus précises. Nous avons donc travaillé avec des médiateurs de plusieurs langues et consulté des familles. Notre objectif n'est pas de raconter deux histoires contradictoires, mais de rendre le même patrimoine compréhensible pour des publics divers.\nEn quoi, selon la responsable, les nouveaux parcours bilingues se distinguent-ils d’une simple traduction mot à mot ?","segments":[{"voice":"female","text":"Question 30."},{"voice":"male","text":"Votre musée propose désormais des parcours bilingues, mais ils ne sont pas tous de simples traductions. Pourquoi ?"},{"voice":"female","text":"Nous avons remarqué que les visiteurs ne connaissent pas nécessairement les mêmes références culturelles. Certains concepts demandent une explication supplémentaire, des exemples différents ou des images plus précises. Nous avons donc travaillé avec des médiateurs de plusieurs langues et consulté des familles. Notre objectif n'est pas de raconter deux histoires contradictoires, mais de rendre le même patrimoine compréhensible pour des publics divers."},{"voice":"female","text":"En quoi, selon la responsable, les nouveaux parcours bilingues se distinguent-ils d’une simple traduction mot à mot ?"}],"audio":"q-30.mp3","audioSeconds":41.613,"slotSeconds":69},{"number":31,"kind":"academic-monologue","question":"D'après la conférencière, qu'indique principalement la comparaison des deux groupes d'apprenants ?","options":["Que, quelles que soient les conditions, les performances à un mois reflètent surtout les différences de motivation entre les groupes.","Que la veille du test, il vaut mieux éviter toute révision intensive pour ne pas perturber la mémorisation.","Que travailler plus longtemps au total sur le vocabulaire garantit un meilleur rappel un mois plus tard.","Que la répartition des séances et les occasions de retrouver les mots en mémoire favorisent leur maintien à long terme."],"correct":"D","explanation":"Réponse D : La conférencière affirme explicitement que la répartition des séances et les occasions de retrouver les mots en mémoire favorisent leur maintien à long terme. C'est la conclusion principale de la comparaison des deux groupes. A : Quelqu'un pourrait penser que la motivation explique la différence de performance à un mois, car les groupes sont comparés sur la durée. Cependant, le texte n'évoque pas la motivation comme facteur principal, mais insiste sur la méthode d'apprentissage (répartition des séances et rappels en mémoire). B : La conférencière précise explicitement que la révision intensive n'est pas inutile, ce qui contredit cette option. On pourrait être tenté de croire qu'il faut éviter la révision intensive, mais le texte dit le contraire. C : On pourrait croire que travailler plus longtemps garantit un meilleur rappel, mais le texte indique que le groupe qui travaille moins longtemps chaque jour, mais de façon répétée, réussit mieux. Ce n'est donc pas la quantité totale de travail qui compte, mais la répartition et les rappels.","transcript":"Question 31.\nUne étude compare deux façons d'apprendre du vocabulaire. Le premier groupe révise toutes les listes la veille du test. Le second travaille moins longtemps chaque jour, mais revient sur les mots à plusieurs reprises. Le deuxième groupe obtient un meilleur rappel un mois après l'évaluation. Ce résultat ne signifie pas que toute révision intensive est inutile. Il suggère plutôt que la répartition des séances et les occasions de retrouver une information dans la mémoire jouent un rôle important dans sa conservation. Il faudra cependant confirmer ces effets dans d'autres contextes d'apprentissage.\nD'après la conférencière, qu'indique principalement la comparaison des deux groupes d'apprenants ?","segments":[{"voice":"female","text":"Question 31."},{"voice":"female","text":"Une étude compare deux façons d'apprendre du vocabulaire. Le premier groupe révise toutes les listes la veille du test. Le second travaille moins longtemps chaque jour, mais revient sur les mots à plusieurs reprises. Le deuxième groupe obtient un meilleur rappel un mois après l'évaluation. Ce résultat ne signifie pas que toute révision intensive est inutile. Il suggère plutôt que la répartition des séances et les occasions de retrouver une information dans la mémoire jouent un rôle important dans sa conservation. Il faudra cependant confirmer ces effets dans d'autres contextes d'apprentissage."},{"voice":"female","text":"D'après la conférencière, qu'indique principalement la comparaison des deux groupes d'apprenants ?"}],"audio":"q-31.mp3","audioSeconds":40.411,"slotSeconds":69},{"number":32,"kind":"interview","question":"Que l’université est-elle censée faire lorsqu’un étudiant obtient un score de décrochage élevé ?","options":["Envoyer automatiquement un message indiquant à l’étudiant qu’il est à haut risque.","S’appuyer uniquement sur le score sans vérifier les raisons de ses absences.","S’en servir pour proposer un soutien discret, puis discuter de sa situation en entretien.","Restreindre temporairement ses possibilités d’inscription aux cours suivants."],"correct":"C","explanation":"Réponse C : Le texte indique clairement que le score doit servir à proposer un soutien discret, puis à discuter de la situation lors d’un entretien. C’est la démarche recommandée. A : Quelqu’un pourrait croire qu’il faut envoyer automatiquement un message à l’étudiant à haut risque, car la question est posée dans le stimulus. Cependant, la suite du texte précise que ce n’est pas la bonne démarche : « Nous devons vérifier la situation sans étiqueter les personnes comme incapables de réussir. » B : On pourrait croire qu’il faut s’appuyer uniquement sur le score, car l’outil donne un score de risque. Cependant, le texte insiste sur la nécessité de vérifier la situation de l’étudiant et de ne pas se fier uniquement au score. D : Quelqu’un pourrait penser qu’un score élevé justifie une restriction, mais le texte précise explicitement que l’outil ne doit jamais entraîner de sanction.","transcript":"Question 32.\nVotre équipe a développé un outil qui estime quels étudiants risquent d'interrompre leurs études. Faut-il contacter automatiquement ceux qui obtiennent un score élevé ?\nUn signal peut aider, mais ce modèle s'appuie sur des données incomplètes. Un étudiant peut manquer un cours pour travailler ou pour des raisons familiales. Nous devons vérifier la situation sans étiqueter les personnes comme incapables de réussir. L'outil devrait orienter une offre de soutien discrète, et ses erreurs doivent être étudiées régulièrement. Il ne doit jamais remplacer un entretien ou entraîner une sanction.\nQue l’université est-elle censée faire lorsqu’un étudiant obtient un score de décrochage élevé ?","segments":[{"voice":"female","text":"Question 32."},{"voice":"male","text":"Votre équipe a développé un outil qui estime quels étudiants risquent d'interrompre leurs études. Faut-il contacter automatiquement ceux qui obtiennent un score élevé ?"},{"voice":"female","text":"Un signal peut aider, mais ce modèle s'appuie sur des données incomplètes. Un étudiant peut manquer un cours pour travailler ou pour des raisons familiales. Nous devons vérifier la situation sans étiqueter les personnes comme incapables de réussir. L'outil devrait orienter une offre de soutien discrète, et ses erreurs doivent être étudiées régulièrement. Il ne doit jamais remplacer un entretien ou entraîner une sanction."},{"voice":"female","text":"Que l’université est-elle censée faire lorsqu’un étudiant obtient un score de décrochage élevé ?"}],"audio":"q-32.mp3","audioSeconds":41.012,"slotSeconds":70},{"number":33,"kind":"commentary","question":"Quel aspect le chroniqueur met-il en avant pour relativiser la hausse de trente pour cent des inscriptions ?","options":["Ce chiffre ne dit rien des acquis ni des abandons des apprenants.","Ce chiffre suffit à apprécier à la fois l’intérêt et l’efficacité de la formation.","Ce chiffre montre surtout que les cours du soir sont désormais les plus demandés.","Ce chiffre confirme que l’accompagnement est identique pour tous les publics."],"correct":"A","explanation":"Réponse A : Le chroniqueur insiste sur le fait que le chiffre des inscriptions ne dit rien sur les acquis ni sur les abandons, et qu'il ne suffit pas à juger de l'efficacité pédagogique. B : Quelqu'un pourrait croire que le chiffre suffit à apprécier l’intérêt et l’efficacité, car il est présenté comme une victoire, mais le chroniqueur précise explicitement que ce n’est pas le cas. C : On pourrait croire que le chroniqueur met en avant la demande pour les cours du soir, car il évoque ceux qui ne peuvent venir que le soir, mais il ne dit pas que ce sont les plus demandés. D : Le chroniqueur questionne justement si l’accompagnement est identique, il ne le confirme pas. Quelqu’un pourrait mal comprendre la formulation interrogative comme une affirmation.","transcript":"Question 33.\nLe centre de formation annonce une hausse de trente pour cent des inscriptions et présente ce chiffre comme une victoire. Il témoigne sans doute d'un intérêt réel. Mais combien d'apprenants terminent le parcours ? Combien progressent sur les compétences prévues ? Et ceux qui ne peuvent venir que le soir disposent-ils du même accompagnement ? Le nombre d'inscriptions est un indicateur de demande; il ne suffit pas à juger de l'efficacité pédagogique. Avant de célébrer, regardons aussi les acquis et les abandons.\nQuel aspect le chroniqueur met-il en avant pour relativiser la hausse de trente pour cent des inscriptions ?","segments":[{"voice":"female","text":"Question 33."},{"voice":"male","text":"Le centre de formation annonce une hausse de trente pour cent des inscriptions et présente ce chiffre comme une victoire. Il témoigne sans doute d'un intérêt réel. Mais combien d'apprenants terminent le parcours ? Combien progressent sur les compétences prévues ? Et ceux qui ne peuvent venir que le soir disposent-ils du même accompagnement ? Le nombre d'inscriptions est un indicateur de demande; il ne suffit pas à juger de l'efficacité pédagogique. Avant de célébrer, regardons aussi les acquis et les abandons."},{"voice":"female","text":"Quel aspect le chroniqueur met-il en avant pour relativiser la hausse de trente pour cent des inscriptions ?"}],"audio":"q-33.mp3","audioSeconds":39.706,"slotSeconds":68},{"number":34,"kind":"roundtable","question":"Quelle mesure précise est proposée pour que les devoirs en ligne restent accessibles à tous ?","options":["Ouvrir la salle informatique après les cours au lieu de distribuer des supports imprimés.","Limiter les devoirs en ligne aux familles disposant de plusieurs appareils.","Garder les activités en ligne, mais fournir aussi une version papier des consignes.","Remplacer progressivement tous les devoirs papier par des exercices interactifs."],"correct":"C","explanation":"Réponse C : La mesure précise proposée est de garder les activités en ligne tout en fournissant une version papier des consignes, ce qui répond directement à la question sur l’accessibilité pour tous. A : La proposition d'ouvrir la salle informatique après les cours est effectivement mentionnée, mais elle ne constitue pas la mesure précise visant à rendre les devoirs accessibles à tous. Elle est présentée comme une option supplémentaire, pas comme la mesure principale. Quelqu'un pourrait confondre cette solution complémentaire avec la mesure principale, car elle vise aussi à aider les élèves sans accès à la technologie à la maison. B : Limiter les devoirs en ligne aux familles disposant de plusieurs appareils n'est jamais proposé. Cette option pourrait sembler plausible à quelqu'un qui a entendu les difficultés techniques évoquées, mais la mesure proposée vise l'inclusion, pas l'exclusion. D : Remplacer progressivement tous les devoirs papier par des exercices interactifs n'est pas proposé ; au contraire, il est suggéré de ne pas retirer la solution papier. Quelqu'un pourrait mal comprendre la discussion sur les avantages du numérique comme une volonté de tout numériser, mais cela est contredit par la volonté de garder les deux formats.","transcript":"Question 34.\nPlusieurs écoles proposent des devoirs exclusivement en ligne. Est-ce souhaitable ?\nLes enseignants gagnent du temps pour donner des retours rapides.\nLes parents signalent pourtant que certains foyers partagent un seul appareil ou n'ont pas une connexion fiable.\nNous pourrions conserver les activités interactives, mais proposer aussi une version imprimée des consignes.\nEt ouvrir la salle informatique après les cours pour les élèves qui en ont besoin.\nOui, évaluons les deux possibilités avant de retirer une solution.\nQuelle mesure précise est proposée pour que les devoirs en ligne restent accessibles à tous ?","segments":[{"voice":"female","text":"Question 34.","speaker":"female"},{"voice":"female","text":"Plusieurs écoles proposent des devoirs exclusivement en ligne. Est-ce souhaitable ?","speaker":"female"},{"voice":"male","text":"Les enseignants gagnent du temps pour donner des retours rapides.","speaker":"male"},{"voice":"female","text":"Les parents signalent pourtant que certains foyers partagent un seul appareil ou n'ont pas une connexion fiable.","speaker":"female_alt"},{"voice":"male","text":"Nous pourrions conserver les activités interactives, mais proposer aussi une version imprimée des consignes.","speaker":"male"},{"voice":"female","text":"Et ouvrir la salle informatique après les cours pour les élèves qui en ont besoin.","speaker":"female_alt"},{"voice":"male","text":"Oui, évaluons les deux possibilités avant de retirer une solution.","speaker":"male"},{"voice":"female","text":"Quelle mesure précise est proposée pour que les devoirs en ligne restent accessibles à tous ?","speaker":"female"}],"audio":"q-34.mp3","audioSeconds":41.482,"slotSeconds":70},{"number":35,"kind":"interview","question":"Sur quel élément le chercheur déconseille-t-il de s’appuyer comme seul indicateur des apprentissages ?","options":["L’observation des échanges dans la classe.","La qualité des explications données aux élèves.","La persévérance de l’élève face aux exercices.","La précision des calculs du logiciel."],"correct":"D","explanation":"Réponse D : Le chercheur précise qu’il ne faut pas s’appuyer uniquement sur la précision des calculs du logiciel comme indicateur des apprentissages, ce qui répond exactement à la question. A : Quelqu’un pourrait croire que l’observation des échanges n’est pas suffisante, mais le chercheur dit explicitement qu’il faut l’observer, ce n’est donc pas déconseillé comme seul indicateur. B : La qualité des explications est mentionnée comme un élément à observer, donc il ne déconseille pas de s’y appuyer. C : La persévérance est évoquée comme un facteur important, mais il n’est pas dit qu’il ne faut pas s’y appuyer.","transcript":"Question 35.\nVotre laboratoire étudie les logiciels qui adaptent les exercices au niveau de chaque élève. Pourquoi les résultats sont-ils moins bons dans certaines classes ?\nParce qu'une bonne adaptation automatique n'assure pas que l'élève comprend la consigne ou persévère. Un programme peut proposer le bon niveau de difficulté, mais si l'activité manque de sens ou si l'enseignant ne peut pas intervenir, l'apprentissage reste limité. Nous devons observer les échanges dans la classe et la qualité des explications, pas seulement la précision des calculs du logiciel.\nSur quel élément le chercheur déconseille-t-il de s’appuyer comme seul indicateur des apprentissages ?","segments":[{"voice":"female","text":"Question 35."},{"voice":"female","text":"Votre laboratoire étudie les logiciels qui adaptent les exercices au niveau de chaque élève. Pourquoi les résultats sont-ils moins bons dans certaines classes ?"},{"voice":"male","text":"Parce qu'une bonne adaptation automatique n'assure pas que l'élève comprend la consigne ou persévère. Un programme peut proposer le bon niveau de difficulté, mais si l'activité manque de sens ou si l'enseignant ne peut pas intervenir, l'apprentissage reste limité. Nous devons observer les échanges dans la classe et la qualité des explications, pas seulement la précision des calculs du logiciel."},{"voice":"female","text":"Sur quel élément le chercheur déconseille-t-il de s’appuyer comme seul indicateur des apprentissages ?"}],"audio":"q-35.mp3","audioSeconds":41.038,"slotSeconds":68},{"number":36,"kind":"interview","question":"Que, selon le texte, les élèves doivent-ils obtenir lorsque leurs idées ne sont pas retenues ?","options":["Une réponse argumentée expliquant ce refus.","La promesse de reprendre leurs idées l’année suivante.","Une nouvelle liste d’activités parmi lesquelles choisir.","Une mention de leur participation sur le bulletin scolaire."],"correct":"A","explanation":"Réponse A : Le texte dit explicitement que les élèves doivent recevoir une réponse argumentée lorsque leurs idées ne sont pas retenues. B : Quelqu’un pourrait croire qu’il s’agit d’une promesse de reprendre les idées plus tard, mais le texte ne mentionne rien à propos d’une reprise l’année suivante. Il insiste uniquement sur la nécessité d’une explication argumentée. C : Le texte mentionne que les élèves peuvent proposer des alternatives, mais il ne dit pas qu’ils reçoivent une nouvelle liste d’activités à choisir si leurs idées sont refusées. La confusion vient d’une interprétation trop large du passage sur les alternatives. D : Le texte ne parle jamais d’une mention sur le bulletin scolaire. Quelqu’un pourrait croire que la participation est valorisée officiellement, mais ce n’est pas évoqué ici.","transcript":"Question 36.\nVotre collège consulte les élèves sur les activités proposées. Est-ce une forme de démocratie scolaire ?\nPas si nous leur demandons seulement de voter pour une décision déjà prise. Ils doivent connaître les contraintes, proposer des alternatives et recevoir une réponse argumentée quand leurs idées ne sont pas retenues. Il faut aussi veiller à entendre ceux qui parlent rarement en réunion. La participation devient éducative lorsqu'elle donne une réelle possibilité de discussion, plutôt qu'une simple photographie de la popularité d'une proposition.\nQue, selon le texte, les élèves doivent-ils obtenir lorsque leurs idées ne sont pas retenues ?","segments":[{"voice":"female","text":"Question 36."},{"voice":"male","text":"Votre collège consulte les élèves sur les activités proposées. Est-ce une forme de démocratie scolaire ?"},{"voice":"female","text":"Pas si nous leur demandons seulement de voter pour une décision déjà prise. Ils doivent connaître les contraintes, proposer des alternatives et recevoir une réponse argumentée quand leurs idées ne sont pas retenues. Il faut aussi veiller à entendre ceux qui parlent rarement en réunion. La participation devient éducative lorsqu'elle donne une réelle possibilité de discussion, plutôt qu'une simple photographie de la popularité d'une proposition."},{"voice":"female","text":"Que, selon le texte, les élèves doivent-ils obtenir lorsque leurs idées ne sont pas retenues ?"}],"audio":"q-36.mp3","audioSeconds":38.896,"slotSeconds":70},{"number":37,"kind":"interview","question":"Selon la chercheuse, à quoi sert de conserver des témoignages opposés sur le nouveau calendrier scolaire ?","options":["À dégager un récit unique plus représentatif en fusionnant les expériences individuelles.","À contrôler si les établissements appliquent correctement les nouveaux horaires annoncés.","À distinguer les familles favorables de celles qui s’opposent globalement à toute réforme scolaire.","À comprendre comment se répartissent bénéfices et difficultés entre des familles aux contraintes différentes."],"correct":"D","explanation":"Réponse D : La chercheuse explique explicitement que conserver des témoignages opposés permet de comprendre comment les bénéfices et difficultés se répartissent entre des familles aux contraintes différentes. C’est l’objectif principal mentionné dans le texte. A : Quelqu’un pourrait croire que l'objectif est de fusionner les expériences pour obtenir un récit unique, car la question mentionne le récit le plus représentatif. Cependant, la chercheuse explique que cela ne suffit pas : « Une moyenne ne fait pas disparaître les écarts. Elle gagne à être complétée par l'analyse des personnes qui se trouvent de part et d'autre. » Il s'agit donc de garder la diversité des témoignages, pas de les fusionner. B : La chercheuse mentionne qu'ils vérifient les horaires et les dépenses, ce qui pourrait faire croire que conserver les témoignages sert à contrôler l’application des horaires. Mais elle précise que la conservation des situations particulières sert à comprendre la répartition des bénéfices et difficultés, pas à contrôler l’application. C : On pourrait penser qu’il s’agit de distinguer les familles favorables ou opposées à la réforme, car des exemples d’avis opposés sont donnés. Mais la chercheuse insiste sur la diversité des contraintes, pas sur une simple opposition globale à la réforme.","transcript":"Question 37.\nLes élèves, les familles et les enseignants racontent des expériences opposées du nouveau calendrier scolaire. Pourquoi ne pas choisir le récit le plus représentatif ?\nParce que les effets varient selon les contraintes. Une famille peut apprécier une sortie plus tôt, tandis qu'une autre doit payer une garde supplémentaire. Nous vérifions les horaires et les dépenses, mais nous conservons aussi ces situations particulières pour comprendre la répartition des bénéfices et des difficultés. Une moyenne ne fait pas disparaître les écarts. Elle gagne à être complétée par l'analyse des personnes qui se trouvent de part et d'autre.\nSelon la chercheuse, à quoi sert de conserver des témoignages opposés sur le nouveau calendrier scolaire ?","segments":[{"voice":"female","text":"Question 37."},{"voice":"male","text":"Les élèves, les familles et les enseignants racontent des expériences opposées du nouveau calendrier scolaire. Pourquoi ne pas choisir le récit le plus représentatif ?"},{"voice":"female","text":"Parce que les effets varient selon les contraintes. Une famille peut apprécier une sortie plus tôt, tandis qu'une autre doit payer une garde supplémentaire. Nous vérifions les horaires et les dépenses, mais nous conservons aussi ces situations particulières pour comprendre la répartition des bénéfices et des difficultés. Une moyenne ne fait pas disparaître les écarts. Elle gagne à être complétée par l'analyse des personnes qui se trouvent de part et d'autre."},{"voice":"female","text":"Selon la chercheuse, à quoi sert de conserver des témoignages opposés sur le nouveau calendrier scolaire ?"}],"audio":"q-37.mp3","audioSeconds":42.867,"slotSeconds":70},{"number":38,"kind":"public-lecture","question":"Quel lien précis entre popularité et qualité du dispositif la conférence décrit-elle ? (question reformulée pour préciser le contraste)","options":["Plus le programme est demandé, plus il devient facile de recruter des tuteurs qualifiés.","Moins le programme est demandé, plus il est difficile de mesurer les progrès réalisés.","Plus le programme est demandé, plus le temps disponible par élève peut diminuer.","Moins le programme est demandé, plus les élèves ayant le plus de besoins doivent attendre une place."],"correct":"C","explanation":"Réponse C : Le texte explique clairement que lorsque la demande augmente au-delà de la capacité, le temps disponible par élève diminue. C'est le lien direct entre popularité et qualité du dispositif. A : Quelqu'un pourrait croire que la popularité facilite le recrutement de tuteurs car le texte mentionne la nécessité de préparer davantage de tuteurs, mais il n'est jamais dit que cela devient plus facile avec la demande. Au contraire, la surcharge complique la situation. B : Le texte insiste sur l'importance de mesurer les progrès, mais il ne dit pas que la difficulté de mesure augmente quand la demande baisse. Le problème évoqué est lié à la surcharge, pas à un manque de demande. D : Il est vrai que certains élèves attendent, mais cela arrive quand la demande est forte, pas faible. La formulation inverse la relation décrite dans le texte.","transcript":"Question 38.\nL'ouverture d'un programme de soutien scolaire gratuit a suscité un intérêt considérable. Pourtant, son succès peut le fragiliser. Lorsque les inscriptions dépassent la capacité d'accueil, les bénévoles disposent de moins de temps pour chaque élève; certains enfants qui ont les besoins les plus importants attendent plusieurs semaines. Annoncer un grand nombre de participants ne suffit donc pas à démontrer une amélioration de l'apprentissage. Il faut définir des priorités transparentes, préparer davantage de tuteurs et mesurer les progrès réels. Une initiative peut être populaire tout en échouant à offrir l'aide promise à ceux qui en ont le plus besoin.\nQuel lien précis entre popularité et qualité du dispositif la conférence décrit-elle ? (question reformulée pour préciser le contraste)","segments":[{"voice":"female","text":"Question 38."},{"voice":"female","text":"L'ouverture d'un programme de soutien scolaire gratuit a suscité un intérêt considérable. Pourtant, son succès peut le fragiliser. Lorsque les inscriptions dépassent la capacité d'accueil, les bénévoles disposent de moins de temps pour chaque élève; certains enfants qui ont les besoins les plus importants attendent plusieurs semaines. Annoncer un grand nombre de participants ne suffit donc pas à démontrer une amélioration de l'apprentissage. Il faut définir des priorités transparentes, préparer davantage de tuteurs et mesurer les progrès réels. Une initiative peut être populaire tout en échouant à offrir l'aide promise à ceux qui en ont le plus besoin."},{"voice":"female","text":"Quel lien précis entre popularité et qualité du dispositif la conférence décrit-elle ? (question reformulée pour préciser le contraste)"}],"audio":"q-38.mp3","audioSeconds":47.7,"slotSeconds":81},{"number":39,"kind":"interview","question":"Selon la responsable, quelle condition doit être remplie avant d’augmenter le nombre d’inscriptions ?","options":["S’assurer que les tuteurs actuels restent jusqu’à la fin de l’année scolaire.","Disposer de nouveaux tuteurs formés pour assurer la continuité du suivi.","Augmenter progressivement le nombre d’élèves en acceptant un suivi moins régulier au départ.","Obtenir l’engagement formel des écoles partenaires avant chaque nouvelle inscription."],"correct":"B","explanation":"Réponse B : La responsable explique clairement que la condition pour augmenter les inscriptions est de disposer de nouveaux tuteurs formés pour garantir la continuité du suivi. C’est la seule condition explicitement mentionnée comme préalable indispensable. A : Quelqu’un pourrait croire qu’il faut s’assurer que les tuteurs actuels restent, car la responsable mentionne que certains partent. Cependant, elle insiste sur la nécessité de former de nouveaux tuteurs pour garantir la continuité, pas de retenir absolument les anciens. C : On pourrait croire qu’il s’agit d’accepter un suivi moins régulier, mais la responsable rejette explicitement cette option en disant qu’il ne faut pas multiplier les inscriptions sans continuité pédagogique. D : La coordination avec les écoles est mentionnée, mais il n’est jamais question d’un engagement formel des écoles partenaires comme condition préalable à l’augmentation des inscriptions.","transcript":"Question 39.\nVotre réseau de tutorat bénévole a aidé beaucoup d'élèves cette année. Pourquoi ne pas augmenter immédiatement le nombre d'inscriptions ?\nNous avons pu compter sur des étudiants très motivés, mais certains terminent leur formation ou quittent la ville. Nous devons former de nouveaux tuteurs, assurer le suivi des élèves lorsqu'un bénévole se retire et maintenir une coordination régulière avec les écoles. Sans cela, une expansion rapide créera des promesses impossibles à tenir. Il vaut mieux proposer une place stable à moins d'élèves que multiplier les inscriptions sans continuité pédagogique.\nSelon la responsable, quelle condition doit être remplie avant d’augmenter le nombre d’inscriptions ?","segments":[{"voice":"female","text":"Question 39."},{"voice":"male","text":"Votre réseau de tutorat bénévole a aidé beaucoup d'élèves cette année. Pourquoi ne pas augmenter immédiatement le nombre d'inscriptions ?"},{"voice":"female","text":"Nous avons pu compter sur des étudiants très motivés, mais certains terminent leur formation ou quittent la ville. Nous devons former de nouveaux tuteurs, assurer le suivi des élèves lorsqu'un bénévole se retire et maintenir une coordination régulière avec les écoles. Sans cela, une expansion rapide créera des promesses impossibles à tenir. Il vaut mieux proposer une place stable à moins d'élèves que multiplier les inscriptions sans continuité pédagogique."},{"voice":"female","text":"Selon la responsable, quelle condition doit être remplie avant d’augmenter le nombre d’inscriptions ?"}],"audio":"q-39.mp3","audioSeconds":41.3,"slotSeconds":81}]},{"id":"tcf-listening-05","version":"tcf-listening-2026-11-test05-v4","title":"TCF Listening · Test 05","seconds":2100,"questions":[{"number":1,"kind":"image","question":"Quelle situation est représentée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"Réponse B : L'image montre clairement la gestionnaire (personne en bleu) tenant la tablette face à l'autre personne, ce qui correspond à une présentation d'informations sur le logement. A : On ne voit pas la future locataire signer quoi que ce soit sur la tablette. La tablette est tenue par la personne en bleu, ce qui pourrait faire croire à une signature, mais aucun geste de signature n'est visible. C : La gestionnaire tient la tablette mais ne semble pas écrire dessus. Quelqu'un pourrait croire qu'elle prend des notes, mais il n'y a aucun stylet ou geste d'écriture visible. D : La future locataire ne lit pas seule la tablette, car la tablette est tenue par la gestionnaire et tournée vers elle. On pourrait penser qu'elle lit, mais elle n'est pas seule à consulter la tablette.","transcript":"Question 1.\nRegardez l’image et écoutez les propositions.\nA. La future locataire signe l'état des lieux sur la tablette. B. La gestionnaire montre des informations sur le logement sur sa tablette. C. La gestionnaire prend des notes sur sa tablette pendant la visite. D. La future locataire lit seule le contrat affiché sur la tablette.","segments":[{"voice":"female","text":"Question 1."},{"voice":"female","text":"Regardez l’image et écoutez les propositions."},{"voice":"female","text":"A. La future locataire signe l'état des lieux sur la tablette. B. La gestionnaire montre des informations sur le logement sur sa tablette. C. La gestionnaire prend des notes sur sa tablette pendant la visite. D. La future locataire lit seule le contrat affiché sur la tablette."}],"audio":"q-01.mp3","audioSeconds":21.551,"slotSeconds":34,"image":"q-01.svg"},{"number":2,"kind":"image","question":"Quelle situation est représentée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"Réponse B : L'image montre une structure en bois en cours de montage, avec une personne semblant travailler sur l'ossature d'une maison, ce qui correspond à l'action d'un charpentier. A : L'image ne montre pas de tuiles ni d'éléments de toiture, et aucune action sur un toit n'est visible. Quelqu'un pourrait confondre la structure en bois avec un toit, mais il n'y a pas de tuiles cassées ni de réparation. C : Il n'y a pas de fenêtres visibles ni d'éléments de menuiserie terminés à installer. Quelqu'un pourrait croire que les cadres en bois sont des fenêtres, mais elles ne sont pas terminées ni installées dans une façade. D : Aucune fissure ni mur en maçonnerie n'est visible sur l'image, seulement une structure en bois. Quelqu'un pourrait penser à des réparations, mais il n'y a pas d'élément de maçonnerie.","transcript":"Question 2.\nRegardez l’image et écoutez les propositions.\nA. Un couvreur remplace des tuiles cassées sur un toit. B. Un charpentier monte la structure en bois d’une maison. C. Un menuisier installe les fenêtres terminées d’une façade. D. Un maçon rebouche une fissure sur un mur extérieur.","segments":[{"voice":"female","text":"Question 2."},{"voice":"female","text":"Regardez l’image et écoutez les propositions."},{"voice":"female","text":"A. Un couvreur remplace des tuiles cassées sur un toit. B. Un charpentier monte la structure en bois d’une maison. C. Un menuisier installe les fenêtres terminées d’une façade. D. Un maçon rebouche une fissure sur un mur extérieur."}],"audio":"q-02.mp3","audioSeconds":20.689,"slotSeconds":33,"image":"q-02.svg"},{"number":3,"kind":"image","question":"Quelle situation est représentée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"Réponse A : L'image montre un résident qui lit un panneau affiché dans le hall d'entrée, où il est clairement écrit 'AVIS DE TRAVAUX'. Cela correspond exactement à la première proposition. B : Bien que le résident lise un panneau dans le hall, il ne s'agit pas du règlement intérieur mais d'un avis de travaux, comme indiqué sur le panneau. C : Le résident consulte bien un panneau près de l'entrée, mais il ne s'agit pas d'un plan d'évacuation, c'est un avis de travaux. D : Le résident regarde un panneau, mais il n'est pas question d'arrivée de colis, le panneau indique 'AVIS DE TRAVAUX'.","transcript":"Question 3.\nRegardez l’image et écoutez les propositions.\nA. Le résident lit un avis de travaux affiché dans le hall. B. Le résident prend connaissance du règlement intérieur de l’immeuble. C. Le résident consulte le plan d’évacuation affiché près de l’entrée. D. Le résident vérifie sur le panneau l’arrivée de ses colis.","segments":[{"voice":"female","text":"Question 3."},{"voice":"female","text":"Regardez l’image et écoutez les propositions."},{"voice":"female","text":"A. Le résident lit un avis de travaux affiché dans le hall. B. Le résident prend connaissance du règlement intérieur de l’immeuble. C. Le résident consulte le plan d’évacuation affiché près de l’entrée. D. Le résident vérifie sur le panneau l’arrivée de ses colis."}],"audio":"q-03.mp3","audioSeconds":21.577,"slotSeconds":34,"image":"q-03.svg"},{"number":4,"kind":"image","question":"Quelle situation est représentée ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"Réponse C : L'image montre deux personnes debout devant un parterre de fleurs, ce qui correspond à l'entretien d'un espace partagé de la résidence. Il n'y a pas d'éléments qui contredisent cette description. A : On ne voit pas d'entrée d'immeuble ni d'éléments qui indiquent une discussion devant une porte. Les deux personnes sont devant un parterre de fleurs, ce qui pourrait faire penser à l'entrée, mais il n'y a pas de porte visible. B : On ne voit pas de balcons ni d'arrosoirs. Les deux personnes sont côte à côte devant le même parterre, ce qui pourrait faire penser à des balcons, mais il n'y a pas de séparation ni de plantes individuelles. D : Aucune clôture n'est visible autour du jardin. Les deux personnes tiennent des objets, mais rien n'indique qu'il s'agit d'une installation de clôture.","transcript":"Question 4.\nRegardez l’image et écoutez les propositions.\nA. Deux voisins discutent devant l’entrée de l’immeuble. B. Deux voisins arrosent chacun une plante sur leur balcon privé. C. Deux voisins entretiennent le parterre partagé de la résidence. D. Deux voisins installent une clôture autour du jardin.","segments":[{"voice":"female","text":"Question 4."},{"voice":"female","text":"Regardez l’image et écoutez les propositions."},{"voice":"female","text":"A. Deux voisins discutent devant l’entrée de l’immeuble. B. Deux voisins arrosent chacun une plante sur leur balcon privé. C. Deux voisins entretiennent le parterre partagé de la résidence. D. Deux voisins installent une clôture autour du jardin."}],"audio":"q-04.mp3","audioSeconds":21.342,"slotSeconds":34,"image":"q-04.svg"},{"number":5,"kind":"response","question":"Quelle réponse convient ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"Réponse B : Dans un immeuble, le premier interlocuteur pour signaler un problème comme une fuite est le gardien, qui pourra ensuite orienter vers le bon service si nécessaire. C'est la réponse attendue dans ce contexte. A : Il est tentant de penser qu'il faut contacter le service des eaux car il s'agit d'un problème d'eau, mais dans le contexte d'un immeuble, ce n'est pas la première personne à contacter pour une fuite dans son appartement. C : On pourrait croire qu'il faut contacter l'assurance pour déclarer un sinistre, mais une simple fuite de robinet ne constitue pas un sinistre à déclarer immédiatement à l'assurance. Cette option confond la gravité du problème. D : Il est plausible de penser à prévenir la voisine du dessous si la fuite risque de l'affecter, mais la question porte sur la personne à qui signaler le problème en premier lieu, pas sur qui prévenir en cas de dégâts.","transcript":"Question 5.\nLe robinet de la cuisine fuit. À qui dois-je le signaler ?\nA. Directement au service des eaux. B. Au gardien de l’immeuble. C. À l’assurance pour déclarer un sinistre. D. À la voisine qui habite dessous.","segments":[{"voice":"female","text":"Question 5."},{"voice":"female","text":"Le robinet de la cuisine fuit. À qui dois-je le signaler ?"},{"voice":"male","text":"A. Directement au service des eaux. B. Au gardien de l’immeuble. C. À l’assurance pour déclarer un sinistre. D. À la voisine qui habite dessous."}],"audio":"q-05.mp3","audioSeconds":17.685,"slotSeconds":33},{"number":6,"kind":"response","question":"Quelle réponse convient ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"Réponse C : Cette réponse accepte explicitement la proposition de déplacer la visite à vendredi après-midi, ce qui correspond exactement à la demande formulée dans la question. A : Cette réponse propose le mardi comme préférence, alors que la question demande de déplacer au vendredi. Quelqu'un pourrait croire qu'on demande simplement une préférence de jour, mais la question cible spécifiquement le vendredi. B : Cette réponse suppose que la question porte sur la disponibilité de l'appartement, alors qu'il s'agit de déplacer la date de la visite. On pourrait croire que la question concerne la disponibilité, mais ce n'est pas le cas ici. D : Cette réponse affirme que la visite est déjà vendredi, ce qui pourrait être choisi si l'on croit que la visite est déjà prévue ce jour-là. Cependant, la question implique que la visite n'est pas encore prévue pour vendredi.","transcript":"Question 6.\nPouvez-vous déplacer la visite de l'appartement à vendredi ?\nA. Oui, je préfère plutôt le mardi. B. Oui, il est encore disponible. C. Oui, vendredi après-midi, c’est parfait. D. Non, la visite est déjà vendredi.","segments":[{"voice":"female","text":"Question 6."},{"voice":"male","text":"Pouvez-vous déplacer la visite de l'appartement à vendredi ?"},{"voice":"female","text":"A. Oui, je préfère plutôt le mardi. B. Oui, il est encore disponible. C. Oui, vendredi après-midi, c’est parfait. D. Non, la visite est déjà vendredi."}],"audio":"q-06.mp3","audioSeconds":19.252,"slotSeconds":35},{"number":7,"kind":"response","question":"Quelle réponse convient ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"Réponse C : C'est la seule réponse qui indique explicitement que la personne possède une copie et peut l'imprimer, ce qui répond directement à la demande. A : Cette réponse indique que la personne a fait modifier le règlement hier, ce qui pourrait être confondu avec le fait d'avoir une copie récente, mais elle ne répond pas directement à la demande d'une copie. B : Répondre qu'il faut rediscuter le règlement en réunion montre une confusion entre avoir une copie et devoir discuter du contenu ; cela ne répond pas à la demande de fournir une copie. D : Dire que le règlement est affiché dans l'entrée pourrait sembler pertinent, mais cela ne répond pas à la question de savoir si la personne a une copie à fournir.","transcript":"Question 7.\nAvez-vous une copie du règlement de l'immeuble ?\nA. Oui, je l’ai fait modifier hier. B. Oui, je dois le rediscuter en réunion. C. Oui, je peux vous l’imprimer. D. Oui, il est affiché dans l’entrée.","segments":[{"voice":"female","text":"Question 7."},{"voice":"female","text":"Avez-vous une copie du règlement de l'immeuble ?"},{"voice":"male","text":"A. Oui, je l’ai fait modifier hier. B. Oui, je dois le rediscuter en réunion. C. Oui, je peux vous l’imprimer. D. Oui, il est affiché dans l’entrée."}],"audio":"q-07.mp3","audioSeconds":19.513,"slotSeconds":33},{"number":8,"kind":"response","question":"Quelle réponse convient ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"Réponse B : Cette réponse (« Normalement avant la fin de journée. ») répond directement à la question sur le moment où l'ascenseur sera réparé. Elle donne une estimation temporelle, ce qui est exactement ce qui est demandé. A : Cette réponse (« Il est souvent en panne, vous savez. ») commente la fréquence des pannes, mais ne répond pas à la question principale qui porte sur le moment de la réparation. Quelqu'un pourrait la choisir en se concentrant sur le fait que l'ascenseur est souvent en panne, mais cela ne répond pas à la demande d'information sur la réparation. C : Cette réponse (« Non, il fonctionne très bien. ») contredit l'information donnée dans la question, qui indique que l'ascenseur est en panne. Quelqu'un pourrait mal comprendre et penser qu'on demande si l'ascenseur fonctionne, mais cela va à l'encontre du contexte. D : Cette réponse (« Oui, il est très ancien. ») commente l'âge de l'ascenseur, ce qui pourrait expliquer pourquoi il tombe en panne, mais ne répond pas à la question sur la date de réparation. Elle pourrait être choisie par quelqu'un qui se concentre sur la cause de la panne plutôt que sur la réparation.","transcript":"Question 8.\nL'ascenseur est encore en panne. Savez-vous quand il sera réparé ?\nA. Il est souvent en panne, vous savez. B. Normalement avant la fin de journée. C. Non, il fonctionne très bien. D. Oui, il est très ancien.","segments":[{"voice":"female","text":"Question 8."},{"voice":"male","text":"L'ascenseur est encore en panne. Savez-vous quand il sera réparé ?"},{"voice":"female","text":"A. Il est souvent en panne, vous savez. B. Normalement avant la fin de journée. C. Non, il fonctionne très bien. D. Oui, il est très ancien."}],"audio":"q-08.mp3","audioSeconds":18.808,"slotSeconds":38},{"number":9,"kind":"announcement","question":"Que précise l'annonce au sujet des livraisons volumineuses ?","options":["Elles sont maintenues, mais uniquement par l’escalier.","Elles sont autorisées seulement entre neuf heures et midi.","Elles devront être effectuées uniquement l’après-midi.","Elles doivent être reportées à une autre date."],"correct":"D","explanation":"Réponse D : L’annonce précise clairement que les livraisons volumineuses doivent être reportées, ce qui correspond exactement à cette option. A : Quelqu’un pourrait croire que les livraisons volumineuses sont possibles par l’escalier, car il est mentionné qu’ils restent accessibles. Cependant, l’annonce précise explicitement que les livraisons volumineuses doivent être reportées, ce qui contredit cette option. B : Il est indiqué que l’ascenseur ne fonctionne pas entre 9h et midi, mais il n’est jamais dit que les livraisons volumineuses sont autorisées seulement à ce moment-là. Au contraire, elles doivent être reportées. C : Quelqu’un pourrait penser que les livraisons volumineuses doivent être faites l’après-midi, lorsque l’ascenseur fonctionne à nouveau. Cependant, l’annonce demande explicitement de les reporter, donc pas de les effectuer l’après-midi même.","transcript":"Question 9.\nLa copropriété du boulevard Victor-Hugo informe les résidents qu'une inspection de l'ascenseur aura lieu jeudi entre neuf heures et midi. L'appareil restera à l'arrêt pendant ce créneau, mais il sera remis en service dans l'après-midi. Les escaliers demeureront accessibles. Les livraisons volumineuses doivent être reportées.\nQue précise l'annonce au sujet des livraisons volumineuses ?","segments":[{"voice":"female","text":"Question 9."},{"voice":"female","text":"La copropriété du boulevard Victor-Hugo informe les résidents qu'une inspection de l'ascenseur aura lieu jeudi entre neuf heures et midi. L'appareil restera à l'arrêt pendant ce créneau, mais il sera remis en service dans l'après-midi. Les escaliers demeureront accessibles. Les livraisons volumineuses doivent être reportées."},{"voice":"female","text":"Que précise l'annonce au sujet des livraisons volumineuses ?"}],"audio":"q-09.mp3","audioSeconds":23.327,"slotSeconds":38},{"number":10,"kind":"dialogue","question":"Lors de la deuxième visite, quel élément la candidate veut-elle principalement évaluer ?","options":["L’ambiance de l’immeuble quand les voisins rentrent.","Le calme de la cour après la fermeture du restaurant.","Le niveau de bruit du restaurant en soirée.","L’animation de la rue vers vingt heures."],"correct":"C","explanation":"Réponse C : La candidate veut revenir le soir pour évaluer le niveau de bruit du restaurant, car elle craint de ne pas pouvoir dormir à cause de celui-ci. A : Quelqu’un pourrait penser que la candidate veut évaluer l’ambiance générale de l’immeuble à l’arrivée des voisins, mais elle ne mentionne que le bruit du restaurant, pas les voisins. B : La cour est mentionnée, ce qui pourrait faire croire que le calme de la cour est en jeu, mais la préoccupation principale est le bruit du restaurant, pas la cour elle-même. D : La mention de l’heure de la visite (vingt heures) pourrait faire croire que l’animation de la rue à ce moment-là est l’objet de l’évaluation, mais la candidate précise que c’est le bruit du restaurant qui l’intéresse.","transcript":"Question 10.\nCet appartement vous convient-il ? La cuisine a été rénovée et la chambre donne sur la cour.\nLa pièce est agréable, mais le restaurant au rez-de-chaussée ferme très tard. J'aimerais revenir un soir pour entendre le bruit.\nNous pouvons organiser une deuxième visite à vingt heures.\nMerci. Le loyer me convient, mais je voudrais être sûre de pouvoir dormir.\nLors de la deuxième visite, quel élément la candidate veut-elle principalement évaluer ?","segments":[{"voice":"female","text":"Question 10."},{"voice":"male","text":"Cet appartement vous convient-il ? La cuisine a été rénovée et la chambre donne sur la cour."},{"voice":"female","text":"La pièce est agréable, mais le restaurant au rez-de-chaussée ferme très tard. J'aimerais revenir un soir pour entendre le bruit."},{"voice":"male","text":"Nous pouvons organiser une deuxième visite à vingt heures."},{"voice":"female","text":"Merci. Le loyer me convient, mais je voudrais être sûre de pouvoir dormir."},{"voice":"female","text":"Lors de la deuxième visite, quel élément la candidate veut-elle principalement évaluer ?"}],"audio":"q-10.mp3","audioSeconds":30.198,"slotSeconds":44},{"number":11,"kind":"announcement","question":"Avant quelle échéance les résidents doivent-ils envoyer la description d’une réparation non urgente ?","options":["Avant mardi soir","Avant lundi midi","Avant mercredi matin","Avant mardi midi"],"correct":"D","explanation":"Réponse D : La consigne indique explicitement que la description doit être envoyée avant mardi midi, ce qui correspond exactement à cette option. A : Quelqu’un pourrait confondre « mardi soir » avec « mardi midi » car ce sont tous les deux des moments du mardi, mais le texte précise clairement « avant mardi midi ». B : « Lundi midi » précède bien « mardi midi », mais le texte demande explicitement l’envoi avant mardi midi, donc choisir lundi midi serait une interprétation trop restrictive. C : Quelqu’un pourrait penser que « mercredi matin » laisse plus de temps, mais le texte indique clairement que la date limite est « avant mardi midi », donc après cette échéance ce n’est plus accepté.","transcript":"Question 11.\nLa société de gestion rappelle aux résidents de l'immeuble des Tilleuls que les réparations non urgentes seront regroupées la semaine prochaine. Afin de planifier l'intervention, merci de transmettre la description du problème avant mardi midi. Les fuites importantes et les pannes dangereuses doivent toujours être signalées immédiatement par téléphone.\nAvant quelle échéance les résidents doivent-ils envoyer la description d’une réparation non urgente ?","segments":[{"voice":"female","text":"Question 11."},{"voice":"male","text":"La société de gestion rappelle aux résidents de l'immeuble des Tilleuls que les réparations non urgentes seront regroupées la semaine prochaine. Afin de planifier l'intervention, merci de transmettre la description du problème avant mardi midi. Les fuites importantes et les pannes dangereuses doivent toujours être signalées immédiatement par téléphone."},{"voice":"female","text":"Avant quelle échéance les résidents doivent-ils envoyer la description d’une réparation non urgente ?"}],"audio":"q-11.mp3","audioSeconds":28.839,"slotSeconds":41},{"number":12,"kind":"dialogue","question":"Que faut-il faire, d’après l’artisan, pour que le problème d’humidité soit réellement réglé ?","options":["Réparer l’étanchéité sans modifier les joints.","Changer le carrelage et renforcer l’isolation.","Traiter le joint et vérifier la ventilation.","Se contenter d’améliorer la ventilation de la pièce."],"correct":"C","explanation":"Réponse C : C’est la seule option qui reprend exactement les deux conditions données par l’artisan pour régler le problème d’humidité : traiter le joint et vérifier la ventilation. A : Cette option propose de réparer l’étanchéité sans modifier les joints, mais l’artisan précise qu’il faut aussi traiter le joint. Quelqu’un pourrait croire que réparer l’étanchéité suffit, mais le texte exige explicitement une action sur le joint. B : L’artisan dit que changer le carrelage n’est pas indispensable immédiatement. Quelqu’un pourrait penser que c’est nécessaire pour régler le problème, mais il est explicitement dit que cela peut attendre. D : L’artisan précise qu’il ne suffit pas de vérifier la ventilation, il faut aussi traiter le joint. Cette option est donc incomplète.","transcript":"Question 12.\nLe devis prévoit de refaire toute la salle de bains, mais notre budget ne le permet pas.\nNous pouvons réparer d'abord l'étanchéité autour de la douche. Le changement du carrelage peut attendre.\nEst-ce que cela règle le problème d'humidité ?\nOui, si l'on traite aussi le joint et si l'on vérifie la ventilation. Je vous prépare un devis réduit.\nD'accord, faisons les travaux indispensables en priorité.\nQue faut-il faire, d’après l’artisan, pour que le problème d’humidité soit réellement réglé ?","segments":[{"voice":"female","text":"Question 12."},{"voice":"female","text":"Le devis prévoit de refaire toute la salle de bains, mais notre budget ne le permet pas."},{"voice":"male","text":"Nous pouvons réparer d'abord l'étanchéité autour de la douche. Le changement du carrelage peut attendre."},{"voice":"female","text":"Est-ce que cela règle le problème d'humidité ?"},{"voice":"male","text":"Oui, si l'on traite aussi le joint et si l'on vérifie la ventilation. Je vous prépare un devis réduit."},{"voice":"female","text":"D'accord, faisons les travaux indispensables en priorité."},{"voice":"female","text":"Que faut-il faire, d’après l’artisan, pour que le problème d’humidité soit réellement réglé ?"}],"audio":"q-12.mp3","audioSeconds":30.824,"slotSeconds":43},{"number":13,"kind":"announcement","question":"D’après cet avis, que peut-on encore faire en dehors de la plage 8 h 30–17 h 30 ?","options":["Seuls les outils très bruyants sont encore permis, mais sur une durée plus courte.","Tous les travaux de façade, à condition de prévenir les voisins.","Uniquement des opérations silencieuses, si le règlement de l’immeuble les autorise.","Aucun type de travaux, même silencieux, n’est plus toléré."],"correct":"C","explanation":"Réponse C : Le texte dit clairement que seules les opérations silencieuses sont possibles en dehors de la plage horaire, et seulement si le règlement de l’immeuble le permet. A : Quelqu’un pourrait croire que seuls les outils très bruyants sont autorisés sur une durée plus courte, mais le texte précise qu’ils sont interdits en dehors de la plage horaire indiquée. Ce n’est donc pas possible d’utiliser ces outils en dehors de 8 h 30–17 h 30. B : On pourrait penser que tous les travaux de façade sont permis si on prévient les voisins, mais le texte distingue bien entre travaux bruyants (interdits hors horaires) et opérations silencieuses (autorisées selon le règlement). D : On pourrait croire qu’aucun type de travaux n’est toléré en dehors de la plage horaire, mais le texte précise que les opérations silencieuses restent possibles sous condition.","transcript":"Question 13.\nDans le cadre des travaux de façade, la mairie rappelle que les outils très bruyants ne peuvent être utilisés avant huit heures trente ni après dix-sept heures trente en semaine. Ils sont interdits le dimanche. Les opérations silencieuses, comme la peinture intérieure, restent possibles en dehors de ces horaires selon le règlement de l'immeuble.\nD’après cet avis, que peut-on encore faire en dehors de la plage 8 h 30–17 h 30 ?","segments":[{"voice":"female","text":"Question 13."},{"voice":"female","text":"Dans le cadre des travaux de façade, la mairie rappelle que les outils très bruyants ne peuvent être utilisés avant huit heures trente ni après dix-sept heures trente en semaine. Ils sont interdits le dimanche. Les opérations silencieuses, comme la peinture intérieure, restent possibles en dehors de ces horaires selon le règlement de l'immeuble."},{"voice":"female","text":"D’après cet avis, que peut-on encore faire en dehors de la plage 8 h 30–17 h 30 ?"}],"audio":"q-13.mp3","audioSeconds":25.913,"slotSeconds":39},{"number":14,"kind":"dialogue","question":"Après avoir accepté le principe d’un repas qui se termine avant vingt heures, comment le voisin prévoit-il de faire valider ce projet ?","options":["Le présenter au conseil des résidents et vérifier que tout le monde est d’accord.","Rédiger une affiche pour annoncer que le repas aura bien lieu samedi soir.","Glisser un questionnaire dans les boîtes aux lettres des familles concernées par le bruit.","Demander au gardien de recueillir individuellement l’avis des habitants pendant sa tournée."],"correct":"A","explanation":"Réponse A : Le voisin dit explicitement qu'il va présenter le projet au conseil des résidents et vérifier l'accord de tous, ce qui correspond exactement à l'option 0. B : Quelqu'un pourrait penser qu'une affiche est nécessaire pour annoncer l'événement, mais le texte ne mentionne pas la rédaction d'une affiche, seulement la discussion au conseil. C : On pourrait croire qu'un questionnaire permettrait de recueillir l'avis des familles concernées, mais il n'est jamais question d'un tel document dans l'extrait. D : Il serait logique de demander au gardien de faire une tournée, mais le voisin prévoit une validation collective au conseil, pas une démarche individuelle par le gardien.","transcript":"Question 14.\nNous voulions organiser un repas collectif samedi soir, mais des enfants se couchent tôt dans les appartements qui donnent sur la cour.\nEt si nous commencions en fin d'après-midi, puis terminions avant vingt heures ?\nCela me paraît raisonnable. Nous pourrions aussi installer les tables loin des fenêtres.\nJe vais en parler au conseil des résidents et vérifier si tout le monde est d'accord.\nAprès avoir accepté le principe d’un repas qui se termine avant vingt heures, comment le voisin prévoit-il de faire valider ce projet ?","segments":[{"voice":"female","text":"Question 14."},{"voice":"male","text":"Nous voulions organiser un repas collectif samedi soir, mais des enfants se couchent tôt dans les appartements qui donnent sur la cour."},{"voice":"female","text":"Et si nous commencions en fin d'après-midi, puis terminions avant vingt heures ?"},{"voice":"male","text":"Cela me paraît raisonnable. Nous pourrions aussi installer les tables loin des fenêtres."},{"voice":"female","text":"Je vais en parler au conseil des résidents et vérifier si tout le monde est d'accord."},{"voice":"female","text":"Après avoir accepté le principe d’un repas qui se termine avant vingt heures, comment le voisin prévoit-il de faire valider ce projet ?"}],"audio":"q-14.mp3","audioSeconds":33.985,"slotSeconds":47},{"number":15,"kind":"radio-news","question":"Comment la métropole de Dijon compte-t-elle répondre aux hésitations des locataires ?","options":["En envoyant un guide explicatif à tous les foyers concernés.","En mettant en place une permanence juridique dédiée.","En ouvrant une ligne téléphonique d’information sur l’isolation.","En organisant des réunions publiques dans chaque quartier."],"correct":"B","explanation":"Réponse B : Le texte indique clairement que la métropole prévoit une permanence juridique pour expliquer les protections et obligations, ce qui répond directement à la question sur la manière de répondre aux hésitations des locataires. A : Quelqu’un pourrait penser qu’un guide explicatif serait envoyé pour informer les locataires, car il s’agit d’une méthode courante d’information. Cependant, le texte ne mentionne à aucun moment l’envoi d’un guide, mais parle explicitement d’une permanence juridique. C : Une ligne téléphonique d’information pourrait sembler logique pour répondre aux questions, mais le texte ne mentionne pas ce dispositif. La confusion peut venir de l’idée d’un service d’information, mais ici il s’agit d’une permanence juridique, pas d’une ligne téléphonique. D : Organiser des réunions publiques dans chaque quartier pourrait être une autre façon de répondre aux hésitations, mais le texte ne mentionne que la mise en place d’une permanence juridique. Quelqu’un pourrait confondre une permanence avec une réunion publique, mais ce n’est pas le cas ici.","transcript":"Question 15.\nLa métropole de Dijon a lancé une aide à l'isolation des logements anciens. Les premières demandes sont nombreuses, mais plusieurs associations signalent que des locataires hésitent à entamer la procédure. Ils craignent que leurs propriétaires répercutent ensuite une partie des travaux sur les charges. La collectivité prévoit une permanence juridique afin d'expliquer les protections et les obligations de chacun.\nComment la métropole de Dijon compte-t-elle répondre aux hésitations des locataires ?","segments":[{"voice":"female","text":"Question 15."},{"voice":"female","text":"La métropole de Dijon a lancé une aide à l'isolation des logements anciens. Les premières demandes sont nombreuses, mais plusieurs associations signalent que des locataires hésitent à entamer la procédure. Ils craignent que leurs propriétaires répercutent ensuite une partie des travaux sur les charges. La collectivité prévoit une permanence juridique afin d'expliquer les protections et les obligations de chacun."},{"voice":"female","text":"Comment la métropole de Dijon compte-t-elle répondre aux hésitations des locataires ?"}],"audio":"q-15.mp3","audioSeconds":29.257,"slotSeconds":49},{"number":16,"kind":"dialogue","question":"À quel moment le plombier propose-t-il de venir à la place de lundi ?","options":["Mardi à neuf heures.","Mercredi à neuf heures.","Lundi en fin de matinée.","Mardi en début d’après-midi."],"correct":"A","explanation":"Réponse A : Le plombier propose explicitement de venir mardi à neuf heures, ce qui répond directement à la question posée. B : Quelqu’un pourrait confondre mardi avec mercredi car ce sont deux jours consécutifs, mais le texte ne mentionne jamais mercredi. La proposition concerne mardi uniquement. C : On pourrait croire que le rendez-vous est maintenu le lundi mais à un autre moment de la journée, car le lundi matin était initialement prévu. Cependant, le plombier précise qu’il ne pourra pas être là avant mardi. D : Quelqu’un pourrait confondre l’heure proposée (neuf heures) avec un autre moment de la journée (début d’après-midi), mais le texte indique clairement neuf heures du matin.","transcript":"Question 16.\nJe vous avais réservé le lundi matin pour réparer la tuyauterie de la buanderie.\nJe dois terminer une intervention urgente dans un immeuble voisin et je ne pourrai pas être là avant mardi.\nLa fuite est maîtrisée pour l'instant. Mardi à neuf heures, cela vous irait ?\nOui. Je vous confirmerai par message et vous présenterai le matériel nécessaire.\nÀ quel moment le plombier propose-t-il de venir à la place de lundi ?","segments":[{"voice":"female","text":"Question 16."},{"voice":"female","text":"Je vous avais réservé le lundi matin pour réparer la tuyauterie de la buanderie."},{"voice":"male","text":"Je dois terminer une intervention urgente dans un immeuble voisin et je ne pourrai pas être là avant mardi."},{"voice":"female","text":"La fuite est maîtrisée pour l'instant. Mardi à neuf heures, cela vous irait ?"},{"voice":"male","text":"Oui. Je vous confirmerai par message et vous présenterai le matériel nécessaire."},{"voice":"female","text":"À quel moment le plombier propose-t-il de venir à la place de lundi ?"}],"audio":"q-16.mp3","audioSeconds":27.742,"slotSeconds":42},{"number":17,"kind":"announcement","question":"Quel service sera interrompu mercredi matin ?","options":["Le chauffage collectif des bâtiments A et B, de huit heures à onze heures.","L'alimentation en eau froide des bâtiments A et B, de huit heures à onze heures.","L'alimentation en eau chaude des bâtiments A et B, de huit heures à onze heures.","L'alimentation en eau froide du seul bâtiment A, de huit heures à onze heures."],"correct":"B","explanation":"Réponse B : C'est exactement ce qui est annoncé dans le texte : l'alimentation en eau froide des bâtiments A et B sera interrompue mercredi matin de 8h à 11h. A : Quelqu'un pourrait croire que le chauffage collectif sera interrompu, mais le texte précise qu'il continuera à fonctionner normalement, donc ce n'est pas le service interrompu. C : Quelqu'un pourrait confondre eau froide et eau chaude, mais le texte ne mentionne que l'eau froide. L'eau chaude n'est pas concernée. D : On pourrait croire que seul le bâtiment A est concerné, mais le texte précise bien que les deux bâtiments A et B sont touchés.","transcript":"Question 17.\nEn raison du remplacement d'une vanne principale, l'eau froide sera coupée dans les bâtiments A et B mercredi de huit heures à onze heures. Le chauffage collectif continuera à fonctionner normalement. Les habitants sont invités à remplir quelques récipients à l'avance. En cas de problème après la remise en service, contactez le gardien.\nQuel service sera interrompu mercredi matin ?","segments":[{"voice":"female","text":"Question 17."},{"voice":"male","text":"En raison du remplacement d'une vanne principale, l'eau froide sera coupée dans les bâtiments A et B mercredi de huit heures à onze heures. Le chauffage collectif continuera à fonctionner normalement. Les habitants sont invités à remplir quelques récipients à l'avance. En cas de problème après la remise en service, contactez le gardien."},{"voice":"female","text":"Quel service sera interrompu mercredi matin ?"}],"audio":"q-17.mp3","audioSeconds":26.828,"slotSeconds":47},{"number":18,"kind":"telephone","question":"Que précise la locataire au sujet de son virement de loyer après le changement de banque ?","options":["Qu'il part toujours du même compte, mais avec une nouvelle référence de logement.","Qu'il est désormais prélevé automatiquement sans qu'elle ait à intervenir.","Qu'il part d'un nouveau compte et qu'elle a aussi changé la référence du logement.","Qu'il part d'un nouveau compte, mais avec la même référence de logement."],"correct":"D","explanation":"Réponse D : La locataire précise clairement que le virement part d'un nouveau compte, mais que la référence du logement n'a pas changé. C'est exactement ce que dit l'option 4. A : Quelqu'un pourrait croire que seule la référence a changé, mais la locataire précise que c'est le compte qui a changé, pas la référence. B : On pourrait supposer que le virement est devenu automatique, mais la locataire ne mentionne rien à ce sujet ; elle parle seulement du changement de compte. C : Quelqu'un pourrait penser que la référence a changé en même temps que le compte, mais la locataire précise explicitement que seule la banque a changé, pas la référence.","transcript":"Question 18.\nBonjour, j'ai réglé mon loyer le premier du mois, pourtant votre espace en ligne m'indique un retard.\nAvez-vous changé de banque récemment ?\nOui, le virement part désormais d'un nouveau compte, mais la référence du logement est restée la même.\nJe vais comparer les opérations reçues et vous envoyer une confirmation avant de modifier votre dossier.\nMerci, je préfère éviter un rappel injustifié.\nQue précise la locataire au sujet de son virement de loyer après le changement de banque ?","segments":[{"voice":"female","text":"Question 18."},{"voice":"female","text":"Bonjour, j'ai réglé mon loyer le premier du mois, pourtant votre espace en ligne m'indique un retard."},{"voice":"male","text":"Avez-vous changé de banque récemment ?"},{"voice":"female","text":"Oui, le virement part désormais d'un nouveau compte, mais la référence du logement est restée la même."},{"voice":"male","text":"Je vais comparer les opérations reçues et vous envoyer une confirmation avant de modifier votre dossier."},{"voice":"female","text":"Merci, je préfère éviter un rappel injustifié."},{"voice":"female","text":"Que précise la locataire au sujet de son virement de loyer après le changement de banque ?"}],"audio":"q-18.mp3","audioSeconds":32.496,"slotSeconds":46},{"number":19,"kind":"announcement","question":"Que pourront concrètement faire les résidents lors de cette réunion de mercredi ?","options":["Consulter le calendrier prévisionnel et signaler leurs besoins liés aux déplacements de meubles.","Présenter des propositions de nouvelles entreprises et en débattre avec le syndic.","Discuter de la répartition des coûts et demander un échelonnement des paiements.","Voter le calendrier définitif et valider les modalités d’accès pendant les travaux."],"correct":"A","explanation":"Réponse A : La réunion permettra effectivement aux résidents de consulter le calendrier prévisionnel et de signaler leurs besoins liés aux déplacements de meubles, ce qui correspond exactement à l'option 0. B : L'option 1 suppose que les résidents pourront présenter des propositions de nouvelles entreprises et en débattre avec le syndic, mais le texte ne mentionne pas la possibilité de présenter ou débattre de nouvelles entreprises. Quelqu’un pourrait croire que toute réunion permet ce genre d’échanges, mais ici, la réunion est centrée sur le calendrier et les besoins logistiques. C : L'option 2 parle de discuter de la répartition des coûts et d’un échelonnement des paiements, mais rien dans le texte ne mentionne ces sujets. On pourrait croire que toute réunion sur des travaux aborde les coûts, mais ici, ce n’est pas le cas. D : L'option 3 suppose que les résidents vont voter le calendrier définitif et valider les modalités d’accès, mais le texte précise qu’aucun vote n’aura lieu lors de cette réunion. Quelqu’un pourrait confondre cette réunion préparatoire avec l’assemblée décisionnelle du mois prochain.","transcript":"Question 19.\nL'association des habitants tiendra mercredi une réunion sur les prochaines rénovations de l'immeuble. Les résidents pourront consulter le calendrier prévisionnel, poser des questions sur les accès temporaires et signaler les besoins particuliers liés au déménagement de certains meubles. Aucun vote ne sera organisé ce soir-là; une décision formelle interviendra lors de l'assemblée du mois prochain.\nQue pourront concrètement faire les résidents lors de cette réunion de mercredi ?","segments":[{"voice":"female","text":"Question 19."},{"voice":"female","text":"L'association des habitants tiendra mercredi une réunion sur les prochaines rénovations de l'immeuble. Les résidents pourront consulter le calendrier prévisionnel, poser des questions sur les accès temporaires et signaler les besoins particuliers liés au déménagement de certains meubles. Aucun vote ne sera organisé ce soir-là; une décision formelle interviendra lors de l'assemblée du mois prochain."},{"voice":"female","text":"Que pourront concrètement faire les résidents lors de cette réunion de mercredi ?"}],"audio":"q-19.mp3","audioSeconds":27.115,"slotSeconds":40},{"number":20,"kind":"dialogue","question":"Que prévoit le résident pour vérifier que l'accès conviendra à sa mère ?","options":["Proposer de reporter les travaux d'entrée tant que sa mère utilise un déambulateur.","Demander à l'entreprise d'installer un deuxième ascenseur pendant les travaux.","Solliciter un plan coté de la rampe et organiser un essai avec les résidents concernés.","Demander que la rampe provisoire soit remplacée par quelques marches plus étroites."],"correct":"C","explanation":"Réponse C : C'est exactement ce que le résident prévoit : demander un plan coté et organiser un essai avec les résidents concernés. A : Quelqu'un pourrait croire que le résident souhaite reporter les travaux pour le confort de sa mère, car il s'inquiète de l'accès. Cependant, il ne propose pas de reporter les travaux, mais de vérifier la largeur de la rampe. B : On pourrait penser qu'il veut un deuxième ascenseur parce qu'il mentionne l'ascenseur immobilisé, mais il ne propose jamais d'en installer un autre. Il cherche une solution temporaire avec la rampe. D : Quelqu'un pourrait confondre la rampe provisoire avec des marches, mais le résident ne demande pas de remplacer la rampe par des marches, il veut s'assurer que la rampe convient.","transcript":"Question 20.\nLe nouveau plan d'accès me plaît, mais ma mère utilise un déambulateur et habite au deuxième étage.\nLes travaux d'entrée doivent durer deux semaines, avec une rampe provisoire.\nJ'aimerais vérifier que la rampe sera suffisamment large, surtout les jours où l'ascenseur est immobilisé.\nJe vais demander à l'entreprise un plan coté et organiser un essai avec les résidents concernés.\nQue prévoit le résident pour vérifier que l'accès conviendra à sa mère ?","segments":[{"voice":"female","text":"Question 20."},{"voice":"male","text":"Le nouveau plan d'accès me plaît, mais ma mère utilise un déambulateur et habite au deuxième étage."},{"voice":"female","text":"Les travaux d'entrée doivent durer deux semaines, avec une rampe provisoire."},{"voice":"male","text":"J'aimerais vérifier que la rampe sera suffisamment large, surtout les jours où l'ascenseur est immobilisé."},{"voice":"female","text":"Je vais demander à l'entreprise un plan coté et organiser un essai avec les résidents concernés."},{"voice":"female","text":"Que prévoit le résident pour vérifier que l'accès conviendra à sa mère ?"}],"audio":"q-20.mp3","audioSeconds":29.649,"slotSeconds":46},{"number":21,"kind":"announcement","question":"À quoi servira concrètement l’indication de plusieurs créneaux possibles par les habitants ?","options":["À regrouper un maximum d’entretiens sur le créneau le plus demandé.","À distinguer strictement les entretiens prévus en soirée de ceux du samedi.","À réserver en priorité les meilleurs horaires aux personnes en horaires décalés.","À éviter que tous les rendez-vous soient placés sur le même après-midi."],"correct":"D","explanation":"Réponse D : Le texte explique explicitement que l’indication de plusieurs créneaux sert à éviter que tous les rendez-vous soient placés sur le même après-midi. A : Quelqu’un pourrait penser que l’objectif est de regrouper les entretiens sur le créneau le plus demandé, car on parle de choix de créneaux, mais le texte précise au contraire qu’il s’agit d’éviter la concentration sur un même moment. B : On pourrait croire que l’indication de plusieurs créneaux sert à distinguer les entretiens du soir de ceux du samedi, car ces deux moments sont mentionnés. Cependant, le texte ne parle pas de distinction stricte, mais de répartition pour éviter la concentration. C : Certains pourraient penser que les meilleurs horaires sont réservés à ceux en horaires décalés, car on mentionne leur situation, mais il n’est jamais question de priorité ou de 'meilleurs horaires'.","transcript":"Question 21.\nLe conseil de quartier prépare une consultation des résidents sur l'usage de la cour commune. Les entretiens individuels auront lieu le soir et le samedi. Comme plusieurs personnes travaillent en horaires décalés, nous vous invitons à indiquer au moins deux créneaux possibles. Ces informations permettront de répartir les rendez-vous sans concentrer tous les échanges sur le même après-midi.\nÀ quoi servira concrètement l’indication de plusieurs créneaux possibles par les habitants ?","segments":[{"voice":"female","text":"Question 21."},{"voice":"female","text":"Le conseil de quartier prépare une consultation des résidents sur l'usage de la cour commune. Les entretiens individuels auront lieu le soir et le samedi. Comme plusieurs personnes travaillent en horaires décalés, nous vous invitons à indiquer au moins deux créneaux possibles. Ces informations permettront de répartir les rendez-vous sans concentrer tous les échanges sur le même après-midi."},{"voice":"female","text":"À quoi servira concrètement l’indication de plusieurs créneaux possibles par les habitants ?"}],"audio":"q-21.mp3","audioSeconds":28.003,"slotSeconds":53},{"number":22,"kind":"interview","question":"D’après elle, qu’est-ce qui rend l’expérience du jardin surtout précieuse, même lorsque certaines plantes meurent ?","options":["Les liens qui se tissent et se maintiennent entre voisins.","Les connaissances de jardinage qu’elle acquiert en échangeant des conseils.","Le fait de mieux s’organiser pour l’arrosage de la cour.","La possibilité de récolter malgré tout quelques herbes fraîches."],"correct":"A","explanation":"Réponse A : La personne explique clairement que ce sont les relations entre voisins qui rendent l'expérience du jardin précieuse, même lorsque certaines plantes meurent. Elle insiste sur l'importance des liens humains créés et maintenus grâce au jardin collectif. B : Il est vrai qu'elle mentionne l'échange de conseils de jardinage, ce qui pourrait faire croire que l'acquisition de connaissances est ce qui rend l'expérience précieuse. Cependant, elle précise que ce n'est pas l'essentiel et insiste que ce sont les relations qui comptent le plus. C : L'organisation de l'arrosage est évoquée comme une activité collective, mais ce n'est pas ce qui rend l'expérience précieuse selon elle. C'est une conséquence de la collaboration, pas la source de la valeur principale. D : Elle mentionne la récolte d'herbes, mais précise que ce n'est pas l'essentiel. Quelqu'un pourrait croire que la possibilité de récolter des herbes fraîches est précieuse, mais elle contredit cette idée en la minimisant.","transcript":"Question 22.\nDepuis la création du jardin collectif dans la cour, votre immeuble semble plus animé. Qu'est-ce qui a changé pour vous ?\nJe cultive quelques herbes, mais ce n'est pas l'essentiel. Avant, les voisins se croisaient sans se parler. Maintenant nous échangeons des conseils, décidons ensemble de l'arrosage et apprenons à résoudre de petits désaccords. Il arrive que des plantes meurent, mais les contacts continuent. Pour moi, ce sont surtout ces relations qui rendent l'expérience précieuse.\nD’après elle, qu’est-ce qui rend l’expérience du jardin surtout précieuse, même lorsque certaines plantes meurent ?","segments":[{"voice":"female","text":"Question 22."},{"voice":"male","text":"Depuis la création du jardin collectif dans la cour, votre immeuble semble plus animé. Qu'est-ce qui a changé pour vous ?"},{"voice":"female","text":"Je cultive quelques herbes, mais ce n'est pas l'essentiel. Avant, les voisins se croisaient sans se parler. Maintenant nous échangeons des conseils, décidons ensemble de l'arrosage et apprenons à résoudre de petits désaccords. Il arrive que des plantes meurent, mais les contacts continuent. Pour moi, ce sont surtout ces relations qui rendent l'expérience précieuse."},{"voice":"female","text":"D’après elle, qu’est-ce qui rend l’expérience du jardin surtout précieuse, même lorsque certaines plantes meurent ?"}],"audio":"q-22.mp3","audioSeconds":37.904,"slotSeconds":62},{"number":23,"kind":"panel-discussion","question":"Quelle démarche les participants retiennent-ils pour concilier rénovation et protection des locataires ?","options":["Rénover immédiatement plusieurs immeubles, puis analyser ensuite les factures d’énergie afin de décider s’il faut instaurer des aides.","Maintenir les charges inchangées pendant tout le chantier et reporter à plus tard la mesure précise des consommations d’hiver.","Rédiger d’abord une charte générale avec les propriétaires, sans passer par un bâtiment test, puis négocier ensuite les compensations pour les ménages fragiles.","Rénover d’abord un seul immeuble, suivre les consommations pendant l’hiver, publier les coûts et prévoir une aide ciblée avant d’étendre les travaux."],"correct":"D","explanation":"Réponse D : Cette option reprend fidèlement la démarche décrite dans le stimulus : test sur un bâtiment, suivi des consommations, publication des coûts, aide ciblée, puis extension éventuelle. A : Cette option pourrait sembler plausible car elle reprend l'idée d'une rénovation rapide, mais elle ne tient pas compte de la démarche progressive décrite dans le stimulus (commencer par un seul bâtiment, mesurer, publier, puis étendre). De plus, il n'est pas question d'analyser les factures après coup pour décider d'aides, mais de prévoir une aide ciblée avant l'extension. B : Cette option s'appuie sur la préoccupation des locataires concernant les charges, mais le stimulus ne mentionne pas le maintien inchangé des charges pendant tout le chantier ni le report de la mesure des consommations. Au contraire, il est prévu de mesurer les consommations pendant l'hiver du bâtiment test. C : Cette option pourrait être tentante car il est question d'un accord général, mais le stimulus précise qu'il faut d'abord tester sur un bâtiment avant d'étendre. Il n'est pas question de rédiger une charte générale sans test préalable.","transcript":"Question 23.\nNous discutons du partage du coût de la rénovation énergétique.\nLes propriétaires souhaitent isoler les façades rapidement pour réduire les pertes de chaleur.\nLes représentants des locataires veulent des garanties sur les charges et sur la durée du chantier.\nNous pourrions commencer par un seul bâtiment, mesurer les consommations pendant l'hiver et publier les dépenses exactes.\nOui, à condition de prévoir une aide pour les ménages les plus fragiles si une augmentation temporaire est nécessaire.\nDans ce cas, élaborons ensemble un accord avant d'étendre les travaux.\nQuelle démarche les participants retiennent-ils pour concilier rénovation et protection des locataires ?","segments":[{"voice":"female","text":"Question 23.","speaker":"female"},{"voice":"female","text":"Nous discutons du partage du coût de la rénovation énergétique.","speaker":"female"},{"voice":"male","text":"Les propriétaires souhaitent isoler les façades rapidement pour réduire les pertes de chaleur.","speaker":"male"},{"voice":"female","text":"Les représentants des locataires veulent des garanties sur les charges et sur la durée du chantier.","speaker":"female_alt"},{"voice":"male","text":"Nous pourrions commencer par un seul bâtiment, mesurer les consommations pendant l'hiver et publier les dépenses exactes.","speaker":"male"},{"voice":"female","text":"Oui, à condition de prévoir une aide pour les ménages les plus fragiles si une augmentation temporaire est nécessaire.","speaker":"female_alt"},{"voice":"male","text":"Dans ce cas, élaborons ensemble un accord avant d'étendre les travaux.","speaker":"male"},{"voice":"female","text":"Quelle démarche les participants retiennent-ils pour concilier rénovation et protection des locataires ?","speaker":"female"}],"audio":"q-23.mp3","audioSeconds":41.979,"slotSeconds":72},{"number":24,"kind":"interview","question":"Quel biais d'échantillonnage l’urbaniste met-elle en avant à propos du sondage ?","options":["Les réponses proviennent surtout d’habitants qui ont des difficultés à sortir de chez eux.","Les réponses proviennent surtout d’habitants des étages récemment réhabilités.","Les réponses proviennent surtout d’habitants qui utilisent déjà les nouveaux espaces au quotidien.","Les réponses proviennent surtout d’habitants qui ont choisi de se rendre à l’inauguration."],"correct":"D","explanation":"Réponse D : L’urbaniste explique clairement que le biais d’échantillonnage provient du fait que les questionnaires ont été distribués lors de l’inauguration, donc principalement à des habitants qui ont choisi de s’y rendre. Cela limite la représentativité des résultats. A : Quelqu’un pourrait croire que le biais concerne surtout les personnes ayant des difficultés à sortir, car l’urbaniste mentionne qu’elles étaient peu présentes. Cependant, le biais évoqué est que les réponses proviennent principalement de ceux qui ont choisi de venir à l’inauguration, donc ce groupe est sous-représenté, pas sur-représenté. B : On pourrait penser que seuls les habitants des étages récemment réhabilités ont répondu, car l’urbaniste dit qu’il faut encore rencontrer les autres. Mais elle ne précise pas que le biais vient de là, seulement que ces habitants n’ont pas encore été consultés. C : Il serait tentant de croire que le biais concerne les utilisateurs quotidiens des nouveaux espaces, mais l’urbaniste précise que le biais vient du fait que les répondants sont ceux qui ont choisi de venir à l’inauguration, pas nécessairement des usagers quotidiens.","transcript":"Question 24.\nVotre sondage suggère que les résidents apprécient les espaces rénovés. Pouvez-vous généraliser cette conclusion ?\nPas encore. Nous avons distribué les questionnaires lors de l'inauguration, à des personnes qui avaient choisi de venir. Celles qui ont du mal à sortir de chez elles ou qui se sentent exclues du projet étaient peu présentes. Nous devons rencontrer les habitants d'autres étages, y compris ceux qui rencontrent des difficultés d'accès, pour comprendre l'ensemble des usages. Une inauguration réussie ne garantit pas une amélioration équitable.\nQuel biais d'échantillonnage l’urbaniste met-elle en avant à propos du sondage ?","segments":[{"voice":"female","text":"Question 24."},{"voice":"male","text":"Votre sondage suggère que les résidents apprécient les espaces rénovés. Pouvez-vous généraliser cette conclusion ?"},{"voice":"female","text":"Pas encore. Nous avons distribué les questionnaires lors de l'inauguration, à des personnes qui avaient choisi de venir. Celles qui ont du mal à sortir de chez elles ou qui se sentent exclues du projet étaient peu présentes. Nous devons rencontrer les habitants d'autres étages, y compris ceux qui rencontrent des difficultés d'accès, pour comprendre l'ensemble des usages. Une inauguration réussie ne garantit pas une amélioration équitable."},{"voice":"female","text":"Quel biais d'échantillonnage l’urbaniste met-elle en avant à propos du sondage ?"}],"audio":"q-24.mp3","audioSeconds":37.433,"slotSeconds":70},{"number":25,"kind":"television-report","question":"Sur quels points l'association des locataires insiste-t-elle dans le reportage ?","options":["Sur l'adaptation des solutions de relogement aux familles avec enfants et la prise en charge des déplacements des habitants.","Sur l'obtention de dates plus précises pour le chantier et la garantie d'absence de hausse de loyer.","Sur l'obtention de dates plus précises pour le chantier et la prise en charge des déplacements des habitants.","Sur le maintien des habitants dans leurs appartements pendant les travaux et la réduction de la durée du chantier."],"correct":"C","explanation":"Réponse C : C'est la seule option qui reprend exactement les deux revendications de l'association telles qu'énoncées dans le reportage : des dates plus précises pour le chantier et la prise en charge des déplacements des habitants. A : Cette option mélange une préoccupation exprimée par une habitante (l'adaptation des solutions de relogement aux familles avec enfants) avec une demande de l'association (prise en charge des déplacements). Or, l'association n'insiste pas sur l'adaptation des solutions de relogement, mais sur d'autres points. B : Cette option mentionne la demande de dates plus précises (correct) mais ajoute la garantie d'absence de hausse de loyer, qui n'est pas évoquée dans le reportage. Quelqu'un pourrait supposer que la hausse de loyer est une préoccupation habituelle lors de rénovations, mais ce n'est pas mentionné ici. D : Cette option propose le maintien des habitants dans leurs appartements et la réduction de la durée du chantier, mais l'association ne demande pas cela. Au contraire, il est explicitement dit que les habitants doivent quitter leur logement. Quelqu'un pourrait mal comprendre et penser que l'association souhaite éviter le déménagement, mais ce n'est pas ce qui est dit.","transcript":"Question 25.\nÀ Brest, un ancien ensemble de logements est en cours de rénovation. Les façades vont être isolées et les fenêtres remplacées.\nNous attendions ces améliorations, témoigne une habitante, mais nous devons quitter nos appartements pendant six semaines. Les solutions de relogement ne conviennent pas toutes aux familles avec enfants.\nLe bailleur promet un accompagnement, tandis que l'association des locataires demande des dates plus précises et la prise en charge des déplacements. Le chantier doit donc avancer sans laisser les habitants supporter seuls ses conséquences.\nSur quels points l'association des locataires insiste-t-elle dans le reportage ?","segments":[{"voice":"female","text":"Question 25."},{"voice":"female","text":"À Brest, un ancien ensemble de logements est en cours de rénovation. Les façades vont être isolées et les fenêtres remplacées."},{"voice":"male","text":"Nous attendions ces améliorations, témoigne une habitante, mais nous devons quitter nos appartements pendant six semaines. Les solutions de relogement ne conviennent pas toutes aux familles avec enfants."},{"voice":"female","text":"Le bailleur promet un accompagnement, tandis que l'association des locataires demande des dates plus précises et la prise en charge des déplacements. Le chantier doit donc avancer sans laisser les habitants supporter seuls ses conséquences."},{"voice":"female","text":"Sur quels points l'association des locataires insiste-t-elle dans le reportage ?"}],"audio":"q-25.mp3","audioSeconds":39.053,"slotSeconds":71},{"number":26,"kind":"interview","question":"Selon l’architecte, quel exemple précis montre qu’une rampe posée sans adaptation peut rester inutilisable malgré le respect des normes ?","options":["Une rampe trop étroite, conforme aux plans, mais impraticable pour certains fauteuils roulants.","Une rampe installée correctement, mais qui impose un long détour par l’arrière de l’immeuble.","Une rampe bien dimensionnée, mais qui bloque partiellement l’ouverture de quelques portes d’entrée.","Une rampe suffisamment large, mais tellement pentue que les usagers n’osent pas l’emprunter seuls."],"correct":"A","explanation":"Réponse A : L’architecte donne précisément l’exemple d’une rampe trop étroite, conforme aux plans (donc respectant les normes), mais qui reste inutilisable pour certains fauteuils roulants. C’est l’exemple exact demandé par la question. B : Quelqu’un pourrait croire que le détour imposé par l’arrière de l’immeuble est un exemple d’inadaptation, car l’architecte évoque la diversité des usages et des accès, mais il ne parle jamais d’un détour ou d’une rampe installée à l’arrière. C : L’architecte mentionne que les portes diffèrent, ce qui pourrait faire penser à un problème d’ouverture de porte, mais il ne dit jamais qu’une rampe bloque l’ouverture des portes. Il parle seulement de largeur insuffisante pour certains fauteuils. D : L’architecte évoque les différences de pente, ce qui pourrait laisser croire à un problème de pente trop forte, mais il ne donne pas cet exemple précis. Il insiste sur la largeur insuffisante, pas sur la pente.","transcript":"Question 26.\nVous travaillez sur l'accessibilité des immeubles anciens. Pourquoi ne pas poser partout le même modèle de rampe ?\nParce que les bâtiments n'ont pas les mêmes pentes, les mêmes portes ni les mêmes usages. Une rampe trop étroite peut être techniquement conforme à un plan et pourtant inutilisable avec certains fauteuils. Nous préférons observer les déplacements réels, mesurer les contraintes et tester plusieurs solutions avec les résidents concernés. L'objectif est de rendre l'accès réellement possible, pas simplement d'afficher un équipement neuf.\nSelon l’architecte, quel exemple précis montre qu’une rampe posée sans adaptation peut rester inutilisable malgré le respect des normes ?","segments":[{"voice":"female","text":"Question 26."},{"voice":"female","text":"Vous travaillez sur l'accessibilité des immeubles anciens. Pourquoi ne pas poser partout le même modèle de rampe ?"},{"voice":"male","text":"Parce que les bâtiments n'ont pas les mêmes pentes, les mêmes portes ni les mêmes usages. Une rampe trop étroite peut être techniquement conforme à un plan et pourtant inutilisable avec certains fauteuils. Nous préférons observer les déplacements réels, mesurer les contraintes et tester plusieurs solutions avec les résidents concernés. L'objectif est de rendre l'accès réellement possible, pas simplement d'afficher un équipement neuf."},{"voice":"female","text":"Selon l’architecte, quel exemple précis montre qu’une rampe posée sans adaptation peut rester inutilisable malgré le respect des normes ?"}],"audio":"q-26.mp3","audioSeconds":42.71,"slotSeconds":65},{"number":27,"kind":"dialogue","question":"Quelle organisation précise du local est finalement retenue ?","options":["Tracer deux zones, envoyer au sous-sol le matériel peu utilisé et garantir des passages larges pour les poussettes.","Laisser les objets rarement utilisés près de l'entrée et réduire un peu la largeur des passages pour gagner de la place.","Tracer deux zones sans rien déplacer au sous-sol, en comptant seulement sur un meilleur rangement.","Envoyer toutes les poussettes au sous-sol pour dégager une grande zone réservée aux vélos."],"correct":"A","explanation":"Réponse A : La solution retenue combine le traçage de deux zones, le déplacement du matériel peu utilisé au sous-sol, et la garantie de passages larges pour les poussettes, comme discuté explicitement dans l'échange. B : Cette option propose de réduire la largeur des passages, ce qui contredit la consigne claire de garantir des passages larges pour les poussettes. Quelqu'un pourrait mal comprendre et penser que gagner de la place implique rétrécir les passages, mais ce n'est pas ce qui est retenu. C : Cette option omet le déplacement des objets rarement utilisés au sous-sol, alors que c'est explicitement mentionné comme partie de la solution. On pourrait croire que seul un meilleur rangement suffit, mais le déplacement est bien prévu. D : Cette option propose d'envoyer toutes les poussettes au sous-sol, alors que le texte insiste sur la nécessité de garder des passages larges pour elles dans le local. Quelqu'un pourrait croire qu'il faut tout dégager pour les vélos, mais ce n'est pas ce qui est décidé.","transcript":"Question 27.\nLe local à vélos est devenu trop encombré. Plusieurs poussettes y sont aussi rangées.\nLes familles n'ont pas d'autre espace près de l'entrée.\nNous pourrions tracer deux zones et déplacer les objets rarement utilisés vers le rangement du sous-sol.\nD'accord, mais assurons-nous que les passages restent assez larges pour les poussettes.\nJe préparerai un plan et le soumettrai au conseil.\nQuelle organisation précise du local est finalement retenue ?","segments":[{"voice":"female","text":"Question 27."},{"voice":"male","text":"Le local à vélos est devenu trop encombré. Plusieurs poussettes y sont aussi rangées."},{"voice":"female","text":"Les familles n'ont pas d'autre espace près de l'entrée."},{"voice":"male","text":"Nous pourrions tracer deux zones et déplacer les objets rarement utilisés vers le rangement du sous-sol."},{"voice":"female","text":"D'accord, mais assurons-nous que les passages restent assez larges pour les poussettes."},{"voice":"male","text":"Je préparerai un plan et le soumettrai au conseil."},{"voice":"female","text":"Quelle organisation précise du local est finalement retenue ?"}],"audio":"q-27.mp3","audioSeconds":31.216,"slotSeconds":58},{"number":28,"kind":"interview","question":"Pour quelle raison précise l'experte estime-t-elle que la participation ressemble surtout à une opération de communication ?","options":["Parce que la mairie a demandé aux habitants de valider l’ensemble du chantier sans préciser quelles parties du projet restaient négociables.","Parce que la consultation a été organisée une fois les décisions principales arrêtées, en ne laissant aux habitants que des choix de détail.","Parce que la consultation a été lancée avant même que les grandes orientations du projet ne soient définies, ce qui la rendait trop abstraite.","Parce que les habitants pouvaient discuter des accès provisoires et des horaires de chantier, mais pas des aspects esthétiques comme les couleurs."],"correct":"B","explanation":"Réponse B : C'est exactement ce que dit l'experte : la consultation a été organisée après les décisions principales, ne laissant que des choix de détail aux habitants. C'est la raison précise pour laquelle elle estime que la participation ressemble à une opération de communication. A : Quelqu'un pourrait penser que l'absence de précision sur les parties négociables est le problème, car l'experte recommande de préciser quelles décisions restent ouvertes. Cependant, la raison principale donnée est le moment de la consultation, pas le manque de précision. C : On pourrait croire que la consultation a été lancée trop tôt, mais le texte dit le contraire : elle a été organisée trop tard, après les décisions principales. D : Quelqu'un pourrait se tromper en pensant que seuls les aspects esthétiques étaient ouverts à la discussion, mais l'experte critique surtout le fait que les décisions principales étaient déjà prises, pas spécifiquement le type de choix laissé.","transcript":"Question 28.\nLes plans de rénovation ont été présentés aux résidents avant les travaux. N'est-ce pas suffisant ?\nLa consultation a eu lieu une fois les décisions principales prises. Les habitants pouvaient choisir une couleur de peinture, mais pas discuter de l'emplacement des accès provisoires ou des horaires de chantier. C'est précisément là qu'ils avaient des informations utiles. Nous recommandons d'organiser les échanges plus tôt et de préciser quelles décisions restent ouvertes. Sinon, la participation ressemble davantage à une opération de communication qu'à une influence réelle.\nPour quelle raison précise l'experte estime-t-elle que la participation ressemble surtout à une opération de communication ?","segments":[{"voice":"female","text":"Question 28."},{"voice":"male","text":"Les plans de rénovation ont été présentés aux résidents avant les travaux. N'est-ce pas suffisant ?"},{"voice":"female","text":"La consultation a eu lieu une fois les décisions principales prises. Les habitants pouvaient choisir une couleur de peinture, mais pas discuter de l'emplacement des accès provisoires ou des horaires de chantier. C'est précisément là qu'ils avaient des informations utiles. Nous recommandons d'organiser les échanges plus tôt et de préciser quelles décisions restent ouvertes. Sinon, la participation ressemble davantage à une opération de communication qu'à une influence réelle."},{"voice":"female","text":"Pour quelle raison précise l'experte estime-t-elle que la participation ressemble surtout à une opération de communication ?"}],"audio":"q-28.mp3","audioSeconds":42.162,"slotSeconds":66},{"number":29,"kind":"debate","question":"Sur quel point les intervenants affirment-ils explicitement être d’accord ?","options":["Sur l’idée que l’encadrement des loyers aura inévitablement des effets immédiats négatifs.","Sur la nécessité d’augmenter la construction de logements abordables.","Sur le fait qu’il faut surtout renforcer les aides à la rénovation plutôt que construire davantage.","Sur le principe d’étendre le plafonnement des loyers à l’ensemble du territoire."],"correct":"B","explanation":"Réponse B : Les intervenants affirment explicitement être d'accord sur la nécessité d'augmenter la construction de logements abordables. A : Quelqu'un pourrait croire que les intervenants sont d'accord sur les effets négatifs immédiats de l'encadrement, car ils évoquent des risques (réduction de l'offre), mais la phrase citée indique explicitement qu'ils ne sont pas d'accord sur ce point. C : La combinaison des aides à la rénovation et de la construction est proposée, mais il n'est jamais dit qu'il faut surtout privilégier la rénovation au détriment de la construction. Quelqu'un pourrait mal interpréter la proposition de combinaison comme une préférence exclusive. D : La discussion porte sur l'encadrement dans certains quartiers, et il n'est jamais question d'étendre le plafonnement à l'ensemble du territoire. Quelqu'un pourrait généraliser à tort la question locale à une portée nationale.","transcript":"Question 29.\nFaut-il encadrer davantage les loyers dans les quartiers où les prix augmentent ?\nUne limitation peut protéger les locataires actuels contre des hausses soudaines.\nMais si les propriétaires renoncent à mettre des logements sur le marché, nous risquons de réduire l'offre disponible.\nC'est pourquoi je propose de combiner l'encadrement avec des aides à la rénovation et une production de logements abordables.\nNous sommes d'accord sur le besoin de construire. Nous divergeons surtout sur les conséquences immédiates du plafond de loyer.\nSur quel point les intervenants affirment-ils explicitement être d’accord ?","segments":[{"voice":"female","text":"Question 29.","speaker":"female"},{"voice":"female","text":"Faut-il encadrer davantage les loyers dans les quartiers où les prix augmentent ?","speaker":"female"},{"voice":"male","text":"Une limitation peut protéger les locataires actuels contre des hausses soudaines.","speaker":"male"},{"voice":"female","text":"Mais si les propriétaires renoncent à mettre des logements sur le marché, nous risquons de réduire l'offre disponible.","speaker":"female_alt"},{"voice":"male","text":"C'est pourquoi je propose de combiner l'encadrement avec des aides à la rénovation et une production de logements abordables.","speaker":"male"},{"voice":"female","text":"Nous sommes d'accord sur le besoin de construire. Nous divergeons surtout sur les conséquences immédiates du plafond de loyer.","speaker":"female_alt"},{"voice":"female","text":"Sur quel point les intervenants affirment-ils explicitement être d’accord ?","speaker":"female"}],"audio":"q-29.mp3","audioSeconds":36.65,"slotSeconds":64},{"number":30,"kind":"interview","question":"Selon l’architecte, à quelle condition la transformation de l’usine en logements peut-elle encore relever de la conservation du patrimoine ?","options":["Si l’on conserve les éléments qui rendent son ancien usage compréhensible et que l’on documente les transformations.","Si toutes les traces de l’activité passée sont conservées, même au détriment du confort.","Si l’usine reste vide mais intacte, sans nouveaux usages ni habitants.","Si l’on ne garde que l’enveloppe extérieure du bâtiment tout en restructurant entièrement l’intérieur."],"correct":"A","explanation":"Réponse A : L’architecte insiste sur la nécessité de conserver les éléments qui rendent l’ancien usage compréhensible et de documenter les transformations. C’est la condition pour que la transformation soit considérée comme relevant de la conservation du patrimoine. B : Quelqu’un pourrait croire qu’il faut tout conserver, mais l’architecte précise qu’il faut aussi installer des logements confortables. Donc, conserver toutes les traces au détriment du confort n’est pas la condition retenue. C : Certains pourraient penser que garder l’usine vide et intacte est une forme de conservation, mais l’architecte dit explicitement que cela ne garantit pas la survie du bâtiment. D : On pourrait croire que garder seulement l’enveloppe suffit, mais l’architecte insiste sur la conservation d’éléments permettant de comprendre l’ancien usage, ce qui va au-delà de la simple enveloppe extérieure.","transcript":"Question 30.\nL'ancienne usine de briques va devenir des logements. Peut-on parler de conservation du patrimoine ?\nOui, si nous rendons lisible son histoire. La grande charpente et certaines traces de machines méritent d'être conservées. Mais nous devons aussi installer des logements confortables, accessibles et peu énergivores. Garder le bâtiment vide ne garantit pas sa survie. Le plus important est de documenter les transformations et de ne pas effacer les éléments qui permettent de comprendre son ancien usage.\nSelon l’architecte, à quelle condition la transformation de l’usine en logements peut-elle encore relever de la conservation du patrimoine ?","segments":[{"voice":"female","text":"Question 30."},{"voice":"male","text":"L'ancienne usine de briques va devenir des logements. Peut-on parler de conservation du patrimoine ?"},{"voice":"female","text":"Oui, si nous rendons lisible son histoire. La grande charpente et certaines traces de machines méritent d'être conservées. Mais nous devons aussi installer des logements confortables, accessibles et peu énergivores. Garder le bâtiment vide ne garantit pas sa survie. Le plus important est de documenter les transformations et de ne pas effacer les éléments qui permettent de comprendre son ancien usage."},{"voice":"female","text":"Selon l’architecte, à quelle condition la transformation de l’usine en logements peut-elle encore relever de la conservation du patrimoine ?"}],"audio":"q-30.mp3","audioSeconds":41.953,"slotSeconds":69},{"number":31,"kind":"academic-monologue","question":"Comment, selon la conférencière, faut-il s’y prendre pour évaluer les économies de chauffage après des travaux d’isolation ?","options":["Comparer la consommation réelle observée après les travaux à la réduction théorique annoncée au moment du devis.","Comparer la facture de chauffage de l’hiver juste avant les travaux à celle du premier hiver suivant, en supposant que les usages n’ont pas changé.","Comparer la consommation du logement rénové à celle de logements voisins qui n’ont pas été isolés pendant la même période.","Comparer des périodes où les températures extérieures sont proches en corrigeant les résultats pour les changements de comportement des habitants."],"correct":"D","explanation":"Réponse D : C’est exactement ce que recommande la conférencière : comparer des périodes où les températures sont proches et corriger pour les changements de comportement des habitants. A : La conférencière précise qu'il ne faut pas confondre la réduction théorique annoncée avant les travaux avec la consommation réelle observée après. Cette option propose justement cette comparaison, ce qui est explicitement déconseillé. B : Comparer la facture de l’hiver avant et après les travaux sans corriger pour les changements de comportement ou de température extérieure ne suffit pas, car la conférencière insiste sur la nécessité de prendre en compte ces facteurs. C : La conférencière ne mentionne pas la comparaison avec des logements voisins, mais insiste sur la comparaison dans le même logement et la correction pour comportement et température. Quelqu’un pourrait croire que comparer à des voisins est pertinent, mais ce n’est pas ce qui est recommandé.","transcript":"Question 31.\nAprès des travaux d'isolation, les consommations de chauffage peuvent diminuer moins que prévu. Cela ne signifie pas nécessairement que les matériaux sont inefficaces. Certains habitants choisissent de chauffer davantage des pièces auparavant trop froides. D'autres rencontrent des problèmes de réglage ou d'aération. Pour mesurer les économies, il faut comparer des périodes aux températures comparables et tenir compte de ces modifications de comportement. Une réduction théorique calculée avant les travaux ne doit pas être confondue avec la consommation réellement observée ensuite.\nComment, selon la conférencière, faut-il s’y prendre pour évaluer les économies de chauffage après des travaux d’isolation ?","segments":[{"voice":"female","text":"Question 31."},{"voice":"female","text":"Après des travaux d'isolation, les consommations de chauffage peuvent diminuer moins que prévu. Cela ne signifie pas nécessairement que les matériaux sont inefficaces. Certains habitants choisissent de chauffer davantage des pièces auparavant trop froides. D'autres rencontrent des problèmes de réglage ou d'aération. Pour mesurer les économies, il faut comparer des périodes aux températures comparables et tenir compte de ces modifications de comportement. Une réduction théorique calculée avant les travaux ne doit pas être confondue avec la consommation réellement observée ensuite."},{"voice":"female","text":"Comment, selon la conférencière, faut-il s’y prendre pour évaluer les économies de chauffage après des travaux d’isolation ?"}],"audio":"q-31.mp3","audioSeconds":40.568,"slotSeconds":72},{"number":32,"kind":"interview","question":"Comment, selon le responsable, faut-il présenter aux occupants les prévisions de consommation après la rénovation ?","options":["Communiquer la valeur moyenne prévue en précisant qu’elle est garantie si rien ne change.","Montrer différents scénarios possibles sans évoquer les raisons de leurs écarts.","Présenter une fourchette de consommation et expliciter les sources d’incertitude.","Annoncer une valeur unique assortie d’une marge de sécurité plutôt qu’une fourchette."],"correct":"C","explanation":"Réponse C : C’est exactement ce que recommande le responsable : présenter une fourchette et expliciter les sources d’incertitude. A : Quelqu’un pourrait croire qu’il faut donner une valeur moyenne garantie, car on parle de prévisions, mais le texte dit explicitement que ce serait trompeur. B : On pourrait penser qu’il suffit de montrer des scénarios, mais le responsable insiste sur l’importance d’expliquer les écarts, ce que cette option omet. D : Quelqu’un pourrait penser qu’une valeur unique avec une marge de sécurité suffit, mais le responsable rejette explicitement cette approche.","transcript":"Question 32.\nVotre équipe prévoit la demande d'énergie d'un immeuble après rénovation. Les chiffres sont-ils suffisamment précis pour fixer toutes les charges futures ?\nNon. Ils servent à explorer des scénarios, car le nombre d'occupants, leurs habitudes et le climat peuvent changer. Nous confrontons chaque trimestre les prévisions aux factures réelles et ajustons les hypothèses. Communiquer une seule valeur comme si elle était garantie serait trompeur. Il vaut mieux présenter une fourchette et expliquer pourquoi le résultat pourrait s'écarter du modèle.\nComment, selon le responsable, faut-il présenter aux occupants les prévisions de consommation après la rénovation ?","segments":[{"voice":"female","text":"Question 32."},{"voice":"male","text":"Votre équipe prévoit la demande d'énergie d'un immeuble après rénovation. Les chiffres sont-ils suffisamment précis pour fixer toutes les charges futures ?"},{"voice":"female","text":"Non. Ils servent à explorer des scénarios, car le nombre d'occupants, leurs habitudes et le climat peuvent changer. Nous confrontons chaque trimestre les prévisions aux factures réelles et ajustons les hypothèses. Communiquer une seule valeur comme si elle était garantie serait trompeur. Il vaut mieux présenter une fourchette et expliquer pourquoi le résultat pourrait s'écarter du modèle."},{"voice":"female","text":"Comment, selon le responsable, faut-il présenter aux occupants les prévisions de consommation après la rénovation ?"}],"audio":"q-32.mp3","audioSeconds":40.098,"slotSeconds":71},{"number":33,"kind":"commentary","question":"Quelle réserve la chroniqueuse émet-elle principalement sur l’annonce d’une baisse du loyer médian ?","options":["Elle souligne que cet indicateur ne renseigne pas sur le nombre de familles qui parviennent à trouver un logement adapté à leurs revenus.","Elle souligne que cet indicateur ne permet pas de comparer correctement les écarts de loyers entre les différents quartiers.","Elle souligne que cet indicateur ne prend pas en considération le niveau réel des charges que les locataires doivent payer en plus du loyer.","Elle souligne que cet indicateur ne tient pas compte de la taille exacte des logements proposés sur le marché."],"correct":"A","explanation":"Réponse A : La chroniqueuse insiste principalement sur le fait que la baisse du loyer médian ne renseigne pas sur le nombre de familles qui parviennent à accéder à un logement adapté à leurs revenus. Elle précise que la médiane ne remplace pas l’analyse des ménages exclus du marché, ce qui correspond exactement à cette option. B : La chroniqueuse mentionne que les prix évoluent différemment selon les quartiers, mais elle ne dit pas que l’indicateur ne permet pas de comparer correctement les écarts de loyers entre quartiers. Quelqu’un pourrait croire que la mention des quartiers implique une critique de la comparabilité, mais ce n’est pas la réserve principale formulée. C : Elle évoque la nécessité de regarder aussi les charges, mais ce n’est pas la réserve principale : elle insiste surtout sur l’accès des familles à un logement adapté. Quelqu’un pourrait se tromper en se focalisant sur la mention des charges, mais ce n’est pas le cœur de sa critique. D : La taille des logements est évoquée comme un autre facteur à considérer, mais la réserve principale porte sur l’accès des familles à un logement adapté à leurs revenus. On pourrait confondre la mention de la taille comme réserve principale, mais ce n’est pas le cas.","transcript":"Question 33.\nOn nous annonce que le loyer médian a légèrement baissé cette année. C'est une information importante, mais elle ne dit pas combien de familles trouvent effectivement un logement adapté à leurs revenus. Il faut aussi regarder les charges, la taille des logements disponibles et les quartiers où les prix évoluent autrement. Une médiane résume une distribution; elle ne peut remplacer l'analyse des ménages qui restent exclus du marché. Un prix moins élevé ne signifie pas toujours un accès plus facile.\nQuelle réserve la chroniqueuse émet-elle principalement sur l’annonce d’une baisse du loyer médian ?","segments":[{"voice":"female","text":"Question 33."},{"voice":"female","text":"On nous annonce que le loyer médian a légèrement baissé cette année. C'est une information importante, mais elle ne dit pas combien de familles trouvent effectivement un logement adapté à leurs revenus. Il faut aussi regarder les charges, la taille des logements disponibles et les quartiers où les prix évoluent autrement. Une médiane résume une distribution; elle ne peut remplacer l'analyse des ménages qui restent exclus du marché. Un prix moins élevé ne signifie pas toujours un accès plus facile."},{"voice":"female","text":"Quelle réserve la chroniqueuse émet-elle principalement sur l’annonce d’une baisse du loyer médian ?"}],"audio":"q-33.mp3","audioSeconds":35.265,"slotSeconds":66},{"number":34,"kind":"roundtable","question":"Quel dispositif concret de suivi des demandes les intervenants envisagent-ils ?","options":["Répartir les demandes par type de panne et afficher la liste des interventions à venir dans le hall de l’immeuble.","Attribuer un numéro à chaque demande et donner une réponse sur les délais prévus grâce à un suivi en ligne.","Confier aux gardiens un cahier où ils notent les demandes et barrent celles qui ont été traitées.","Envoyer au début de chaque mois un calendrier détaillé des passages des techniciens à tous les résidents."],"correct":"B","explanation":"Réponse B : C’est exactement ce que proposent les intervenants : attribuer un numéro à chaque demande et donner une réponse sur les délais grâce à un suivi (en ligne ou par téléphone pour ceux qui n’utilisent pas Internet). A : Quelqu’un pourrait croire que la répartition par type de panne et l’affichage dans le hall aideraient à la gestion, mais le texte ne mentionne ni affichage ni répartition par type. Il s’agit d’un dispositif non évoqué dans l’enregistrement. C : Le texte mentionne un suivi par téléphone pour certains, mais pas un cahier tenu par les gardiens. Quelqu’un pourrait confondre le suivi manuel (cahier) avec la solution téléphonique, mais ce n’est pas ce qui est proposé. D : Le problème du manque d’information sur les délais est évoqué, mais il n’est jamais question d’un calendrier mensuel envoyé à tous les résidents. Quelqu’un pourrait croire qu’un calendrier détaillé répondrait au besoin d’information, mais ce n’est pas la solution proposée.","transcript":"Question 34.\nNous parlons de l'entretien des immeubles collectifs.\nLes locataires signalent les pannes, mais ne savent pas toujours quand une intervention aura lieu.\nLes gestionnaires reçoivent de nombreuses demandes sans description précise, ce qui complique les priorités.\nNous pourrions instaurer un suivi des demandes avec un numéro et une réponse sur les délais prévus.\nEt conserver un téléphone pour les résidents qui n'utilisent pas Internet.\nOui, à condition que les urgences restent traitées immédiatement.\nQuel dispositif concret de suivi des demandes les intervenants envisagent-ils ?","segments":[{"voice":"female","text":"Question 34.","speaker":"female"},{"voice":"female","text":"Nous parlons de l'entretien des immeubles collectifs.","speaker":"female"},{"voice":"male","text":"Les locataires signalent les pannes, mais ne savent pas toujours quand une intervention aura lieu.","speaker":"male"},{"voice":"female","text":"Les gestionnaires reçoivent de nombreuses demandes sans description précise, ce qui complique les priorités.","speaker":"female_alt"},{"voice":"male","text":"Nous pourrions instaurer un suivi des demandes avec un numéro et une réponse sur les délais prévus.","speaker":"male"},{"voice":"female","text":"Et conserver un téléphone pour les résidents qui n'utilisent pas Internet.","speaker":"female_alt"},{"voice":"male","text":"Oui, à condition que les urgences restent traitées immédiatement.","speaker":"male"},{"voice":"female","text":"Quel dispositif concret de suivi des demandes les intervenants envisagent-ils ?","speaker":"female"}],"audio":"q-34.mp3","audioSeconds":36.31,"slotSeconds":71},{"number":35,"kind":"interview","question":"Dans un immeuble partagé, quelle erreur de fonctionnement le spécialiste redoute-t-il avec ces thermostats ?","options":["Augmenter la chaleur dans un logement vide pour compenser les absences prolongées.","Abaisser le chauffage dès qu’aucun mouvement n’est détecté dans les parties communes.","Maintenir en permanence une température basse dans les logements rarement occupés.","Réduire la température alors qu’une personne vulnérable se trouve encore dans l’appartement."],"correct":"D","explanation":"Réponse D : Le spécialiste redoute explicitement que le système réduise la température alors qu’une personne vulnérable se trouve encore dans l’appartement, ce qui peut créer un inconfort. A : Quelqu’un pourrait croire que le spécialiste craint une surchauffe pour compenser les absences, mais le texte ne mentionne pas l’augmentation de la chaleur dans un logement vide. Il s’inquiète plutôt d’une baisse inappropriée de la température. B : On pourrait penser que le problème concerne les parties communes, mais le spécialiste parle des logements individuels et des personnes vulnérables, pas des espaces communs. C : Il est tentant de croire que maintenir une température basse dans des logements rarement occupés est le problème, mais le spécialiste s’inquiète d’un abaissement de température alors qu’une personne fragile est présente, pas de la basse température en soi.","transcript":"Question 35.\nLes nouveaux thermostats adaptent le chauffage à la présence des occupants. N'est-ce pas une solution idéale ?\nPas toujours. Dans une maison, les habitudes sont relativement stables; dans un immeuble partagé, les horaires peuvent varier fortement. Si le système abaisse la température alors qu'une personne fragile est présente, il crée un inconfort. Il faut permettre aux occupants de comprendre les réglages, de les corriger et de signaler un problème. Une technologie performante ne dispense pas d'observer la vie quotidienne.\nDans un immeuble partagé, quelle erreur de fonctionnement le spécialiste redoute-t-il avec ces thermostats ?","segments":[{"voice":"female","text":"Question 35."},{"voice":"male","text":"Les nouveaux thermostats adaptent le chauffage à la présence des occupants. N'est-ce pas une solution idéale ?"},{"voice":"female","text":"Pas toujours. Dans une maison, les habitudes sont relativement stables; dans un immeuble partagé, les horaires peuvent varier fortement. Si le système abaisse la température alors qu'une personne fragile est présente, il crée un inconfort. Il faut permettre aux occupants de comprendre les réglages, de les corriger et de signaler un problème. Une technologie performante ne dispense pas d'observer la vie quotidienne."},{"voice":"female","text":"Dans un immeuble partagé, quelle erreur de fonctionnement le spécialiste redoute-t-il avec ces thermostats ?"}],"audio":"q-35.mp3","audioSeconds":39.497,"slotSeconds":69},{"number":36,"kind":"interview","question":"Quel risque particulier lié aux capteurs est mis en avant pour justifier la demande d'avis des habitants ?","options":["Qu’ils transmettent automatiquement les données aux assurances sans information préalable.","Qu’ils entraînent surtout des erreurs de facturation en cas de panne ou de coupure.","Qu’ils puissent enregistrer des images des occupants malgré l’absence déclarée de caméras.","Qu’ils permettent de déduire certaines habitudes de vie, comme les périodes d’absence."],"correct":"D","explanation":"Réponse D : Le texte explique clairement que le risque particulier est la possibilité de déduire des habitudes de vie, telles que les périodes d’absence, à partir des données techniques recueillies par les capteurs. A : Quelqu’un pourrait croire que la question de la transmission automatique aux assurances est évoquée, car on parle d’accès aux données, mais il n’est jamais question d’assurances ni de transmission automatique. Le risque mis en avant concerne la déduction d’habitudes de vie, pas la transmission à des tiers spécifiques. B : Il est possible de penser que des erreurs de facturation pourraient être un problème lié à la technique, mais le texte ne mentionne ni pannes ni erreurs de facturation. Le risque mis en avant est la révélation d’habitudes de vie, non des erreurs techniques. C : La question précise que les appareils ne filment pas, ce qui exclut l’enregistrement d’images. Quelqu’un pourrait mal comprendre et croire qu’il y a un risque d’image, mais le texte insiste sur l’absence de caméras.","transcript":"Question 36.\nVotre immeuble teste des capteurs de consommation. Pourquoi demandez-vous l'avis des habitants alors que les appareils ne filment personne ?\nDes données techniques peuvent révéler indirectement certaines habitudes, comme les périodes d'absence. Les résidents doivent savoir ce qui est mesuré, combien de temps les données seront conservées et qui pourra y accéder. Ils doivent aussi disposer d'un moyen de poser des questions et de contester un usage inapproprié. La transparence ne se résume pas à une phrase dans un contrat.\nQuel risque particulier lié aux capteurs est mis en avant pour justifier la demande d'avis des habitants ?","segments":[{"voice":"female","text":"Question 36."},{"voice":"male","text":"Votre immeuble teste des capteurs de consommation. Pourquoi demandez-vous l'avis des habitants alors que les appareils ne filment personne ?"},{"voice":"female","text":"Des données techniques peuvent révéler indirectement certaines habitudes, comme les périodes d'absence. Les résidents doivent savoir ce qui est mesuré, combien de temps les données seront conservées et qui pourra y accéder. Ils doivent aussi disposer d'un moyen de poser des questions et de contester un usage inapproprié. La transparence ne se résume pas à une phrase dans un contrat."},{"voice":"female","text":"Quel risque particulier lié aux capteurs est mis en avant pour justifier la demande d'avis des habitants ?"}],"audio":"q-36.mp3","audioSeconds":37.146,"slotSeconds":71},{"number":37,"kind":"interview","question":"Quel rôle précis l'enquêtrice attribue-t-elle aux témoignages par rapport aux mesures sonores ?","options":["Ils sont utilisés principalement pour illustrer de façon qualitative les résultats des mesures, sans modifier réellement l’analyse.","Ils permettent de corriger les relevés chiffrés en les remplaçant lorsque ceux-ci ne reflètent pas le ressenti des habitants.","Ils complètent les mesures pour comprendre pourquoi un même niveau de bruit ne se traduit pas par la même gêne chez tous les résidents.","Ils servent surtout à vérifier si les chiffres sont cohérents avec les plaintes et à écarter les situations jugées atypiques."],"correct":"C","explanation":"Réponse C : C’est la bonne réponse : l’enquêtrice explique que les témoignages servent à comprendre pourquoi un même niveau de bruit ne provoque pas la même gêne chez tous, en fonction de la façade, des horaires, etc. Les témoignages complètent donc les mesures pour expliquer la diversité des ressentis. A : Quelqu’un pourrait croire que les témoignages servent seulement à illustrer qualitativement les mesures, car l’enquêtrice insiste sur le maintien des données objectives. Cependant, elle précise que les témoignages servent à comprendre pourquoi un même niveau de bruit n’a pas le même effet selon les personnes, ce qui va au-delà d’une simple illustration. B : On pourrait penser que les témoignages remplacent les mesures si les chiffres ne reflètent pas le ressenti, mais l’enquêtrice dit explicitement qu’on ne renonce pas aux données objectives. Les témoignages ne servent donc pas à corriger ou remplacer les mesures. D : Quelqu’un pourrait croire que les témoignages servent à vérifier la cohérence des chiffres ou à écarter des cas atypiques, car l’enquêtrice parle de différences selon les situations. Mais elle ne mentionne pas l’exclusion de cas atypiques ni la vérification de cohérence ; elle insiste sur la compréhension des différences de ressenti.","transcript":"Question 37.\nCertains résidents disent que le chantier est supportable; d'autres parlent d'une gêne quotidienne. Comment expliquer cette différence ?\nLeurs appartements ne donnent pas tous sur la même façade et certaines personnes travaillent de nuit. Nous avons mesuré les niveaux sonores, mais nous devons aussi examiner la durée d'exposition et les horaires de repos. Le même bruit peut avoir des conséquences très différentes. Conserver les témoignages permet de comprendre cette répartition, sans renoncer aux données objectives des mesures.\nQuel rôle précis l'enquêtrice attribue-t-elle aux témoignages par rapport aux mesures sonores ?","segments":[{"voice":"female","text":"Question 37."},{"voice":"male","text":"Certains résidents disent que le chantier est supportable; d'autres parlent d'une gêne quotidienne. Comment expliquer cette différence ?"},{"voice":"female","text":"Leurs appartements ne donnent pas tous sur la même façade et certaines personnes travaillent de nuit. Nous avons mesuré les niveaux sonores, mais nous devons aussi examiner la durée d'exposition et les horaires de repos. Le même bruit peut avoir des conséquences très différentes. Conserver les témoignages permet de comprendre cette répartition, sans renoncer aux données objectives des mesures."},{"voice":"female","text":"Quel rôle précis l'enquêtrice attribue-t-elle aux témoignages par rapport aux mesures sonores ?"}],"audio":"q-37.mp3","audioSeconds":37.59,"slotSeconds":72},{"number":38,"kind":"public-lecture","question":"Quel exemple d'effet pervers de la densification est donné à l'échelle du quartier ?","options":["La densification qui étend les immeubles sur les terres agricoles en périphérie de la ville.","La densification qui remplace des cours plantées par des surfaces minérales, rendant les étés plus chauds.","La densification qui rallonge les trajets domicile-travail en éloignant logements et transports en commun.","La densification qui réduit le nombre de logements pour laisser plus de place aux espaces verts de quartier."],"correct":"B","explanation":"Réponse B : Le texte donne précisément cet exemple d'effet pervers à l'échelle du quartier : la substitution de surfaces végétalisées par des surfaces minérales, ce qui rend les quartiers plus chauds en été. A : Cette option décrit un effet positif de la densification (limiter l'étalement urbain sur les terres agricoles), et non un effet pervers à l'échelle du quartier. Quelqu'un pourrait confondre l'effet global évoqué en début de texte avec un effet local, mais le texte précise que le problème à l'échelle du quartier est ailleurs. C : Le texte évoque la nécessité de rapprocher logements et transports, mais ne parle pas d'un allongement des trajets comme effet pervers. Quelqu'un pourrait mal interpréter la phrase sur la réduction des distances parcourues, mais le texte ne mentionne pas ce problème. D : Le texte ne mentionne jamais une réduction du nombre de logements pour augmenter les espaces verts ; au contraire, il insiste sur la nécessité de concilier logements et espaces ombragés. Quelqu'un pourrait penser que privilégier les espaces verts réduit les logements, mais ce n'est pas présenté comme un effet pervers de la densification.","transcript":"Question 38.\nDensifier les villes peut limiter l'étalement des constructions sur les terres agricoles. Mais si cette densification remplace systématiquement les cours plantées par des surfaces minérales, les quartiers deviennent plus chauds et moins agréables en été. L'objectif de réduction des distances parcourues ne doit donc pas faire oublier la qualité de vie locale. Il faut associer logements, transports, espaces ombragés et gestion de l'eau. Une solution qui semble écologique à l'échelle de la région peut produire des effets négatifs à l'échelle de la rue si l'on néglige ses conditions d'application.\nQuel exemple d'effet pervers de la densification est donné à l'échelle du quartier ?","segments":[{"voice":"female","text":"Question 38."},{"voice":"female","text":"Densifier les villes peut limiter l'étalement des constructions sur les terres agricoles. Mais si cette densification remplace systématiquement les cours plantées par des surfaces minérales, les quartiers deviennent plus chauds et moins agréables en été. L'objectif de réduction des distances parcourues ne doit donc pas faire oublier la qualité de vie locale. Il faut associer logements, transports, espaces ombragés et gestion de l'eau. Une solution qui semble écologique à l'échelle de la région peut produire des effets négatifs à l'échelle de la rue si l'on néglige ses conditions d'application."},{"voice":"female","text":"Quel exemple d'effet pervers de la densification est donné à l'échelle du quartier ?"}],"audio":"q-38.mp3","audioSeconds":39.158,"slotSeconds":81},{"number":39,"kind":"interview","question":"Avant d'envisager un deuxième immeuble, qu’affirme-t-elle devoir être assuré ?","options":["Être capable d’entretenir les parties communes et de financer les grosses réparations du premier immeuble.","Disposer de nouvelles subventions équivalentes à celles du premier immeuble.","Répondre au maximum de demandes en remplissant déjà tous les logements disponibles.","Terminer la formation des nouveaux membres aux décisions collectives avant d’accepter d’autres candidatures."],"correct":"A","explanation":"Réponse A : La personne affirme explicitement qu'il faut d'abord s'assurer de la capacité à entretenir les parties communes et à financer les grosses réparations avant d'envisager un deuxième immeuble. C'est la condition principale mentionnée en premier dans l'extrait. B : Quelqu'un pourrait croire qu'il faut absolument obtenir de nouvelles subventions, car il est mentionné que les subventions du premier immeuble ne se répéteront pas nécessairement. Cependant, il n'est pas dit qu'il faut disposer de subventions équivalentes, mais plutôt qu'il faut vérifier la capacité à financer sans compter sur ces subventions. C : On pourrait penser que la priorité est de répondre à toutes les demandes et de remplir tous les logements, car la question commence par évoquer de nombreuses demandes. Cependant, la condition évoquée dans la réponse correcte concerne l'entretien et le financement, pas le taux d'occupation. D : Il est mentionné qu'il faut former les nouveaux membres, mais ce n'est pas présenté comme une condition préalable à l'ouverture d'un deuxième immeuble, seulement comme une nécessité générale. La condition principale reste la capacité d'entretien et de financement.","transcript":"Question 39.\nVotre coopérative de logements accueille de nombreuses demandes. Pourquoi ne pas ouvrir immédiatement un second bâtiment ?\nNous devons d'abord vérifier notre capacité à entretenir les parties communes et à financer les grosses réparations. Le premier immeuble a bénéficié de subventions de lancement qui ne se répéteront pas nécessairement. Il nous faut aussi former de nouveaux membres aux décisions collectives, car la participation ne s'improvise pas. Un nouveau bâtiment serait une bonne nouvelle seulement si les logements existants restent abordables et correctement entretenus.\nAvant d'envisager un deuxième immeuble, qu’affirme-t-elle devoir être assuré ?","segments":[{"voice":"female","text":"Question 39."},{"voice":"male","text":"Votre coopérative de logements accueille de nombreuses demandes. Pourquoi ne pas ouvrir immédiatement un second bâtiment ?"},{"voice":"female","text":"Nous devons d'abord vérifier notre capacité à entretenir les parties communes et à financer les grosses réparations. Le premier immeuble a bénéficié de subventions de lancement qui ne se répéteront pas nécessairement. Il nous faut aussi former de nouveaux membres aux décisions collectives, car la participation ne s'improvise pas. Un nouveau bâtiment serait une bonne nouvelle seulement si les logements existants restent abordables et correctement entretenus."},{"voice":"female","text":"Avant d'envisager un deuxième immeuble, qu’affirme-t-elle devoir être assuré ?"}],"audio":"q-39.mp3","audioSeconds":39.34,"slotSeconds":81}]},{"id":"tcf-listening-06","version":"tcf-listening-2026-11-test06-v4","title":"TCF Listening · Test 06","seconds":2100,"questions":[{"number":1,"kind":"image","question":"Quelle action voit-on ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"Réponse C : La personne tend la main vers le présentoir et touche un fruit, ce qui correspond à l’action de prendre un fruit sur le présentoir. A : On ne voit pas la personne remettre un fruit dans un panier ; il n’y a pas de panier visible et le geste va vers le présentoir, pas vers un panier. B : La personne ne pèse pas un sac de fruits ; il n’y a ni balance ni sac visible sur l’image. D : La personne ne paie pas les fruits au vendeur ; il n’y a pas d’échange d’argent ni de vendeur visible.","transcript":"Question 1.\nRegardez l’image et écoutez les propositions.\nA. La personne remet un fruit dans le panier. B. La personne pèse un sac de fruits. C. La personne prend un fruit sur le présentoir. D. La personne paie les fruits au vendeur.","segments":[{"voice":"female","text":"Question 1."},{"voice":"female","text":"Regardez l’image et écoutez les propositions."},{"voice":"female","text":"A. La personne remet un fruit dans le panier. B. La personne pèse un sac de fruits. C. La personne prend un fruit sur le présentoir. D. La personne paie les fruits au vendeur."}],"audio":"q-01.mp3","audioSeconds":17.842,"slotSeconds":33,"image":"q-01.svg"},{"number":2,"kind":"image","question":"Quelle action voit-on ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"Réponse B : L’image montre l’agriculteur qui semble manipuler un tuyau bleu posé entre les rangs de culture, ce qui correspond à l’ajustement d’un tuyau d’irrigation. A : On ne voit pas l’agriculteur couper des légumes ; il n’y a pas d’outil visible ni de geste de coupe. Quelqu’un pourrait croire à cette action car l’agriculteur est penché vers les planches de culture, mais aucun légume n’est manifestement coupé. C : L’agriculteur ne retire pas de mauvaises herbes ; il touche un tuyau. La confusion peut venir du fait qu’il se penche entre les rangs, geste similaire à l’arrachage, mais aucun végétal n’est retiré. D : Il n’enroule pas le tuyau, il le manipule à plat. Quelqu’un pourrait penser à cette action car il tient le tuyau, mais il n’y a aucun mouvement d’enroulement visible.","transcript":"Question 2.\nRegardez l’image et écoutez les propositions.\nA. L’agriculteur coupe des légumes sur les planches de culture. B. L’agriculteur ajuste un tuyau d’irrigation entre les rangs. C. L’agriculteur arrache les mauvaises herbes entre les rangs. D. L’agriculteur enroule un tuyau d’arrosage pour le ranger.","segments":[{"voice":"female","text":"Question 2."},{"voice":"female","text":"Regardez l’image et écoutez les propositions."},{"voice":"female","text":"A. L’agriculteur coupe des légumes sur les planches de culture. B. L’agriculteur ajuste un tuyau d’irrigation entre les rangs. C. L’agriculteur arrache les mauvaises herbes entre les rangs. D. L’agriculteur enroule un tuyau d’arrosage pour le ranger."}],"audio":"q-02.mp3","audioSeconds":20.114,"slotSeconds":33,"image":"q-02.svg"},{"number":3,"kind":"image","question":"Quelle action voit-on ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"Réponse C : L’image montre clairement du pain posé sur un objet affichant un poids, ce qui correspond à une balance. A : On ne voit aucun placard sur l’image et le pain est posé sur une boîte ou une balance, pas rangé dans un placard. B : Le pain n’est pas emballé dans un sachet, il est visible à l’air libre sur la boîte ou la balance. D : Le pain n’est pas découpé, il est entier et posé sur la boîte ou la balance.","transcript":"Question 3.\nRegardez l’image et écoutez les propositions.\nA. Le pain est rangé dans un placard. B. Du pain est emballé dans un sachet. C. Du pain est posé sur une balance. D. Le pain est découpé sur la table.","segments":[{"voice":"female","text":"Question 3."},{"voice":"female","text":"Regardez l’image et écoutez les propositions."},{"voice":"female","text":"A. Le pain est rangé dans un placard. B. Du pain est emballé dans un sachet. C. Du pain est posé sur une balance. D. Le pain est découpé sur la table."}],"audio":"q-03.mp3","audioSeconds":16.849,"slotSeconds":34,"image":"q-03.svg"},{"number":4,"kind":"image","question":"Quelle action voit-on ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"Réponse A : On voit une personne qui manipule des légumes posés sur un plan de travail avec des ustensiles, ce qui correspond à la préparation de légumes sur un plan de travail. B : On pourrait croire que les légumes sont cuits au four car ils sont dans un plat, mais il n'y a aucun signe de four ou de cuisson visible sur l'image. C : Quelqu’un pourrait penser que les légumes sont pesés car ils sont regroupés, mais il n’y a aucune balance visible sur l’image. D : On pourrait croire que les légumes sont lavés car ils sont manipulés, mais il n’y a ni robinet ni eau visible sur l’image.","transcript":"Question 4.\nRegardez l’image et écoutez les propositions.\nA. Des légumes sont préparés sur un plan de travail. B. Des légumes sont cuits au four dans un plat. C. Des légumes sont pesés sur une balance. D. Des légumes sont lavés sous le robinet.","segments":[{"voice":"female","text":"Question 4."},{"voice":"female","text":"Regardez l’image et écoutez les propositions."},{"voice":"female","text":"A. Des légumes sont préparés sur un plan de travail. B. Des légumes sont cuits au four dans un plat. C. Des légumes sont pesés sur une balance. D. Des légumes sont lavés sous le robinet."}],"audio":"q-04.mp3","audioSeconds":18.416,"slotSeconds":33,"image":"q-04.svg"},{"number":5,"kind":"response","question":"Quelle réponse convient ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"Réponse B : Cette réponse ('Oui, elles viennent bien d'ici.') répond directement à la question sur la provenance des tomates, confirmant qu'elles viennent de l'exploitation. A : Cette réponse parle de la durée de présence des tomates ('toute la semaine'), alors que la question porte sur leur provenance. Quelqu'un pourrait confondre la question sur l'origine avec une question sur la disponibilité, mais ce n'est pas ce qui est demandé. C : Cette réponse donne le prix des tomates ('deux euros cinquante'), ce qui pourrait être confondu si l'on croit que la question porte sur le prix, mais la question concerne leur origine. D : Cette réponse parle de la fréquence de livraison ('On les reçoit fraîches chaque matin'), ce qui pourrait être confondu avec une question sur la fraîcheur ou la livraison, mais la question porte sur la provenance.","transcript":"Question 5.\nCes tomates viennent-elles de votre exploitation ?\nA. Elles seront là toute la semaine. B. Oui, elles viennent bien d'ici. C. Elles sont à deux euros cinquante. D. On les reçoit fraîches chaque matin.","segments":[{"voice":"female","text":"Question 5."},{"voice":"female","text":"Ces tomates viennent-elles de votre exploitation ?"},{"voice":"male","text":"A. Elles seront là toute la semaine. B. Oui, elles viennent bien d'ici. C. Elles sont à deux euros cinquante. D. On les reçoit fraîches chaque matin."}],"audio":"q-05.mp3","audioSeconds":16.3,"slotSeconds":35},{"number":6,"kind":"response","question":"Quelle réponse convient ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"Réponse A : Cette réponse confirme la demande du client (« réserver un panier de légumes pour samedi ») en répétant le jour exact demandé. Elle répond directement et positivement à la requête. B : Cette réponse propose de venir sans réserver, ce qui contredit la demande explicite de réservation. Quelqu’un pourrait choisir cette option en pensant que la réservation n’est pas nécessaire, mais cela ne répond pas à la demande de réservation pour samedi. C : Cette réponse refuse la réservation pour les paniers de légumes, alors que la question porte précisément sur ce type de panier. Quelqu’un pourrait mal comprendre et croire que seules les réservations de fruits sont possibles, mais rien dans la question ne le suggère. D : Cette réponse propose de garder le panier pour dimanche matin, alors que la demande porte sur samedi. Une confusion sur le jour pourrait amener à choisir cette option, mais elle ne respecte pas la date demandée.","transcript":"Question 6.\nPuis-je réserver un panier de légumes pour samedi ?\nA. Oui, je vous le garde pour samedi. B. Venez plutôt sans réserver en semaine. C. Non, on réserve seulement les paniers de fruits. D. Oui, je vous le garde pour dimanche matin.","segments":[{"voice":"female","text":"Question 6."},{"voice":"male","text":"Puis-je réserver un panier de légumes pour samedi ?"},{"voice":"female","text":"A. Oui, je vous le garde pour samedi. B. Venez plutôt sans réserver en semaine. C. Non, on réserve seulement les paniers de fruits. D. Oui, je vous le garde pour dimanche matin."}],"audio":"q-06.mp3","audioSeconds":18.834,"slotSeconds":35},{"number":7,"kind":"response","question":"Quelle réponse convient ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"Réponse C : C’est la seule réponse qui donne une méthode concrète pour conserver des herbes fraîches, ce qui correspond exactement à la question posée. A : Cette réponse pourrait être choisie par quelqu’un qui pense qu’acheter des herbes sèches est une solution pour la conservation, mais la question porte sur la meilleure façon de conserver des herbes fraîches, pas sèches. La réponse ne concerne pas la conservation des herbes fraîches. B : Cette option pourrait attirer quelqu’un qui pense à l’utilisation des herbes, mais elle ne répond pas à la question de la conservation. Elle parle de leur usage en cuisine, pas de leur conservation. D : Quelqu’un pourrait croire que couper les tiges aide à conserver les herbes, mais sans autre indication (comme les mettre dans l’eau), cela ne répond pas à la question de la meilleure façon de les conserver.","transcript":"Question 7.\nVous connaissez la meilleure façon de conserver ces herbes fraîches ?\nA. Il vaut mieux les acheter sèches. B. Elles parfumeront très bien la soupe. C. Mettez-les dans un verre d’eau. D. Coupez toutes les tiges au ras.","segments":[{"voice":"female","text":"Question 7."},{"voice":"female","text":"Vous connaissez la meilleure façon de conserver ces herbes fraîches ?"},{"voice":"male","text":"A. Il vaut mieux les acheter sèches. B. Elles parfumeront très bien la soupe. C. Mettez-les dans un verre d’eau. D. Coupez toutes les tiges au ras."}],"audio":"q-07.mp3","audioSeconds":17.006,"slotSeconds":33},{"number":8,"kind":"response","question":"Quelle réponse convient ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"Réponse A : Cette réponse répond directement à la question posée (« Est-ce que la dégustation de ce soir est comprise dans le billet ? ») en précisant que la dégustation n’est pas comprise et qu’il faut la payer séparément. C’est une réponse claire et appropriée à la question. B : Quelqu’un pourrait choisir cette réponse s’il a mal compris la question et pense qu’on demande si la dégustation a lieu ce soir ou un autre jour. Cependant, la question porte sur l’inclusion dans le billet, pas sur la date. La réponse ne traite pas du tout de la question du billet. C : Cette réponse pourrait être tentante si l’on croit qu’il existe plusieurs types de billets et que certains incluent la dégustation. Cependant, rien dans la question ou le contexte ne mentionne un « pass journée » ou différents types de billets. La question demande simplement si la dégustation est comprise dans le billet, sans préciser de type. D : On pourrait choisir cette réponse en pensant que toutes les prestations sont incluses dans le billet, mais la réponse A précise explicitement que ce n’est pas le cas (« c’est à régler à part »). Cette option est donc contredite par la bonne réponse.","transcript":"Question 8.\nEst-ce que la dégustation de ce soir est comprise dans le billet ?\nA. Non, c’est à régler à part. B. Non, elle est reportée à demain. C. Oui, mais seulement avec le pass journée. D. Oui, elle est incluse dans tout billet.","segments":[{"voice":"female","text":"Question 8."},{"voice":"male","text":"Est-ce que la dégustation de ce soir est comprise dans le billet ?"},{"voice":"female","text":"A. Non, c’est à régler à part. B. Non, elle est reportée à demain. C. Oui, mais seulement avec le pass journée. D. Oui, elle est incluse dans tout billet."}],"audio":"q-08.mp3","audioSeconds":18.364,"slotSeconds":37},{"number":9,"kind":"announcement","question":"Samedi, à quelles heures la distribution des paniers sera-t-elle ouverte aux abonnés ?","options":["De dix heures à midi.","De neuf heures à onze heures.","De huit heures à dix heures.","De huit heures à midi."],"correct":"C","explanation":"Réponse C : C'est la seule option qui correspond exactement à l'horaire annoncé pour la distribution aux abonnés samedi, suite à l'avancement d'une heure à cause de la chaleur. A : Cette option propose un horaire de dix heures à midi, ce qui pourrait être confondu avec l'heure limite de conservation des paniers (« jusqu'à midi »), mais la distribution pour les abonnés est bien de huit à dix heures. B : Cette option propose neuf à onze heures, ce qui pourrait être une confusion avec l'horaire habituel si on ne tient pas compte du changement annoncé (« commencera une heure plus tôt que d'habitude »). D : Cette option propose une plage plus longue (de huit à midi), ce qui pourrait être confondu avec la période de conservation des paniers non retirés (« jusqu'à midi »), mais la distribution n'est ouverte que jusqu'à dix heures.","transcript":"Question 9.\nEn raison de la chaleur annoncée pour samedi, la distribution des paniers de légumes commencera une heure plus tôt que d'habitude. Les abonnés pourront récupérer leur commande de huit heures à dix heures au hangar du marché. Le lieu reste le même et les paniers non retirés seront conservés dans la chambre froide jusqu'à midi.\nSamedi, à quelles heures la distribution des paniers sera-t-elle ouverte aux abonnés ?","segments":[{"voice":"female","text":"Question 9."},{"voice":"female","text":"En raison de la chaleur annoncée pour samedi, la distribution des paniers de légumes commencera une heure plus tôt que d'habitude. Les abonnés pourront récupérer leur commande de huit heures à dix heures au hangar du marché. Le lieu reste le même et les paniers non retirés seront conservés dans la chambre froide jusqu'à midi."},{"voice":"female","text":"Samedi, à quelles heures la distribution des paniers sera-t-elle ouverte aux abonnés ?"}],"audio":"q-09.mp3","audioSeconds":23.824,"slotSeconds":37},{"number":10,"kind":"dialogue","question":"Pourquoi la restauratrice modifie-t-elle sa commande ?","options":["Parce que le producteur ne peut lui fournir que dix kilos de courgettes.","Parce qu’elle souhaite ajouter des aubergines au menu, indépendamment des courgettes.","Parce que le mauvais temps a fait monter le prix des courgettes.","Parce que la livraison initiale de courgettes est repoussée à l’après-midi."],"correct":"A","explanation":"Réponse A : La restauratrice modifie sa commande parce que le producteur ne peut lui fournir que dix kilos de courgettes, alors qu'elle en avait commandé quinze. Elle demande donc de compléter avec cinq kilos d'aubergines. B : Quelqu’un pourrait croire qu’elle souhaite ajouter des aubergines indépendamment des courgettes, car elle en commande. Mais elle ne les demande que pour compenser le manque de courgettes, pas par choix initial. C : On pourrait penser que le mauvais temps a fait monter le prix, car il a eu un impact, mais il n’est jamais question de prix dans l’extrait, seulement d’un retard de récolte. D : Quelqu’un pourrait croire que la livraison est repoussée à l’après-midi, mais il est clairement dit que la livraison aura lieu le matin.","transcript":"Question 10.\nBonjour, je vous ai commandé quinze kilos de courgettes pour demain.\nNous en avons seulement dix. Les dernières pluies ont retardé une partie de la récolte.\nDans ce cas, pouvez-vous compléter avec cinq kilos d'aubergines ? Je pourrai adapter le menu.\nOui, je vous livrerai les deux produits demain matin.\nTrès bien, je préviens la cuisine.\nPourquoi la restauratrice modifie-t-elle sa commande ?","segments":[{"voice":"female","text":"Question 10."},{"voice":"female","text":"Bonjour, je vous ai commandé quinze kilos de courgettes pour demain."},{"voice":"male","text":"Nous en avons seulement dix. Les dernières pluies ont retardé une partie de la récolte."},{"voice":"female","text":"Dans ce cas, pouvez-vous compléter avec cinq kilos d'aubergines ? Je pourrai adapter le menu."},{"voice":"male","text":"Oui, je vous livrerai les deux produits demain matin."},{"voice":"female","text":"Très bien, je préviens la cuisine."},{"voice":"female","text":"Pourquoi la restauratrice modifie-t-elle sa commande ?"}],"audio":"q-10.mp3","audioSeconds":26.723,"slotSeconds":43},{"number":11,"kind":"announcement","question":"Comment et jusqu'à quelle date faut-il s'inscrire à l'atelier ?","options":["Sur le site de l'association, avant jeudi.","En s'adressant à l'animateur, jusqu'à samedi.","Par téléphone à la médiathèque, au plus tard vendredi.","Sur le formulaire de la médiathèque, avant jeudi."],"correct":"D","explanation":"Réponse D : C'est la seule option qui correspond exactement à l'information donnée dans le texte : il faut s'inscrire sur le formulaire de la médiathèque, avant jeudi. A : Cette option indique de s'inscrire sur le site de l'association, alors que le texte précise que l'inscription se fait via le formulaire de la médiathèque. Quelqu'un pourrait confondre l'association organisatrice avec le lieu d'inscription, mais ce n'est pas ce qui est demandé. B : Cette option propose de s'adresser à l'animateur et jusqu'à samedi, alors que le texte précise que la réservation doit se faire avant jeudi et via un formulaire à la médiathèque. La confusion peut venir du fait que l'atelier a lieu samedi, mais la date limite d'inscription est jeudi. C : Cette option propose de s'inscrire par téléphone à la médiathèque jusqu'à vendredi, mais le texte indique que l'inscription se fait sur un formulaire (pas par téléphone) et avant jeudi (pas vendredi). Quelqu'un pourrait confondre le lieu (médiathèque) et supposer que le téléphone est une méthode possible, mais ce n'est pas mentionné.","transcript":"Question 11.\nL'association Saveurs du quartier propose samedi un atelier consacré aux plats de saison. Les participants doivent réserver leur place avant jeudi sur le formulaire disponible à la médiathèque. Les ingrédients seront fournis. Il n'est pas nécessaire d'apporter de matériel, mais un tablier personnel reste conseillé.\nComment et jusqu'à quelle date faut-il s'inscrire à l'atelier ?","segments":[{"voice":"female","text":"Question 11."},{"voice":"male","text":"L'association Saveurs du quartier propose samedi un atelier consacré aux plats de saison. Les participants doivent réserver leur place avant jeudi sur le formulaire disponible à la médiathèque. Les ingrédients seront fournis. Il n'est pas nécessaire d'apporter de matériel, mais un tablier personnel reste conseillé."},{"voice":"female","text":"Comment et jusqu'à quelle date faut-il s'inscrire à l'atelier ?"}],"audio":"q-11.mp3","audioSeconds":25.731,"slotSeconds":40},{"number":12,"kind":"dialogue","question":"Selon l’échange, à quelle condition le fournisseur accepte-t-il d’avancer la livraison à samedi soir ?","options":["Que le quai de déchargement reste libre samedi soir.","Que quelqu’un puisse les installer au frais le dimanche matin.","Que la chambre froide soit simplement ouverte avant l’arrivée du camion.","Que les fromages soient mis immédiatement dans la chambre froide."],"correct":"D","explanation":"Réponse D : Le fournisseur accepte d’avancer la livraison à la condition expresse que les fromages soient mis immédiatement au frais, ce qui est clairement énoncé dans l’échange. A : Cette phrase est mentionnée dans l'échange, mais ce n'est pas la condition posée par le fournisseur pour avancer la livraison. Le fait que le quai soit libre est une information contextuelle, pas une exigence. B : Il est question d'avoir quelqu'un pour ouvrir la chambre froide, mais la condition posée par le fournisseur est de mettre les fromages immédiatement au frais, pas simplement d'avoir quelqu'un le dimanche matin pour les installer. C : Le fait d'ouvrir la chambre froide avant l'arrivée du camion n'est pas suffisant selon le fournisseur. Il précise qu'il faut placer les fromages immédiatement au frais, ce qui va au-delà de simplement ouvrir la chambre froide.","transcript":"Question 12.\nNotre camion ne pourra pas accéder au marché pendant la course cycliste de dimanche.\nLe quai de déchargement sera encore libre samedi soir. Pouvez-vous avancer la livraison des fromages ?\nOui, vers dix-huit heures trente. Mais il faudra les placer immédiatement au frais.\nNous aurons une personne sur place pour ouvrir la chambre froide.\nSelon l’échange, à quelle condition le fournisseur accepte-t-il d’avancer la livraison à samedi soir ?","segments":[{"voice":"female","text":"Question 12."},{"voice":"male","text":"Notre camion ne pourra pas accéder au marché pendant la course cycliste de dimanche."},{"voice":"female","text":"Le quai de déchargement sera encore libre samedi soir. Pouvez-vous avancer la livraison des fromages ?"},{"voice":"male","text":"Oui, vers dix-huit heures trente. Mais il faudra les placer immédiatement au frais."},{"voice":"female","text":"Nous aurons une personne sur place pour ouvrir la chambre froide."},{"voice":"female","text":"Selon l’échange, à quelle condition le fournisseur accepte-t-il d’avancer la livraison à samedi soir ?"}],"audio":"q-12.mp3","audioSeconds":29.858,"slotSeconds":44},{"number":13,"kind":"announcement","question":"Quels étals ne sont pas inclus dans le contrôle annoncé ?","options":["Tous les étals équipés de réfrigération.","Uniquement les étals d'objets artisanaux.","Les étals de fruits secs et d'objets artisanaux.","Les étals de produits sensibles et de fruits secs."],"correct":"C","explanation":"Réponse C : La phrase indique explicitement que ces deux types d’étals ne sont pas inclus dans le contrôle. A : Quelqu’un pourrait croire que tous les étals équipés de réfrigération sont concernés, mais la phrase précise que certains étals ne le sont pas. B : On pourrait croire que seuls les étals d’objets artisanaux ne sont pas inclus, mais la phrase cite aussi les fruits secs. D : Quelqu’un pourrait confondre les produits sensibles avec les étals de fruits secs, mais la phrase distingue bien les deux.","transcript":"Question 13.\nLe marché couvert informe les commerçants qu'un contrôle de température sera réalisé mercredi matin sur les installations de réfrigération. Les produits sensibles doivent rester dans leur équipement habituel jusqu'au passage de l'agent. Les étals de fruits secs et d'objets artisanaux ne sont pas concernés.\nQuels étals ne sont pas inclus dans le contrôle annoncé ?","segments":[{"voice":"female","text":"Question 13."},{"voice":"female","text":"Le marché couvert informe les commerçants qu'un contrôle de température sera réalisé mercredi matin sur les installations de réfrigération. Les produits sensibles doivent rester dans leur équipement habituel jusqu'au passage de l'agent. Les étals de fruits secs et d'objets artisanaux ne sont pas concernés."},{"voice":"female","text":"Quels étals ne sont pas inclus dans le contrôle annoncé ?"}],"audio":"q-13.mp3","audioSeconds":22.779,"slotSeconds":39},{"number":14,"kind":"dialogue","question":"Quel plat a finalement été préparé à la place du gratin de pommes de terre ?","options":["Une soupe de patates douces, carottes et lentilles.","Une purée de patates douces servie en accompagnement.","Un gratin de patates douces avec des carottes.","Une salade tiède de lentilles et de carottes sans patates douces."],"correct":"A","explanation":"Réponse A : La personne explique clairement qu'ils ont préparé une soupe avec les patates douces, des carottes et des lentilles à la place du gratin de pommes de terre. C'est la seule option qui correspond exactement à la description donnée dans le stimulus. B : Quelqu'un pourrait croire qu'une purée a été faite car il s'agit aussi d'une préparation à base de patates douces, mais le texte précise qu'il s'agit d'une soupe, pas d'une purée. C : On pourrait penser qu'un gratin de patates douces a été préparé, car la livraison contenait des patates douces, mais il est clairement dit qu'ils ont fait une soupe, pas un gratin. D : Quelqu'un pourrait retenir la présence de lentilles et de carottes, mais la soupe contient aussi des patates douces, donc une salade sans patates douces ne correspond pas à la description.","transcript":"Question 14.\nJe pensais que vous serviez un gratin de pommes de terre aujourd'hui.\nC'était prévu, mais notre livraison est arrivée avec des patates douces à la place.\nVous avez changé la recette ?\nOui, nous en avons fait une soupe avec des carottes et des lentilles. Les allergies sont indiquées sur l'ardoise.\nD'accord, je vais essayer cette soupe.\nQuel plat a finalement été préparé à la place du gratin de pommes de terre ?","segments":[{"voice":"female","text":"Question 14."},{"voice":"male","text":"Je pensais que vous serviez un gratin de pommes de terre aujourd'hui."},{"voice":"female","text":"C'était prévu, mais notre livraison est arrivée avec des patates douces à la place."},{"voice":"male","text":"Vous avez changé la recette ?"},{"voice":"female","text":"Oui, nous en avons fait une soupe avec des carottes et des lentilles. Les allergies sont indiquées sur l'ardoise."},{"voice":"male","text":"D'accord, je vais essayer cette soupe."},{"voice":"female","text":"Quel plat a finalement été préparé à la place du gratin de pommes de terre ?"}],"audio":"q-14.mp3","audioSeconds":27.481,"slotSeconds":46},{"number":15,"kind":"radio-news","question":"Face à l’irrégularité des récoltes, quelle mesure la coopérative étudie-t-elle pour limiter les annulations de dernière minute ?","options":["Réduire le nombre de cantines desservies par la plateforme","Demander aux producteurs des prévisions de récolte plus strictes","Introduire des commandes plus souples pour les cantines","Modifier la fréquence des tournées de livraison des camions"],"correct":"C","explanation":"Réponse C : C’est exactement ce que dit le texte : la coopérative étudie l’introduction de commandes plus souples pour limiter les annulations de dernière minute. A : Quelqu’un pourrait penser que réduire le nombre de cantines desservies limiterait les annulations, car cela pourrait simplifier la gestion, mais le texte ne mentionne aucune réduction du nombre de cantines. Il est question d’adapter la souplesse des commandes, pas de réduire la clientèle. B : On pourrait croire que demander des prévisions plus strictes aux producteurs aiderait, car le problème vient de l’irrégularité des récoltes. Cependant, la mesure étudiée est d’introduire des commandes plus souples, pas de renforcer les prévisions. D : Quelqu’un pourrait croire que modifier la fréquence des tournées de livraison aiderait à gérer les annulations, car le texte mentionne la logistique des livraisons. Cependant, la mesure étudiée concerne la souplesse des commandes, pas la fréquence des livraisons.","transcript":"Question 15.\nUn groupement de producteurs du Lot a ouvert une plateforme commune pour livrer les cantines scolaires. Le système doit réduire les déplacements séparés de chaque ferme. Pourtant, plusieurs maraîchers soulignent que leurs récoltes ne sont pas toujours disponibles aux quantités et dates prévues. La coopérative envisage des commandes plus souples afin de limiter les annulations de dernière minute.\nFace à l’irrégularité des récoltes, quelle mesure la coopérative étudie-t-elle pour limiter les annulations de dernière minute ?","segments":[{"voice":"female","text":"Question 15."},{"voice":"female","text":"Un groupement de producteurs du Lot a ouvert une plateforme commune pour livrer les cantines scolaires. Le système doit réduire les déplacements séparés de chaque ferme. Pourtant, plusieurs maraîchers soulignent que leurs récoltes ne sont pas toujours disponibles aux quantités et dates prévues. La coopérative envisage des commandes plus souples afin de limiter les annulations de dernière minute."},{"voice":"female","text":"Face à l’irrégularité des récoltes, quelle mesure la coopérative étudie-t-elle pour limiter les annulations de dernière minute ?"}],"audio":"q-15.mp3","audioSeconds":31.269,"slotSeconds":49},{"number":16,"kind":"dialogue","question":"Quelle condition la responsable de la cantine pose-t-elle pour accepter la livraison le mercredi ?","options":["Que l’entretien de la cuisine soit terminé la veille.","Que le camion de livraison arrive avant huit heures.","Que le chef de cuisine soit déjà sur place à la réception.","Qu’une personne soit disponible pour signer le bordereau."],"correct":"B","explanation":"Réponse B : La responsable accepte la livraison mercredi uniquement à condition que le camion arrive avant huit heures, ce qui est dit explicitement dans le dialogue. A : Quelqu’un pourrait penser que l’entretien doit être terminé la veille car la cuisine est fermée mardi pour entretien, mais la responsable accepte la livraison mercredi sans exiger explicitement que l’entretien soit terminé la veille. La condition posée porte sur l’heure d’arrivée, pas sur la fin de l’entretien. C : Il est mentionné que le chef sera présent, mais ce n’est pas la condition posée pour accepter la livraison. La condition concerne l’heure d’arrivée, pas la présence du chef. D : La nécessité d’avoir quelqu’un pour signer le bordereau est mentionnée, mais ce n’est pas la condition pour accepter la livraison ; c’est une organisation interne. La condition posée est l’heure d’arrivée.","transcript":"Question 16.\nLe fournisseur de pommes me propose une livraison mardi, mais notre cuisine sera fermée pour entretien.\nNous pourrions venir mercredi matin, avant la préparation du déjeuner.\nMercredi, oui, à condition d'arriver avant huit heures.\nJe note sept heures trente. Il faudra quelqu'un pour signer le bordereau.\nLe chef sera présent.\nQuelle condition la responsable de la cantine pose-t-elle pour accepter la livraison le mercredi ?","segments":[{"voice":"female","text":"Question 16."},{"voice":"female","text":"Le fournisseur de pommes me propose une livraison mardi, mais notre cuisine sera fermée pour entretien."},{"voice":"male","text":"Nous pourrions venir mercredi matin, avant la préparation du déjeuner."},{"voice":"female","text":"Mercredi, oui, à condition d'arriver avant huit heures."},{"voice":"male","text":"Je note sept heures trente. Il faudra quelqu'un pour signer le bordereau."},{"voice":"female","text":"Le chef sera présent."},{"voice":"female","text":"Quelle condition la responsable de la cantine pose-t-elle pour accepter la livraison le mercredi ?"}],"audio":"q-16.mp3","audioSeconds":29.283,"slotSeconds":42},{"number":17,"kind":"announcement","question":"Que doivent préparer les commerçants avant l’arrivée des équipes de collecte ?","options":["Séparer les fruits et légumes encore consommables de ceux qui devront aller au compost.","Rassembler tous les invendus sans distinction pour que les bénévoles fassent le tri sur place.","Mettre de côté uniquement les produits abîmés pour qu’ils partent directement au compost.","Conserver les invendus encore frais pour les vendre le lendemain et ne présenter que les produits non conformes."],"correct":"A","explanation":"Réponse A : Le texte indique explicitement que les commerçants doivent séparer les fruits et légumes encore consommables de ceux qui devront aller au compost avant l’arrivée des équipes de collecte. B : Quelqu’un pourrait croire que les bénévoles font le tri sur place, mais le texte précise que le tri doit être fait par les commerçants avant l’arrivée des équipes. C : On pourrait penser que seuls les produits abîmés doivent être mis de côté, mais le texte demande de séparer les deux catégories, pas seulement de mettre de côté les abîmés. D : Quelqu’un pourrait croire qu’il faut garder les invendus frais pour les vendre le lendemain, mais le texte indique qu’ils doivent être séparés pour la collecte, pas conservés pour la vente.","transcript":"Question 17.\nLa collecte contre le gaspillage se tiendra jeudi à la fermeture du marché. Les bénévoles reprendront les fruits et légumes encore consommables qui n'ont pas trouvé preneur. Les produits abîmés ou non conformes à la consommation seront orientés vers la filière de compostage. Les commerçants doivent séparer les deux catégories avant l'arrivée des équipes.\nQue doivent préparer les commerçants avant l’arrivée des équipes de collecte ?","segments":[{"voice":"female","text":"Question 17."},{"voice":"male","text":"La collecte contre le gaspillage se tiendra jeudi à la fermeture du marché. Les bénévoles reprendront les fruits et légumes encore consommables qui n'ont pas trouvé preneur. Les produits abîmés ou non conformes à la consommation seront orientés vers la filière de compostage. Les commerçants doivent séparer les deux catégories avant l'arrivée des équipes."},{"voice":"female","text":"Que doivent préparer les commerçants avant l’arrivée des équipes de collecte ?"}],"audio":"q-17.mp3","audioSeconds":27.115,"slotSeconds":47},{"number":18,"kind":"telephone","question":"Quand le client souhaite-t-il être recontacté au sujet de son panier ?","options":["Uniquement s’il y a une nouvelle erreur","Après la vérification avec l’équipe de préparation","Dès réception du colis de remplacement","Avant la prochaine livraison"],"correct":"D","explanation":"Réponse D : Le client demande clairement d’être recontacté avant la prochaine livraison pour s’assurer que l’erreur ne se reproduira pas. A : Quelqu'un pourrait penser que le client souhaite être recontacté uniquement en cas de nouvelle erreur, car il mentionne vouloir s'assurer que l'erreur ne se reproduira pas. Cependant, il demande explicitement d'être rappelé avant la prochaine livraison, indépendamment d'une nouvelle erreur. B : La mention de la vérification avec l’équipe de préparation pourrait faire croire que le client souhaite être recontacté après cette étape. Pourtant, la demande précise est d’être rappelé avant la prochaine livraison. C : Le client parle du colis de remplacement, ce qui pourrait laisser penser qu’il souhaite être recontacté dès sa réception. Cependant, il demande explicitement d’être rappelé avant la prochaine livraison, pas à la réception du colis.","transcript":"Question 18.\nBonjour, j'ai reçu un panier qui contenait des produits laitiers, alors que mon abonnement indique une formule sans lait.\nJe vois bien votre choix dans le dossier. Je vais prévenir l'équipe de préparation et vérifier le colis de remplacement.\nPouvez-vous me rappeler avant la prochaine livraison ? Je veux m'assurer que l'erreur ne se reproduira pas.\nBien sûr, notre responsable vous contactera aujourd'hui.\nQuand le client souhaite-t-il être recontacté au sujet de son panier ?","segments":[{"voice":"female","text":"Question 18."},{"voice":"male","text":"Bonjour, j'ai reçu un panier qui contenait des produits laitiers, alors que mon abonnement indique une formule sans lait."},{"voice":"female","text":"Je vois bien votre choix dans le dossier. Je vais prévenir l'équipe de préparation et vérifier le colis de remplacement."},{"voice":"male","text":"Pouvez-vous me rappeler avant la prochaine livraison ? Je veux m'assurer que l'erreur ne se reproduira pas."},{"voice":"female","text":"Bien sûr, notre responsable vous contactera aujourd'hui."},{"voice":"female","text":"Quand le client souhaite-t-il être recontacté au sujet de son panier ?"}],"audio":"q-18.mp3","audioSeconds":30.746,"slotSeconds":46},{"number":19,"kind":"announcement","question":"Où les explications seront-elles données pendant la visite de la ferme pédagogique ?","options":["À proximité des animaux, dans des espaces parfois étroits.","Directement à l’intérieur des bâtiments de soins, au milieu des interventions.","Uniquement en extérieur, regroupés dans la cour principale de la ferme.","Dans une salle de projection aménagée à l’écart des animaux."],"correct":"A","explanation":"Réponse A : La phrase du stimulus indique explicitement que les explications se feront à proximité des animaux, dans des espaces parfois étroits, ce qui correspond exactement à cette option. B : Quelqu’un pourrait croire que les explications ont lieu à l’intérieur des bâtiments de soins, car il est mentionné que les visiteurs ne doivent pas gêner les soins. Cependant, le texte précise que les explications se font à proximité des animaux, pas au milieu des interventions. C : On pourrait penser que tout se passe uniquement en extérieur, car une ferme comporte souvent une cour principale. Toutefois, le texte parle d’espaces parfois étroits, ce qui exclut une grande cour principale comme unique lieu. D : Quelqu’un pourrait supposer qu’une salle de projection est utilisée pour des explications, mais le texte ne mentionne rien de tel et insiste sur la proximité avec les animaux.","transcript":"Question 19.\nLors des visites de la ferme pédagogique, les groupes ne dépasseront pas huit personnes. Les explications auront lieu à proximité des animaux, dans des espaces parfois étroits. Ce nombre réduit permettra aux visiteurs d'entendre les consignes, de poser des questions et de circuler sans gêner les soins apportés aux bêtes.\nOù les explications seront-elles données pendant la visite de la ferme pédagogique ?","segments":[{"voice":"female","text":"Question 19."},{"voice":"female","text":"Lors des visites de la ferme pédagogique, les groupes ne dépasseront pas huit personnes. Les explications auront lieu à proximité des animaux, dans des espaces parfois étroits. Ce nombre réduit permettra aux visiteurs d'entendre les consignes, de poser des questions et de circuler sans gêner les soins apportés aux bêtes."},{"voice":"female","text":"Où les explications seront-elles données pendant la visite de la ferme pédagogique ?"}],"audio":"q-19.mp3","audioSeconds":24.712,"slotSeconds":40},{"number":20,"kind":"dialogue","question":"Comment l’interlocuteur suggère-t-il de gérer l’irrégularité des récoltes du producteur voisin ?","options":["Négocier avec le producteur pour qu’il cultive les mêmes variétés toute l’année.","Élaborer des menus saisonniers avec des remplacements prévus.","Commander une partie des légumes auprès d’un grossiste plus flexible.","Limiter la carte aux plats qui utilisent des légumes disponibles toute l’année."],"correct":"B","explanation":"Réponse B : L’interlocuteur propose explicitement d’élaborer des menus saisonniers et de prévoir des remplacements, ce qui répond directement à la question sur la gestion de l’irrégularité des récoltes. A : Quelqu’un pourrait croire qu’il s’agit de demander au producteur de cultiver les mêmes variétés toute l’année, car l’interlocuteur évoque le problème de ne pas pouvoir proposer les mêmes plats toute l’année. Cependant, la solution proposée n’est pas de négocier avec le producteur pour qu’il cultive les mêmes variétés, mais d’adapter les menus. C : Quelqu’un pourrait penser à commander chez un grossiste plus flexible pour pallier l’irrégularité, car il est question de l’approvisionnement, mais il n’est jamais question de faire appel à un grossiste dans l’extrait. D : Limiter la carte aux plats utilisant des légumes disponibles toute l’année pourrait sembler une solution logique à l’irrégularité, mais l’interlocuteur propose au contraire de changer les menus selon les saisons, pas de limiter la carte.","transcript":"Question 20.\nNous pourrions acheter tous nos légumes au producteur voisin. Son offre est intéressante.\nC'est possible, mais il faut tenir compte des périodes où certaines variétés ne poussent pas.\nJustement. Je ne veux pas promettre les mêmes plats toute l'année si les récoltes sont irrégulières.\nNous pouvons établir des menus qui changent selon les saisons et prévoir des substitutions.\nComment l’interlocuteur suggère-t-il de gérer l’irrégularité des récoltes du producteur voisin ?","segments":[{"voice":"female","text":"Question 20."},{"voice":"male","text":"Nous pourrions acheter tous nos légumes au producteur voisin. Son offre est intéressante."},{"voice":"female","text":"C'est possible, mais il faut tenir compte des périodes où certaines variétés ne poussent pas."},{"voice":"male","text":"Justement. Je ne veux pas promettre les mêmes plats toute l'année si les récoltes sont irrégulières."},{"voice":"female","text":"Nous pouvons établir des menus qui changent selon les saisons et prévoir des substitutions."},{"voice":"female","text":"Comment l’interlocuteur suggère-t-il de gérer l’irrégularité des récoltes du producteur voisin ?"}],"audio":"q-20.mp3","audioSeconds":30.459,"slotSeconds":47},{"number":21,"kind":"announcement","question":"D’après l’annonce, sur quoi sera surtout basée la répartition des équipes de bénévoles entre les trois marchés ?","options":["Sur la distance à parcourir entre les marchés et l’entrepôt de la banque alimentaire.","Sur les véhicules disponibles et les créneaux horaires indiqués par les bénévoles.","Sur le nombre habituel de commerçants présents dans chacun des marchés.","Sur la quantité estimée d’invendus dans chaque marché avant leur fermeture."],"correct":"B","explanation":"Réponse B : L’annonce précise explicitement que la répartition des équipes sera faite selon les véhicules disponibles et les créneaux horaires indiqués par les bénévoles. C’est le seul critère clairement mentionné. A : Quelqu’un pourrait penser que la distance à parcourir est importante à cause de la mention du départ rapide des véhicules, mais il n’est jamais question de la distance entre les marchés et l’entrepôt. L’annonce ne mentionne pas ce critère pour la répartition. C : On pourrait croire que le nombre habituel de commerçants influence la répartition, mais l’annonce indique que les quantités ne sont pas connues à l’avance et ne mentionne pas ce critère. D : Quelqu’un pourrait penser que la quantité estimée d’invendus est utilisée, mais l’annonce précise que ces quantités ne seront connues qu’à la fermeture, donc elles ne peuvent pas servir à la répartition préalable.","transcript":"Question 21.\nLa banque alimentaire organise samedi une récupération des invendus dans trois marchés. Les quantités ne seront connues qu'à la fermeture et les véhicules devront partir rapidement. Merci aux bénévoles de préciser s'ils peuvent aider en fin d'après-midi ou en début de soirée. Nous répartirons les équipes selon les véhicules et les horaires, afin de ne pas laisser certains marchés sans collecte.\nD’après l’annonce, sur quoi sera surtout basée la répartition des équipes de bénévoles entre les trois marchés ?","segments":[{"voice":"female","text":"Question 21."},{"voice":"female","text":"La banque alimentaire organise samedi une récupération des invendus dans trois marchés. Les quantités ne seront connues qu'à la fermeture et les véhicules devront partir rapidement. Merci aux bénévoles de préciser s'ils peuvent aider en fin d'après-midi ou en début de soirée. Nous répartirons les équipes selon les véhicules et les horaires, afin de ne pas laisser certains marchés sans collecte."},{"voice":"female","text":"D’après l’annonce, sur quoi sera surtout basée la répartition des équipes de bénévoles entre les trois marchés ?"}],"audio":"q-21.mp3","audioSeconds":29.048,"slotSeconds":52},{"number":22,"kind":"interview","question":"Selon la maraîchère, quel effet principal les échanges directs avec les habitants ont-ils sur la préparation des paniers ?","options":["Adapter la composition des paniers aux habitudes et contraintes des habitants.","Garantir une composition de paniers identique malgré les changements de saison.","Remplir davantage les paniers lorsque les récoltes sont abondantes pour vendre plus.","Écarter des paniers les récoltes jugées trop petites ou moins belles."],"correct":"A","explanation":"Réponse A : La maraîchère explique que les échanges directs lui permettent de connaître les habitudes et contraintes des habitants, ce qui l'aide à organiser (adapter) les paniers. C'est l'effet principal mentionné sur la préparation des paniers. B : Quelqu'un pourrait croire que la composition reste identique malgré les saisons, mais la maraîchère dit précisément que les produits changent et que la communication aide à éviter les malentendus à ce sujet, pas à garantir l'identité des paniers. C : On pourrait penser que vendre plus est l'objectif, mais la maraîchère précise que ce n'est pas l'essentiel. Elle ne parle pas de remplir davantage les paniers pour vendre plus, mais d'adapter aux besoins des habitants. D : Quelqu'un pourrait croire que les produits moins beaux ou petits sont écartés, mais la maraîchère dit que les habitants comprennent mieux leur présence dans les paniers, pas qu'ils sont retirés.","transcript":"Question 22.\nVous participez depuis trois ans à un marché géré par les producteurs. Est-ce d'abord une manière de vendre davantage ?\nC'est important, mais l'essentiel est que nous discutons directement avec les habitants. Ils comprennent mieux pourquoi certaines récoltes sont plus petites ou moins belles. De notre côté, nous découvrons leurs habitudes et leurs contraintes. Cela nous aide à organiser les paniers et évite des malentendus lorsque les produits changent au fil de l'année. La relation compte autant que la transaction.\nSelon la maraîchère, quel effet principal les échanges directs avec les habitants ont-ils sur la préparation des paniers ?","segments":[{"voice":"female","text":"Question 22."},{"voice":"male","text":"Vous participez depuis trois ans à un marché géré par les producteurs. Est-ce d'abord une manière de vendre davantage ?"},{"voice":"female","text":"C'est important, mais l'essentiel est que nous discutons directement avec les habitants. Ils comprennent mieux pourquoi certaines récoltes sont plus petites ou moins belles. De notre côté, nous découvrons leurs habitudes et leurs contraintes. Cela nous aide à organiser les paniers et évite des malentendus lorsque les produits changent au fil de l'année. La relation compte autant que la transaction."},{"voice":"female","text":"Selon la maraîchère, quel effet principal les échanges directs avec les habitants ont-ils sur la préparation des paniers ?"}],"audio":"q-22.mp3","audioSeconds":37.433,"slotSeconds":62},{"number":23,"kind":"panel-discussion","question":"Sur quel dispositif concret les participants s'accordent-ils pour introduire les produits locaux dans les menus ?","options":["Prévoir sur un trimestre un menu entièrement local une fois par semaine, sans modifier le reste de la carte.","Mettre en place pendant un semestre un calendrier saisonnier avec plusieurs produits locaux servis chaque jour.","Essayer pendant un trimestre un calendrier saisonnier avec deux produits locaux par semaine, en évaluant les restes et les réactions des élèves.","Ajouter chaque semaine deux produits locaux aux menus actuels, à condition que les parents donnent leur avis sur les factures."],"correct":"C","explanation":"Réponse C : C'est la seule option qui reprend exactement la proposition discutée : tester pendant un trimestre un calendrier saisonnier avec deux produits locaux par semaine, en évaluant les restes et les réactions des élèves. A : Cette option propose un menu entièrement local une fois par semaine, ce qui n'est pas mentionné dans l'enregistrement. Quelqu'un pourrait confondre l'idée de 'deux produits locaux chaque semaine' avec un menu complet local, mais le texte précise seulement l'introduction de deux produits, pas un menu entier. B : L'option parle d'un semestre et de plusieurs produits locaux servis chaque jour, alors que l'enregistrement mentionne un test sur un trimestre et seulement deux produits locaux par semaine. La confusion peut venir de l'expression 'calendrier saisonnier', mais la durée et la fréquence sont incorrectes. D : L'option ajoute une condition sur l'avis des parents concernant les factures, qui n'est pas évoquée dans l'enregistrement. Quelqu'un pourrait se tromper en pensant que la mention du coût maîtrisé implique une consultation parentale, mais ce n'est pas ce qui est décidé.","transcript":"Question 23.\nNous discutons de la place des aliments locaux dans les cantines.\nPour les producteurs, des contrats réguliers faciliteraient les investissements.\nDu côté des cuisines, nous devons prévoir des recettes qui acceptent des quantités variables.\nEt les parents veulent des repas équilibrés et un coût maîtrisé.\nNous pourrions tester un calendrier saisonnier sur un trimestre, avec deux produits locaux chaque semaine.\nD'accord, si les équipes évaluent aussi les restes et les réactions des élèves.\nSur quel dispositif concret les participants s'accordent-ils pour introduire les produits locaux dans les menus ?","segments":[{"voice":"female","text":"Question 23.","speaker":"female"},{"voice":"female","text":"Nous discutons de la place des aliments locaux dans les cantines.","speaker":"female"},{"voice":"male","text":"Pour les producteurs, des contrats réguliers faciliteraient les investissements.","speaker":"male"},{"voice":"female","text":"Du côté des cuisines, nous devons prévoir des recettes qui acceptent des quantités variables.","speaker":"female_alt"},{"voice":"male","text":"Et les parents veulent des repas équilibrés et un coût maîtrisé.","speaker":"male_alt"},{"voice":"female","text":"Nous pourrions tester un calendrier saisonnier sur un trimestre, avec deux produits locaux chaque semaine.","speaker":"female_alt"},{"voice":"male","text":"D'accord, si les équipes évaluent aussi les restes et les réactions des élèves.","speaker":"male"},{"voice":"female","text":"Sur quel dispositif concret les participants s'accordent-ils pour introduire les produits locaux dans les menus ?","speaker":"female"}],"audio":"q-23.mp3","audioSeconds":36.023,"slotSeconds":71},{"number":24,"kind":"interview","question":"Que précise l’économiste au sujet du public qui a répondu au questionnaire ?","options":["Ce sont principalement des clients interrogés à la sortie de supermarchés.","Ce sont surtout des foyers déjà abonnés à des paniers de produits locaux.","Ce sont des visiteurs d’un festival consacré à l’agriculture régionale.","Ce sont en grande partie des personnes tirées au hasard dans la population générale."],"correct":"C","explanation":"Réponse C : Le texte précise explicitement que les personnes interrogées ont répondu à un questionnaire diffusé lors d’un festival consacré à l’agriculture régionale. C’est donc la bonne réponse. A : Quelqu’un pourrait penser que les personnes interrogées sont des clients de supermarchés, car on parle de consommateurs et d’achats, mais le texte précise que le questionnaire a été diffusé lors d’un festival, pas à la sortie de supermarchés. B : On pourrait croire que ce sont surtout des foyers déjà abonnés à des paniers de produits locaux, car ils sont intéressés par l’agriculture régionale, mais le texte ne dit pas qu’ils sont abonnés, seulement qu’ils sont plus intéressés. D : On pourrait penser que l’échantillon est représentatif de la population générale, mais le texte précise justement que ce n’est pas le cas, car les personnes interrogées étaient probablement plus intéressées par ces sujets.","transcript":"Question 24.\nUne enquête indique que les consommateurs achètent plus volontiers des produits locaux. Peut-on en conclure que leurs habitudes ont changé ?\nNous devons nuancer. Les personnes interrogées avaient répondu à un questionnaire diffusé lors d'un festival consacré à l'agriculture régionale. Elles étaient donc probablement plus intéressées par ces sujets que la population générale. Il faut comparer ces déclarations aux achats réels et interroger aussi ceux qui ne fréquentent pas ce type d'événement. Dire ce que l'on préfère ne signifie pas toujours agir en conséquence.\nQue précise l’économiste au sujet du public qui a répondu au questionnaire ?","segments":[{"voice":"female","text":"Question 24."},{"voice":"male","text":"Une enquête indique que les consommateurs achètent plus volontiers des produits locaux. Peut-on en conclure que leurs habitudes ont changé ?"},{"voice":"female","text":"Nous devons nuancer. Les personnes interrogées avaient répondu à un questionnaire diffusé lors d'un festival consacré à l'agriculture régionale. Elles étaient donc probablement plus intéressées par ces sujets que la population générale. Il faut comparer ces déclarations aux achats réels et interroger aussi ceux qui ne fréquentent pas ce type d'événement. Dire ce que l'on préfère ne signifie pas toujours agir en conséquence."},{"voice":"female","text":"Que précise l’économiste au sujet du public qui a répondu au questionnaire ?"}],"audio":"q-24.mp3","audioSeconds":37.329,"slotSeconds":69},{"number":25,"kind":"television-report","question":"Selon le coordinateur, dans quel cas les avantages économiques et environnementaux des livraisons sont-ils en partie annulés ?","options":["Quand la coopérative espace davantage les livraisons pour que chaque tournée reste rentable.","Quand un camion part presque vide desservir quelques villages éloignés.","Quand un même camion très chargé doit multiplier les arrêts le long des grands axes.","Quand les restaurateurs doivent se déplacer eux-mêmes vers des points de regroupement pour récupérer leurs commandes."],"correct":"B","explanation":"Réponse B : C’est exactement ce que dit le coordinateur : un camion presque vide qui dessert quelques villages éloignés annule en partie les avantages économiques et environnementaux. A : Quelqu’un pourrait croire que l’espacement des livraisons ou la recherche de rentabilité annule les avantages, car cela est évoqué comme une solution testée. Cependant, le texte ne dit pas que cela annule les gains, mais que cela est testé pour les préserver. C : On pourrait penser qu’un camion très chargé qui multiplie les arrêts serait problématique, mais le texte explique que la centralisation vise justement à éviter les tournées individuelles, pas à limiter les arrêts d’un camion chargé. D : Quelqu’un pourrait croire que demander aux restaurateurs de se déplacer annule les avantages, car cela implique un déplacement supplémentaire. Cependant, le texte ne dit pas que cela annule les gains, seulement que c’est une solution testée pour éviter les camions peu remplis.","transcript":"Question 25.\nDans les Alpes, une coopérative propose aux restaurateurs des produits issus de petites exploitations. Les commandes sont centralisées pour éviter que chaque producteur effectue une longue tournée.\nMais certains villages restent loin des axes de transport, explique le coordinateur. Un camion peu rempli peut annuler une partie des gains économiques et environnementaux.\nLa coopérative teste désormais des points de regroupement et des jours de livraison communs, sans promettre que toutes les exploitations pourront être desservies chaque semaine.\nSelon le coordinateur, dans quel cas les avantages économiques et environnementaux des livraisons sont-ils en partie annulés ?","segments":[{"voice":"female","text":"Question 25."},{"voice":"female","text":"Dans les Alpes, une coopérative propose aux restaurateurs des produits issus de petites exploitations. Les commandes sont centralisées pour éviter que chaque producteur effectue une longue tournée."},{"voice":"male","text":"Mais certains villages restent loin des axes de transport, explique le coordinateur. Un camion peu rempli peut annuler une partie des gains économiques et environnementaux."},{"voice":"female","text":"La coopérative teste désormais des points de regroupement et des jours de livraison communs, sans promettre que toutes les exploitations pourront être desservies chaque semaine."},{"voice":"female","text":"Selon le coordinateur, dans quel cas les avantages économiques et environnementaux des livraisons sont-ils en partie annulés ?"}],"audio":"q-25.mp3","audioSeconds":42.005,"slotSeconds":72},{"number":26,"kind":"interview","question":"Que conseille l'agronome aux producteurs qui installent ces capteurs d’arrosage ?","options":["Appliquer un même seuil d’humidité pour l’ensemble des parcelles de l’exploitation.","Désactiver les automatismes et revenir à un arrosage uniquement manuel.","Laisser les capteurs décider entièrement des moments d’arrosage.","Comparer les mesures aux observations sur le terrain et adapter les réglages à chaque parcelle."],"correct":"D","explanation":"Réponse D : L'agronome conseille de comparer les mesures aux observations sur le terrain et d'adapter les réglages à chaque parcelle, ce qui correspond exactement à cette option. A : Quelqu'un pourrait croire qu'il faut simplifier la gestion en appliquant un seuil unique, mais l'agronome explique explicitement que cela peut entraîner des erreurs d'arrosage. B : On pourrait penser qu'il faut désactiver les automatismes, mais l'agronome ne recommande pas d'abandonner la technologie, seulement de ne pas s'y fier aveuglément. C : Certains pourraient croire qu'il faut laisser les capteurs décider seuls, mais l'agronome dit précisément le contraire : il faut garder une intervention humaine.","transcript":"Question 26.\nDes capteurs peuvent désormais déclencher automatiquement l'arrosage. Pourquoi certains producteurs restent-ils prudents ?\nLes mesures sont utiles, mais un sol argileux retient l'eau autrement qu'un sol sableux. Les cultures, l'exposition au vent et la profondeur des racines comptent aussi. Si l'on applique le même seuil à toutes les parcelles, on risque d'arroser trop ou pas assez. Nous recommandons de vérifier les données avec des observations de terrain et d'ajuster les réglages selon les besoins réels, plutôt que d'abandonner toute décision aux capteurs.\nQue conseille l'agronome aux producteurs qui installent ces capteurs d’arrosage ?","segments":[{"voice":"female","text":"Question 26."},{"voice":"male","text":"Des capteurs peuvent désormais déclencher automatiquement l'arrosage. Pourquoi certains producteurs restent-ils prudents ?"},{"voice":"female","text":"Les mesures sont utiles, mais un sol argileux retient l'eau autrement qu'un sol sableux. Les cultures, l'exposition au vent et la profondeur des racines comptent aussi. Si l'on applique le même seuil à toutes les parcelles, on risque d'arroser trop ou pas assez. Nous recommandons de vérifier les données avec des observations de terrain et d'ajuster les réglages selon les besoins réels, plutôt que d'abandonner toute décision aux capteurs."},{"voice":"female","text":"Que conseille l'agronome aux producteurs qui installent ces capteurs d’arrosage ?"}],"audio":"q-26.mp3","audioSeconds":38.531,"slotSeconds":65},{"number":27,"kind":"dialogue","question":"Comment le responsable décide-t-il de répartir la commande de pommes entre les fournisseurs ?","options":["Utiliser le lot moins cher pour les desserts en tranches et garder le fournisseur habituel pour les compotes.","Rester entièrement avec le fournisseur habituel pour toutes les pommes et remettre à plus tard l’achat du lot moins cher.","Commander une partie du lot moins cher pour les compotes et garder le fournisseur habituel pour les desserts en tranches.","Basculer toutes les pommes, pour compotes et desserts, chez le nouveau fournisseur moins cher."],"correct":"C","explanation":"Réponse C : C’est exactement ce que dit le responsable : utiliser le lot moins cher pour les compotes et garder le fournisseur habituel pour les desserts en tranches. A : Cette option inverse l'utilisation des fournisseurs : le lot moins cher est réservé aux desserts en tranches, alors que le texte dit que ces pommes ne conviennent pas aux desserts (elles sont trop petites). Quelqu’un pourrait mal comprendre et croire que le lot moins cher est utilisé pour les desserts, mais c’est contredit par la phrase sur le calibre. B : Cette option suppose que le responsable reste entièrement avec le fournisseur habituel et reporte l’achat du lot moins cher, alors que le texte indique explicitement qu’une partie du lot moins cher sera commandée pour les compotes. Quelqu’un pourrait croire que la prudence l’emporte, mais c’est contredit par la décision de commander une partie du lot. D : Cette option suppose que toutes les pommes seront commandées chez le nouveau fournisseur moins cher, alors que le responsable précise qu’il ne prendra qu’une partie du lot pour les compotes et gardera l’habitude pour le reste. Quelqu’un pourrait mal interpréter la volonté de faire des économies, mais c’est contredit par la répartition décidée.","transcript":"Question 27.\nLe fournisseur nous propose des pommes moins chères, mais leur calibre est plus petit que d'habitude.\nCela peut convenir aux compotes, mais pas aux desserts qui exigent de grandes tranches.\nAlors commandons une partie du lot pour les compotes et gardons notre fournisseur habituel pour le reste.\nJe vérifierai les quantités nécessaires pour chaque recette.\nComment le responsable décide-t-il de répartir la commande de pommes entre les fournisseurs ?","segments":[{"voice":"female","text":"Question 27."},{"voice":"male","text":"Le fournisseur nous propose des pommes moins chères, mais leur calibre est plus petit que d'habitude."},{"voice":"female","text":"Cela peut convenir aux compotes, mais pas aux desserts qui exigent de grandes tranches."},{"voice":"male","text":"Alors commandons une partie du lot pour les compotes et gardons notre fournisseur habituel pour le reste."},{"voice":"female","text":"Je vérifierai les quantités nécessaires pour chaque recette."},{"voice":"female","text":"Comment le responsable décide-t-il de répartir la commande de pommes entre les fournisseurs ?"}],"audio":"q-27.mp3","audioSeconds":27.716,"slotSeconds":59},{"number":28,"kind":"interview","question":"Quel aspect du projet le chercheur reproche-t-il d’avoir été planifié avant l’observation réelle de la circulation des denrées ?","options":["Ils ont fixé les nouveaux horaires de collecte avant de connaître les contraintes des commerçants.","Ils ont programmé la formation des bénévoles avant d’avoir des retours sur les collectes tardives.","Ils ont défini les procédures de traçabilité avant de tester le matériel sur le terrain.","Ils ont calibré la taille de la chambre froide avant d’étudier concrètement les flux de denrées."],"correct":"D","explanation":"Réponse D : Le chercheur reproche explicitement d’avoir calibré la taille de la chambre froide (capacité de stockage) avant d’étudier concrètement les flux de denrées. C’est l’objet principal de la critique. A : Quelqu’un pourrait croire que les horaires de collecte ont été fixés trop tôt, car le chercheur mentionne qu’il faut les revoir. Cependant, il ne dit pas qu’ils ont été planifiés avant l’observation, mais plutôt que leur organisation n’était pas adaptée. B : La formation des bénévoles est évoquée comme un aspect à revoir, mais il n’est pas dit qu’elle a été programmée avant l’observation des collectes tardives. La critique porte sur la planification de la chambre froide, pas sur la formation. C : La traçabilité est mentionnée comme un élément à revoir, mais il n’est pas indiqué que les procédures ont été définies avant de tester le matériel. Le chercheur insiste sur la capacité de stockage planifiée trop tôt, pas sur la traçabilité.","transcript":"Question 28.\nVotre association a acheté une grande chambre froide pour réduire le gaspillage. Pourtant, les pertes n'ont pas diminué. Pourquoi ?\nNous avions évalué la capacité de stockage avant d'observer la façon dont les denrées circulaient réellement. Certaines collectes arrivaient trop tard pour être redistribuées le lendemain; d'autres produits nécessitaient un tri rapide. Le matériel était performant, mais l'organisation ne suivait pas. Nous devons maintenant revoir les horaires de collecte, la formation des bénévoles et la traçabilité. Acheter une machine n'a pas remplacé le travail d'analyse des besoins.\nQuel aspect du projet le chercheur reproche-t-il d’avoir été planifié avant l’observation réelle de la circulation des denrées ?","segments":[{"voice":"female","text":"Question 28."},{"voice":"male","text":"Votre association a acheté une grande chambre froide pour réduire le gaspillage. Pourtant, les pertes n'ont pas diminué. Pourquoi ?"},{"voice":"female","text":"Nous avions évalué la capacité de stockage avant d'observer la façon dont les denrées circulaient réellement. Certaines collectes arrivaient trop tard pour être redistribuées le lendemain; d'autres produits nécessitaient un tri rapide. Le matériel était performant, mais l'organisation ne suivait pas. Nous devons maintenant revoir les horaires de collecte, la formation des bénévoles et la traçabilité. Acheter une machine n'a pas remplacé le travail d'analyse des besoins."},{"voice":"female","text":"Quel aspect du projet le chercheur reproche-t-il d’avoir été planifié avant l’observation réelle de la circulation des denrées ?"}],"audio":"q-28.mp3","audioSeconds":43.86,"slotSeconds":66},{"number":29,"kind":"debate","question":"Sur quoi porte exactement le désaccord annoncé à la fin de l'extrait ?","options":["Sur la vitesse à laquelle les cantines devraient modifier leurs approvisionnements.","Sur la rigidité du pourcentage de produits locaux rendu obligatoire pour les cantines.","Sur le fait d’imposer 100 % de produits locaux plutôt qu’une simple majorité.","Sur l’idée même de renforcer l’emploi agricole régional grâce aux cantines."],"correct":"B","explanation":"Réponse B : C’est explicitement le point de désaccord annoncé à la fin de l’extrait. Le débat porte sur la rigidité du pourcentage obligatoire de produits locaux dans les cantines. A : Quelqu’un pourrait croire que le désaccord porte sur la vitesse de mise en œuvre, car il est question de ne pas changer trop vite. Cependant, la phrase finale précise que le désaccord porte sur la rigidité du pourcentage imposé, pas sur la rapidité. C : On pourrait croire que le débat porte sur l’imposition de 100 %, car la question initiale évoque cette possibilité. Cependant, la discussion évolue et le désaccord final porte sur la rigidité du pourcentage, pas sur le fait d’imposer 100 % précisément. D : Quelqu’un pourrait penser que le désaccord porte sur l’idée même de soutenir l’emploi agricole, car cela est évoqué. Mais la phrase « Nous sommes d'accord pour soutenir la région » montre que ce n’est pas le point de désaccord.","transcript":"Question 29.\nFaut-il encourager toutes les cantines à utiliser uniquement des produits locaux ?\nCela renforcerait les emplois agricoles de la région et raccourcirait certains transports.\nMais les producteurs locaux ne peuvent pas forcément fournir toutes les variétés ni toutes les quantités toute l'année. Il faut éviter que l'obligation crée des pénuries ou des coûts trop élevés.\nJe ne réclame pas un changement en une semaine. Nous pouvons fixer des objectifs progressifs.\nNous sommes d'accord pour soutenir la région, mais pas sur la rigidité du pourcentage imposé.\nSur quoi porte exactement le désaccord annoncé à la fin de l'extrait ?","segments":[{"voice":"female","text":"Question 29.","speaker":"female"},{"voice":"female","text":"Faut-il encourager toutes les cantines à utiliser uniquement des produits locaux ?","speaker":"female"},{"voice":"male","text":"Cela renforcerait les emplois agricoles de la région et raccourcirait certains transports.","speaker":"male"},{"voice":"female","text":"Mais les producteurs locaux ne peuvent pas forcément fournir toutes les variétés ni toutes les quantités toute l'année. Il faut éviter que l'obligation crée des pénuries ou des coûts trop élevés.","speaker":"female_alt"},{"voice":"male","text":"Je ne réclame pas un changement en une semaine. Nous pouvons fixer des objectifs progressifs.","speaker":"male"},{"voice":"female","text":"Nous sommes d'accord pour soutenir la région, mais pas sur la rigidité du pourcentage imposé.","speaker":"female_alt"},{"voice":"female","text":"Sur quoi porte exactement le désaccord annoncé à la fin de l'extrait ?","speaker":"female"}],"audio":"q-29.mp3","audioSeconds":39.993,"slotSeconds":68},{"number":30,"kind":"interview","question":"Que propose la spécialiste pour traiter les méthodes anciennes lorsqu’on adapte les recettes régionales ?","options":["Les consigner précisément et transmettre les savoir-faire, tout en laissant évoluer recettes et ingrédients.","Les remplacer progressivement par des techniques modernes mieux adaptées aux contraintes actuelles.","Les réserver aux reconstitutions patrimoniales, en encourageant ailleurs une totale liberté de création.","Les archiver dans des ouvrages de référence, sans chercher à les faire pratiquer au quotidien."],"correct":"A","explanation":"Réponse A : La spécialiste insiste sur la nécessité de consigner précisément les méthodes anciennes et de transmettre les savoir-faire, mais aussi de permettre l'évolution des recettes et des ingrédients selon les besoins et les goûts actuels. Cela correspond exactement à la proposition 0. B : Quelqu’un pourrait croire que la spécialiste suggère de remplacer les méthodes anciennes par des techniques modernes, car elle parle d’adaptation aux contraintes actuelles. Cependant, elle précise qu’il faut documenter et transmettre les méthodes anciennes, pas les remplacer. C : La mention de la tradition vivante pourrait faire croire qu’on réserve les méthodes anciennes aux reconstitutions patrimoniales, mais la spécialiste rejette explicitement cette idée en disant que la tradition n’est pas figée comme dans un musée. D : On pourrait penser qu’il suffit d’archiver les méthodes anciennes, car la spécialiste parle de documentation. Cependant, elle insiste aussi sur la transmission et la pratique, ce qui contredit l’idée de ne pas chercher à les faire pratiquer.","transcript":"Question 30.\nVous travaillez sur la préservation des recettes régionales. Faut-il les reproduire exactement ?\nLes recettes racontent une histoire, mais elles n'ont jamais été totalement immobiles. Les ingrédients disponibles changent, les familles adaptent leurs gestes et les techniques évoluent. Il est important de documenter les méthodes anciennes et de transmettre les savoir-faire, tout en laissant les cuisiniers répondre aux goûts et aux contraintes actuels. Une tradition vivante n'est pas une pièce de musée qu'on ne pourrait plus toucher.\nQue propose la spécialiste pour traiter les méthodes anciennes lorsqu’on adapte les recettes régionales ?","segments":[{"voice":"female","text":"Question 30."},{"voice":"male","text":"Vous travaillez sur la préservation des recettes régionales. Faut-il les reproduire exactement ?"},{"voice":"female","text":"Les recettes racontent une histoire, mais elles n'ont jamais été totalement immobiles. Les ingrédients disponibles changent, les familles adaptent leurs gestes et les techniques évoluent. Il est important de documenter les méthodes anciennes et de transmettre les savoir-faire, tout en laissant les cuisiniers répondre aux goûts et aux contraintes actuels. Une tradition vivante n'est pas une pièce de musée qu'on ne pourrait plus toucher."},{"voice":"female","text":"Que propose la spécialiste pour traiter les méthodes anciennes lorsqu’on adapte les recettes régionales ?"}],"audio":"q-30.mp3","audioSeconds":38.165,"slotSeconds":69},{"number":31,"kind":"academic-monologue","question":"Selon la conférencière, comment faut‑il s’y prendre concrètement pour estimer ce que le nouvel outil apporte vraiment ?","options":["Mettre en parallèle les exploitations qui ont adopté l’outil et celles qui l’ont refusé, mais seulement sur une année aux pluies favorables.","Comparer les rendements globaux de chaque ferme avant et après l’achat de l’outil, en supposant que le reste est resté stable.","Observer uniquement les parcelles équipées de l’outil pendant plusieurs saisons, sans les rapprocher des autres parcelles.","Comparer des parcelles semblables en suivant leurs résultats sur plusieurs saisons, en tenant compte des autres changements intervenus."],"correct":"D","explanation":"Réponse D : Cette option reprend exactement la méthode recommandée par la conférencière : comparer des parcelles semblables, suivre les résultats sur plusieurs saisons et tenir compte des autres changements intervenus. A : Cette option propose de comparer les exploitations ayant adopté ou refusé l’outil, mais seulement sur une année aux pluies favorables. Or, la conférencière insiste sur la nécessité de comparer sur plusieurs saisons et de tenir compte des autres changements, ce qui contredit la limitation à une seule année et l’absence de prise en compte des autres facteurs. B : Comparer les rendements globaux avant et après l’achat de l’outil sans tenir compte des autres changements est précisément ce que la conférencière déconseille, car d’autres facteurs (rotations, pluies) peuvent influencer les résultats. C : Observer uniquement les parcelles équipées sans les rapprocher des autres parcelles ne permet pas de distinguer l’effet de l’outil des autres facteurs. La conférencière recommande explicitement la comparaison avec des parcelles semblables non équipées.","transcript":"Question 31.\nDans plusieurs exploitations, les rendements ont augmenté après l'adoption d'un nouvel outil d'analyse des sols. Il serait tentant d'attribuer cette progression uniquement à l'outil. Pourtant, les agriculteurs ont aussi modifié les rotations et bénéficié de pluies plus régulières. Pour déterminer ce que le dispositif apporte réellement, nous devons comparer des parcelles semblables, suivre les résultats plusieurs saisons et tenir compte des autres changements. Une amélioration constatée après une innovation ne constitue pas, à elle seule, une preuve de causalité.\nSelon la conférencière, comment faut‑il s’y prendre concrètement pour estimer ce que le nouvel outil apporte vraiment ?","segments":[{"voice":"female","text":"Question 31."},{"voice":"female","text":"Dans plusieurs exploitations, les rendements ont augmenté après l'adoption d'un nouvel outil d'analyse des sols. Il serait tentant d'attribuer cette progression uniquement à l'outil. Pourtant, les agriculteurs ont aussi modifié les rotations et bénéficié de pluies plus régulières. Pour déterminer ce que le dispositif apporte réellement, nous devons comparer des parcelles semblables, suivre les résultats plusieurs saisons et tenir compte des autres changements. Une amélioration constatée après une innovation ne constitue pas, à elle seule, une preuve de causalité."},{"voice":"female","text":"Selon la conférencière, comment faut‑il s’y prendre concrètement pour estimer ce que le nouvel outil apporte vraiment ?"}],"audio":"q-31.mp3","audioSeconds":41.535,"slotSeconds":74},{"number":32,"kind":"interview","question":"Selon le spécialiste, quelle précaution doit accompagner la présentation des prévisions de récolte aux coopératives ?","options":["Mentionner uniquement que des événements extrêmes pourraient modifier le volume prévu.","Expliquer les hypothèses de départ et annoncer que la fourchette sera révisée avec les nouvelles observations.","Rassurer les acheteurs en présentant la fourchette comme une quantité pratiquement déjà récoltée.","Garder les hypothèses techniques en interne et ne communiquer qu’une fourchette globale aux coopératives."],"correct":"B","explanation":"Réponse B : Le spécialiste recommande explicitement d’expliquer les hypothèses de départ et d’annoncer que la fourchette sera révisée avec les nouvelles observations. Cette option reprend exactement ces deux éléments. A : Quelqu’un pourrait croire que la seule précaution à prendre est de mentionner les risques d’événements extrêmes, car le spécialiste évoque ces facteurs. Cependant, il précise aussi qu’il faut expliquer les hypothèses de départ et réviser la fourchette avec de nouvelles observations, ce qui va au-delà de la simple mention des risques. C : Quelqu’un pourrait croire qu’il faut rassurer les acheteurs en présentant la fourchette comme une quantité sûre, car le spécialiste mentionne le besoin d’anticiper des acheteurs. Cependant, il précise qu’il serait irresponsable de présenter l’estimation comme une quantité déjà récoltée, ce qui contredit cette option. D : On pourrait penser qu’il vaut mieux garder les hypothèses techniques en interne, mais le spécialiste dit explicitement qu’il faut expliquer les hypothèses de départ aux coopératives, ce qui contredit cette option.","transcript":"Question 32.\nVous prévoyez la production de blé de l'année prochaine. Peut-on annoncer un chiffre précis aux coopératives ?\nNous pouvons présenter une fourchette, mais une température extrême ou une maladie des plantes pourrait changer les résultats. Il faut expliquer les hypothèses de départ et mettre les prévisions à jour quand de nouvelles observations arrivent. Les acheteurs ont besoin d'anticiper, certes, mais il serait irresponsable de traiter une estimation comme une quantité déjà récoltée.\nSelon le spécialiste, quelle précaution doit accompagner la présentation des prévisions de récolte aux coopératives ?","segments":[{"voice":"female","text":"Question 32."},{"voice":"male","text":"Vous prévoyez la production de blé de l'année prochaine. Peut-on annoncer un chiffre précis aux coopératives ?"},{"voice":"female","text":"Nous pouvons présenter une fourchette, mais une température extrême ou une maladie des plantes pourrait changer les résultats. Il faut expliquer les hypothèses de départ et mettre les prévisions à jour quand de nouvelles observations arrivent. Les acheteurs ont besoin d'anticiper, certes, mais il serait irresponsable de traiter une estimation comme une quantité déjà récoltée."},{"voice":"female","text":"Selon le spécialiste, quelle précaution doit accompagner la présentation des prévisions de récolte aux coopératives ?"}],"audio":"q-32.mp3","audioSeconds":35.814,"slotSeconds":70},{"number":33,"kind":"commentary","question":"Quelle critique la chroniqueuse adresse-t-elle à l'indicateur présenté ?","options":["Il surestime surtout l’impact des ventes à bas prix, alors que celles-ci représentent une part marginale des invendus.","Il mélange dans un même chiffre les dons, les soldes et les déchets, sans distinguer ces catégories.","Il sous-estime l’effet positif des dons aux associations en les comptant encore comme du gaspillage.","Il ne tient compte que de ce qui finit à la poubelle et ignore le devenir des produits donnés ou revendus."],"correct":"D","explanation":"Réponse D : La chroniqueuse reproche à l'indicateur de ne tenir compte que de ce qui finit à la poubelle et d'ignorer ce qu'il advient des produits donnés ou revendus, ce qui correspond exactement à cette option. A : Quelqu'un pourrait croire que la chroniqueuse critique la surestimation de l'impact des ventes à bas prix, car elle souligne que ces produits ne sont pas forcément consommés. Cependant, elle ne dit pas que ces ventes représentent une part marginale des invendus, ni que l'indicateur surestime leur impact ; elle critique plutôt le fait que l'indicateur ne suit pas ce qu'il advient réellement de ces produits. B : On pourrait croire que l'indicateur mélange dons, soldes et déchets, mais la chroniqueuse explique au contraire qu'il ne prend en compte que les déchets jetés, pas les autres catégories. C : Quelqu'un pourrait penser que l'indicateur sous-estime l'effet positif des dons, mais la chroniqueuse reconnaît que c'est un progrès et ne critique pas l'indicateur sur ce point.","transcript":"Question 33.\nUne enseigne annonce avoir réduit de moitié le gaspillage dans ses magasins. C'est encourageant, mais ce chiffre repose uniquement sur le poids des déchets jetés. Certains produits ont désormais été donnés à des associations, ce qui constitue un progrès; d'autres sont simplement revendus à bas prix alors qu'ils ne seront pas forcément consommés. Il faut suivre la destination réelle des aliments et les quantités effectivement utilisées. Déplacer un produit hors de la poubelle ne signifie pas toujours qu'il a évité le gaspillage.\nQuelle critique la chroniqueuse adresse-t-elle à l'indicateur présenté ?","segments":[{"voice":"female","text":"Question 33."},{"voice":"female","text":"Une enseigne annonce avoir réduit de moitié le gaspillage dans ses magasins. C'est encourageant, mais ce chiffre repose uniquement sur le poids des déchets jetés. Certains produits ont désormais été donnés à des associations, ce qui constitue un progrès; d'autres sont simplement revendus à bas prix alors qu'ils ne seront pas forcément consommés. Il faut suivre la destination réelle des aliments et les quantités effectivement utilisées. Déplacer un produit hors de la poubelle ne signifie pas toujours qu'il a évité le gaspillage."},{"voice":"female","text":"Quelle critique la chroniqueuse adresse-t-elle à l'indicateur présenté ?"}],"audio":"q-33.mp3","audioSeconds":34.456,"slotSeconds":67},{"number":34,"kind":"roundtable","question":"Quelle condition est ajoutée à la proposition de contrats saisonniers avec substitutions acceptées à l'avance ?","options":["De suivre précisément les quantités réellement consommées.","De maintenir inchangées les recettes déjà prévues.","Que les prix restent dans le budget des cantines.","D'assurer aux agriculteurs un prix minimum garanti."],"correct":"A","explanation":"Réponse A : La condition explicitement ajoutée à la proposition de contrats saisonniers avec substitutions acceptées à l'avance est de suivre aussi les quantités réellement consommées. C'est dit clairement dans le stimulus. B : Quelqu'un pourrait croire que les recettes doivent rester inchangées parce qu'il est question de repas variés et de planification, mais il n'est jamais exigé de maintenir les recettes prévues. Au contraire, la possibilité de substitutions montre que les recettes peuvent changer. C : Il est mentionné que les cantines doivent tenir leur budget, ce qui pourrait faire croire que les prix doivent rester dans le budget. Cependant, ce n'est pas formulé comme une condition ajoutée à la proposition de contrats saisonniers avec substitutions acceptées à l'avance. D : Les agriculteurs souhaitent de la stabilité, mais il n'est jamais question d'un prix minimum garanti comme condition à la proposition. Quelqu'un pourrait confondre la demande de stabilité avec une garantie de prix, mais ce n'est pas ce qui est dit.","transcript":"Question 34.\nUne table ronde réunit des agriculteurs, des responsables de cantine et des consommateurs.\nNous aimerions des commandes stables pour planifier nos semis.\nLes cantines doivent tenir leur budget, mais les enfants veulent aussi des repas variés.\nSi une récolte échoue, nous avons besoin de pouvoir proposer une autre variété sans être pénalisés.\nNous pourrions conclure des contrats saisonniers avec une liste de substitutions acceptées à l'avance.\nÀ condition de suivre aussi les quantités réellement consommées.\nD'accord, testons cette formule sur un trimestre.\nQuelle condition est ajoutée à la proposition de contrats saisonniers avec substitutions acceptées à l'avance ?","segments":[{"voice":"female","text":"Question 34.","speaker":"female"},{"voice":"female","text":"Une table ronde réunit des agriculteurs, des responsables de cantine et des consommateurs.","speaker":"female"},{"voice":"male","text":"Nous aimerions des commandes stables pour planifier nos semis.","speaker":"male"},{"voice":"female","text":"Les cantines doivent tenir leur budget, mais les enfants veulent aussi des repas variés.","speaker":"female_alt"},{"voice":"male","text":"Si une récolte échoue, nous avons besoin de pouvoir proposer une autre variété sans être pénalisés.","speaker":"male"},{"voice":"female","text":"Nous pourrions conclure des contrats saisonniers avec une liste de substitutions acceptées à l'avance.","speaker":"female_alt"},{"voice":"male","text":"À condition de suivre aussi les quantités réellement consommées.","speaker":"male"},{"voice":"female","text":"D'accord, testons cette formule sur un trimestre.","speaker":"female_alt"},{"voice":"female","text":"Quelle condition est ajoutée à la proposition de contrats saisonniers avec substitutions acceptées à l'avance ?","speaker":"female"}],"audio":"q-34.mp3","audioSeconds":42.71,"slotSeconds":70},{"number":35,"kind":"interview","question":"Quelle affirmation courante à propos des emballages réutilisables l'ingénieure critique-t-elle explicitement ?","options":["Qu’un emballage réutilisable doit toujours être transporté sur de longues distances pour être écologiquement rentable.","Que le simple fait d’être étiqueté « réutilisable » suffit pour conclure à un bon impact environnemental.","Qu’il est impossible de comparer l’impact d’emballages réutilisables selon les contextes d’utilisation.","Que seuls le nombre de réutilisations et la durée de vie permettent de juger l’impact d’un emballage réutilisable."],"correct":"B","explanation":"Réponse B : L’ingénieure critique explicitement l’idée que le simple fait d’être étiqueté « réutilisable » suffit à garantir un bon impact environnemental. Elle explique qu’il faut évaluer d’autres critères comme la durée de vie, le nombre de réutilisations, les transports et le lavage. A : Quelqu’un pourrait croire que l’ingénieure critique le transport sur de longues distances, car elle mentionne que cela réduit l’intérêt écologique. Cependant, elle ne dit pas qu’il faut toujours transporter sur de longues distances pour que ce soit rentable, mais que le transport est un facteur à prendre en compte. C : Quelqu’un pourrait penser que l’ingénieure dit qu’il est impossible de comparer les impacts selon les contextes, car elle mentionne plusieurs facteurs. Mais en réalité, elle explique qu’il faut justement prendre en compte ces facteurs pour comparer, pas que c’est impossible. D : On pourrait croire que seuls le nombre de réutilisations et la durée de vie suffisent, car ils sont cités. Mais l’ingénieure ajoute explicitement d’autres critères comme les transports et le lavage, donc ce n’est pas suffisant.","transcript":"Question 35.\nLes nouveaux emballages réutilisables semblent très écologiques. Pourtant, vous demandez une évaluation plus complète. Pourquoi ?\nIl faut mesurer leur durée de vie, le nombre réel de réutilisations, les transports nécessaires au retour et l'eau utilisée pour le lavage. Un contenant peut être excellent s'il circule longtemps près de son lieu d'utilisation, mais beaucoup moins intéressant s'il parcourt des centaines de kilomètres après chaque livraison. L'étiquette « réutilisable » ne suffit donc pas à décrire son impact.\nQuelle affirmation courante à propos des emballages réutilisables l'ingénieure critique-t-elle explicitement ?","segments":[{"voice":"female","text":"Question 35."},{"voice":"male","text":"Les nouveaux emballages réutilisables semblent très écologiques. Pourtant, vous demandez une évaluation plus complète. Pourquoi ?"},{"voice":"female","text":"Il faut mesurer leur durée de vie, le nombre réel de réutilisations, les transports nécessaires au retour et l'eau utilisée pour le lavage. Un contenant peut être excellent s'il circule longtemps près de son lieu d'utilisation, mais beaucoup moins intéressant s'il parcourt des centaines de kilomètres après chaque livraison. L'étiquette « réutilisable » ne suffit donc pas à décrire son impact."},{"voice":"female","text":"Quelle affirmation courante à propos des emballages réutilisables l'ingénieure critique-t-elle explicitement ?"}],"audio":"q-35.mp3","audioSeconds":38.87,"slotSeconds":68},{"number":36,"kind":"interview","question":"Dans quel cas le jardin reste-t-il simplement agréable sans vraiment développer l’entraide, d’après l’intervenant ?","options":["Quand les décisions restent informelles et que personne n’assume clairement la coordination.","Quand chacun choisit ses tâches à distance par message sans passer par les réunions.","Quand tout le monde participe aux décisions mais que certains refusent les tâches les moins valorisantes.","Quand un petit groupe prend toutes les décisions et que les autres se contentent d’exécuter."],"correct":"D","explanation":"Réponse D : L’intervenant dit explicitement que si un petit groupe prend toutes les décisions et que les autres se contentent d’exécuter, le jardin reste agréable mais ne développe pas vraiment l’entraide. A : Quelqu’un pourrait croire que l’absence de coordination claire empêche l’entraide, car le texte insiste sur la transparence des décisions. Cependant, il n’est pas dit que cela mène seulement à un jardin agréable sans entraide. B : On pourrait penser que la participation à distance sans réunions empêche l’entraide, car le texte parle de la difficulté de certains à venir aux heures habituelles. Mais il n’est pas dit que cela aboutit à un simple jardin agréable sans entraide. C : Le texte mentionne la nécessité de prévoir des tâches adaptées, ce qui pourrait faire croire que si certains refusent les tâches moins valorisantes, l’entraide ne se développe pas. Cependant, ce cas n’est pas explicitement relié à un jardin simplement agréable sans entraide.","transcript":"Question 36.\nLe jardin communautaire est très fréquenté. Est-ce suffisant pour dire qu'il favorise la solidarité ?\nPas nécessairement. Certaines personnes n'osent pas prendre la parole ou ne peuvent venir aux heures habituelles. Nous devons rendre les décisions transparentes, prévoir des tâches adaptées et permettre à chacun de participer sans devoir justifier ses contraintes. Si quelques membres décident de tout et les autres exécutent, le lieu peut rester agréable mais ne crée pas une véritable entraide.\nDans quel cas le jardin reste-t-il simplement agréable sans vraiment développer l’entraide, d’après l’intervenant ?","segments":[{"voice":"female","text":"Question 36."},{"voice":"male","text":"Le jardin communautaire est très fréquenté. Est-ce suffisant pour dire qu'il favorise la solidarité ?"},{"voice":"female","text":"Pas nécessairement. Certaines personnes n'osent pas prendre la parole ou ne peuvent venir aux heures habituelles. Nous devons rendre les décisions transparentes, prévoir des tâches adaptées et permettre à chacun de participer sans devoir justifier ses contraintes. Si quelques membres décident de tout et les autres exécutent, le lieu peut rester agréable mais ne crée pas une véritable entraide."},{"voice":"female","text":"Dans quel cas le jardin reste-t-il simplement agréable sans vraiment développer l’entraide, d’après l’intervenant ?"}],"audio":"q-36.mp3","audioSeconds":37.799,"slotSeconds":71},{"number":37,"kind":"interview","question":"Pourquoi l'historienne conserve-t-elle des témoignages contradictoires ?","options":["Pour compenser l’absence d’archives en traitant tous les souvenirs comme des faits établis.","Pour repérer les erreurs de mémoire et ne garder que les souvenirs confirmés par les archives.","Pour démontrer que les témoins finissent par s’accorder sur les mêmes faits malgré des récits divergents.","Pour éclairer des peurs et des intérêts différents en les replaçant dans la situation de chaque témoin."],"correct":"D","explanation":"Réponse D : La réponse correcte est que l’historienne conserve les témoignages contradictoires pour éclairer des peurs et des intérêts différents en les replaçant dans la situation de chaque témoin, ce qui correspond exactement à l’explication donnée dans le texte. A : Quelqu’un pourrait croire que l’historienne traite tous les souvenirs comme des faits établis pour compenser l’absence d’archives, mais le texte précise qu’elle distingue les faits établis des impressions et commence par vérifier dans les archives. B : On pourrait penser que l’historienne ne garde que les souvenirs confirmés par les archives, mais elle explique qu’elle conserve aussi les contradictions pour comprendre les différents points de vue, pas seulement pour éliminer les erreurs. C : Certains pourraient croire que les témoins finissent par s’accorder, mais le texte insiste sur la persistance des divergences et leur utilité pour comprendre des intérêts différents, pas sur une convergence finale.","transcript":"Question 37.\nLes anciens producteurs ne racontent pas tous la même chose sur la fermeture de la conserverie. Comment traiter ces différences ?\nNous vérifions d'abord les faits dans les archives : dates, décisions et effectifs. Mais le responsable de l'usine, un saisonnier et un commerçant n'avaient pas la même place dans l'événement. Leurs souvenirs révèlent des inquiétudes et des intérêts différents. Les contradictions deviennent utiles lorsqu'on connaît le contexte des témoignages, sans renoncer à distinguer les faits établis des impressions.\nPourquoi l'historienne conserve-t-elle des témoignages contradictoires ?","segments":[{"voice":"female","text":"Question 37."},{"voice":"male","text":"Les anciens producteurs ne racontent pas tous la même chose sur la fermeture de la conserverie. Comment traiter ces différences ?"},{"voice":"female","text":"Nous vérifions d'abord les faits dans les archives : dates, décisions et effectifs. Mais le responsable de l'usine, un saisonnier et un commerçant n'avaient pas la même place dans l'événement. Leurs souvenirs révèlent des inquiétudes et des intérêts différents. Les contradictions deviennent utiles lorsqu'on connaît le contexte des témoignages, sans renoncer à distinguer les faits établis des impressions."},{"voice":"female","text":"Pourquoi l'historienne conserve-t-elle des témoignages contradictoires ?"}],"audio":"q-37.mp3","audioSeconds":36.598,"slotSeconds":71},{"number":38,"kind":"public-lecture","question":"Selon le conférencier, en quoi le succès touristique d’un marché de produits du terroir est-il paradoxal ?","options":["Parce qu’en augmentant fortement les volumes pour les visiteurs, il permet aux producteurs de baisser les prix pour leurs clients habituels.","Parce qu’en attirant toujours plus de visiteurs, il finit par limiter l’accès des habitants aux produits et aux prix qui faisaient la réputation du lieu.","Parce qu’en se spécialisant dans la vente aux touristes, il garantit aux habitants une offre plus large mais à des tarifs plus élevés.","Parce qu’en devenant une vitrine presque exclusivement touristique, il préserve la fonction d’approvisionnement quotidien tout en affaiblissant l’image de terroir du marché."],"correct":"B","explanation":"Réponse B : C’est exactement ce que dit le conférencier : le succès touristique attire plus de visiteurs, ce qui limite l’accès des habitants aux produits et aux prix d’origine, créant ainsi le paradoxe. A : Quelqu’un pourrait croire que l’augmentation des volumes pour les touristes permettrait de baisser les prix pour les locaux, mais le texte ne dit pas que les prix baissent pour les clients habituels ; au contraire, il parle de la perte d’accès aux produits et aux prix d’origine. C : On pourrait croire que la spécialisation dans la vente aux touristes garantit une offre plus large, mais le texte indique que cela se fait au détriment des clients habituels, sans mentionner une offre plus large pour les habitants. D : Quelqu’un pourrait penser qu’en devenant une vitrine touristique, le marché préserve sa fonction d’approvisionnement quotidien, mais le texte dit précisément que cette fonction est menacée pour les habitants.","transcript":"Question 38.\nPromouvoir une destination pour ses produits du terroir peut attirer un grand nombre de visiteurs. Mais si le succès transforme les marchés en lieux destinés presque uniquement aux touristes, les habitants risquent de perdre l'accès aux produits et aux prix qui faisaient la réputation du lieu. Les producteurs peuvent aussi être poussés à privilégier des volumes et des présentations adaptés aux visiteurs plutôt que leurs clients habituels. Il faut donc distinguer le succès commercial immédiat de la capacité du marché à continuer de servir la communauté locale.\nSelon le conférencier, en quoi le succès touristique d’un marché de produits du terroir est-il paradoxal ?","segments":[{"voice":"female","text":"Question 38."},{"voice":"male","text":"Promouvoir une destination pour ses produits du terroir peut attirer un grand nombre de visiteurs. Mais si le succès transforme les marchés en lieux destinés presque uniquement aux touristes, les habitants risquent de perdre l'accès aux produits et aux prix qui faisaient la réputation du lieu. Les producteurs peuvent aussi être poussés à privilégier des volumes et des présentations adaptés aux visiteurs plutôt que leurs clients habituels. Il faut donc distinguer le succès commercial immédiat de la capacité du marché à continuer de servir la communauté locale."},{"voice":"female","text":"Selon le conférencier, en quoi le succès touristique d’un marché de produits du terroir est-il paradoxal ?"}],"audio":"q-38.mp3","audioSeconds":40.751,"slotSeconds":81},{"number":39,"kind":"interview","question":"Selon l’économiste, quelle étape doit précéder toute installation de la cuisine dans d’autres quartiers ?","options":["S’assurer d’abord de retrouver un local gratuit et une équipe de bénévoles aussi disponibles.","Attendre que la fréquentation se stabilise sur la première cuisine avant de formaliser un modèle.","Calculer le coût réel des repas, réorganiser le travail et vérifier que la gestion reste soutenable.","Tester le même fonctionnement dans un autre quartier avant de revoir la répartition des rôles."],"correct":"C","explanation":"Réponse C : L’économiste explique clairement que la première étape est de calculer le coût réel, de réorganiser le travail et de vérifier la soutenabilité de la gestion avant toute extension du modèle. A : Quelqu’un pourrait croire que la priorité est de retrouver un local gratuit et des bénévoles disponibles, car l’économiste mentionne la dépendance à ces éléments. Cependant, il précise que la première étape est de connaître le coût réel des repas, de réorganiser le travail et de vérifier la soutenabilité de la gestion avant d’étendre le modèle. B : On pourrait penser qu’il faut attendre la stabilisation de la fréquentation, car le texte évoque la popularité initiale. Mais l’économiste insiste sur la nécessité de calculer les coûts et de réorganiser avant toute extension, pas simplement d’attendre. D : Quelqu’un pourrait croire qu’il faut tester le fonctionnement ailleurs avant de revoir la répartition des rôles, car il est question d’adapter le modèle à d’autres lieux. Mais l’ordre indiqué est d’abord de réorganiser et de vérifier la gestion, puis d’envisager l’extension.","transcript":"Question 39.\nVotre cuisine partagée sert désormais beaucoup de repas. Pourquoi ne pas reproduire exactement son organisation actuelle dans d'autres quartiers ?\nParce qu'elle dépend encore d'un local prêté gratuitement et de bénévoles présents presque tous les jours. Nous devons d'abord connaître le coût réel des repas, répartir équitablement le travail et former des personnes capables de remplacer l'équipe de départ. Nous pouvons ensuite adapter le modèle à d'autres lieux, mais seulement si sa gestion reste soutenable. La popularité des premières semaines ne paiera pas à elle seule les charges régulières.\nSelon l’économiste, quelle étape doit précéder toute installation de la cuisine dans d’autres quartiers ?","segments":[{"voice":"female","text":"Question 39."},{"voice":"male","text":"Votre cuisine partagée sert désormais beaucoup de repas. Pourquoi ne pas reproduire exactement son organisation actuelle dans d'autres quartiers ?"},{"voice":"female","text":"Parce qu'elle dépend encore d'un local prêté gratuitement et de bénévoles présents presque tous les jours. Nous devons d'abord connaître le coût réel des repas, répartir équitablement le travail et former des personnes capables de remplacer l'équipe de départ. Nous pouvons ensuite adapter le modèle à d'autres lieux, mais seulement si sa gestion reste soutenable. La popularité des premières semaines ne paiera pas à elle seule les charges régulières."},{"voice":"female","text":"Selon l’économiste, quelle étape doit précéder toute installation de la cuisine dans d’autres quartiers ?"}],"audio":"q-39.mp3","audioSeconds":41.43,"slotSeconds":82}]}]$six_papers$::jsonb;
 item jsonb; prior jsonb; protected_before jsonb; protected_after jsonb;
 old_before jsonb; old_after jsonb; other_before jsonb; other_after jsonb;
 engine_before text; engine_after text;
begin
 perform pg_advisory_xact_lock(hashtext('hzad-listening-01-06-review-v4'));
 select jsonb_build_array((select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from auth.users t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from public.purchase_entitlements t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from public.academy_learning_progress t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.wallets t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.requests t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.ledger t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.policy t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.activities t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.testing_grants t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_writing.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_speaking.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_speaking.calls t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_exams.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_reading.papers t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_reading.published_papers t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_reading.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_listening.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_listening.navigation t)) into protected_before;
 select coalesce(jsonb_object_agg(id||':'||version,md5(content::text)),'{}') into old_before
  from academy_tcf_listening.papers where version not in ('tcf-listening-2026-11-test01-v4','tcf-listening-2026-11-test02-v4','tcf-listening-2026-11-test03-v4','tcf-listening-2026-11-test04-v4','tcf-listening-2026-11-test05-v4','tcf-listening-2026-11-test06-v4');
 select coalesce(jsonb_object_agg(test_id,version),'{}') into other_before
  from academy_tcf_listening.published where test_id not in ('tcf-listening-01','tcf-listening-02','tcf-listening-03','tcf-listening-04','tcf-listening-05','tcf-listening-06');
 select md5(pg_get_functiondef('public.academy_tcf_listening_command(text,uuid,jsonb)'::regprocedure)) into engine_before;
 for item in select value from jsonb_array_elements(wanted) loop
  select content into prior from academy_tcf_listening.papers where id=item->>'id' and version=item->>'version';
  if found and prior is distinct from item then raise exception 'Immutable review version differs: %',item->>'id';end if;
  select content into prior from academy_tcf_listening.papers where id=item->>'id'
   and version=case when item->>'id'='tcf-listening-01' then 'tcf-listening-2026-11-v1' else 'tcf-listening-2026-11-test'||right(item->>'id',2)||'-v1' end;
  if not found then raise exception 'Historical bank missing';end if;
  if jsonb_array_length(item->'questions')<>39 or (item->>'seconds')::int<>2100
   or (select sum((q->>'slotSeconds')::numeric) from jsonb_array_elements(item->'questions') q)<>2100
   or exists(select 1 from jsonb_array_elements(item->'questions') with ordinality as x(q,n)
    where (q->>'number')::int<>n or jsonb_array_length(q->'options')<>4 or q->>'correct' not in ('A','B','C','D')
     or coalesce((q->>'audioSeconds')::numeric,0)<=0 or (q->>'audioSeconds')::numeric+12>(q->>'slotSeconds')::numeric)
   then raise exception 'Invalid complete bank';end if;
  if exists(select 1 from jsonb_array_elements(item->'questions') q join jsonb_array_elements(prior->'questions') oldq on q->>'number'=oldq->>'number'
   where q->'slotSeconds' is distinct from oldq->'slotSeconds' or q->'kind' is distinct from oldq->'kind')then raise exception 'Historical format/timing changed';end if;
  insert into academy_tcf_listening.papers(id,version,content) values(item->>'id',item->>'version',item) on conflict(id,version) do nothing;
  insert into academy_tcf_listening.published(test_id,version) values(item->>'id',item->>'version') on conflict(test_id) do update set version=excluded.version
   where academy_tcf_listening.published.version is distinct from excluded.version;
 end loop;
 select jsonb_build_array((select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from auth.users t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from public.purchase_entitlements t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from public.academy_learning_progress t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.wallets t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.requests t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.ledger t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.policy t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.activities t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_ai.testing_grants t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_writing.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_speaking.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_speaking.calls t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_exams.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_reading.papers t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_reading.published_papers t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_reading.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_listening.attempts t),(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by to_jsonb(t)::text),'')) from academy_tcf_listening.navigation t)) into protected_after;
 select coalesce(jsonb_object_agg(id||':'||version,md5(content::text)),'{}') into old_after
  from academy_tcf_listening.papers where version not in ('tcf-listening-2026-11-test01-v4','tcf-listening-2026-11-test02-v4','tcf-listening-2026-11-test03-v4','tcf-listening-2026-11-test04-v4','tcf-listening-2026-11-test05-v4','tcf-listening-2026-11-test06-v4');
 select coalesce(jsonb_object_agg(test_id,version),'{}') into other_after
  from academy_tcf_listening.published where test_id not in ('tcf-listening-01','tcf-listening-02','tcf-listening-03','tcf-listening-04','tcf-listening-05','tcf-listening-06');
 select md5(pg_get_functiondef('public.academy_tcf_listening_command(text,uuid,jsonb)'::regprocedure)) into engine_after;
 if protected_before is distinct from protected_after or old_before is distinct from old_after or other_before is distinct from other_after or engine_before is distinct from engine_after
  then raise exception 'Preservation check failed; review publication rolled back';end if;
 if exists(select 1 from jsonb_array_elements(wanted) p where not exists(select 1 from academy_tcf_listening.papers b join academy_tcf_listening.published v on v.test_id=b.id and v.version=b.version
  where b.id=p->>'id' and b.version=p->>'version' and b.content=p))then raise exception 'Exact review publication failed';end if;
 if exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='academy_tcf_listening' and c.relkind='r' and not c.relrowsecurity)
  or has_table_privilege('anon','academy_tcf_listening.papers','select') or has_table_privilege('authenticated','academy_tcf_listening.papers','select')
  then raise exception 'Private bank protection changed';end if;
end;
$publish_six$;
